--- Check if a card is The Fool
-- @param card table: Card to check
-- @return boolean: true if card is The Fool
function M.isFool(card)
    if not card then return false end
    return card.name == "The Fool" or (card.is_major and card.value == 0)
end

local function isGreaterDoomCard(card)
    local value = tonumber(card and card.value) or 0
    return value >= 15 and value <= 21
end

local function isGMEntity(entity)
    return entity and not entity.isPC
end

local function normalizeSocialTag(value)
    if type(value) ~= "string" then
        return nil
    end

    local normalized = value:lower()
    normalized = normalized:gsub("^%s+", ""):gsub("%s+$", "")
    normalized = normalized:gsub("[%s%-]+", "_")
    return normalized
end

local function normalizeTalentKey(value)
    return tostring(value or ""):lower():gsub("[^%w]+", "_"):gsub("^_+", ""):gsub("_+$", "")
end

local function getActionItemForChallengeRules(action)
    if not action then
        return nil
    end
    if action.item then
        return action.item
    end

    local inv = action.actor and action.actor.inventory
    if inv and inv.findItem and action.itemId then
        local item = inv:findItem(action.itemId)
        return item
    end

    return nil
end

local function isAttackLikeItemUse(action)
    if not action then
        return false
    end
    if action.itemUseAttack == true or action.attackLikeItemUse == true or
       action.thrownItem == true or action.bomb == true then
        return true
    end

    local item = getActionItemForChallengeRules(action)
    local props = item and item.properties or {}
    return props.bomb == true or props.offensive == true or props.hostileUse == true or
        props.thrown == true or props.thrownItem == true
end

local function attackLikeItemCanTargetShrouded(action)
    if not action then
        return false
    end
    if action.canTargetShrouded == true or action.canTargetInvisible == true or
       action.targetsShrouded == true or action.targetsInvisible == true then
        return true
    end

    local item = getActionItemForChallengeRules(action)
    local props = item and item.properties or {}
    local effect = props.useEffect or props.challengeEffect or {}
    local target = action.target or {}
    local targetConditions = target.conditions or {}
    local targetProps = target.properties or {}
    local targetIsIntangible = target.intangible == true or target.incorporeal == true or
        target.ethereal == true or target.tangible == false or targetConditions.intangible == true or
        targetConditions.incorporeal == true or targetConditions.ethereal == true or
        targetConditions.tangible == false or targetProps.intangible == true or
        targetProps.incorporeal == true or targetProps.ethereal == true or targetProps.tangible == false
    if props.targetsShrouded == true or props.targetsInvisible == true or
       (props.targetsIntangible == true and targetIsIntangible) then
        return true
    end

    return effect.targetsShrouded == true or effect.targetsInvisible == true or
        (effect.targetsIntangible == true and targetIsIntangible) or effect.type == "materialize_intangible"
end

local function isAllowedMiscVigilanceFollowUp(actionType, actionDef)
    return actionType == M.ACTION_TYPES.TRIVIAL_ACTION and
        actionDef and actionDef.suit == action_registry.SUITS.MISC
end

local function getEntityTalentEntry(actor, talentId)
    local talents = actor and actor.talents
    if type(talents) ~= "table" then
        return nil
    end

    local requested = normalizeTalentKey(talentId)
    for key, value in pairs(talents) do
        if normalizeTalentKey(key) == requested then
            return value
        end
        if type(value) == "table" and normalizeTalentKey(value.id or value.name or value.talentId) == requested then
            return value
        end
    end

    return nil
end

local function getUsableTalentEntry(actor, talentId)
    local entry = getEntityTalentEntry(actor, talentId)
    if not entry or entry == false then
        return nil
    end
    if type(entry) == "table" and entry.wounded == true then
        return nil
    end
    return entry
end

local function entityHasUsableTalent(actor, talentId)
    local entry = getUsableTalentEntry(actor, talentId)
    if not entry then
        return false
    end
    if type(entry) == "table" then
        return entry.wounded ~= true
    end
    return entry == true
end

local function getMagicSenseSubjects(subjects, senseKey)
    local smelled = {}
    for _, subject in ipairs(subjects or {}) do
        if subject then
            local conditions = subject.conditions or {}
            local props = subject.properties or {}
            local sorcerer = subject.isSorcerer == true or subject.sorcerer == true or
                entityHasUsableTalent(subject, "gramarye") or
                entityHasUsableTalent(subject, "magic_of_the_wastes") or
                entityHasUsableTalent(subject, "magic_of_the_weald") or
                entityHasUsableTalent(subject, "magic_of_the_weird") or
                entityHasUsableTalent(subject, "magic_of_the_welkin")
            local activeSpells = subject.activeSpells
            local magicalEffect = type(activeSpells) == "table" and next(activeSpells) ~= nil or
                subject.magicEffects ~= nil or subject.magical == true or props.magical == true or
                conditions.ungoat_spell_ward == true or conditions.shrouded == true or
                conditions.invisible == true
            if sorcerer or magicalEffect then
                smelled[#smelled + 1] = {
                    subject = subject,
                    sorcerer = sorcerer,
                    magicalEffect = magicalEffect,
                    [senseKey or "sense"] = true,
                }
            end
        end
    end
    return smelled
end

local function getMagicScentSubjects(subjects)
    return getMagicSenseSubjects(subjects, "scent")
end

local function getMagicSightSubjects(subjects)
    return getMagicSenseSubjects(subjects, "sight")
end

local function normalizedTableContains(value, wanted)
    wanted = normalizeTalentKey(wanted)
    if type(value) ~= "table" then
        return false
    end

    for key, item in pairs(value) do
        if normalizeTalentKey(key) == wanted and item ~= false then
            return true
        end
        if type(item) == "string" and normalizeTalentKey(item) == wanted then
            return true
        end
        if type(item) == "table" and normalizeTalentKey(item.id or item.name or item.tag) == wanted then
            return true
        end
    end

    return false
end

local function entityHasNormalizedTag(entity, tag)
    if not entity then
        return false
    end
    return normalizedTableContains(entity.tags, tag) or
        normalizedTableContains(entity.aiTags, tag) or
        normalizedTableContains(entity.traits, tag)
end

local function isPoisonCondition(condition)
    local normalized = normalizeTalentKey(condition)
    return normalized == "poison" or normalized == "poisoned"
end

local function normalizedEntitySize(entity)
    if not entity then
        return nil
    end
    return normalizeTalentKey(entity.size or entity.sizeCategory or entity.scale or entity.category)
end

local CREATURE_SIZE_RANKS = {
    tiny = 0,
    minuscule = 0,
    small = 1,
    halfling = 1,
    gnome = 1,
    normal = 2,
    medium = 2,
    human = 2,
    human_sized = 2,
    person = 2,
    person_sized = 2,
    large = 3,
    big = 3,
    huge = 4,
    giant = 4,
    massive = 4,
    gargantuan = 5,
    colossal = 5,
    titanic = 5,
}

local function creatureSizeRank(entity)
    if not entity then
        return 2
    end

    local props = entity.properties or {}
    if entity.giantSized or entity.giantSize or entity.huge or entity.massive or entity.giant then
        return 4
    end
    if entity.large or props.large or props.largerThanPerson then
        return 3
    end

    local size = normalizedEntitySize(entity)
    local rank = CREATURE_SIZE_RANKS[size] or 2
    local multiplier = tonumber(entity.sizeMultiplier)
    if multiplier and multiplier >= 2 then
        rank = rank + 1
    elseif multiplier and multiplier > 0 and multiplier < 1 then
        rank = rank - 1
    end

    return rank
end

local function isBareHandWeapon(weapon)
    if not weapon then
        return false
    end

    if weapon.unarmed or weapon.bareHands then
        return true
    end

    local name = normalizeTalentKey(weapon.id or weapon.name or weapon.type or weapon.weaponType)
    return name == "fists" or name == "fist" or name == "bare_hands" or
        name == "bare_fists" or name == "unarmed"
end

local RULEBOOK_MORALE_BANDS = {
    perfect = 20,
    perfectly_confident = 20,
    confident = 20,
    overwhelming_forces = 20,
    overwhelming = 20,
    superior_positioning = 20,
    superior_position = 20,
    secret_escape_route = 20,
    neutral = 18,
    wary = 10,
    bloodied = 10,
    wasted_resources = 10,
    no_profit = 10,
    no_obvious_profit = 10,
    panicking = 8,
    panic = 8,
    forces_annihilated = 8,
    annihilated_forces = 8,
    backed_into_a_corner = 8,
    backed_into_corner = 8,
    cornered = 8,
    grievously_injured = 8,
}

local function explicitMoraleBandKey(target, action)
    local context = action and (action.moraleContext or action.socialContext or action.context) or nil
    local raw = action and (action.moraleState or action.moraleSituation or action.moraleBand or
        action.targetMoraleState or action.targetMoraleSituation) or nil
    raw = raw or (context and (context.moraleState or context.moraleSituation or context.moraleBand))
    raw = raw or (target and (target.moraleState or target.moraleSituation or target.moraleBand))

    local key = normalizeTalentKey(raw)
    if key ~= "" and RULEBOOK_MORALE_BANDS[key] then
        return key
    end

    local conditions = target and target.conditions or {}
    if target and (target.panicking or target.cornered or target.backedIntoCorner or target.grievouslyInjured or
       conditions.panicking or conditions.cornered or conditions.backed_into_corner or conditions.grievously_injured) then
        return "panicking"
    end
    if target and (target.wary or target.bloodied or conditions.wary or conditions.bloodied) then
        return "wary"
    end

    return nil
end

local function isGiantSizedEntity(entity)
    if not entity then
        return false
    end
    if entity.giantSized or entity.giantSize or entity.huge or entity.massive or entity.giant then
        return true
    end
    local size = normalizedEntitySize(entity)
    return size == "huge" or size == "giant" or size == "massive" or
        size == "gargantuan" or size == "colossal" or size == "titanic"
end

local function targetRequiresGiantSizeToRoughhouse(target)
    if not target then
        return false
    end
    if target.roughhouseImmuneUnlessGiantSized or target.roughhouseRequiresGiantSize then
        return true
    end
    local dragonHuge = target.dragon and target.dragon.huge
    return dragonHuge and dragonHuge.immuneToRoughhouseUnlessGiantSized
end

local function actionCanAffectGiantSizedTarget(action)
    if not action then
        return false
    end
    if action.canAffectGiantSize or action.affectsGiantSize or action.giantSizedRoughhouse or
       action.canRoughhouseHuge then
        return true
    end
    return isGiantSizedEntity(action.actor)
end

