            end
        elseif actor and (actor.loreBids or 0) <= 0 then
            return {
                success = false,
                readThePastLore = true,
                effects = { "lore_bid", "lore_unavailable" },
                description = "No lore bids remaining",
            }
        end

        local question = request.question or request.memoryQuestion or request.recallQuestion
        local answer = firstNonNil(request.answer, request.recollection, request.memory, request.summary, request.detail)
        if request.noNewInformation == true or request.noInfo == true or answer == nil or answer == "" then
            local noInfo = self:resolveBidLoreOutcome(action, {
                verdict = "rephrase_needed",
                reason = "No new remembered detail is available.",
                loreSpend = false,
                suggestedQuestionTypes = {},
                scoreBreakdown = {},
                selection = {
                    talent = "read_the_past",
                    question = question,
                },
            })
            noInfo.readThePastLore = true
            noInfo.effects[#noInfo.effects + 1] = "read_the_past_no_new_information"
            return noInfo
        end

        local bidLoreResult = {
            verdict = "accepted",
            reason = "Read the Past supplies an eidetic recollection.",
            loreSpend = true,
            readThePastLore = true,
            response = {
                summary = tostring(answer),
                details = { tostring(answer) },
                implication = "The memory is accurate to what the high elf once saw or heard.",
                sourceRefs = { "talent:read_the_past" },
            },
            scoreBreakdown = {
                talent = "read_the_past",
            },
            selection = {
                talent = "read_the_past",
                question = question,
            },
        }

        local result = self:resolveBidLoreOutcome(action, bidLoreResult)
        result.readThePastLore = true
        result.recollection = {
            question = question,
            answer = answer,
            accurate = true,
        }
        result.effects[#result.effects + 1] = "read_the_past_lore"
        result.effects[#result.effects + 1] = "eidetic_memory"
        if actor then
            actor.recalledMemories = actor.recalledMemories or {}
            actor.recalledMemories[#actor.recalledMemories + 1] = result.recollection
        end
        return result
    end

    function resolver:resolveKeenSensesLore(request)
        request = request or {}
        local actor = request.actor or request.entity

        if not entityHasUsableTalent(actor, "keen_senses") then
            return {
                success = false,
                keenSensesLore = true,
                effects = { "lore_bid", "keen_senses_blocked" },
                description = "Requires Keen Senses to sharpen a sense for lore.",
            }
        end

        local action = {
            actor = actor,
            type = M.ACTION_TYPES.BID_LORE,
            keenSensesLore = true,
            spendResolveForLore = request.spendResolveForLore == true or request.resolveForLore == true or
                request.useResolveForLore == true or request.spendResolveForBidLore == true,
        }
        if self:wantsResolveForLore(action) then
            local canSpendResolve, resolveReason = self:canSpendLoremasterResolveForLore(actor)
            if not canSpendResolve then
                return {
                    success = false,
                    keenSensesLore = true,
                    effects = { "lore_bid", "lore_unavailable", "resolve_missing" },
                    description = loreResolveFailureText(resolveReason),
                }
            end
        elseif actor and (actor.loreBids or 0) <= 0 then
            return {
                success = false,
                keenSensesLore = true,
                effects = { "lore_bid", "lore_unavailable" },
                description = "No lore bids remaining",
            }
        end

        local sense = normalizeTalentKey(request.sense or request.heightenedSense or request.focusedSense or "sense")
        if sense == "" then
            sense = "sense"
        end
        local question = request.question or request.senseQuestion
        local answer = firstNonNil(request.answer, request.sensoryDetail, request.detail, request.summary)
        if request.noNewInformation == true or request.noInfo == true or answer == nil or answer == "" then
            local noInfo = self:resolveBidLoreOutcome(action, {
                verdict = "rephrase_needed",
                reason = "No new sensory detail is available.",
                loreSpend = false,
                suggestedQuestionTypes = {},
                scoreBreakdown = {},
                selection = {
                    talent = "keen_senses",
                    sense = sense,
                    question = question,
                },
            })
            noInfo.keenSensesLore = true
            noInfo.effects[#noInfo.effects + 1] = "keen_senses_no_new_information"
            return noInfo
        end

        local bidLoreResult = {
            verdict = "accepted",
            reason = "Keen Senses supplies a momentary heightened sense.",
            loreSpend = true,
            keenSensesLore = true,
            response = {
                summary = tostring(answer),
                details = { tostring(answer) },
                implication = "The sharpened sense lasts only a moment.",
                sourceRefs = { "talent:keen_senses" },
            },
            scoreBreakdown = {
                talent = "keen_senses",
                sense = sense,
            },
            selection = {
                talent = "keen_senses",
                sense = sense,
                question = question,
            },
        }

        local result = self:resolveBidLoreOutcome(action, bidLoreResult)
        result.keenSensesLore = true
        result.keenSense = {
            sense = sense,
            question = question,
            answer = answer,
            expires = "momentary",
        }
        result.effects[#result.effects + 1] = "keen_senses_lore"
        result.effects[#result.effects + 1] = "keen_senses_momentary"
        result.effects[#result.effects + 1] = "keen_senses_" .. sense
        if actor then
            actor.keenSenseQuestions = actor.keenSenseQuestions or {}
            actor.keenSenseQuestions[#actor.keenSenseQuestions + 1] = result.keenSense
        end
        return result
    end

    function resolver:resolveAkashicConsciousness(request)
        request = request or {}
        local actor = request.actor or request.entity

        if not entityHasUsableTalent(actor, "akashic_consciousness") then
            return {
                success = false,
                akashicConsciousness = true,
                effects = { "akashic_consciousness_blocked" },
                description = "Requires Akashic Consciousness.",
            }
        end

        local question = request.question or request.pastQuestion or request.eventQuestion
        if not question or question == "" then
            return {
                success = false,
                akashicConsciousness = true,
                effects = { "akashic_consciousness_rephrase_needed" },
                description = "Akashic Consciousness requires a question about a past event.",
            }
        end

        local answer = firstNonNil(request.answer, request.ancestralAnswer, request.response, request.summary)
        if request.ancestorCouldKnow == false or request.possible == false or answer == nil or answer == "" then
            return {
                success = false,
                akashicConsciousness = true,
                effects = { "akashic_consciousness_unavailable" },
                description = "No ancestor or past incarnation could answer that question.",
            }
        end

        local spent, spendReason = self:spendResolveAmount(actor, 1)
        if not spent then
            return {
                success = false,
                akashicConsciousness = true,
                effects = { "resolve_missing", "akashic_consciousness_blocked" },
                description = "Cannot spend Resolve for Akashic Consciousness: " ..
                    (spendReason or "resolve unavailable") .. ".",
            }
        end

        local record = {
            question = question,
            answer = answer,
            source = request.source or "ancestor",
            subject = request.subject,
        }
        if actor then
            actor.ancestralMemories = actor.ancestralMemories or {}
            actor.ancestralMemories[#actor.ancestralMemories + 1] = record
        end

        return {
            success = true,
            akashicConsciousness = true,
            memory = record,
            effects = { "akashic_consciousness", "resolve_spent_for_akashic" },
            description = "Akashic Consciousness answers the past question.",
        }
    end

    function resolver:resolveSpoutDoom(request)
        request = request or {}
        local actor = request.actor or request.entity

        if not entityHasUsableTalent(actor, "spout_doom") then
            return {
                success = false,
                spoutDoom = true,
                effects = { "spout_doom_blocked" },
                description = "Requires Spout Doom.",
            }
        end

        local ifAction = request.ifAction or request.actionDescription or request.doing or request.x
        if not ifAction or ifAction == "" then
            return {
                success = false,
                spoutDoom = true,
                effects = { "spout_doom_rephrase_needed" },
                description = "Spout Doom needs an 'If I do X, what will happen?' question.",
            }
        end

        local prophecy = firstNonNil(request.prophecy, request.answer, request.response, request.summary)
        if prophecy == nil or prophecy == "" then
            return {
                success = false,
                spoutDoom = true,
                effects = { "spout_doom_no_prophecy" },
                description = "No prophecy is available for that action.",
            }
        end

        local spent, spendReason = self:spendResolveAmount(actor, 1)
        if not spent then
            return {
                success = false,
                spoutDoom = true,
                effects = { "resolve_missing", "spout_doom_blocked" },
                description = "Cannot spend Resolve for Spout Doom: " ..
                    (spendReason or "resolve unavailable") .. ".",
            }
        end

        local record = {
            ifAction = ifAction,
            prophecy = prophecy,
            poursUnbidden = true,
        }
        if actor then
            actor.spoutedDooms = actor.spoutedDooms or {}
            actor.spoutedDooms[#actor.spoutedDooms + 1] = record
        end

        return {
            success = true,
            spoutDoom = true,
            prophecy = record,
            effects = { "spout_doom", "resolve_spent_for_spout_doom" },
            description = "Spout Doom provides a prophecy.",
        }
    end

    function resolver:resolveAreaSense(request)
        request = request or {}
        local actor = request.actor or request.entity

        if not entityHasUsableTalent(actor, "area_sense") then
            return {
                success = false,
                areaSense = true,
                effects = { "area_sense_blocked" },
                description = "Requires Area Sense.",
            }
        end

        local card = request.card or request.drawnCard or request.visionCard
        if not card then
            local deck = request.deck or request.playerDeck or self.playerDeck
            if deck and deck.draw then
                card = deck:draw()
            end
        end
        local cardValue = tonumber(request.cardValue or request.value or (card and card.value)) or 0
        if cardValue <= 0 then
            return {
                success = false,
                areaSense = true,
                effects = { "area_sense_requires_card" },
                description = "Area Sense requires a drawn card value.",
            }
        end

        local spent, spendReason = self:spendResolveAmount(actor, 2)
        if not spent then
            return {
                success = false,
                areaSense = true,
                effects = { "resolve_missing", "area_sense_blocked" },
                description = "Cannot spend 2 Resolve for Area Sense: " ..
                    (spendReason or "resolve unavailable") .. ".",
            }
        end

        local visions = request.visions or request.visionDetails or request.details or {}
        if type(visions) == "string" then
            visions = { visions }
        end
        local record = {
            card = card,
            cardValue = cardValue,
            visions = visions,
            visionCount = cardValue,
            duration = "watch",
            meatgrinderAfterVisions = true,
        }
        if actor then
            actor.areaSenseVisions = actor.areaSenseVisions or {}
            actor.areaSenseVisions[#actor.areaSenseVisions + 1] = record
        end

        return {
            success = true,
            areaSense = true,
            areaSenseVisions = record,
            card = card,
            visionCount = cardValue,
            effects = { "area_sense", "resolve_spent_for_area_sense", "area_sense_watch_meditation" },
            description = "Area Sense reveals " .. tostring(cardValue) .. " vision(s).",
        }
    end

    local function normalizeDefenseChoice(value)
        if value == true then
            return "dodge"
        end
        if type(value) ~= "string" then
            return nil
        end

        local normalized = value:lower():gsub("%s+", "_")
        if normalized == "dodge" or normalized == "riposte" then
            return normalized
        end
        return nil
    end

    function resolver:getGuardianAngelDefenseType(action, target)
        action = action or {}
        local angel = target and target.guardianAngel
        local choice = action.guardianAngelDefenseType or action.useGuardianAngelAs or action.guardianAngelUse
        if not choice and angel and angel.autoUse then
            choice = angel.defenseType or angel.autoUse
        end
        return normalizeDefenseChoice(choice)
    end

    function resolver:consumeGuardianAngelDefense(target, defenseType)
        defenseType = normalizeDefenseChoice(defenseType)
        local angel = target and target.guardianAngel
        if not target or not angel or angel.used or not defenseType then
            return nil
        end

        angel.used = true
        angel.usedAs = defenseType
        target.guardianAngel = nil
        target.guardianAngelCard = nil
        if target.conditions then
            target.conditions.guardianAngel = false
        end

        target.usedGuardianAngels = target.usedGuardianAngels or {}
        target.usedGuardianAngels[#target.usedGuardianAngels + 1] = angel

        self.eventBus:emit("guardian_angel_used", {
            target = target,
            angel = angel,
            defenseType = defenseType,
        })

        return {
            type = defenseType,
            card = angel.card,
            value = angel.value or (angel.card and angel.card.value) or 0,
            guardianAngel = angel,
            source = "guardian_angel",
        }
    end

    function resolver:isDefeatedForDefense(entity)
        return entity and entity.conditions and (entity.conditions.dead or entity.conditions.deaths_door)
    end

    function resolver:getDefenseCandidates(action)
        if action and type(action.allEntities) == "table" then
            return action.allEntities
        end

        local controller = action and action.challengeController or self.challengeController
        if controller and type(controller.allCombatants) == "table" then
            return controller.allCombatants
        end

        return {}
    end

    function resolver:consumeAllyDefense(action, target, result)
        if not target then
            return nil
        end

        for _, candidate in ipairs(self:getDefenseCandidates(action)) do
            if candidate ~= target and candidate.isPC == target.isPC and
                candidate.zone == target.zone and
                not self:isDefeatedForDefense(candidate) and
                candidate.hasDefense and candidate:hasDefense() and candidate.consumeDefense then
                local defense = candidate:consumeDefense()
                if defense then
                    defense.source = "ally"
                    defense.defender = candidate
                    defense.protectedTarget = target
                    self:discardConsumedDefenseCard(action, candidate, defense, result)
                    return defense
                end
            end
        end

        return nil
    end

    function resolver:consumeIncomingDefense(action, target, result)
        if not target then
            return nil
        end

        local vampireDefense = self:consumeVampireGraceDefense(action, target)
        if vampireDefense then
            return vampireDefense
        end

        local guardianType = self:getGuardianAngelDefenseType(action, target)
        local pending = nil
        if target.hasDefense and target:hasDefense() then
            pending = target:getDefense()
        end

        if guardianType then
            local angelDefense = self:consumeGuardianAngelDefense(target, guardianType)
            if angelDefense then
                if pending and pending.type == guardianType then
                    local prepared = target:consumeDefense()
                    angelDefense.preparedDefense = prepared
                    angelDefense.value = (angelDefense.value or 0) + (prepared and prepared.value or 0)
                    angelDefense.cards = { prepared and prepared.card, angelDefense.card }
                    angelDefense.combined = true
                    self:discardConsumedDefenseCard(action, target, angelDefense, result)
                end
                return angelDefense
            end
        end

        if pending and target.consumeDefense then
            local defense = target:consumeDefense()
            self:discardConsumedDefenseCard(action, target, defense, result)
            return defense
        end

        local allyDefense = self:consumeAllyDefense(action, target, result)
        if allyDefense then
            return allyDefense
        end

        return nil
    end

    function resolver:resolveInitiativeContest(action, result, options)
        options = options or {}
        local target = action.target

        if not target then
            result.success = false
            result.description = "No target!"
            return { success = false }
        end

        local giantsStrengthContest = self:resolveGiantsStrengthContest(action, result)
        if giantsStrengthContest then
            return giantsStrengthContest
        end

        local attackValue = result.testValue
        local baseInitiative = self:getTargetInitiative(target, action) or result.difficulty
        local tieWins = options.tieWins or false
        local considerShield = options.considerShield or false
        local defenderHasShield = considerShield and self:entityHasShield(target) or false

        local riposteTriggered = false
        local riposteDefense = nil

        local defense = self:consumeIncomingDefense(action, target, result)
        if defense then
            if defense.guardianAngel then
                result.effects[#result.effects + 1] = "guardian_angel_used"
            end
            if defense.source == "ally" then
                result.effects[#result.effects + 1] = "ally_defense_used"
            end
            if defense.type == "dodge" then
                local dodgeValue = defense.value or 0
                local newInitiative = baseInitiative + dodgeValue
                result.effects[#result.effects + 1] = "dodge_used"

                if newInitiative > attackValue then
                    result.success = false
                    result.description = "Dodged! "
                    result.effects[#result.effects + 1] = "dodged"
                    return {
                        success = false,
                        dodged = true,
                        attackValue = attackValue,
                        baseInitiative = baseInitiative,
                    }
                else
                    result.effects[#result.effects + 1] = "dodge_failed"
                end
            elseif defense.type == "riposte" then
                local handled, stopped = self:resolvePolearmRiposteInterrupt(action, result, defense, attackValue, target)
                if stopped then
                    return {
                        success = false,
                        interrupted = true,
                        attackValue = attackValue,
                        baseInitiative = baseInitiative,
                        riposteResult = result.riposteResult,
                    }
                end
                if not handled then
                    riposteTriggered = true
                    riposteDefense = defense
                    result.effects[#result.effects + 1] = "riposte_ready"
                end
            end
        end

        result.success = (attackValue > baseInitiative) or
                         (tieWins and attackValue == baseInitiative and not defenderHasShield)
        result.difficulty = baseInitiative

        return {
            success = result.success,
            attackValue = attackValue,
            baseInitiative = baseInitiative,
            riposteTriggered = riposteTriggered,
            riposteDefense = riposteDefense,
        }
    end

    function resolver:resolveGiantsStrengthContest(action, result)
        local actor = action and action.actor
        local target = action and action.target
        if not actor or not target then
            return nil
        end
        if not (entityHasUsableTalent(actor, "giants_strength") or entityHasUsableTalent(actor, "giant_strength")) then
            return nil
        end
        if not actionHasRawStrengthContext(action) then
            return nil
        end
        if not entityIsNonTrollKin(action, target) then
            return nil
        end

        local baseInitiative = self:getTargetInitiative(target, action) or result.difficulty
        result.success = true
        result.difficulty = baseInitiative
        result.giantsStrengthAutoWin = true
        result.effects[#result.effects + 1] = "giants_strength_auto_win"
        result.effects[#result.effects + 1] = "talent_giants_strength"

        self.eventBus:emit("giants_strength_contest_won", {
            actor = actor,
            target = target,
            action = action,
        })

        return {
            success = true,
            giantsStrength = true,
            attackValue = result.testValue,
            baseInitiative = baseInitiative,
            riposteTriggered = false,
            riposteDefense = nil,
        }
    end

    function resolver:getActionRound(action)
        if action and action.round then
            return action.round
        end
        local controller = (action and action.challengeController) or self.challengeController
        return controller and controller.currentRound or nil
    end

    function resolver:markPetrifiedByCockatriceGaze(target, action)
        target.conditions = target.conditions or {}
        target.conditions.petrified = true
        target.conditions.petrification = true
        target.petrified = true
        target.curseOfPetrification = true
        target.petrificationCurse = true
        target.material = "stone"

        target.nonRecoverableConditions = target.nonRecoverableConditions or {}
        target.nonRecoverableConditions.petrified = "cockatrice_gaze"
        target.nonRecoverableConditions.petrification = "cockatrice_gaze"

        local source = action and action.actor
        local malediction = {
            active = true,
            curseId = "petrification",
            curseName = "Petrification",
            petrification = true,
            source = "cockatrice_gaze",
            sourceId = source and source.id or nil,
            sourceName = source and source.name or nil,
            curse = {
                id = "petrification",
                name = "Petrification",
            },
        }
        target.petrificationMalediction = malediction
        target.maledictions = target.maledictions or {}
        target.maledictions.petrification = malediction
        if type(target.malediction) ~= "table" or not target.malediction.active or
           target.malediction.curseId == "petrification" or
           (target.malediction.curse and target.malediction.curse.id == "petrification") then
            target.malediction = malediction
        end

        if target.cockatriceGazeRooted or target.rootedBy == "cockatrice_gaze" then
            target.conditions.rooted = false
            target.cockatriceGazeRooted = false
            if target.rootedBy == "cockatrice_gaze" then
                target.rootedBy = nil
            end
        end
    end

    function resolver:isCockatrice(entity)
        return entity and (entity.cockatrice ~= nil or entityHasNormalizedTag(entity, "cockatrice"))
    end

    function resolver:cockatriceGreaterDoomReady(action, effectType, doomId)
        local doom = action and (action.greaterDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            (doomId and doom and doom.id == doomId) or (effect and effect.type == effectType))
    end

    function resolver:applyCockatriceTailBite(action, result, target, effect, doom)
        local actor = action and action.actor
        if not (self:isCockatrice(actor) and target) then
            return false
        end

        result.damageDealt = math.max(result.damageDealt or 0, effect.wounds or 1)
        result.effects[#result.effects + 1] = "cockatrice_tail_bite"
        result.effects[#result.effects + 1] = "displaced"

        local oldZone = target.zone
        local destZone = action.displaceToZone or action.destinationZone or action.targetDestinationZone
        if destZone then
            if self.zoneSystem and target.id then
                self.zoneSystem:placeEntity(target.id, destZone)
            end
            target.zone = destZone
            result.displacedToZone = destZone
            self.eventBus:emit("entity_zone_changed", {
                entity = target,
                oldZone = oldZone,
                newZone = destZone,
                reason = "cockatrice_tail_bite",
            })
        end

        self:clearAllEngagements(target, action.allEntities)
        result.description = result.description .. (doom and doom.name or "Tail Bite") ..
            " displaces the target. "
        return true
    end

    function resolver:resolveCockatriceFlutter(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local targetZone = action.destinationZone
        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect or {}

        if not self:isCockatrice(actor) then
            result.success = false
            result.description = "Flutter requires a cockatrice."
            result.effects[#result.effects + 1] = "cockatrice_flutter_blocked"
            return result
        end
        if not self:cockatriceGreaterDoomReady(action, "disengage_and_move", "flutter") then
            result.success = false
            result.description = "Cockatrice Flutter requires a greater doom."
            result.effects[#result.effects + 1] = "cockatrice_flutter_requires_greater_doom"
            return result
        end
        if not targetZone then
            result.success = false
            result.description = "Cockatrice Flutter needs a destination zone."
            result.effects[#result.effects + 1] = "cockatrice_flutter_missing_destination"
            return result
        end

        self:clearAllEngagements(actor, action.allEntities)
        action.maxMoveDistance = math.min(action.maxMoveDistance or effect.moveZones or 1, effect.moveZones or 1)
        self:resolveMove(action, result, action.allEntities)

        if result.success then
            actor.conditions = actor.conditions or {}
            actor.conditions.flying = effect.flying ~= false
            actor.flying = effect.flying ~= false
            result.automatic = true
            result.effects[#result.effects + 1] = "cockatrice_flutter"
            result.effects[#result.effects + 1] = "greater_doom"
            result.effects[#result.effects + 1] = "disengaged"
            if actor.flying then
                result.effects[#result.effects + 1] = "flying"
            end
            result.greaterDoom = {
                name = doom and doom.name or "Flutter",
                card = action.greaterDoomCard,
            }
            result.description = (actor.name or "Cockatrice") .. " flutters away to " .. tostring(targetZone) .. "."
        end

        action.result = result
        return result
    end

    function resolver:resolveCreatureGaze(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target

        if not actor then
            result.success = false
            result.description = "No actor for creature gaze."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not target then
            result.success = false
            result.description = "No target for creature gaze."
            result.effects[#result.effects + 1] = "missing_target"
            return result
        end

        local gaze = action.gaze or (actor.cockatrice and actor.cockatrice.gaze)
        local isCockatrice = action.type == M.ACTION_TYPES.COCKATRICE_GAZE or
            entityHasNormalizedTag(actor, "cockatrice") or (actor.cockatrice and actor.cockatrice.gaze)
        if not isCockatrice or not gaze then
            result.success = false
            result.description = "Creature gaze is not defined."
            result.effects[#result.effects + 1] = "creature_gaze_missing"
            return result
        end

        local round = self:getActionRound(action)
        if gaze.oncePerRound and round and actor.cockatriceGazeUsedRound == round then
            result.success = false
            result.description = "Cockatrice gaze already used this round."
            result.effects[#result.effects + 1] = "cockatrice_gaze_round_spent"
            return result
        end
        if gaze.oncePerRound and round then
            actor.cockatriceGazeUsedRound = round
        end

        result.success = true
        result.automatic = true
        result.cardValue = 0
        result.testValue = 0
        result.difficulty = 0
        result.gaze = gaze
        result.effects[#result.effects + 1] = "creature_gaze"
        result.effects[#result.effects + 1] = "cockatrice_gaze"

        if action.reflectedByMirror or action.mirrorReflection then
            result.effects[#result.effects + 1] = "cockatrice_gaze_not_reflected_by_mirror"
        end

        target.conditions = target.conditions or {}
        if target.conditions.rooted then
            self:markPetrifiedByCockatriceGaze(target, action)
            result.effects[#result.effects + 1] = "cockatrice_gaze_petrified"
            result.effects[#result.effects + 1] = "petrification_curse"
            result.effects[#result.effects + 1] = "condition_petrified"
            result.description = (target.name or "Target") .. " is turned to stone by the Cockatrice's gaze."
        else
            self:applyRooted(target, { action = action, reason = "cockatrice_gaze" })
            target.cockatriceGazeRooted = true
            target.cockatriceGazeSource = actor.id or actor.name
            target.cockatriceGazeRound = round
            target.rootedBy = "cockatrice_gaze"
            result.effects[#result.effects + 1] = "cockatrice_gaze_rooted"
            result.effects[#result.effects + 1] = "rooted"
            result.description = (target.name or "Target") .. " is Rooted by the Cockatrice's gaze."
        end

        self.eventBus:emit("creature_gaze_resolved", {
            actor = actor,
            target = target,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:requiresGreaterDoomForGriffinGrab(action)
        if not action then
            return true
        end
        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect
        if effect and effect.type == "roughhouse_grab" then
            return false
        end
        return not (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            action.griffinGrabGreaterDoom == true)
    end

    function resolver:isGriffinGrabRoughhouse(action, effect)
        if effect == "grab" or effect == "griffin_grab" then
            return true
        end
        if action and (action.griffinGrab == true or action.grab == true) then
            return true
        end
        local doom = action and (action.greaterDoom or action.doom)
        local doomEffect = doom and doom.effect
        return doomEffect and doomEffect.type == "roughhouse_grab"
    end

    function resolver:isBadLittleHandsRoughhouse(action, effect)
        if effect ~= "steal_belt_item" then
            return false
        end
        if not action then
            return false
        end
        if action.badLittleHands == true or action.stealBeltItem == true then
            return true
        end

        local doom = action.lesserDoom or action.doom
        local doomEffect = doom and doom.effect
        if doomEffect and doomEffect.type == "roughhouse_steal_belt_item" then
            return true
        end

        return entityHasNormalizedTag(action.actor, "face_rat")
    end

    function resolver:getBadLittleHandsTargetItem(action)
        local target = action and action.target
        local inv = target and target.inventory
        if not inv or not inv.getItems then
            return nil, nil, "missing_inventory"
        end

        if action.itemId and inv.findItem then
            local item, location = inv:findItem(action.itemId)
            if item and location == inventory.LOCATIONS.BELT then
                return item, location, nil
            end
            return nil, location, "selected_item_not_on_belt"
        end

        if action.item and action.item.id and inv.findItem then
            local item, location = inv:findItem(action.item.id)
            if item and location == inventory.LOCATIONS.BELT then
                return item, location, nil
            end
            return nil, location, "selected_item_not_on_belt"
        end

        local beltItems = inv:getItems(inventory.LOCATIONS.BELT) or {}
        return beltItems[1], inventory.LOCATIONS.BELT, nil
    end

    function resolver:recordBadLittleHandsItem(faceRat, owner, item, location, action)
        faceRat.badLittleHands = faceRat.badLittleHands or {}
        faceRat.stolenItems = faceRat.stolenItems or {}

        local record = {
            item = item,
            from = owner,
            fromId = owner and owner.id or nil,
            fromName = owner and owner.name or nil,
            location = location or inventory.LOCATIONS.BELT,
            retrieveBy = { "disarm", "kill" },
            reason = "bad_little_hands",
            action = action,
        }

        faceRat.badLittleHands[#faceRat.badLittleHands + 1] = item
        faceRat.stolenItems[#faceRat.stolenItems + 1] = record

        item.stolenBy = faceRat.id
        item.stolenByName = faceRat.name
        item.stolenFrom = owner and owner.id or nil
        item.stolenFromName = owner and owner.name or nil
        item.heldInBadLittleHands = true

        return record
    end

    function resolver:peekBadLittleHandsItem(faceRat)
        if not faceRat then
            return nil, nil
        end
        if faceRat.stolenItems and #faceRat.stolenItems > 0 then
            local record = faceRat.stolenItems[1]
            return record.item, record
        end
        if faceRat.badLittleHands and #faceRat.badLittleHands > 0 then
            local item = faceRat.badLittleHands[1]
            return item, { item = item, location = inventory.LOCATIONS.BELT }
        end
        return nil, nil
    end

    function resolver:popBadLittleHandsItem(faceRat)
        if not faceRat then
            return nil, nil
        end

        local record = nil
        local item = nil
        if faceRat.stolenItems and #faceRat.stolenItems > 0 then
            record = table.remove(faceRat.stolenItems, 1)
            item = record and record.item
        end
        if faceRat.badLittleHands and #faceRat.badLittleHands > 0 then
            if item and item.id then
                for i, held in ipairs(faceRat.badLittleHands) do
                    if held == item or held.id == item.id then
                        table.remove(faceRat.badLittleHands, i)
                        break
                    end
                end
            else
                item = table.remove(faceRat.badLittleHands, 1)
            end
        end

        if item and not record then
            record = { item = item, location = inventory.LOCATIONS.BELT }
        end

        return item, record
    end

    function resolver:clearBadLittleHandsItemMetadata(item)
        if not item then
            return
        end
        item.stolenBy = nil
        item.stolenByName = nil
        item.stolenFrom = nil
        item.stolenFromName = nil
        item.heldInBadLittleHands = nil
    end

    function resolver:returnBadLittleHandsItem(faceRat, item, record, reason)
        local owner = record and record.from or nil
        local recovered = {
            item = item,
            owner = owner,
            ownerId = record and record.fromId or nil,
            reason = reason or "bad_little_hands_recovered",
            returned = false,
        }

        self:clearBadLittleHandsItemMetadata(item)

        if owner and owner.inventory and owner.inventory.addItem then
            local tried = {}
            local function tryLocation(location)
                if not location or tried[location] then
                    return false
                end
                tried[location] = true
                local ok, addReason = owner.inventory:addItem(item, location)
                if ok then
                    recovered.returned = true
                    recovered.location = location
                    return true
                end
                recovered.error = addReason
                return false
            end

            tryLocation(record and record.location)
            if not recovered.returned then
                tryLocation(inventory.LOCATIONS.BELT)
            end
            if not recovered.returned then
                tryLocation(inventory.LOCATIONS.PACK)
            end
            if not recovered.returned then
                tryLocation(inventory.LOCATIONS.HANDS)
            end
        end

        if not recovered.returned and faceRat then
            faceRat.droppedItems = faceRat.droppedItems or {}
            faceRat.droppedItems[#faceRat.droppedItems + 1] = item
            recovered.dropped = true
        end

        self.eventBus:emit(events.EVENTS.INVENTORY_CHANGED, {
            entity = owner or faceRat,
            item = item,
            reason = reason or "bad_little_hands_recovered",
            source = faceRat,
            recovery = recovered,
        })

        return recovered
    end

    function resolver:releaseBadLittleHandsItem(faceRat, reason)
        local item, record = self:popBadLittleHandsItem(faceRat)
        if not item then
            return nil
        end
        return self:returnBadLittleHandsItem(faceRat, item, record, reason)
    end

    function resolver:releaseAllBadLittleHandsItems(faceRat, reason)
        local released = {}
        while self:peekBadLittleHandsItem(faceRat) do
            local recovery = self:releaseBadLittleHandsItem(faceRat, reason)
            if not recovery then
                break
            end
            released[#released + 1] = recovery
        end
        return released
    end

    function resolver:releaseGriffinGrab(griffin, victim, reason)
        griffin = griffin or (victim and victim.griffinGrabbedBy)
        victim = victim or (griffin and griffin.grabbedVictim)
        if not victim then
            return nil
        end

        if victim.conditions and (victim.griffinGrabbedBy or victim.rootedBy == "griffin_grab") then
            victim.conditions.rooted = false
        end
        victim.griffinGrabbedBy = nil
        victim.griffinGrabbedById = nil
        victim.griffinGrabbedByName = nil
        victim.griffinGrabMovesWith = nil
        victim.griffinGrabRecoverCausesFallingDamage = nil
        victim.griffinGrabFallHeightFeet = nil
        if victim.rootedBy == "griffin_grab" then
            victim.rootedBy = nil
        end

        if griffin then
            griffin.grabbedVictim = nil
            griffin.griffinGrab = nil
        end

        return {
            victim = victim,
            griffin = griffin,
            reason = reason or "released",
        }
    end

    function resolver:applyGriffinGrabMove(actor, oldZone, newZone, action, result)
        local grab = actor and actor.griffinGrab
        local victim = grab and grab.victim
        if not victim or not grab.targetMovesWithActor or not newZone then
            return nil
        end

        local victimOldZone = victim.zone
        if self.zoneSystem and victim.id then
            self.zoneSystem:placeEntity(victim.id, newZone)
        end
        victim.zone = newZone
        result.griffinGrabMovedVictim = {
            victim = victim,
            oldZone = victimOldZone,
            newZone = newZone,
        }
        result.effects[#result.effects + 1] = "griffin_grab_victim_moved"

        self.eventBus:emit("entity_zone_changed", {
            entity = victim,
            oldZone = victimOldZone or oldZone,
            newZone = newZone,
            reason = "griffin_grab",
        })

        return victim
    end

    function resolver:redirectMissedAttackToGrabbedVictim(action, result, opts)
        opts = opts or {}
        local griffin = action and action.target
        local grab = griffin and griffin.griffinGrab
        local victim = grab and grab.victim
        if not victim or not grab.missedAttacksHitGrabbedVictim then
            return false
        end
        if victim.conditions and (victim.conditions.dead or victim.conditions.deaths_door) then
            return false
        end

        local damage = opts.damage or action.griffinGrabRedirectDamage or 1
        result.griffinGrabRedirect = {
            griffin = griffin,
            victim = victim,
            damage = damage,
        }
        result.effects[#result.effects + 1] = "miss_redirected_to_grabbed_victim"
        result.effects[#result.effects + 1] = "griffin_grab_victim_hit"
        result.description = (result.description or "Miss!") .. " The missed Attack hits the grabbed victim."

        if damage > 0 then
            self:applyDamage(victim, damage, result.effects, action.weapon, action.allEntities,
                self:getActionWoundOptions(action, victim), {
                    source = "griffin_grab_missed_attack",
                    action = action,
                    useAegis = action.useAegis,
                })
        end

        return true
    end

    function resolver:applyGriffinGrabFall(victim, action, result, reason)
        if not victim then
            return nil
        end

        local heightFeet = action and (action.heightFeet or action.roomHeightFeet or action.fallHeightFeet) or
            victim.griffinGrabFallHeightFeet or 0
        local fall = self:resolveFall(victim, heightFeet, {
            card = action and action.fallCard,
            testResult = action and action.fallTestResult,
            success = action and action.fallSuccess,
            greatSuccess = action and action.fallGreatSuccess,
            greatFailure = action and action.fallGreatFailure,
            allEntities = action and action.allEntities,
            woundOptions = action and action.fallWoundOptions,
            promptAcrobatFallChoice = action and action.promptAcrobatFallChoice,
            requestAcrobatFallChoice = action and action.requestAcrobatFallChoice,
            spendResolveForAcrobat = action and (action.spendResolveForAcrobat or
                action.spendResolveForAcrobatFall),
            declineAcrobatFallReduction = action and (action.declineAcrobatFallReduction or
                action.skipAcrobatFallReduction or action.acrobatFallDeclined),
            fallContext = {
                action = action,
                reason = reason,
            },
        })
        result.griffinGrabFall = fall
        if fall.pendingAcrobatFallChoice then
            result.pendingAcrobatFallChoice = true
            result.acrobatFallChoice = fall.acrobatFallChoice
            action.pendingAcrobatFallChoice = fall.acrobatFallChoice
        end
        result.effects[#result.effects + 1] = "griffin_grab_fall"
        for _, effect in ipairs(fall.effects or {}) do
            result.effects[#result.effects + 1] = effect
        end
        result.description = (result.description or "") .. " " .. (fall.description or "Victim falls.")
        return fall
    end

    function resolver:resolveGriffinDrop(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local grab = actor and actor.griffinGrab
        local victim = action.target or (grab and grab.victim)

        if not actor or not victim or not grab then
            result.success = false
            result.description = "No grabbed victim to drop."
            result.effects[#result.effects + 1] = "griffin_drop_blocked"
            return result
        end

        local causesFall = action.causesFallingDamage ~= false and
            (action.heightFeet or action.roomHeightFeet or action.fallHeightFeet or grab.flying or actor.flying)
        if not action.heightFeet and not action.roomHeightFeet and not action.fallHeightFeet and grab.heightFeet then
            action.heightFeet = grab.heightFeet
        end
        self:releaseGriffinGrab(actor, victim, "griffin_drop")

        result.success = true
        result.effects[#result.effects + 1] = "griffin_drop"
        result.effects[#result.effects + 1] = "griffin_grab_released"
        result.description = (actor.name or "Griffin") .. " drops " .. (victim.name or "the victim") .. "."

        if causesFall then
            self:applyGriffinGrabFall(victim, action, result, "griffin_drop")
        end

        action.result = result
        return result
    end

    function resolver:isBloodybones(entity)
        return entity and (entity.bloodybones ~= nil or entityHasNormalizedTag(entity, "bloodybones"))
    end

    function resolver:resolveBloodybonesImmuneDamage(entity, amount, effects, weapon, damageContext)
        if not self:isBloodybones(entity) or not amount or amount <= 0 then
            return nil
        end

        effects[#effects + 1] = "bloodybones_immune_to_damage"
        effects[#effects + 1] = "infinite_health"
        effects[#effects + 1] = "never_takes_wounds"

        self.eventBus:emit("bloodybones_immune_to_damage", {
            entity = entity,
            amount = amount,
            weapon = weapon,
            source = damageContext and damageContext.source,
        })

        return {
            result = "invulnerable",
            immune = true,
            reason = "bloodybones_immune_to_damage",
            amountPrevented = amount,
        }
    end

    function resolver:getBloodybonesSmelledMagic(actor, subjects)
        if not self:isBloodybones(actor) then
            return {}
        end
        return getMagicScentSubjects(subjects)
    end

    function resolver:isSorcerous(entity)
        return entity and (entity.sorcerous == true or type(entity.sorcerous) == "table" or
            entityHasNormalizedTag(entity, "sorcerous"))
    end

    function resolver:getSorcerousSmelledMagic(actor, subjects)
        if not self:isSorcerous(actor) then
            return {}
        end
        return getMagicScentSubjects(subjects)
    end

    function resolver:getSorcerousStrangeBody(entity)
        if not self:isSorcerous(entity) then
            return nil
        end

        local sorcerous = type(entity.sorcerous) == "table" and entity.sorcerous or {}
        local strange = sorcerous.strangeBody or entity.strangeBody or entity.sorcerousStrangeBody
        if strange == true then
            strange = {}
        end
        if type(strange) ~= "table" then
            return nil
        end

        return strange
    end

    function resolver:getSorcerousStrangeBodyDamageTokens(effects, weapon, damageContext)
        local tokens = self:getDamageElementTokens(effects, weapon, damageContext)
        damageContext = damageContext or {}
        local action = damageContext.action or {}

        appendNormalizedKeys(tokens, damageContext.harmType)
        appendNormalizedKeys(tokens, action.harmType)
        appendNormalizedKeys(tokens, weapon and weapon.weaponType)
        appendNormalizedKeys(tokens, weapon and weapon.type)
        appendNormalizedKeys(tokens, weapon and weapon.damageType)

        if weapon then
            tokens[#tokens + 1] = "weapon"
            tokens[#tokens + 1] = "weapons"
            if M.isWeaponType(weapon, "HAMMER") or M.isWeaponType(weapon, "FLAIL") then
                tokens[#tokens + 1] = "blunt_force_trauma"
                tokens[#tokens + 1] = "bludgeoning"
                tokens[#tokens + 1] = "smashing"
            end
        end

        return tokens
    end

    function resolver:getSorcerousStrangeBodySet(strange, fieldNames)
        local set = {}
        local function add(value)
            local normalized = normalizeTalentKey(value)
            if normalized ~= "" and normalized ~= "varies" and normalized ~= "variable" then
                set[normalized] = true
            end
        end
        local function addMany(value)
            if type(value) == "string" or type(value) == "number" then
                add(value)
                return
            end
            if type(value) ~= "table" then
                return
            end
            for key, item in pairs(value) do
                if item == true then
                    add(key)
                elseif type(item) == "string" or type(item) == "number" then
                    add(item)
                elseif type(item) == "table" then
                    add(item.id or item.name or item.element or item.type or item.damageType)
                end
            end
        end

        for _, fieldName in ipairs(fieldNames or {}) do
            addMany(strange and strange[fieldName])
        end

        return next(set) and set or nil
    end

    function resolver:getSorcerousStrangeBodyToken(entity, effects, weapon, damageContext, fieldNames)
        local strange = self:getSorcerousStrangeBody(entity)
        local set = self:getSorcerousStrangeBodySet(strange, fieldNames)
        if not set then
            return nil
        end

        for _, token in ipairs(self:getSorcerousStrangeBodyDamageTokens(effects, weapon, damageContext)) do
            if set[token] then
                return token, strange
            end
        end

        return nil, strange
    end

    function resolver:resolveSorcerousStrangeBodyDamage(entity, amount, effects, weapon, damageContext)
        if (amount or 0) <= 0 then
            return nil
        end

        local vulnerableToken = self:getSorcerousStrangeBodyToken(entity, effects, weapon, damageContext, {
            "vulnerableTo",
            "vulnerability",
            "vulnerabilities",
            "takesTwoWoundsFrom",
        })
        if vulnerableToken then
            return nil
        end

        local immuneToken = self:getSorcerousStrangeBodyToken(entity, effects, weapon, damageContext, {
            "immuneTo",
            "immunity",
            "immunities",
            "invulnerableTo",
        })
        if not immuneToken then
            return nil
        end

        effects[#effects + 1] = "sorcerous_strange_body_immune"
        effects[#effects + 1] = "strange_body_immune_" .. immuneToken
        self.eventBus:emit("sorcerous_strange_body_immune", {
            entity = entity,
            token = immuneToken,
            weapon = weapon,
            damageContext = damageContext,
        })
        return {
            result = "immune",
            immune = true,
            reason = "sorcerous_strange_body",
            damageType = immuneToken,
            amountPrevented = amount,
        }
    end

    function resolver:applySorcerousStrangeBodyVulnerability(entity, amount, effects, weapon, damageContext)
        if (amount or 0) <= 0 then
            return amount
        end

        local token = self:getSorcerousStrangeBodyToken(entity, effects, weapon, damageContext, {
            "vulnerableTo",
            "vulnerability",
            "vulnerabilities",
            "takesTwoWoundsFrom",
        })
        if not token then
            return amount
        end

        local boosted = math.max(amount or 0, 2)
        effects[#effects + 1] = "sorcerous_strange_body_vulnerable"
        effects[#effects + 1] = "strange_body_vulnerable_" .. token
        if boosted > (amount or 0) then
            effects[#effects + 1] = "strange_body_damage_deals_two_wounds"
        end
        return boosted
    end

    function resolver:isBrainSpider(entity)
        return entity and (entity.brainSpider ~= nil or entityHasNormalizedTag(entity, "brain_spider"))
    end

    function resolver:getBrainSpiderLesserDoomEffect(action, effectType)
        if not (action and self:isBrainSpider(action.actor)) then
            return nil, nil
        end
        local doom = action.lesserDoom or action.doom
        local effect = doom and doom.effect
        if effect and effect.type == effectType then
            return effect, doom
        end
        return nil, nil
    end

    function resolver:getBrainSpiderGreaterDoomEffect(action, effectType)
        if not (action and self:isBrainSpider(action.actor)) then
            return nil, nil
        end
        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect
        if effect and effect.type == effectType then
            return effect, doom
        end
        return nil, nil
    end

    function resolver:isBrainSpiderSquishyWeapon(weapon, effects, damageContext)
        damageContext = damageContext or {}
        local normalized = normalizeTalentKey(damageContext.weaponType or damageContext.damageType or "")
        if normalized == "bludgeoning" or normalized == "smashing" or normalized == "crushing" then
            return true
        end
        for _, effect in ipairs(effects or {}) do
            normalized = normalizeTalentKey(effect)
            if normalized == "bludgeoning" or normalized == "smashing" or normalized == "crushing" then
                return true
            end
        end

        local weaponType = normalizeTalentKey(weapon and (weapon.weaponType or weapon.type or weapon.name))
        local props = weapon and weapon.properties or {}
        return weaponType == "hammer" or weaponType == "mace" or weaponType == "club" or
            weaponType == "maul" or weaponType == "bludgeon" or props.bludgeoning == true or
            props.smashing == true or props.crushing == true
    end

    function resolver:resolveBrainSpiderSquishyDamage(entity, amount, effects, weapon, damageContext)
        if not (self:isBrainSpider(entity) and (amount or 0) > 0) then
            return nil
        end
        if not self:isBrainSpiderSquishyWeapon(weapon, effects, damageContext) then
            return nil
        end

        effects[#effects + 1] = "brain_spider_squishy_immune"
        effects[#effects + 1] = "bludgeoning_weapon_immune"
        self.eventBus:emit("brain_spider_squishy_immune", {
            entity = entity,
            weapon = weapon,
            damageContext = damageContext,
        })
        return {
            result = "immune",
            immune = true,
            reason = "brain_spider_squishy",
        }
    end

    function resolver:getBrainSpiderGreatLeap(action)
        local effect, doom = self:getBrainSpiderLesserDoomEffect(action, "dash_jump")
        if effect or (action and action.brainSpiderGreatLeap == true) then
            return effect or {
                moveZones = 2,
                clearsInterveningObstacles = true,
            }, doom
        end
        return nil, nil
    end

    function resolver:applyBrainSpiderGreatLeapResult(action, result, effect, doom)
        if not (result and result.success and effect) then
            return
        end

        result.brainSpiderGreatLeap = {
            moveZones = effect.moveZones or action.maxMoveDistance or 2,
            clearsInterveningObstacles = effect.clearsInterveningObstacles ~= false,
            obstacles = action.interveningObstacles or action.obstacles or {},
        }
        result.effects[#result.effects + 1] = "brain_spider_great_leap"
        if result.brainSpiderGreatLeap.clearsInterveningObstacles then
            result.effects[#result.effects + 1] = "clears_intervening_obstacles"
        end
        if doom then
            result.lesserDoom = {
                name = doom.name,
                id = doom.id,
            }
        end
    end

    function resolver:applyBrainSpiderWallCrawlingMove(action, result, destinationZone)
        local effect, doom = self:getBrainSpiderLesserDoomEffect(action, "wall_crawl")
        if not (effect or action.wallCrawling == true or action.wallCrawl == true) then
            return nil
        end

        local actor = action.actor
        actor.conditions = actor.conditions or {}
        actor.conditions.wall_crawling = true
        actor.wallCrawling = {
            zone = destinationZone,
            effortlessClimb = true,
            canLeaveArea = true,
        }

        result.brainSpiderWallCrawling = actor.wallCrawling
        result.effects[#result.effects + 1] = "brain_spider_wall_crawling"
        result.effects[#result.effects + 1] = "wall_crawling"
        if doom then
            result.lesserDoom = {
                name = doom.name,
                id = doom.id,
            }
        end

        if action.leaveArea ~= false and action.pursuerCanKeepUp ~= true then
            actor.leftArea = true
            actor.escapedByWallCrawling = true
            self:clearAllEngagements(actor, action.allEntities)
            result.escaped = true
            result.effects[#result.effects + 1] = "left_area"
            result.effects[#result.effects + 1] = "escaped_by_wall_crawling"
        end

        return actor.wallCrawling
    end

    function resolver:applyBrainSpiderTactics(action, result, actionType)
        local effect, doom = self:getBrainSpiderGreaterDoomEffect(action, "standard_action_as_interrupt")
        if not effect then
            return nil
        end

        action.isQuickInterrupt = true
        action.quickInterrupt = true
        result.quickInterrupt = true
        result.brainSpiderTactics = {
            actionType = actionType,
            doom = doom,
        }
        result.effects[#result.effects + 1] = "brain_spider_tactics"
        result.effects[#result.effects + 1] = "interrupt"
        result.effects[#result.effects + 1] = "standard_action_as_interrupt"
        return result.brainSpiderTactics
    end

    function resolver:getStrategistGreaterDoomEffect(action, effectType, doomId)
        local actor = action and action.actor
        if not self:isStrategist(actor) then
            return nil, nil
        end

        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect
        local matchesEffect = effect and effect.type == effectType
        local matchesId = doomId and doom and doom.id == doomId
        if not (matchesEffect or matchesId) then
            return nil, nil
        end

        if action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
           action.greaterDoomAsInterrupt == true or matchesEffect then
            return effect or {}, doom
        end

        return nil, nil
    end

    function resolver:applyStrategistTactics(action, result, actionType)
        local effect, doom = self:getStrategistGreaterDoomEffect(action, "standard_action_as_interrupt", "tactics")
        if not effect then
            return nil
        end

        action.isQuickInterrupt = true
        action.quickInterrupt = true
        result.quickInterrupt = true
        result.strategistTactics = {
            actionType = actionType,
            doom = doom,
        }
        result.effects[#result.effects + 1] = "strategist_tactics"
        result.effects[#result.effects + 1] = "interrupt"
        result.effects[#result.effects + 1] = "standard_action_as_interrupt"
        if self:isBrainSpider(action.actor) then
            result.brainSpiderTactics = result.strategistTactics
            result.effects[#result.effects + 1] = "brain_spider_tactics"
        end
        return result.strategistTactics
    end

    function resolver:isHarpy(entity)
        return entity and (entity.harpy ~= nil or entityHasNormalizedTag(entity, "harpy"))
    end

    function resolver:isHarpyOnTurn(action)
        return action and (action.onHarpyTurn == true or action.onTurn == true or
            action.isTurnAction == true or action.actorTurn == true)
    end

    function resolver:getHarpyLesserDoomEffect(action, effectType, doomId)
        local actor = action and action.actor
        if not self:isHarpy(actor) then
            return nil, nil
        end

        local doom = action.lesserDoom or action.doom
        local effect = doom and doom.effect
        if doomId and doom and doom.id == doomId then
            return effect or {}, doom
        end
        if effect and effect.type == effectType then
            return effect, doom
        end
        return nil, nil
    end

    function resolver:getHarpyFlightEffect(action)
        return self:getHarpyLesserDoomEffect(action, "fly_move", "flight")
    end

    function resolver:validateHarpyFlight(action, result)
        local effect = self:getHarpyFlightEffect(action)
        if not effect then
            return true
        end

        if effect.requiresEnoughSpace ~= false and
           (action.enoughSpace == false or action.hasEnoughSpace == false or action.roomHasEnoughSpace == false) then
            result.success = false
            result.description = "Harpy Flight requires enough space."
            result.effects[#result.effects + 1] = "harpy_flight_requires_space"
            return false
        end

        return true
    end

    function resolver:isHarpyFlying(entity)
        local conditions = entity and entity.conditions or {}
        return self:isHarpy(entity) and (entity.flying == true or conditions.flying == true or
            (entity.harpyFlight and entity.harpyFlight.active == true))
    end

    function resolver:isHarpyOutOfMeleeReach(entity)
        return self:isHarpyFlying(entity) and entity.harpyMeleeTargetableThisTurn ~= true
    end

    function resolver:isHarpyFlyByAttack(action)
        local actor = action and action.actor
        return self:isHarpyFlying(actor) and
            (action.flyByAttack == true or action.harpyFlyByAttack == true or action.flying == true)
    end

    function resolver:applyHarpyFlight(action, result, allEntities, effect, doom)
        local actor = action and action.actor
        if not self:isHarpy(actor) then
            return false
        end
        if not effect then
            effect, doom = self:getHarpyFlightEffect(action)
        end
        if not effect then
            return false
        end

        actor.conditions = actor.conditions or {}
        actor.conditions.flying = true
        actor.flying = true
        actor.harpyMeleeTargetableThisTurn = false
        actor.harpyFlight = {
            active = true,
            rangedWeaponsStillApply = effect.rangedWeaponsStillApply ~= false,
            flyByAttackAllowed = effect.flyByAttackAllowed ~= false,
            flyByAttackDoesNotCauseEngagement = actor.harpy and actor.harpy.flight and
                actor.harpy.flight.flyByAttackDoesNotCauseEngagement ~= false,
            doom = doom,
        }

        self:clearAllEngagements(actor, allEntities)
        result.effects[#result.effects + 1] = "harpy_flight"
        result.effects[#result.effects + 1] = "flying"
        result.effects[#result.effects + 1] = "harpy_out_of_melee_engagement"
        if effect.rangedWeaponsStillApply ~= false then
            result.effects[#result.effects + 1] = "ranged_weapons_still_apply"
        end
        return true
    end

    function resolver:resolveHarpyFlutterMove(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isHarpy(actor) then
            result.success = false
            result.description = "Flutter requires a harpy."
            result.effects[#result.effects + 1] = "harpy_flutter_blocked"
            return result
        end
        if not self:isHarpyOnTurn(action) then
            result.success = false
            result.description = "Harpy Flutter can only be used on the harpy's turn."
            result.effects[#result.effects + 1] = "harpy_flutter_requires_turn"
            return result
        end

        action.maxMoveDistance = math.min(action.maxMoveDistance or 1,
            actor.harpy and actor.harpy.flutterMoveZones or 1)
        self:resolveMove(action, result, action.allEntities)

        if result.success then
            result.cardless = true
            result.countsTowardTurnCard = false
            result.effects[#result.effects + 1] = "harpy_flutter"
            result.effects[#result.effects + 1] = "free_move_on_turn"
            result.description = (actor.name or "Harpy") .. " flutters one zone. " ..
                (result.description or "")
        end

        action.result = result
        return result
    end

    function resolver:resolveHarpyFlightMove(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local effect = self:getHarpyFlightEffect(action)

        if not self:isHarpy(actor) then
            result.success = false
            result.description = "Flight requires a harpy."
            result.effects[#result.effects + 1] = "harpy_flight_blocked"
            return result
        end
        if not effect then
            result.success = false
            result.description = "Harpy Flight requires its lesser doom."
            result.effects[#result.effects + 1] = "harpy_flight_requires_lesser_doom"
            return result
        end

        action.maxMoveDistance = math.min(action.maxMoveDistance or 1, 1)
        self:resolveMove(action, result, action.allEntities)
        if result.success then
            result.effects[#result.effects + 1] = "lesser_doom"
            result.description = (actor.name or "Harpy") .. " takes flight. " ..
                (result.description or "")
        end

        action.result = result
        return result
    end

    function resolver:resolveHarpyPeltWithStones(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isHarpy(actor) then
            result.success = false
            result.description = "Pelt with Stones requires a harpy."
            result.effects[#result.effects + 1] = "harpy_pelt_with_stones_blocked"
            return result
        end
        if not action.card then
            result.success = false
            result.description = "Pelt with Stones requires any card."
            result.effects[#result.effects + 1] = "harpy_pelt_with_stones_requires_card"
            return result
        end

        local sceneryName = action.sceneryName or "Thrown Scenery"
        actor.harpyPreparedStone = {
            id = "harpy_scenery_" .. tostring(actor.id or "stone"),
            name = sceneryName,
            weaponType = "thrown",
            type = "thrown",
            isWeapon = true,
            uses_ammo = false,
            harpySceneryStone = true,
            source = "harpy_pelt_with_stones",
        }

        result.success = true
        result.cardValue = action.card.value or 0
        result.preparedWeapon = actor.harpyPreparedStone
        result.effects[#result.effects + 1] = "harpy_pelt_with_stones"
        result.effects[#result.effects + 1] = "thrown_scenery_prepared"
        result.description = (actor.name or "Harpy") .. " picks up scenery to throw."

        action.result = result
        return result
    end

    function resolver:isHarpyStoneMissileAttack(action)
        local actor = action and action.actor
        if not self:isHarpy(actor) then
            return false
        end
        local weapon = action.weapon or actor.harpyPreparedStone
        return weapon and weapon.harpySceneryStone == true
    end

    function resolver:prepareHarpyStoneMissileAttack(action, result)
        if not self:isHarpyStoneMissileAttack(action) then
            return true
        end

        local actor = action.actor
        if not self:isHarpyFlying(actor) then
            result.success = false
            result.description = "Pelt with Stones can only be thrown while the harpy is flying."
            result.effects[#result.effects + 1] = "harpy_pelt_with_stones_requires_flight"
            return false
        end

        action.weapon = action.weapon or actor.harpyPreparedStone
        result.effects[#result.effects + 1] = "harpy_pelt_with_stones"
        result.effects[#result.effects + 1] = "thrown_scenery"
        return true
    end

    function resolver:finishHarpyStoneMissileAttack(action, result)
        if not self:isHarpyStoneMissileAttack(action) then
            return
        end

        if action.actor and action.actor.harpyPreparedStone == action.weapon then
            action.actor.harpyPreparedStone = nil
        end
        result.effects[#result.effects + 1] = "harpy_scenery_thrown"
    end

    function resolver:resolveHarpyPullIntoAir(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target
        local effect, doom = self:getHarpyLesserDoomEffect(action, "roughhouse_lift_and_drop", "pull_into_the_air")

        if not self:isHarpy(actor) then
            result.success = false
            result.description = "Pull Into the Air requires a harpy."
            result.effects[#result.effects + 1] = "harpy_pull_into_air_blocked"
            return result
        end
        if not effect then
            result.success = false
            result.description = "Pull Into the Air requires its lesser doom."
            result.effects[#result.effects + 1] = "harpy_pull_into_air_requires_lesser_doom"
            return result
        end
        if not target then
            result.success = false
            result.description = "Pull Into the Air requires a target."
            result.effects[#result.effects + 1] = "harpy_pull_into_air_missing_target"
            return result
        end
        if not action.card then
            result.success = false
            result.description = "Pull Into the Air requires an action card."
            result.effects[#result.effects + 1] = "harpy_pull_into_air_requires_card"
            return result
        end

        result.cardValue = action.card.value or 0
        result.modifier = 0
        if self:isHarpyOnTurn(action) and effect.addsPentaclesOnOwnTurn ~= false then
            result.modifier = actor.pentacles or 0
            result.effects[#result.effects + 1] = "harpy_pentacles_added"
        end
        result.testValue = result.cardValue + result.modifier
        result.effects[#result.effects + 1] = "harpy_pull_into_air"
        result.effects[#result.effects + 1] = "lesser_doom"
        result.effects[#result.effects + 1] = "roughhouse"

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = true,
            considerShield = true,
        })

        if contest.dodged then
            action.result = result
            return result
        end

        if result.success then
            result.damageDealt = 1
            result.effects[#result.effects + 1] = effect.damageType or "piercing"
            result.effects[#result.effects + 1] = "dropped_from_air"
            self:applyDamage(target, result.damageDealt, result.effects, nil, action.allEntities,
                self:getActionWoundOptions(action, target), {
                    source = "harpy_pull_into_air",
                    action = action,
                    useAegis = action.useAegis,
                })
            if effect.actorBecomesEngaged ~= false then
                self:formEngagement(actor, target)
                result.effects[#result.effects + 1] = "harpy_engaged_by_pull"
            end
            result.description = (doom and doom.name or "Pull Into the Air") ..
                " drops " .. (target.name or "the target") .. " for Piercing damage."
        else
            result.description = (doom and doom.name or "Pull Into the Air") .. " misses."
        end

        self:appendRoughhouseRiposte(action, result, contest)
        action.result = result
        return result
    end

    function resolver:resolveHarpyShriek(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No harpy for Shriek."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not (entityHasNormalizedTag(actor, "harpy") or actor.harpy) then
            result.success = false
            result.description = "Shriek requires a harpy."
            result.effects[#result.effects + 1] = "harpy_shriek_blocked"
            return result
        end

        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect
        if not (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
           (effect and effect.type == "same_zone_stun")) then
            result.success = false
            result.description = "Harpy Shriek requires a greater doom."
            result.effects[#result.effects + 1] = "harpy_shriek_requires_greater_doom"
            return result
        end

        local zone = action.zone or actor.zone
        local affected = {}
        local skipped = {}
        local candidates = action.targets or action.allEntities or {}
        for _, candidate in ipairs(candidates) do
            if candidate ~= actor and candidate.zone == zone and not entityHasNormalizedTag(candidate, "harpy") then
                self:applyStun(candidate, {
                    action = action,
                    instant = true,
                    hand = candidate.challengeHand,
                    handData = candidate.challengeHandData,
                    playerHand = action.playerHand,
                    playerDeck = action.playerDeck,
                    gmDeck = action.gmDeck,
                    npcAI = action.npcAI,
                })
                affected[#affected + 1] = candidate
            elseif candidate ~= actor then
                skipped[#skipped + 1] = candidate
            end
        end

        result.success = true
        result.affected = affected
        result.skipped = skipped
        result.drawsNearbyCreatures = true
        result.loudNoise = {
            source = actor,
            kind = "harpy_shriek",
            zone = zone,
            drawsNearbyCreatures = true,
        }
        actor.lastLoudNoise = result.loudNoise
        if action.room then
            action.room.loudNoise = result.loudNoise
        end

        result.effects[#result.effects + 1] = "harpy_shriek"
        result.effects[#result.effects + 1] = "same_zone_stun"
        result.effects[#result.effects + 1] = "loud_noise"
        result.effects[#result.effects + 1] = "draws_nearby_creatures"
        result.description = "Harpy Shriek stuns " .. tostring(#affected) .. " non-harpy creature(s)."

        self.eventBus:emit("harpy_shriek", {
            actor = actor,
            zone = zone,
            affected = affected,
            skipped = skipped,
            loudNoise = result.loudNoise,
        })

        action.result = result
        return result
    end

    function resolver:isLion(entity)
        return entity and (entity.lion ~= nil or entityHasNormalizedTag(entity, "lion"))
    end

    function resolver:textSuggestsTracking(value)
        if type(value) == "string" then
            local key = normalizeTalentKey(value)
            return key == "track" or key == "tracking" or key == "trail" or key == "spoor" or
                key == "follow_trail" or key == "following_trail" or
                key:find("track", 1, true) ~= nil or
                key:find("trail", 1, true) ~= nil or
                key:find("spoor", 1, true) ~= nil
        end

        if type(value) == "table" then
            for _, entry in ipairs(value) do
                if self:textSuggestsTracking(entry) then
                    return true
                end
            end
            for key, entry in pairs(value) do
                if type(key) ~= "number" and entry and self:textSuggestsTracking(key) then
                    return true
                end
                if type(entry) == "string" and self:textSuggestsTracking(entry) then
                    return true
                end
            end
        end

        return false
    end

    function resolver:isTrackingAttempt(action, commandName)
        action = action or {}

        if action.trackAttempt == true or action.trackingAttempt == true or
           action.followTrail == true or action.trailFollowing == true or
           action.track == true or action.tracking == true then
            return true
        end

        if self:textSuggestsTracking(commandName) or
           self:textSuggestsTracking(action.commandName) or
           self:textSuggestsTracking(action.command) or
           self:textSuggestsTracking(action.context) or
           self:textSuggestsTracking(action.challengeContext) or
           self:textSuggestsTracking(action.testContext) or
           self:textSuggestsTracking(action.intent) or
           self:textSuggestsTracking(action.activity) or
           self:textSuggestsTracking(action.tags) or
           self:textSuggestsTracking(action.actionTags) or
           self:textSuggestsTracking(action.fateTags) then
            return true
        end

        return false
    end

    function resolver:getTrackingSubject(action)
        action = action or {}
        local subject = action.trackSubject or action.trackingSubject or action.trailSubject or
            action.trailTarget or action.quarry or action.trail
        if type(subject) == "table" then
            return subject
        end
        return action.target
    end

    function resolver:lionKnowsItIsBeingHunted(lion, action)
        if not self:isLion(lion) then
            return false
        end

        action = action or {}
        if action.lionKnowsItIsBeingHunted == true or action.lionKnowsHunted == true or
           action.knowsItIsBeingHunted == true or action.knownHunted == true then
            return true
        end

        if lion.knowsItIsBeingHunted == true or lion.knowsBeingHunted == true or
           lion.isBeingHunted == true or lion.beingHunted == true or
           lion.hunted == true or lion.awareOfHunters == true then
            return true
        end

        local lionState = lion.lion
        if type(lionState) == "table" then
            return lionState.knowsItIsBeingHunted == true or lionState.knowsBeingHunted == true or
                lionState.isBeingHunted == true or lionState.beingHunted == true or
                lionState.hunted == true or lionState.awareOfHunters == true
        end

        return false
    end

    function resolver:lionUntrackableBlocksTracking(action, result, commandName)
        action = action or {}
        result.effects = result.effects or {}

        if not self:isTrackingAttempt(action, commandName) then
            return false
        end

        local subject = self:getTrackingSubject(action)
        if not self:isLion(subject) and self:isLion(action.target) then
            subject = action.target
        end
        if not self:isLion(subject) then
            return false
        end
        if not self:lionKnowsItIsBeingHunted(subject, action) then
            return false
        end

        subject.tracksCoveredByTail = true
        subject.trackingPrevented = true
        if type(subject.lion) == "table" then
            subject.lion.tracksCoveredByTail = true
            subject.lion.trackingPrevented = true
        end

        result.success = false
        result.pendingTestOfFate = false
        result.trackSubject = subject
        result.trackingBlocked = {
            target = subject,
            reason = "lion_untrackable",
        }
        result.effects[#result.effects + 1] = "lion_untrackable"
        result.effects[#result.effects + 1] = "tracks_covered_by_tail"
        result.effects[#result.effects + 1] = "tracking_prevented"
        result.description = "The lion covers its tracks with its tail; tracking is impossible."

        self.eventBus:emit("lion_untrackable_tracking_prevented", {
            lion = subject,
            actor = action.actor,
            action = action,
            command = commandName,
        })

        action.result = result
        return true
    end

    function resolver:targetRequestsLionMercy(target, action)
        action = action or {}
        if action.prostratingForMercy == true or action.prostratesForMercy == true or
           action.beggingMercy == true or action.asksMercy == true or action.targetAsksMercy == true then
            return true
        end
        if not target then
            return false
        end

        if target.prostratingForMercy == true or target.prostratesForMercy == true or
           target.beggingMercy == true or target.asksMercy == true or target.requestedMercy == true or
           target.mercyRequested == true then
            return true
        end

        local conditions = target.conditions or {}
        if conditions.prostratingForMercy == true or conditions.prostratesForMercy == true or
           conditions.beggingMercy == true or conditions.asksMercy == true or
           conditions.requestedMercy == true or conditions.mercyRequested == true then
            return true
        end

        local prostrates = target.prostrating == true or target.prostrated == true or
            conditions.prostrating == true or conditions.prostrated == true
        local asks = target.asksForMercy == true or target.askingMercy == true or
            target.begsForMercy == true or target.beggingForMercy == true or
            conditions.asksForMercy == true or conditions.askingMercy == true or
            conditions.begsForMercy == true or conditions.beggingForMercy == true
        return prostrates and asks
    end

    function resolver:lionNobleMercyBlocksAction(action, result, actionType)
        action = action or {}
        result.effects = result.effects or {}

        if action.lionMercyBypassed == true or action.allowLionToKillSupplicant == true or
           action.nonlethal == true or action.mercifulAction == true then
            return false
        end
        if not self:isLion(action.actor) or not self:targetRequestsLionMercy(action.target, action) then
            return false
        end

        local harmful = actionType == M.ACTION_TYPES.MELEE or actionType == M.ACTION_TYPES.MISSILE or
            action.damage ~= nil or action.dealsWound == true or action.killTarget == true or action.lethal == true
        if not harmful then
            return false
        end

        action.target.sparedByLionMercy = true
        action.actor.lionMercySpared = action.actor.lionMercySpared or {}
        action.actor.lionMercySpared[#action.actor.lionMercySpared + 1] = action.target

        result.success = false
        result.effects[#result.effects + 1] = "lion_noble_mercy"
        result.effects[#result.effects + 1] = "mercy_requested"
        result.effects[#result.effects + 1] = "attack_prevented"
        result.description = (action.actor.name or "Lion") .. " refuses to kill a supplicant begging mercy."

        self.eventBus:emit("lion_noble_mercy", {
            actor = action.actor,
            target = action.target,
            action = action,
        })

        action.result = result
        return true
    end

    function resolver:isBeast(entity)
        return entity and (entity.beast == true or type(entity.beast) == "table" or
            entityHasNormalizedTag(entity, "beast"))
    end

    function resolver:getBeastFleetMoveZones(actor)
        local sources = {
            actor and actor.beast,
            actor and actor.lion,
            actor and actor.questingBeast,
            actor and actor.griffin,
            actor and actor.direCentipede,
        }

        local zones = actor and (actor.fleetMoveZones or actor.freeMoveZones)
        for _, source in ipairs(sources) do
            if not zones and type(source) == "table" then
                zones = source.fleetMoveZones or source.freeMoveZones or
                    (type(source.fleet) == "table" and source.fleet.moveZones)
            end
        end

        return math.max(1, tonumber(zones) or 1)
    end

    function resolver:resolveBeastFleetMove(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isBeast(actor) then
            result.success = false
            result.description = "Fleet requires a beast."
            result.effects[#result.effects + 1] = "beast_fleet_blocked"
            return result
        end

        local onTurn = action.onBeastTurn == true or action.onTurn == true or
            action.isTurnAction == true or action.actorTurn == true
        if not onTurn then
            result.success = false
            result.description = "Beast Fleet can only be used on the beast's turn."
            result.effects[#result.effects + 1] = "beast_fleet_requires_turn"
            return result
        end

        local moveZones = self:getBeastFleetMoveZones(actor)
        action.maxMoveDistance = math.min(tonumber(action.maxMoveDistance) or moveZones, moveZones)
        self:resolveMove(action, result, action.allEntities)

        if result.success then
            result.cardless = true
            result.countsTowardTurnCard = false
            result.effects[#result.effects + 1] = "beast_fleet"
            result.effects[#result.effects + 1] = "free_move_on_turn"
            result.description = (actor.name or "Beast") .. " moves with Fleet. " ..
                (result.description or "")
        end

        action.result = result
        return result
    end

    function resolver:lionGreaterDoomReady(action, effectType, doomId)
        local doom = action and (action.greaterDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            (doomId and doom and doom.id == doomId) or (effect and effect.type == effectType))
    end

    function resolver:resolveLionFleetMove(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isLion(actor) then
            result.success = false
            result.description = "Fleet requires a lion."
            result.effects[#result.effects + 1] = "lion_fleet_blocked"
            return result
        end

        local onTurn = action.onLionTurn == true or action.onTurn == true or
            action.isTurnAction == true or action.actorTurn == true
        if not onTurn then
            result.success = false
            result.description = "Lion Fleet can only be used on the lion's turn."
            result.effects[#result.effects + 1] = "lion_fleet_requires_turn"
            return result
        end

        action.maxMoveDistance = math.min(action.maxMoveDistance or 1,
            actor.lion and actor.lion.fleetMoveZones or 1)
        self:resolveMove(action, result, action.allEntities)

        if result.success then
            result.cardless = true
            result.countsTowardTurnCard = false
            result.effects[#result.effects + 1] = "lion_fleet"
            result.effects[#result.effects + 1] = "free_move_on_turn"
            result.description = (actor.name or "Lion") .. " moves with Fleet. " ..
                (result.description or "")
        end

        action.result = result
        return result
    end

    function resolver:isDireCentipede(entity)
        return entity and (entity.direCentipede ~= nil or entityHasNormalizedTag(entity, "dire_centipede") or
            entityHasNormalizedTag(entity, "giant_centipede"))
    end

    function resolver:resolveCentipedeFleetMove(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isDireCentipede(actor) then
            result.success = false
            result.description = "Fleet requires a dire centipede."
            result.effects[#result.effects + 1] = "dire_centipede_fleet_blocked"
            return result
        end

        local onTurn = action.onCentipedeTurn == true or action.onTurn == true or
            action.isTurnAction == true or action.actorTurn == true
        if not onTurn then
            result.success = false
            result.description = "Dire Centipede Fleet can only be used on the centipede's turn."
            result.effects[#result.effects + 1] = "dire_centipede_fleet_requires_turn"
            return result
        end

        action.maxMoveDistance = math.min(action.maxMoveDistance or 1,
            actor.direCentipede and actor.direCentipede.fleetMoveZones or 1)
        self:resolveMove(action, result, action.allEntities)

        if result.success then
            result.cardless = true
            result.countsTowardTurnCard = false
            result.effects[#result.effects + 1] = "dire_centipede_fleet"
            result.effects[#result.effects + 1] = "free_move_on_turn"
            result.description = (actor.name or "Dire Centipede") .. " moves with Fleet. " ..
                (result.description or "")
        end

        action.result = result
        return result
    end

    function resolver:resolveLionCautiousRetreat(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target

        if not actor then
            result.success = false
            result.description = "No lion for Cautious Retreat."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not (entityHasNormalizedTag(actor, "lion") or actor.lion) then
            result.success = false
            result.description = "Cautious Retreat requires a lion."
            result.effects[#result.effects + 1] = "lion_cautious_retreat_blocked"
            return result
        end
        if not target then
            result.success = false
            result.description = "No adventurer to disengage from."
            result.effects[#result.effects + 1] = "lion_cautious_retreat_missing_target"
            return result
        end

        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect
        if not (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
           (effect and effect.type == "disengage_one")) then
            result.success = false
            result.description = "Lion Cautious Retreat requires a greater doom."
            result.effects[#result.effects + 1] = "lion_cautious_retreat_requires_greater_doom"
            return result
        end

        self:breakEngagement(actor, target)

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.effects[#result.effects + 1] = "lion_cautious_retreat"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "disengaged"
        result.greaterDoom = {
            name = doom and doom.name or "Cautious Retreat",
            card = action.greaterDoomCard,
        }
        result.description = (actor.name or "Lion") .. " disengages from " ..
            (target.name or "one adventurer") .. " without spending its turn card."

        self.eventBus:emit("lion_cautious_retreat", {
            actor = actor,
            target = target,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:resolveStrategistCautiousRetreat(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target

        if not actor then
            result.success = false
            result.description = "No strategist for Cautious Retreat."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isStrategist(actor) then
            result.success = false
            result.description = "Cautious Retreat requires a strategist."
            result.effects[#result.effects + 1] = "strategist_cautious_retreat_blocked"
            return result
        end
        if not target then
            result.success = false
            result.description = "No adventurer to disengage from."
            result.effects[#result.effects + 1] = "strategist_cautious_retreat_missing_target"
            return result
        end

        local effect, doom = self:getStrategistGreaterDoomEffect(action, "disengage_one", "cautious_retreat")
        if not effect then
            result.success = false
            result.description = "Strategist Cautious Retreat requires a greater doom."
            result.effects[#result.effects + 1] = "strategist_cautious_retreat_requires_greater_doom"
            return result
        end

        self:breakEngagement(actor, target)

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.effects[#result.effects + 1] = "strategist_cautious_retreat"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "disengaged"
        result.greaterDoom = {
            name = doom and doom.name or "Cautious Retreat",
            card = action.greaterDoomCard,
        }
        result.description = (actor.name or "Strategist") .. " disengages from " ..
            (target.name or "one adventurer") .. " without spending its turn card."

        self.eventBus:emit("strategist_cautious_retreat", {
            actor = actor,
            target = target,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:getEliteGreaterDoomEffect(action, effectType, doomId)
        local actor = action and action.actor
        if not self:isElite(actor) then
            return nil, nil
        end

        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect
        local matchesEffect = effect and effect.type == effectType
        local matchesId = doomId and doom and doom.id == doomId
        if not (matchesEffect or matchesId) then
            return nil, nil
        end

        if action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
           matchesEffect or matchesId then
            return effect or {}, doom
        end

        return nil, nil
    end

    function resolver:setEliteIntangibleState(actor, intangible)
        if not actor then
            return nil
        end

        actor.conditions = actor.conditions or {}
        actor.intangible = intangible == true
        actor.tangible = intangible ~= true
        actor.conditions.intangible = intangible == true
        actor.conditions.tangible = intangible ~= true
        actor.eliteIntangible = intangible == true
        actor.eliteIntangibleActive = intangible == true
        return intangible == true
    end

    function resolver:resolveEliteIntangible(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isElite(actor) then
            result.success = false
            result.description = "Intangible requires an elite."
            result.effects[#result.effects + 1] = "elite_intangible_blocked"
            return result
        end

        local effect, doom = self:getEliteGreaterDoomEffect(action, "toggle_intangible", "intangible")
        if not effect then
            result.success = false
            result.description = "Elite Intangible requires a greater doom."
            result.effects[#result.effects + 1] = "elite_intangible_requires_greater_doom"
            return result
        end

        local currentlyIntangible = actor.intangible == true or
            (actor.conditions and actor.conditions.intangible == true) or actor.tangible == false
        local intangible = not currentlyIntangible
        if action.becomeIntangible == true or action.intangible == true then
            intangible = true
        elseif action.becomeTangible == true or action.tangible == true then
            intangible = false
        end
        self:setEliteIntangibleState(actor, intangible)

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.eliteIntangible = {
            intangible = intangible,
            doom = doom,
        }
        result.effects[#result.effects + 1] = "elite_intangible"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = intangible and "intangible" or "tangible"
        result.description = (actor.name or "Elite") ..
            (intangible and " becomes intangible." or " becomes tangible.")

        action.result = result
        return result
    end

    function resolver:resolveEliteRegenerate(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isElite(actor) then
            result.success = false
            result.description = "Regenerate requires an elite."
            result.effects[#result.effects + 1] = "elite_regenerate_blocked"
            return result
        end

        local effect = self:getEliteGreaterDoomEffect(action, "heal_self", "regenerate")
        if not effect then
            result.success = false
            result.description = "Elite Regenerate requires a greater doom."
            result.effects[#result.effects + 1] = "elite_regenerate_requires_greater_doom"
            return result
        end

        local healed = self:healNPCHealth(actor, action.healWounds or effect.healWounds or effect.wounds or 1)
        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.healed = healed
        result.effects[#result.effects + 1] = "elite_regenerate"
        result.effects[#result.effects + 1] = "greater_doom"
        if healed > 0 then
            result.effects[#result.effects + 1] = "healed"
        end
        result.description = (actor.name or "Elite") .. " regenerates " .. tostring(healed) .. " Wound(s)."
        action.result = result
        return result
    end

    function resolver:applyEliteCommandAttack(target, effect, action, result, doom)
        result.effects = result.effects or {}
        result.damageDealt = 0
        result.controlledActionValue = tonumber(action and action.card and action.card.value) or
            result.cardValue or result.testValue or 0
        result.effects[#result.effects + 1] = "elite_command"
        result.effects[#result.effects + 1] = "wound_replaced"

        if isControlImmuneTarget(target) then
            result.eliteCommandBlocked = "control_immune"
            result.effects[#result.effects + 1] = "control_immune"
            return nil
        end

        target.conditions = target.conditions or {}
        target.conditions.controlled = true
        target.conditions.elite_commanded = true
        target.controlledBy = action.actor
        target.controlOrder = {
            text = action.controlOrder or action.command or "immediate_command",
            source = "elite_command",
            immediate = true,
        }
        target.controlCommandsRemaining = 1
        target.eliteCommanded = {
            elite = action.actor,
            eliteId = action.actor and action.actor.id,
            command = target.controlOrder.text,
            controlledActionValue = result.controlledActionValue,
        }

        result.eliteCommand = target.eliteCommanded
        result.effects[#result.effects + 1] = "controlled"
        if doom and doom.id == "command" then
            result.effects[#result.effects + 1] = "elite_command_greater_doom"
        end

        local priorCompletes = action.controlOrderCompletesAfterImmediate
        action.controlOrderCompletesAfterImmediate = false
        local immediateResult = self:resolveImmediateControlAction(action, result, action.actor, target)
        action.controlOrderCompletesAfterImmediate = priorCompletes

        if immediateResult and action.controlPersists ~= true then
            target.conditions.controlled = false
            target.conditions.elite_commanded = false
            target.controlledBy = nil
            target.controlOrder = nil
            target.controlCommandsRemaining = 0
            target.lastEliteCommand = target.eliteCommanded
            target.eliteCommanded = nil
            result.effects[#result.effects + 1] = "elite_command_released"
        end

        return result.eliteCommand
    end

    function resolver:getElitePotenceEffectName(action, effect)
        local value = action and (action.potenceEffect or action.elitePotenceEffect or action.effectName or
            action.condition or action.statusEffect)
        value = value or effect.effect or effect.condition or effect.statusEffect or effect.conditionName or
            effect.defaultEffect or "stunned"
        return normalizeTalentKey(value)
    end

    function resolver:getElitePotenceItem(target, action)
        if action and action.potenceItems and target then
            local item = action.potenceItems[target] or action.potenceItems[target.id] or action.potenceItems[target.name]
            if item then
                return item
            end
        end
        if action and action.targetItem then
            return action.targetItem
        end
        if target and target.inventory and target.inventory.getItems then
            local hands = target.inventory:getItems(inventory.LOCATIONS.HANDS) or {}
            for _, item in ipairs(hands) do
                if item and not item.destroyed then
                    return item
                end
            end
        end
        return target and target.heldItem
    end

    function resolver:applyElitePotenceEffect(target, effectName, action, result)
        target.conditions = target.conditions or {}

        if effectName == "notch" or effectName == "notched" or effectName == "item_notched" then
            local item = self:getElitePotenceItem(target, action)
            if not item then
                return {
                    target = target,
                    effect = effectName,
                    blocked = "no_item_to_notch",
                }
            end
            local notchResult = inventory.addNotch(item)
            if notchResult == "destroyed" then
                result.effects[#result.effects + 1] = "item_destroyed"
            end
            target.lastElitePotenceNotch = {
                item = item,
                result = notchResult,
            }
            return {
                target = target,
                effect = "notch",
                item = item,
                notchResult = notchResult,
            }
        end

        local condition = effectName
        if condition == "stun" then
            condition = "stunned"
        elseif condition == "deafen" then
            condition = "deafened"
        elseif condition == "silence" then
            condition = "silenced"
        elseif condition == "trip" then
            condition = "prone"
        end
        target.conditions[condition] = true
        return {
            target = target,
            effect = condition,
        }
    end

    function resolver:resolveElitePotence(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isElite(actor) then
            result.success = false
            result.description = "Potence requires an elite."
            result.effects[#result.effects + 1] = "elite_potence_blocked"
            return result
        end

        local effect, doom = self:getEliteGreaterDoomEffect(action, "potence", "potence")
        if not effect then
            effect, doom = self:getEliteGreaterDoomEffect(action, "zone_effect", "potence")
        end
        if not effect then
            result.success = false
            result.description = "Elite Potence requires a greater doom."
            result.effects[#result.effects + 1] = "elite_potence_requires_greater_doom"
            return result
        end

        local effectName = self:getElitePotenceEffectName(action, effect)
        local actorZone = action.zone or actor.zone
        local candidates = action.targets or action.allEntities or {}
        local affected = {}
        for _, candidate in ipairs(candidates) do
            local conditions = candidate.conditions or {}
            if candidate ~= actor and candidate.isPC == true and candidate.zone == actorZone and
               not conditions.dead and not conditions.deaths_door then
                affected[#affected + 1] = self:applyElitePotenceEffect(candidate, effectName, action, result)
            end
        end

        result.success = true
        result.elitePotence = {
            effect = effectName,
            affected = affected,
            doom = doom,
        }
        result.affectedTargets = affected
        result.effects[#result.effects + 1] = "elite_potence"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "elite_potence_" .. effectName
        if effect.countsTowardTurnCard == false then
            result.countsTowardTurnCard = false
        end
        result.description = (actor.name or "Elite") .. " unleashes Potence on " ..
            tostring(#affected) .. " adventurer(s)."
        action.result = result
        return result
    end

    function resolver:applyEliteShapeAbility(actor, ability, result)
        local normalized = normalizeTalentKey(ability)
        if normalized == "" then
            return
        end
        actor.conditions = actor.conditions or {}
        actor.conditions[normalized] = true
        if normalized == "flying" or normalized == "flight" then
            actor.flying = true
            actor.conditions.flying = true
            result.effects[#result.effects + 1] = "flying"
        elseif normalized == "swimming" or normalized == "swim" or normalized == "aquatic" then
            actor.swimming = true
            actor.aquatic = true
            actor.conditions.swimming = true
            result.effects[#result.effects + 1] = "swimming"
        elseif normalized == "intangible" or normalized == "incorporeal" then
            actor.intangible = true
            actor.tangible = false
            actor.conditions.intangible = true
            actor.conditions.tangible = false
            result.effects[#result.effects + 1] = "intangible"
        else
            result.effects[#result.effects + 1] = "shape_ability_" .. normalized
        end
    end

    function resolver:resolveEliteShapeshifter(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isElite(actor) then
            result.success = false
            result.description = "Shapeshifter requires an elite."
            result.effects[#result.effects + 1] = "elite_shapeshifter_blocked"
            return result
        end

        local effect, doom = self:getEliteGreaterDoomEffect(action, "shapeshifter", "shapeshifter")
        if not effect then
            effect, doom = self:getEliteGreaterDoomEffect(action, "shape_change", "shapeshifter")
        end
        if not effect then
            result.success = false
            result.description = "Elite Shapeshifter requires a greater doom."
            result.effects[#result.effects + 1] = "elite_shapeshifter_requires_greater_doom"
            return result
        end

        local shape = action.shape or action.newShape or action.shapeName or effect.shape or effect.defaultShape or
            doom and doom.shape or "new_shape"
        local abilities = action.shapeAbilities or action.abilities or effect.abilities or effect.grants or {}
        actor.conditions = actor.conditions or {}
        actor.eliteShape = {
            shape = shape,
            abilities = eliteListFromValue(abilities),
            doom = doom,
        }
        actor.shape = shape
        actor.conditions.shapeshifted = true
        for _, ability in ipairs(actor.eliteShape.abilities) do
            self:applyEliteShapeAbility(actor, ability, result)
        end

        result.success = true
        result.eliteShape = actor.eliteShape
        result.effects[#result.effects + 1] = "elite_shapeshifter"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "shapeshifted"
        if effect.countsTowardTurnCard == false then
            result.countsTowardTurnCard = false
        end
        result.description = (actor.name or "Elite") .. " changes shape into " .. tostring(shape) .. "."
        action.result = result
        return result
    end

    function resolver:getEliteOptionalRule(entity, ruleName)
        if not self:isElite(entity) then
            return nil
        end
        local eliteConfig = type(entity.elite) == "table" and entity.elite or {}
        if ruleName == "invulnerable" then
            return entity.eliteInvulnerable or entity.invulnerable or eliteConfig.invulnerable
        elseif ruleName == "threshold" then
            return entity.eliteThreshold or entity.threshold or eliteConfig.threshold
        elseif ruleName == "retributive" then
            return entity.eliteRetributive or entity.retributive or eliteConfig.retributive
        end
        return eliteConfig[ruleName] or entity[ruleName]
    end

    function resolver:eliteDamageMatchesSource(source, effects, weapon, damageContext)
        local normalized = normalizeTalentKey(source)
        damageContext = damageContext or {}
        if normalized == "" then
            return false
        end
        if normalized == "silver" or normalized == "silver_weapon" or normalized == "silver_weapons" then
            if self:isSilverWeapon(weapon) or damageContext.silver == true then
                return true
            end
            for _, effect in ipairs(effects or {}) do
                local effectKey = normalizeTalentKey(effect)
                if effectKey == "silver" or effectKey == "silver_weapon" or effectKey == "silver_weapons" then
                    return true
                end
            end
            return false
        end
        if normalized == "weapon" or normalized == "weapons" then
            return weapon ~= nil
        end
        if normalized == "magic" or normalized == "spell" or normalized == "sorcery" then
            if damageContext.magic == true or damageContext.spell == true or damageContext.sorcery == true then
                return true
            end
        end
        if normalized == "fire" and damageContext.fire == true then
            return true
        end

        local contextKeys = {
            damageContext.source,
            damageContext.damageSource,
            damageContext.damageElement,
            damageContext.element,
            damageContext.material,
        }
        for _, value in ipairs(contextKeys) do
            if normalizeTalentKey(value) == normalized then
                return true
            end
        end

        local weaponKeys = {}
        if weapon then
            local props = weapon.properties or {}
            weaponKeys = {
                weapon.weaponType,
                weapon.type,
                weapon.name,
                weapon.templateId,
                weapon.material,
                props.material,
            }
            if normalized == "iron_weapon" or normalized == "iron_weapons" then
                local material = normalizeTalentKey(weapon.material or props.material)
                if material == "iron" or material == "steel" then
                    return true
                end
            end
        end
        for _, value in ipairs(weaponKeys) do
            if normalizeTalentKey(value) == normalized then
                return true
            end
        end
        for _, effect in ipairs(effects or {}) do
            if normalizeTalentKey(effect) == normalized then
                return true
            end
        end
        return false
    end

    function resolver:isEliteInvulnerableAllowedDamage(entity, effects, weapon, damageContext)
        local rule = self:getEliteOptionalRule(entity, "invulnerable")
        if not rule then
            return true
        end
        local sources = {}
        if type(rule) == "table" then
            sources = rule.except or rule.exceptions or rule.ignoresDamageExcept or rule.vulnerableTo or
                rule.damageSources or rule.allowedDamage or {}
        end
        if #eliteListFromValue(sources) == 0 then
            return false
        end
        for _, source in ipairs(eliteListFromValue(sources)) do
            if self:eliteDamageMatchesSource(source, effects, weapon, damageContext) then
                return true
            end
        end
        return false
    end

    function resolver:resolveEliteInvulnerableDamage(entity, amount, effects, weapon, damageContext)
        if not (self:isElite(entity) and self:getEliteOptionalRule(entity, "invulnerable") and (amount or 0) > 0) then
            return nil
        end
        if self:isEliteInvulnerableAllowedDamage(entity, effects, weapon, damageContext) then
            return nil
        end
        effects[#effects + 1] = "elite_invulnerable"
        effects[#effects + 1] = "damage_ignored"
        self.eventBus:emit("elite_invulnerable_damage_ignored", {
            entity = entity,
            weapon = weapon,
            damageContext = damageContext,
        })
        return {
            result = "immune",
            immune = true,
            reason = "elite_invulnerable",
        }
    end

    function resolver:getEliteThresholdRequiredWounds(entity)
        local rule = self:getEliteOptionalRule(entity, "threshold")
        if not rule then
            return nil
        end
        if type(rule) == "table" then
            local nested = rule.ignoresDamageUntil or {}
            return rule.woundsInSingleTurn or rule.requiredWounds or nested.woundsInSingleTurn or 2
        end
        return 2
    end

    function resolver:resolveEliteThresholdDamage(entity, amount, effects, weapon, damageContext)
        amount = amount or 0
        if amount <= 0 or not self:isElite(entity) or entity.eliteThresholdBroken then
            return nil
        end
        local requiredWounds = self:getEliteThresholdRequiredWounds(entity)
        if not requiredWounds then
            return nil
        end
        if amount < requiredWounds then
            entity.eliteThreshold = entity.eliteThreshold or {}
            entity.eliteThreshold.lastIgnoredWounds = amount
            entity.eliteThreshold.requiredWounds = requiredWounds
            entity.eliteThreshold.source = damageContext and damageContext.source
            effects[#effects + 1] = "elite_threshold_ignored"
            self.eventBus:emit("elite_threshold_ignored", {
                entity = entity,
                amount = amount,
                requiredWounds = requiredWounds,
                source = damageContext and damageContext.source,
            })
            return {
                result = "ignored",
                ignored = true,
                reason = "elite_threshold",
                requiredWounds = requiredWounds,
                amount = amount,
            }
        end

        entity.eliteThresholdBroken = true
        effects[#effects + 1] = "elite_threshold_broken"
        self.eventBus:emit("elite_threshold_broken", {
            entity = entity,
            amount = amount,
            source = damageContext and damageContext.source,
        })
        return nil
    end

    function resolver:eliteRetributiveApplies(elite, target)
        if not (elite and target and elite ~= target and self:getEliteOptionalRule(elite, "retributive")) then
            return false
        end
        if self:areEngaged(elite, target) then
            return true
        end
        return elite.is_engaged and target.is_engaged and elite.zone ~= nil and elite.zone == target.zone
    end

    function resolver:applyEliteRetributiveStartTurn(activeEntity, allEntities, opts)
        opts = opts or {}
        local result = {
            success = true,
            effects = {},
            retributiveHits = {},
        }
        if not activeEntity then
            return result
        end
        local conditions = activeEntity.conditions or {}
        if conditions.dead or conditions.deaths_door then
            return result
        end
        for _, elite in ipairs(allEntities or {}) do
            if self:eliteRetributiveApplies(elite, activeEntity) then
                local rule = self:getEliteOptionalRule(elite, "retributive")
                local wounds = type(rule) == "table" and (rule.wounds or rule.damage or 1) or 1
                local hitEffects = { "elite_retributive" }
                self:applyDamage(activeEntity, wounds, hitEffects, nil, allEntities, nil, {
                    source = "elite_retributive",
                    elite = elite,
                    round = opts.round,
                })
                result.effects[#result.effects + 1] = "elite_retributive"
                result.retributiveHits[#result.retributiveHits + 1] = {
                    elite = elite,
                    target = activeEntity,
                    wounds = wounds,
                    effects = hitEffects,
                }
                if activeEntity.conditions and
                   (activeEntity.conditions.dead or activeEntity.conditions.deaths_door) then
                    break
                end
            end
        end
        return result
    end

    function resolver:getDungeonLordConfig(entity)
        if type(entity and entity.dungeonLord) == "table" then
            return entity.dungeonLord
        end
        if type(entity and entity.dungeon_lord) == "table" then
            return entity.dungeon_lord
        end
        return {}
    end

    function resolver:getDungeonLordPoolDefinitions(entity)
        local config = self:getDungeonLordConfig(entity)
        return config.pools or config.healthPools or config.sections or entity.dungeonLordPools or
            entity.healthPools
    end

    function resolver:getDungeonLordPoolId(rawId)
        local poolId = normalizeTalentKey(rawId)
        if poolId == "leftarm" then
            return "left_arm"
        elseif poolId == "rightarm" then
            return "right_arm"
        elseif poolId == "body" or poolId == "main" then
            return "core"
        end
        return poolId ~= "" and poolId or nil
    end

    function resolver:getDungeonLordActionTargetPool(action)
        if not action then
            return nil
        end
        return self:getDungeonLordPoolId(action.targetPool or action.pool or action.healthPool or
            action.dungeonLordPool or action.targetSection or action.section or action.targetPart)
    end

    function resolver:ensureDungeonLordPoolState(entity)
        if not self:isDungeonLord(entity) or self:isTitanSporehulk(entity) then
            return nil
        end
        if entity.dungeonLordPoolState then
            return entity.dungeonLordPoolState
        end

        local definitions = self:getDungeonLordPoolDefinitions(entity)
        if type(definitions) ~= "table" then
            return nil
        end

        entity.dungeonLordPoolState = {}
        entity.dungeonLordPoolOrder = {}
        local function addPool(key, pool)
            if type(pool) == "number" then
                pool = { health = pool }
            end
            if type(pool) ~= "table" then
                return
            end
            local poolId = self:getDungeonLordPoolId(pool.id or key)
            if not poolId then
                return
            end
            entity.dungeonLordPoolOrder[#entity.dungeonLordPoolOrder + 1] = poolId
            entity.dungeonLordPoolState[poolId] = {
                id = poolId,
                name = pool.name or poolId,
                health = pool.health or pool.hd or pool.hitDice or 0,
                defense = pool.defense or pool.armour or pool.armor or 0,
                maxHealth = pool.health or pool.hd or pool.hitDice or 0,
                maxDefense = pool.defense or pool.armour or pool.armor or 0,
                defeated = pool.defeated == true,
                core = pool.core == true or pool.deathPool == true or pool.deathSection == true,
                source = pool,
            }
        end

        if #definitions > 0 then
            for index, pool in ipairs(definitions) do
                addPool(index, pool)
            end
        else
            for key, pool in pairs(definitions) do
                addPool(key, pool)
            end
        end
        return entity.dungeonLordPoolState
    end

    function resolver:getDungeonLordCorePoolId(entity)
        local config = self:getDungeonLordConfig(entity)
        local explicit = self:getDungeonLordPoolId(config.corePool or config.deathPool or
            entity.dungeonLordCorePool or entity.deathPool)
        if explicit then
            return explicit
        end
        local pools = self:ensureDungeonLordPoolState(entity)
        for poolId, pool in pairs(pools or {}) do
            if pool.core then
                return poolId
            end
        end
        if pools and pools.core then
            return "core"
        end
        return entity.dungeonLordPoolOrder and entity.dungeonLordPoolOrder[1] or nil
    end

    function resolver:getDungeonLordPoolState(entity, poolId)
        local pools = self:ensureDungeonLordPoolState(entity)
        if not pools then
            return nil
        end
        poolId = self:getDungeonLordPoolId(poolId) or self:getDungeonLordCorePoolId(entity)
        return poolId and pools[poolId] or nil, poolId
    end

    function resolver:dungeonLordDefeatRequiresAllPools(entity)
        local config = self:getDungeonLordConfig(entity)
        local mode = normalizeTalentKey(config.defeatMode or config.defeatedWhen or
            entity.dungeonLordDefeatMode)
        return config.defeatRequiresAllPools == true or entity.defeatRequiresAllPools == true or
            mode == "all" or mode == "all_pools" or mode == "all_sections"
    end

    function resolver:isDungeonLordDefeated(entity)
        local pools = self:ensureDungeonLordPoolState(entity)
        if not pools then
            return false
        end
        if self:dungeonLordDefeatRequiresAllPools(entity) then
            for _, pool in pairs(pools) do
                if not pool.defeated then
                    return false
                end
            end
            return true
        end
        local core = self:getDungeonLordPoolState(entity, self:getDungeonLordCorePoolId(entity))
        return core and core.defeated == true
    end

    function resolver:markDungeonLordPoolDefeated(entity, poolId, effects)
        local pool = self:getDungeonLordPoolState(entity, poolId)
        if not pool or pool.defeated then
            return
        end
        pool.defeated = true
        effects[#effects + 1] = "dungeon_lord_pool_defeated"
        effects[#effects + 1] = "dungeon_lord_" .. pool.id .. "_defeated"

        if self:isDungeonLordDefeated(entity) then
            entity.conditions = entity.conditions or {}
            entity.conditions.deaths_door = true
            entity.dungeonLordDefeated = true
            effects[#effects + 1] = "dungeon_lord_defeated"
        end
    end

    function resolver:applyDungeonLordPoolDamage(entity, poolId, amount, effects, opts)
        opts = opts or {}
        effects = effects or {}
        local pool = self:getDungeonLordPoolState(entity, poolId)
        if not pool then
            return nil
        end

        local damageType = normalizeTalentKey(opts.damageType or "normal")
        local bypassDefense = opts.bypassDefense == true or damageType == "piercing" or damageType == "critical"
        local lastResult = nil
        for _ = 1, amount or 1 do
            if not bypassDefense and pool.defense and pool.defense > 0 then
                pool.defense = pool.defense - 1
                lastResult = "pool_defense_reduced"
            elseif pool.health and pool.health > 0 then
                pool.health = pool.health - 1
                lastResult = "pool_health_reduced"
            else
                lastResult = "pool_defeated"
            end
        end

        if pool.id == self:getDungeonLordCorePoolId(entity) then
            entity.npcHealth = pool.health
            entity.npcDefense = pool.defense
        end
        if pool.health <= 0 then
            self:markDungeonLordPoolDefeated(entity, pool.id, effects)
            lastResult = "pool_defeated"
        end

        effects[#effects + 1] = "dungeon_lord_pool_damage"
        effects[#effects + 1] = "dungeon_lord_" .. pool.id .. "_damage"
        return {
            result = lastResult,
            dungeonLordPool = pool.id,
            pool = pool,
            damageApplied = true,
        }
    end

    function resolver:resolveDungeonLordPoolDamage(entity, amount, effects, weapon, damageContext)
        if not self:isDungeonLord(entity) or self:isTitanSporehulk(entity) then
            return nil
        end
        if not self:getDungeonLordPoolDefinitions(entity) then
            return nil
        end

        local damageType = "normal"
        for _, effect in ipairs(effects or {}) do
            if effect == "critical" then
                damageType = "critical"
                break
            elseif effect == "piercing" or effect == "pierce_armor" then
                damageType = "piercing"
            end
        end
        local action = damageContext and damageContext.action or {}
        local poolId = self:getDungeonLordActionTargetPool(action) or self:getDungeonLordCorePoolId(entity)
        return self:applyDungeonLordPoolDamage(entity, poolId, amount or 1, effects, {
            damageType = damageType,
        })
    end

    function resolver:dungeonLordPoolHasDoom(pool, doom)
        if not pool or not doom then
            return false
        end
        local doomId = normalizeTalentKey(doom.id or doom.name)
        if doomId == "" then
            return false
        end
        local source = pool.source or {}
        local lists = {
            source.lesserDooms,
            source.greaterDooms,
            source.dooms,
            source.abilities,
        }
        for index = 1, 4 do
            local list = lists[index]
            if type(list) == "table" then
                for key, value in pairs(list) do
                    local entry = type(value) == "table" and (value.id or value.name) or value
                    if value == true then
                        entry = key
                    end
                    if normalizeTalentKey(entry) == doomId then
                        return true
                    end
                end
            end
        end
        return false
    end

    function resolver:getDungeonLordDoomPoolId(entity, doom, action)
        local explicit = self:getDungeonLordPoolId(action and (action.doomPool or action.doomSection or
            action.actionPool or action.sourcePool) or doom and (doom.poolId or doom.pool or doom.section or
            doom.sourcePool))
        if explicit then
            return explicit
        end
        local pools = self:ensureDungeonLordPoolState(entity)
        for poolId, pool in pairs(pools or {}) do
            if self:dungeonLordPoolHasDoom(pool, doom) then
                return poolId
            end
        end
        return nil
    end

    function resolver:dungeonLordPoolCanUseDoom(entity, doom, action)
        if not self:isDungeonLord(entity) then
            return true
        end
        local poolId = self:getDungeonLordDoomPoolId(entity, doom, action)
        if not poolId then
            return true
        end
        local pool = self:getDungeonLordPoolState(entity, poolId)
        return pool == nil or pool.defeated ~= true
    end

    function resolver:validateDungeonLordDoomAvailable(action, result)
        local actor = action and action.actor
        local doom = action and (action.greaterDoom or action.lesserDoom or action.doom or action.attackDoom)
        if not (actor and doom and self:isDungeonLord(actor)) then
            return true
        end
        local poolId = self:getDungeonLordDoomPoolId(actor, doom, action)
        if not poolId then
            return true
        end
        local pool = self:getDungeonLordPoolState(actor, poolId)
        if not (pool and pool.defeated) then
            return true
        end
        result.success = false
        result.description = (pool.name or poolId) .. " has been defeated and cannot use that doom."
        result.effects[#result.effects + 1] = "dungeon_lord_pool_doom_blocked"
        result.effects[#result.effects + 1] = "dungeon_lord_" .. poolId .. "_defeated"
        action.result = result
        return false
    end

    function resolver:targetQualifiesForLionRoarOfLife(target, action)
        if not target then
            return false
        end
        local conditions = target.conditions or {}
        if not (conditions.dead or target.dead or target.destroyed or target.defeated) then
            return false
        end
        return action.sinless == true or action.diedWithoutSin == true or action.cleansedOfSin == true or
            target.sinless == true or target.diedWithoutSin == true or target.cleansedOfSin == true or
            conditions.sinless == true or conditions.died_without_sin == true or conditions.cleansed_of_sin == true or
            target.isChild == true or target.child == true or conditions.child == true
    end

    function resolver:reviveWithLionRoar(target, action)
        target.conditions = target.conditions or {}
        target.conditions.dead = false
        target.conditions.deaths_door = false
        target.conditions.out_of_action = false
        target.dead = false
        target.destroyed = false
        target.defeated = false

        if target.isPC then
            target.conditions.staggered = false
            target.conditions.injured = false
        else
            if target.npcHealth ~= nil then
                target.npcHealth = math.max(target.npcHealth or 0,
                    math.min(target.npcMaxHealth or action.restoredHealth or 1, action.restoredHealth or 1))
            elseif target.health ~= nil then
                target.health = math.max(target.health or 0,
                    math.min(target.maxHealth or action.restoredHealth or 1, action.restoredHealth or 1))
            end
        end

        target.revivedByLionRoar = {
            source = "lion_roar_of_life",
            lion = action.actor,
            lionId = action.actor and action.actor.id,
            sinless = true,
        }
        return target.revivedByLionRoar
    end

    function resolver:resolveLionRoarOfLife(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target

        if not self:isLion(actor) then
            result.success = false
            result.description = "Roar of Life requires a lion."
            result.effects[#result.effects + 1] = "lion_roar_of_life_blocked"
            return result
        end
        if not self:lionGreaterDoomReady(action, "revive_sinless_dead", "roar_of_life") then
            result.success = false
            result.description = "Lion Roar of Life requires a greater doom."
            result.effects[#result.effects + 1] = "lion_roar_of_life_requires_greater_doom"
            return result
        end
        if not target then
            result.success = false
            result.description = "Roar of Life needs a dead target."
            result.effects[#result.effects + 1] = "lion_roar_of_life_missing_target"
            return result
        end
        if not self:targetQualifiesForLionRoarOfLife(target, action) then
            result.success = false
            result.description = "Roar of Life can only revive a creature that died without sin."
            result.effects[#result.effects + 1] = "lion_roar_of_life_requires_sinless_dead"
            return result
        end

        result.revival = self:reviveWithLionRoar(target, action)
        result.success = true
        result.cardless = true
        result.effects[#result.effects + 1] = "lion_roar_of_life"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "revived"
        result.effects[#result.effects + 1] = "sinless_dead_revived"
        result.greaterDoom = {
            name = action.greaterDoom and action.greaterDoom.name or "Roar of Life",
            card = action.greaterDoomCard,
        }
        result.description = (actor.name or "Lion") .. " roars " ..
            (target.name or "the sinless dead") .. " back to life."

        self.eventBus:emit("lion_roar_of_life", {
            actor = actor,
            target = target,
            revival = result.revival,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:isMimicTarget(entity)
        return entity and (entity.isMimic == true or entity.mimic ~= nil or entityHasNormalizedTag(entity, "mimic"))
    end

    function resolver:isCamouflagedMimic(entity)
        if not self:isMimicTarget(entity) then
            return false
        end
        if entity.mimic and entity.mimic.camouflagedAsObject == false then
            return false
        end
        if entity.camouflagedAsObject == false or entity.awake == true then
            return false
        end
        return entity.camouflagedAsObject == true or entity.objectCamouflage == true or
            (entity.mimic and entity.mimic.camouflagedAsObject ~= false)
    end

    function resolver:isMimicCamouflageInteraction(action, actionType)
        action = action or {}
        if actionType == M.ACTION_TYPES.MIMIC_CAMOUFLAGE_INTERACTION or
           action.interactWithCamouflagedMimic == true or action.mimicCamouflageInteraction == true then
            return true
        end
        return actionType == M.ACTION_TYPES.INTERACT and self:isCamouflagedMimic(action.target)
    end

    function resolver:resolveMimicCamouflageInteraction(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target

        if not actor then
            result.success = false
            result.description = "No actor to interact with the camouflaged mimic."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isCamouflagedMimic(target) then
            result.success = false
            result.description = "No camouflaged mimic to interact with."
            result.effects[#result.effects + 1] = "mimic_camouflage_missing"
            return result
        end
        if not action.card then
            result.success = false
            result.description = "Interacting with a camouflaged mimic requires a Cups test."
            result.effects[#result.effects + 1] = "mimic_camouflage_requires_cups_test"
            return result
        end

        local cardValue = tonumber(action.card.value) or 0
        local cups = tonumber(action.cupsBonus or action.actorCups or actor.cups) or 0
        local difficulty = tonumber(action.difficulty or action.targetNumber or action.testDifficulty) or 10
        result.cardValue = cardValue
        result.modifier = cups
        result.testValue = cardValue + cups
        result.difficulty = difficulty
        result.testAttribute = "cups"
        result.target = target

        if result.testValue >= difficulty then
            result.success = true
            result.effects[#result.effects + 1] = "mimic_camouflage_detected"
            result.effects[#result.effects + 1] = "mimic_interaction_avoided"
            result.description = (actor.name or "Adventurer") ..
                " pulls back before the camouflaged mimic wakes."
            target.mimicCamouflageDetectedBy = actor
            self.eventBus:emit("mimic_camouflage_interaction", {
                actor = actor,
                target = target,
                action = action,
                result = result,
                ambush = false,
            })
            action.result = result
            return result
        end

        result.success = false
        result.damageDealt = 1
        result.ambush = true
        result.challengeMayProceed = true
        result.effects[#result.effects + 1] = "mimic_camouflage_ambush"
        result.effects[#result.effects + 1] = "mimic_wakes"
        result.effects[#result.effects + 1] = "piercing"
        result.description = (target.name or "Mimic") .. " wakes and ambushes " ..
            (actor.name or "the interactor") .. "."

        target.awake = true
        target.camouflagedAsObject = false
        if type(target.mimic) == "table" then
            target.mimic.awake = true
            target.mimic.disturbed = true
            target.mimic.camouflagedAsObject = false
        end

        self:applyDamage(actor, 1, result.effects, nil, action.allEntities, nil, {
            source = "mimic_camouflage_ambush",
            action = action,
        })
        self.eventBus:emit("mimic_camouflage_interaction", {
            actor = actor,
            target = target,
            action = action,
            result = result,
            ambush = true,
        })

        action.result = result
        return result
    end

    function resolver:mimicRequiresExceedInitiative(entity)
        if not self:isMimicTarget(entity) then
            return false
        end
        if entity.mimic and entity.mimic.mustExceedInitiative == false then
            return false
        end
        return true
    end

    function resolver:isAnimateStatue(entity)
        return entity and (entity.animateStatue ~= nil or entityHasNormalizedTag(entity, "animate_statue"))
    end

    function resolver:getAnimateStatueSensedMagic(actor, subjects)
        if not self:isAnimateStatue(actor) then
            return {}
        end
        return getMagicSightSubjects(subjects)
    end

    function resolver:isObjectTargetingMagic(action, spell, target)
        if action and (action.objectTargetingMagic or action.targetsObjectMagic or action.targetAsObjectMagic or
           action.gmAllowsObjectTargetingMagic) then
            return true
        end
        if spell and (spell.objectTargetingMagic or spell.targetsObjectsOnly or spell.targetMode == "object") then
            return true
        end
        return target and target.isItem == true
    end

    function resolver:isAnimateStatueMagicNullBlocked(target, spell, action)
        if not self:isAnimateStatue(target) then
            return false
        end
        local magicNull = target.animateStatue and target.animateStatue.magicNull
        if magicNull and magicNull.immuneToMagic == false then
            return false
        end
        return not self:isObjectTargetingMagic(action, spell, target)
    end

    function resolver:getConstructNotchWounds(target)
        if self:isMimicTarget(target) then
            return target.mimic and target.mimic.treatsNotchesAsWounds or 2,
                "mimic_construct_notch_wounds",
                "mimic_notched",
                "mimic"
        end
        if self:isAnimateStatue(target) then
            return target.animateStatue and target.animateStatue.treatsNotchesAsWounds or 2,
                "animate_statue_construct_notch_wounds",
                "animate_statue_notched",
                "animate statue"
        end
        if target and target.construct and target.treatsNotchesAsWounds then
            return target.treatsNotchesAsWounds,
                "construct_notch_wounds",
                "construct_notched",
                "construct"
        end
        return nil
    end

    function resolver:getAnimateStatueDoomEffect(action, effectType, doomKey)
        if not (action and self:isAnimateStatue(action.actor)) then
            return nil, nil
        end
        local doom = action[doomKey or "lesserDoom"] or action.doom
        local effect = doom and doom.effect
        if effect and effect.type == effectType then
            return effect, doom
        end
        return nil, nil
    end

    function resolver:isAnimateStatueGrabRoughhouse(action, effect)
        if effect ~= "grab" then
            return false
        end
        local doomEffect = self:getAnimateStatueDoomEffect(action, "roughhouse_grab", "lesserDoom")
        return doomEffect ~= nil or action.animateStatueGrab == true
    end

    function resolver:getActiveAnimateStatueGrabbedTargets(statue)
        local targets = {}
        for _, target in ipairs(statue and statue.animateStatueGrabbedTargets or {}) do
            local conditions = target.conditions or {}
            if target.animateStatueGrabbedBy == statue and not conditions.dead and not conditions.deaths_door then
                targets[#targets + 1] = target
            end
        end
        return targets
    end

    function resolver:releaseAnimateStatueGrab(statue, victim, reason)
        statue = statue or (victim and victim.animateStatueGrabbedBy)
        if not victim then
            return nil
        end

        if victim.conditions and (victim.animateStatueGrabbedBy or victim.rootedBy == "animate_statue_grab") then
            victim.conditions.rooted = false
        end
        victim.animateStatueGrabbedBy = nil
        victim.animateStatueGrabbedById = nil
        victim.animateStatueGrabbedByName = nil
        victim.animateStatueGrabMovesWith = nil
        if victim.rootedBy == "animate_statue_grab" then
            victim.rootedBy = nil
        end

        if statue and statue.animateStatueGrabbedTargets then
            for i = #statue.animateStatueGrabbedTargets, 1, -1 do
                if statue.animateStatueGrabbedTargets[i] == victim then
                    table.remove(statue.animateStatueGrabbedTargets, i)
                end
            end
        end

        return {
            statue = statue,
            victim = victim,
            reason = reason or "released",
        }
    end

    function resolver:applyAnimateStatueGrabMove(actor, oldZone, newZone, action, result)
        if not self:isAnimateStatue(actor) or not newZone then
            return {}
        end

        local moved = {}
        for _, victim in ipairs(self:getActiveAnimateStatueGrabbedTargets(actor)) do
            if victim.animateStatueGrabMovesWith ~= false then
                local victimOldZone = victim.zone
                if self.zoneSystem and victim.id then
                    self.zoneSystem:placeEntity(victim.id, newZone)
                end
                victim.zone = newZone
                moved[#moved + 1] = {
                    victim = victim,
                    oldZone = victimOldZone,
                    newZone = newZone,
                }
                self.eventBus:emit("entity_zone_changed", {
                    entity = victim,
                    oldZone = victimOldZone or oldZone,
                    newZone = newZone,
                    reason = "animate_statue_grab",
                })
            end
        end

        if #moved > 0 then
            result.animateStatueGrabMovedVictims = moved
            result.effects[#result.effects + 1] = "animate_statue_grab_victims_moved"
        end
        return moved
    end

    function resolver:redirectMissedAttackToAnimateStatueGrabbedTarget(action, result, opts)
        opts = opts or {}
        local statue = action and action.target
        if not self:isAnimateStatue(statue) then
            return false
        end
        local grabbed = self:getActiveAnimateStatueGrabbedTargets(statue)
        local victim = opts.victim or action.redirectGrabbedTarget or action.grabbedRedirectTarget or grabbed[1]
        if not victim then
            return false
        end

        local damage = opts.damage or action.animateStatueGrabRedirectDamage or 1
        result.animateStatueGrabRedirect = {
            statue = statue,
            victim = victim,
            damage = damage,
        }
        result.effects[#result.effects + 1] = "animate_statue_missed_attack_redirected"
        result.effects[#result.effects + 1] = "miss_redirected_to_grabbed_target"
        result.description = (result.description or "Miss!") .. " The missed Attack hits a grabbed adventurer."

        if damage > 0 then
            self:applyDamage(victim, damage, result.effects, action.weapon, action.allEntities,
                self:getActionWoundOptions(action, victim), {
                    source = "animate_statue_grab_missed_attack",
                    action = action,
                    useAegis = action.useAegis,
                })
        end

        return true
    end

    function resolver:resolveAnimateStatueGrab(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target
        local effect = self:getAnimateStatueDoomEffect(action, "roughhouse_grab", "lesserDoom") or {}
        local capacity = action.holdCapacity or effect.holdCapacity or
            actor and actor.animateStatue and actor.animateStatue.grab and actor.animateStatue.grab.holdCapacity or 2

        if not (actor and self:isAnimateStatue(actor)) then
            result.success = false
            result.description = "Grab requires an animate statue."
            result.effects[#result.effects + 1] = "animate_statue_grab_requires_statue"
            return result
        end
        if not target then
            result.success = false
            result.description = "No target to grab."
            result.effects[#result.effects + 1] = "animate_statue_grab_no_target"
            return result
        end
        if #self:getActiveAnimateStatueGrabbedTargets(actor) >= capacity then
            result.success = false
            result.description = "Animate statue is already holding its limit."
            result.effects[#result.effects + 1] = "animate_statue_grab_capacity_full"
            return result
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = false,
        })
        if contest.dodged then
            return result
        end

        if result.success then
            self:applyRooted(target, { action = action, reason = "animate_statue_grab" })
            actor.animateStatueGrabbedTargets = actor.animateStatueGrabbedTargets or {}
            actor.animateStatueGrabbedTargets[#actor.animateStatueGrabbedTargets + 1] = target
            target.animateStatueGrabbedBy = actor
            target.animateStatueGrabbedById = actor.id
            target.animateStatueGrabbedByName = actor.name
            target.animateStatueGrabMovesWith = effect.targetMovesWithActor ~= false
            target.rootedBy = "animate_statue_grab"

            result.description = "Grabbed! Target is Rooted and moves with the animate statue."
            result.effects[#result.effects + 1] = "animate_statue_grab"
            result.effects[#result.effects + 1] = "rooted"
            result.effects[#result.effects + 1] = "target_moves_with_animate_statue"
            result.grabbedTarget = target
        else
            result.description = "Failed to grab!"
        end

        self:appendRoughhouseRiposte(action, result, contest)
        return result
    end

    function resolver:applyAnimateStatueThrowStones(action, result, effect, doom)
        local actor = action and action.actor
        if not self:isAnimateStatue(actor) then
            return nil
        end

        result.effects[#result.effects + 1] = "animate_statue_throw_stones"
        result.effects[#result.effects + 1] = "throw_heavy_object"
        local thrown = action.thrownHeldTarget or action.thrownGrabbedTarget or action.thrownTarget
        if not thrown or thrown.animateStatueGrabbedBy ~= actor then
            return nil
        end

        self:releaseAnimateStatueGrab(actor, thrown, "throw_stones")
        self:applyDamage(thrown, effect.thrownHeldFoeWounds or 1, result.effects, action.weapon, action.allEntities,
            self:getActionWoundOptions(action, thrown), {
                source = "animate_statue_throw_stones",
                action = action,
                useAegis = action.useAegis,
            })
        result.thrownHeldTarget = thrown
        result.effects[#result.effects + 1] = "thrown_held_foe_wounded"
        result.description = (result.description or "") .. (doom and doom.name or "Throw Stones") ..
            " throws a held adventurer. "
        return thrown
    end

    function resolver:resolveAnimateStatueSqueeze(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local effect, doom = self:getAnimateStatueDoomEffect(action, "wound_grabbed_targets", "greaterDoom")
        effect = effect or {}

        if not (actor and self:isAnimateStatue(actor)) then
            result.success = false
            result.description = "Squeeze requires an animate statue."
            result.effects[#result.effects + 1] = "animate_statue_squeeze_requires_statue"
            return result
        end
        if not (action.greaterDoom or action.useGreaterDoom or action.cardlessGreaterDoom) then
            result.success = false
            result.description = "Animate Statue Squeeze requires a greater doom."
            result.effects[#result.effects + 1] = "animate_statue_squeeze_requires_greater_doom"
            return result
        end

        local targets = self:getActiveAnimateStatueGrabbedTargets(actor)
        if #targets == 0 then
            result.success = false
            result.description = "No grabbed adventurers to squeeze."
            result.effects[#result.effects + 1] = "animate_statue_squeeze_no_targets"
            return result
        end

        local wounds = action.wounds or effect.wounds or 1
        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.squeezedTargets = {}
        result.effects[#result.effects + 1] = "animate_statue_squeeze"
        result.effects[#result.effects + 1] = "greater_doom"
        for _, target in ipairs(targets) do
            self:applyDamage(target, wounds, result.effects, action.weapon, action.allEntities,
                self:getActionWoundOptions(action, target), {
                    source = "animate_statue_squeeze",
                    action = action,
                    useAegis = action.useAegis,
                })
            result.squeezedTargets[#result.squeezedTargets + 1] = target
        end
        result.description = (actor.name or "Animate statue") .. " squeezes " ..
            tostring(#targets) .. " grabbed adventurer(s)."
        result.greaterDoom = doom
        action.result = result
        return result
    end

    function resolver:targetRequiresExceedInitiative(entity, action)
        if not entity then
            return false
        end
        if self:mimicRequiresExceedInitiative(entity) then
            return true
        end
        if entity.mustExceedInitiative or entity.toughRequiresExceedInitiative then
            return true
        end
        if entity.skeleton and entity.skeleton.mustExceedInitiative then
            return true
        end
        if entity.ogre and entity.ogre.mustExceedInitiative then
            return true
        end
        if entity.dragon and entity.dragon.tough and entity.dragon.tough.mustExceedInitiative then
            return true
        end
        if self:isAnimateStatue(entity) and
           entity.animateStatue and entity.animateStatue.tough and entity.animateStatue.tough.mustExceedInitiative then
            return true
        end
        if self:isTitanSporehulk(entity) and self:getTitanActionTargetSection(action) == "torso" then
            local torso = entity.titan and entity.titan.sections and entity.titan.sections.torso
            return torso and torso.notes and torso.notes.toughMustExceedInitiative == true
        end
        return false
    end

    function resolver:getExceedInitiativeEffect(entity, action)
        if self:isMimicTarget(entity) then
            return "mimic_tough_requires_exceed"
        end
        if entity and (entity.skeleton or entityHasNormalizedTag(entity, "skeleton")) then
            return "skeleton_fleshless_requires_exceed"
        end
        if entity and (entity.ogre or entityHasNormalizedTag(entity, "ogre")) then
            return "ogre_tough_requires_exceed"
        end
        if entity and (entity.dragon or entityHasNormalizedTag(entity, "dragon")) then
            return "dragon_tough_requires_exceed"
        end
        if self:isAnimateStatue(entity) then
            return "animate_statue_tough_requires_exceed"
        end
        if self:isTitanSporehulk(entity) and self:getTitanActionTargetSection(action) == "torso" then
            return "titan_torso_tough_requires_exceed"
        end
        return "requires_exceed_initiative"
    end

    function resolver:isOgre(entity)
        return entity and (entity.ogre ~= nil or entityHasNormalizedTag(entity, "ogre"))
    end

    function resolver:isDragon(entity)
        return entity and (entity.dragon ~= nil or entityHasNormalizedTag(entity, "dragon"))
    end

    function resolver:isTitanSporehulk(entity)
        return entity and (entity.titan ~= nil or entityHasNormalizedTag(entity, "sporehulk"))
    end

    function resolver:getTitanActionTargetSection(action)
        if not action then
            return nil
        end
        if action.targetRune or action.runeOfProtection or action.attackRune then
            return "torso"
        end

        local section = action.targetSection or action.section or action.titanSection or action.targetPart
        section = normalizeTalentKey(section)
        if section == "leftarm" then
            return "left_arm"
        end
        if section == "rightarm" then
            return "right_arm"
        end
        if section == "leg" then
            return "legs"
        end
        if section == "arm" then
            return action.armSection or "left_arm"
        end
        if section == "rune" or section == "rune_of_protection" then
            return "torso"
        end
        if section == "legs" or section == "left_arm" or section == "right_arm" or section == "torso" then
            return section
        end
        return nil
    end

    function resolver:isTitanRuneTarget(action)
        if not action then
            return false
        end
        local section = normalizeTalentKey(action.targetSection or action.section or action.titanSection or action.targetPart)
        return action.targetRune == true or action.runeOfProtection == true or action.attackRune == true or
            section == "rune" or section == "rune_of_protection"
    end

    function resolver:ensureTitanSectionState(entity)
        if not self:isTitanSporehulk(entity) then
            return nil
        end
        if entity.titanSections then
            return entity.titanSections
        end

        entity.titanSections = {}
        local sections = entity.titan and entity.titan.sections or {}
        for sectionId, section in pairs(sections) do
            entity.titanSections[sectionId] = {
                id = sectionId,
                name = section.name or sectionId,
                health = section.health or 0,
                defense = section.defense or 0,
                maxHealth = section.health or 0,
                maxDefense = section.defense or 0,
                defeated = false,
                source = section,
            }
        end
        return entity.titanSections
    end

    function resolver:getTitanSectionState(entity, sectionId)
        local sections = self:ensureTitanSectionState(entity)
        if not sections then
            return nil
        end
        sectionId = sectionId or "torso"
        return sections[sectionId]
    end

    function resolver:titanRuneProtectionActive(entity)
        if not self:isTitanSporehulk(entity) then
            return false
        end
        local rune = entity.titan and entity.titan.runeOfProtection
        return rune and rune.damageImmuneUntilDestroyed and not (entity.titanRuneDestroyed or rune.destroyed)
    end

    function resolver:markTitanSectionDefeated(entity, sectionId, effects)
        local section = self:getTitanSectionState(entity, sectionId)
        if not section or section.defeated then
            return
        end

        section.defeated = true
        effects[#effects + 1] = "titan_section_defeated"
        effects[#effects + 1] = "titan_" .. sectionId .. "_defeated"

        if sectionId == "legs" then
            entity.titanLegsDefeated = true
            entity.cannotDash = true
            entity.conditions = entity.conditions or {}
            entity.conditions.crumpled = true
            entity.conditions.kneeling = true
            effects[#effects + 1] = "titan_sporehulk_crumpled"
        elseif sectionId == "torso" then
            entity.titanTorsoDefeated = true
            entity.conditions = entity.conditions or {}
            entity.conditions.deaths_door = true
            effects[#effects + 1] = "titan_torso_defeated"
        end
    end

    function resolver:applyTitanSectionDamage(entity, sectionId, amount, effects, opts)
        opts = opts or {}
        effects = effects or {}
        sectionId = sectionId or "torso"
        local section = self:getTitanSectionState(entity, sectionId)
        if not section then
            return nil
        end

        local damageType = normalizeTalentKey(opts.damageType or "normal")
        local bypassDefense = opts.bypassDefense == true or damageType == "piercing" or damageType == "critical"
        local lastResult = nil

        for _ = 1, amount or 1 do
            if not bypassDefense and section.defense and section.defense > 0 then
                section.defense = section.defense - 1
                lastResult = "section_defense_reduced"
            elseif section.health and section.health > 0 then
                section.health = section.health - 1
                lastResult = "section_health_reduced"
            else
                lastResult = "section_defeated"
            end
        end

        if sectionId == "torso" then
            entity.npcHealth = section.health
            entity.npcDefense = section.defense
        end

        if section.health <= 0 then
            self:markTitanSectionDefeated(entity, sectionId, effects)
            lastResult = "section_defeated"
        end

        effects[#effects + 1] = "titan_section_damage"
        effects[#effects + 1] = "titan_" .. sectionId .. "_damage"
        return {
            result = lastResult,
            titanSection = sectionId,
            section = section,
            damageApplied = true,
        }
    end

    function resolver:resolveTitanRuneAttack(entity, amount, effects, weapon, damageContext)
        local action = damageContext and damageContext.action or {}
        local actor = action.actor
        local actionType = self:normalizeActionType(action.type)
        if actionType == M.ACTION_TYPES.MELEE then
            local climbingThisTitan = actor and (actor.climbingSporehulk == entity or
                actor.climbingSporehulkId == entity.id)
            if not (climbingThisTitan and actor.sporehulkClimbSection == "torso") then
                effects[#effects + 1] = "titan_rune_melee_requires_torso_climb"
                return {
                    result = "blocked",
                    blocked = true,
                    reason = "titan_rune_melee_requires_torso_climb",
                }
            end
        end

        entity.titanRuneDestroyed = true
        if entity.titan and entity.titan.runeOfProtection then
            entity.titan.runeOfProtection.destroyed = true
        end
        effects[#effects + 1] = "titan_rune_destroyed"
        effects[#effects + 1] = "titan_rune_protection_ended"

        local wounds = entity.titan and entity.titan.runeOfProtection and
            entity.titan.runeOfProtection.successfulAttackDealsTorsoWound or 1
        local result = self:applyTitanSectionDamage(entity, "torso", wounds, effects, {
            damageType = "normal",
        })
        result.runeDestroyed = true
        return result
    end

    function resolver:resolveTitanSporehulkDamage(entity, amount, effects, weapon, damageContext)
        if not self:isTitanSporehulk(entity) then
            return nil
        end

        local action = damageContext and damageContext.action or {}
        if self:isTitanRuneTarget(action) then
            return self:resolveTitanRuneAttack(entity, amount, effects, weapon, damageContext)
        end

        if self:titanRuneProtectionActive(entity) then
            effects[#effects + 1] = "titan_rune_protection_immune"
            return {
                result = "immune",
                immune = true,
                reason = "titan_rune_protection",
            }
        end

        local damageType = "normal"
        for _, effect in ipairs(effects or {}) do
            if effect == "critical" then
                damageType = "critical"
                break
            elseif effect == "piercing" or effect == "pierce_armor" then
                damageType = "piercing"
            end
        end

        local sectionId = self:getTitanActionTargetSection(action) or "torso"
        return self:applyTitanSectionDamage(entity, sectionId, amount or 1, effects, {
            damageType = damageType,
        })
    end

    function resolver:isMetalArmorItem(item)
        if not item or not item.isArmor then
            return false
        end

        local props = item.properties or {}
        local armorType = normalizeTalentKey(item.armorType or props.armorType or item.type or props.type)
        return item.metal == true or props.metal == true or props.iron == true or props.latentIron == true or
            armorType == "iron" or armorType == "steel" or armorType == "mail" or armorType == "chainmail" or
            armorType == "plate"
    end

    function resolver:isSwimSneakBlockingArmorItem(item)
        if not item then
            return false
        end

        local props = item.properties or {}
        local armorType = normalizeTalentKey(item.armorType or props.armorType or item.type or props.type)
        return item.isArmor == true and (armorType == "iron" or armorType == "steel" or
            props.blocksSneak == true or props.blocksSwim == true)
    end

    function resolver:entityWearsSwimSneakBlockingArmor(entity)
        if not entity then
            return false
        end

        local armorType = normalizeTalentKey(entity.armorType or entity.wornArmorType or entity.armorMaterial)
        if entity.ironArmor == true or entity.steelArmor == true or entity.heavyArmorBlocksMovement == true or
           armorType == "iron" or armorType == "steel" then
            return true
        end

        if entity.inventory and entity.inventory.getItems then
            for _, item in ipairs(entity.inventory:getItems(inventory.LOCATIONS.BELT) or {}) do
                if self:isSwimSneakBlockingArmorItem(item) then
                    return true
                end
            end
        end

        return false
    end

    function resolver:isVisibleLightSourceItem(item, location)
        if not item then
            return false
        end

        local props = item.properties or {}
        if not (props.light_source == true or item.light_source == true or props.lightSource == true) then
            return false
        end
        if not (props.isLit == true or item.isLit == true or props.lit == true or item.lit == true) then
            return false
        end
        if props.darklight == true or item.darklight == true or props.stealthLight == true or item.stealthLight == true then
            return false
        end
        if props.extinguished == true or item.extinguished == true then
            return false
        end
        if location == inventory.LOCATIONS.BELT and props.provides_belt_light == false then
            return false
        end

        return true
    end

    function resolver:entityHoldsVisibleLightSource(entity)
        if not entity or not entity.inventory or not entity.inventory.getItems then
            return false
        end

        for _, location in ipairs({ inventory.LOCATIONS.HANDS, inventory.LOCATIONS.BELT }) do
            for _, item in ipairs(entity.inventory:getItems(location) or {}) do
                if self:isVisibleLightSourceItem(item, location) then
                    return true
                end
            end
        end

        return false
    end

    function resolver:targetWearsMetalArmor(entity)
        if not entity then
            return false
        end

        local armorType = normalizeTalentKey(entity.armorType or entity.wornArmorType or entity.armorMaterial)
        if entity.metalArmor == true or entity.wearsMetalArmor == true or
           armorType == "iron" or armorType == "steel" or armorType == "mail" or armorType == "chainmail" or
           armorType == "plate" then
            return true
        end

        if entity.inventory and entity.inventory.getItems then
            for _, location in ipairs({ inventory.LOCATIONS.HANDS, inventory.LOCATIONS.BELT, inventory.LOCATIONS.PACK }) do
                for _, item in ipairs(entity.inventory:getItems(location) or {}) do
                    if self:isMetalArmorItem(item) then
                        return true
                    end
                end
            end
        end

        return false
    end

    function resolver:getDragonFlightEffect(action)
        local actor = action and action.actor
        if not self:isDragon(actor) then
            return nil, nil
        end

        local doom = action.lesserDoom or action.doom
        local effect = doom and doom.effect
        if effect and effect.type == "fly_move" then
            return effect, doom
        end
        return nil, nil
    end

    function resolver:isDragonBreathOfFireAction(action)
        local actor = action and action.actor
        local doom = action and action.greaterDoom
        local effect = doom and doom.effect
        return self:isDragon(actor) and effect and effect.type == "attack_fire_breath"
    end

    function resolver:validateDragonFlight(action, result)
        local effect = self:getDragonFlightEffect(action)
        if not effect then
            return true
        end

        if effect.requiresEnoughSpace ~= false and
           (action.enoughSpace == false or action.hasEnoughSpace == false or action.roomHasEnoughSpace == false) then
            result.success = false
            result.description = "Dragon Flight requires enough space."
            result.effects[#result.effects + 1] = "dragon_flight_requires_space"
            return false
        end

        return true
    end

    function resolver:applyDragonFlight(action, result, allEntities, effect, doom)
        local actor = action and action.actor
        if not self:isDragon(actor) then
            return false
        end
        if not effect then
            effect, doom = self:getDragonFlightEffect(action)
        end
        if not effect then
            return false
        end

        actor.conditions = actor.conditions or {}
        actor.conditions.flying = true
        actor.flying = true
        actor.dragonFlight = {
            active = true,
            rangedWeaponsStillApply = effect.rangedWeaponsStillApply ~= false,
            flyByAttackAllowed = effect.flyByAttackAllowed ~= false,
            flyByAttackAllowsMeleeTargetingThisTurn = actor.dragon and actor.dragon.flight and
                actor.dragon.flight.flyByAttackAllowsMeleeTargetingThisTurn or effect.flyByAttackAllowed ~= false,
            flyByAttackDoesNotCauseEngagement = actor.dragon and actor.dragon.flight and
                actor.dragon.flight.flyByAttackDoesNotCauseEngagement or true,
            doom = doom,
        }

        self:clearAllEngagements(actor, allEntities)
        result.effects[#result.effects + 1] = "dragon_flight"
        result.effects[#result.effects + 1] = "flying"
        result.effects[#result.effects + 1] = "dragon_out_of_melee_engagement"
        if effect.rangedWeaponsStillApply ~= false then
            result.effects[#result.effects + 1] = "ranged_weapons_still_apply"
        end
        return true
    end

    function resolver:isDragonFlyByAttack(action)
        local actor = action and action.actor
        if not self:isDragon(actor) then
            return false
        end

        local conditions = actor.conditions or {}
        return action.flyByAttack == true or action.flying == true or actor.flying == true or
            conditions.flying == true
    end

    function resolver:getTitanRampageInitiative(target, action)
        if not (self:isTitanSporehulk(target) and action) then
            return nil
        end

        local doom = action.targetGreaterDoom or action.defenderGreaterDoom or action.initiativeDoom or
            action.rampageDoom
        local effect = doom and doom.effect
        local usesRampage = action.useTitanRampage == true or action.useRampage == true or
            (doom and doom.id == "rampage") or (effect and effect.type == "greater_doom_as_initiative")
        if not usesRampage then
            return nil
        end

        local card = action.targetInitiativeCard or action.defenderInitiativeCard or
            action.greaterDoomInitiativeCard or action.rampageCard
        local value = action.rampageInitiative or action.greaterDoomInitiative or
            action.defenderInitiative or (card and card.value)
        if not value then
            return nil
        end

        action.titanRampageInitiative = {
            value = value,
            card = card,
            doom = doom,
        }
        return value
    end

    function resolver:titanSectionMeleeTargetableFromGround(titan, sectionId)
        if sectionId == "legs" then
            return true
        end
        return titan and titan.titanLegsDefeated == true
    end

    function resolver:validateTitanMeleeTargeting(action, result)
        local titan = action and action.target
        if not self:isTitanSporehulk(titan) then
            return true
        end

        local sectionId = self:getTitanActionTargetSection(action)
        if not sectionId then
            return true
        end

        local actor = action.actor
        local climbingThisTitan = actor and (actor.climbingSporehulk == titan or actor.climbingSporehulkId == titan.id)
        if climbingThisTitan and actor.sporehulkClimbSection == sectionId then
            return true
        end
        if self:titanSectionMeleeTargetableFromGround(titan, sectionId) and not self:isTitanRuneTarget(action) then
            return true
        end

        result.success = false
        result.description = "Melee attacks can only target the climbed Sporehulk section."
        result.effects[#result.effects + 1] = "titan_section_melee_requires_climb"
        return false
    end

    function resolver:canClimbTitanSection(fromSection, toSection)
        fromSection = fromSection or "ground"
        local adjacent = {
            ground = { legs = true },
            legs = { ground = true, torso = true },
            torso = { legs = true, left_arm = true, right_arm = true },
            left_arm = { torso = true },
            right_arm = { torso = true },
        }
        return adjacent[fromSection] and adjacent[fromSection][toSection] == true
    end

    function resolver:resolveTitanSporehulkClimb(action, result)
        if not (action and (action.climbSporehulk or action.titanClimb or action.climbTitan)) then
            return false
        end
        local actor = action.actor
        local titan = action.target or action.titan or action.sporehulk
        if not (actor and self:isTitanSporehulk(titan)) then
            result.success = false
            result.description = "Sporehulk climb requires the titan."
            result.effects[#result.effects + 1] = "titan_climb_requires_sporehulk"
            return true
        end

        local toSection = normalizeTalentKey(action.destinationSection or action.toSection or
            action.targetSection or action.section)
        if toSection == "leftarm" then
            toSection = "left_arm"
        elseif toSection == "rightarm" then
            toSection = "right_arm"
        elseif toSection == "leg" then
            toSection = "legs"
        end

        local fromSection = actor.sporehulkClimbSection or "ground"
        if not self:canClimbTitanSection(fromSection, toSection) then
            result.success = false
            result.description = "Sporehulk climb can move only one adjacent section."
            result.effects[#result.effects + 1] = "titan_climb_invalid_section"
            return true
        end

        if toSection == "ground" then
            actor.climbingSporehulk = nil
            actor.climbingSporehulkId = nil
            actor.sporehulkClimbSection = nil
            actor.conditions = actor.conditions or {}
            actor.conditions.climbing_sporehulk = false
        else
            actor.climbingSporehulk = titan
            actor.climbingSporehulkId = titan.id
            actor.sporehulkClimbSection = toSection
            actor.conditions = actor.conditions or {}
            actor.conditions.climbing_sporehulk = true
            titan.titanClimbers = titan.titanClimbers or {}
            titan.titanClimbers[actor.id] = {
                actor = actor,
                section = toSection,
            }
        end

        result.success = true
        result.description = "Climbed to Sporehulk " .. tostring(toSection) .. "."
        result.effects[#result.effects + 1] = "titan_sporehulk_climb"
        result.effects[#result.effects + 1] = "sporehulk_section_" .. tostring(toSection)
        return true
    end

    function resolver:isTitanShakeRoughhouse(action, effect)
        local actor = action and action.actor
        local doom = action and (action.lesserDoom or action.doom)
        local doomEffect = doom and doom.effect
        return self:isTitanSporehulk(actor) and
            (effect == "shake" or (doomEffect and doomEffect.type == "roughhouse_climbers"))
    end

    function resolver:releaseTitanClimber(titan, target)
        if not target then
            return
        end
        if titan and titan.titanClimbers and target.id then
            titan.titanClimbers[target.id] = nil
        end
        target.climbingSporehulk = nil
        target.climbingSporehulkId = nil
        target.sporehulkClimbSection = nil
        target.zone = "ground"
        target.conditions = target.conditions or {}
        target.conditions.climbing_sporehulk = false
    end

    function resolver:resolveTitanShake(action, result)
        local actor = action.actor
        local doom = action.lesserDoom or action.doom
        local effect = doom and doom.effect or {}
        local targets = {}

        for _, candidate in ipairs(action.allEntities or {}) do
            if candidate ~= actor and candidate.isPC and
               (candidate.climbingSporehulk == actor or candidate.climbingSporehulkId == actor.id) then
                targets[#targets + 1] = candidate
            end
        end

        if #targets == 0 then
            result.success = false
            result.description = "No climbers to shake loose."
            result.effects[#result.effects + 1] = "titan_shake_no_climbers"
            return result
        end

        result.success = true
        result.shakeResults = {}
        result.effects[#result.effects + 1] = "titan_sporehulk_shake"
        for _, target in ipairs(targets) do
            local initiative = self:getZoneAttackTargetInitiative(action, target) or self:getTargetInitiative(target, action) or 0
            local hit = (result.testValue or 0) > initiative
            local entry = {
                target = target,
                initiative = initiative,
                hit = hit,
            }
            if hit then
                self:releaseTitanClimber(actor, target)
                target.conditions = target.conditions or {}
                target.conditions.prone = true
                result.effects[#result.effects + 1] = "titan_climber_shaken_loose"
                result.effects[#result.effects + 1] = "prone"
                local damageEffects = { "piercing", "titan_sporehulk_shake_fall" }
                self:applyDamage(target, 1, damageEffects, nil, action.allEntities,
                    self:getActionWoundOptions(action, target), {
                        source = "titan_sporehulk_shake",
                        action = action,
                    })
                entry.damageEffects = damageEffects
            end
            result.shakeResults[#result.shakeResults + 1] = entry
        end

        result.description = (doom and doom.name or "Shake") .. " shakes " ..
            tostring(#targets) .. " climber(s)."
        return result
    end

    function resolver:getTitanArmSection(action, doom)
        local section = normalizeTalentKey(action and (action.armSection or action.titanArmSection or
            action.sourceSection or action.doomSection or action.section) or doom and doom.section)
        if section == "right" or section == "rightarm" or section == "right_arm" then
            return "right_arm"
        end
        if section == "left" or section == "leftarm" or section == "left_arm" then
            return "left_arm"
        end
        if section == "arm" then
            local side = normalizeTalentKey(action and (action.armSide or action.arm or action.titanArm))
            if side == "right" then
                return "right_arm"
            end
            return "left_arm"
        end
        return section == "" and "left_arm" or section
    end

    function resolver:getTitanDoomSection(action, doom)
        local section = normalizeTalentKey(action and (action.sourceSection or action.doomSection or
            action.titanSection or action.section) or doom and doom.section)
        if section == "arm" or section == "left" or section == "right" or
           section == "leftarm" or section == "rightarm" then
            return self:getTitanArmSection(action, doom)
        end
        if section == "leg" then
            return "legs"
        end
        if section == "" then
            return nil
        end
        return section
    end

    function resolver:titanSectionCanUseDoom(entity, doom, action)
        if not self:isTitanSporehulk(entity) then
            return true
        end
        local sectionId = self:getTitanDoomSection(action, doom)
        if not sectionId then
            return true
        end
        local section = self:getTitanSectionState(entity, sectionId)
        return section == nil or not (section.defeated or section.disabled or section.entangled)
    end

    function resolver:validateTitanDoomAvailable(action, result)
        local actor = action and action.actor
        local doom = action and (action.greaterDoom or action.lesserDoom or action.doom or action.attackDoom)
        if not (actor and doom and self:isTitanSporehulk(actor)) then
            return true
        end
        local sectionId = self:getTitanDoomSection(action, doom)
        local section = sectionId and self:getTitanSectionState(actor, sectionId) or nil
        if not (section and (section.defeated or section.disabled or section.entangled)) then
            return true
        end
        result.success = false
        result.description = (section.name or sectionId) .. " cannot use that Sporehulk doom."
        result.effects[#result.effects + 1] = "titan_section_doom_blocked"
        result.effects[#result.effects + 1] = "titan_" .. sectionId .. "_doom_blocked"
        action.result = result
        return false
    end

    function resolver:greaterDoomAllowsChallengeAction(action)
        local doom = action and action.greaterDoom
        local effect = doom and doom.effect
        return effect and effect.type == "greater_doom_attack_action" and self:isTitanSporehulk(action.actor)
    end

    function resolver:isTitanGrabRoughhouse(action, effect)
        local actor = action and action.actor
        local doom = action and (action.lesserDoom or action.doom)
        local doomEffect = doom and doom.effect
        return self:isTitanSporehulk(actor) and
            (effect == "grab" or action.titanGrab == true or
                (doomEffect and doomEffect.type == "roughhouse_grab"))
    end

    function resolver:getActiveTitanGrabbedTargets(titan, sectionId)
        local targets = {}
        for _, target in ipairs(titan and titan.titanGrabbedTargets or {}) do
            local conditions = target.conditions or {}
            if target.titanGrabbedBy == titan and not conditions.dead and not conditions.deaths_door and
               (not sectionId or target.titanGrabSection == sectionId) then
                targets[#targets + 1] = target
            end
        end
        return targets
    end

    function resolver:releaseTitanGrab(titan, victim, reason)
        titan = titan or (victim and victim.titanGrabbedBy)
        if not victim then
            return nil
        end
        if victim.conditions and (victim.titanGrabbedBy or victim.rootedBy == "titan_sporehulk_grab") then
            victim.conditions.rooted = false
        end
        victim.titanGrabbedBy = nil
        victim.titanGrabbedById = nil
        victim.titanGrabbedByName = nil
        victim.titanGrabMovesWith = nil
        victim.titanGrabSection = nil
        if victim.rootedBy == "titan_sporehulk_grab" then
            victim.rootedBy = nil
        end
        if titan and titan.titanGrabbedTargets then
            for index = #titan.titanGrabbedTargets, 1, -1 do
                if titan.titanGrabbedTargets[index] == victim then
                    table.remove(titan.titanGrabbedTargets, index)
                end
            end
        end
        return {
            titan = titan,
            victim = victim,
            reason = reason or "released",
        }
    end

    function resolver:applyTitanGrabMove(actor, oldZone, newZone, action, result)
        if not self:isTitanSporehulk(actor) or not newZone then
            return {}
        end
        local moved = {}
        for _, victim in ipairs(self:getActiveTitanGrabbedTargets(actor)) do
            if victim.titanGrabMovesWith ~= false then
                local victimOldZone = victim.zone
                if self.zoneSystem and victim.id then
                    self.zoneSystem:placeEntity(victim.id, newZone)
                end
                victim.zone = newZone
                moved[#moved + 1] = {
                    victim = victim,
                    oldZone = victimOldZone,
                    newZone = newZone,
                }
                self.eventBus:emit("entity_zone_changed", {
                    entity = victim,
                    oldZone = victimOldZone or oldZone,
                    newZone = newZone,
                    reason = "titan_sporehulk_grab",
                })
            end
        end
        if #moved > 0 then
            result.titanGrabMovedVictims = moved
            result.effects[#result.effects + 1] = "titan_grab_victims_moved"
        end
        return moved
    end

    function resolver:redirectMissedAttackToTitanGrabbedTarget(action, result, opts)
        opts = opts or {}
        local titan = action and action.target
        if not self:isTitanSporehulk(titan) then
            return false
        end
        local grabbed = self:getActiveTitanGrabbedTargets(titan)
        local victim = opts.victim or action.redirectGrabbedTarget or action.grabbedRedirectTarget or grabbed[1]
        if not victim then
            return false
        end
        local damage = opts.damage or action.titanGrabRedirectDamage or 1
        result.titanGrabRedirect = {
            titan = titan,
            victim = victim,
            damage = damage,
        }
        result.effects[#result.effects + 1] = "titan_missed_attack_redirected"
        result.effects[#result.effects + 1] = "miss_redirected_to_grabbed_foe"
        result.description = (result.description or "Miss!") .. " The missed Attack hits a grabbed adventurer."
        if damage > 0 then
            self:applyDamage(victim, damage, result.effects, action.weapon, action.allEntities,
                self:getActionWoundOptions(action, victim), {
                    source = "titan_sporehulk_grab_missed_attack",
                    action = action,
                    useAegis = action.useAegis,
                })
        end
        return true
    end

    function resolver:resolveTitanGrab(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target
        local doom = action.lesserDoom or action.doom
        local effect = doom and doom.effect or {}
        local sectionId = self:getTitanArmSection(action, doom)
        local capacity = action.holdCapacity or effect.holdCapacity or 2

        if not (actor and self:isTitanSporehulk(actor)) then
            result.success = false
            result.description = "Grab requires the Sporehulk."
            result.effects[#result.effects + 1] = "titan_grab_requires_sporehulk"
            return result
        end
        if not target then
            result.success = false
            result.description = "No target to grab."
            result.effects[#result.effects + 1] = "titan_grab_no_target"
            return result
        end
        if not self:titanSectionCanUseDoom(actor, doom, action) then
            result.success = false
            result.description = "That Sporehulk section cannot Grab."
            result.effects[#result.effects + 1] = "titan_section_doom_blocked"
            result.effects[#result.effects + 1] = "titan_" .. tostring(sectionId) .. "_doom_blocked"
            return result
        end
        if #self:getActiveTitanGrabbedTargets(actor) >= capacity then
            result.success = false
            result.description = "The Sporehulk is already holding its limit."
            result.effects[#result.effects + 1] = "titan_grab_capacity_full"
            return result
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = false,
        })
        if contest.dodged then
            return result
        end

        if result.success then
            self:applyRooted(target, { action = action, reason = "titan_sporehulk_grab" })
            actor.titanGrabbedTargets = actor.titanGrabbedTargets or {}
            actor.titanGrabbedTargets[#actor.titanGrabbedTargets + 1] = target
            target.titanGrabbedBy = actor
            target.titanGrabbedById = actor.id
            target.titanGrabbedByName = actor.name
            target.titanGrabMovesWith = effect.movesWithSource ~= false
            target.titanGrabSection = sectionId
            target.rootedBy = "titan_sporehulk_grab"

            result.description = "Grabbed! Target is Rooted and moves with the Sporehulk."
            result.effects[#result.effects + 1] = "titan_sporehulk_grab"
            result.effects[#result.effects + 1] = "rooted"
            result.effects[#result.effects + 1] = "target_moves_with_titan"
            result.effects[#result.effects + 1] = "missed_attacks_hit_grabbed_foe"
            result.grabbedTarget = target
            result.titanGrabSection = sectionId
        else
            result.description = "Failed to grab!"
        end

        self:appendRoughhouseRiposte(action, result, contest)
        return result
    end

    function resolver:applyTitanThrowStones(action, result, effect, doom)
        local actor = action and action.actor
        if not self:isTitanSporehulk(actor) then
            return nil
        end
        result.effects[#result.effects + 1] = "titan_sporehulk_throw_stones"
        result.effects[#result.effects + 1] = "throw_heavy_object"
        local thrown = action.thrownHeldTarget or action.thrownGrabbedTarget or action.thrownTarget
        if not thrown or thrown.titanGrabbedBy ~= actor then
            return nil
        end

        self:releaseTitanGrab(actor, thrown, "throw_stones")
        self:applyDamage(thrown, effect.thrownHeldFoeWounds or 1, result.effects, action.weapon, action.allEntities,
            self:getActionWoundOptions(action, thrown), {
                source = "titan_sporehulk_throw_stones",
                action = action,
                useAegis = action.useAegis,
            })
        result.thrownHeldTarget = thrown
        result.effects[#result.effects + 1] = "thrown_held_foe_wounded"
        result.description = (result.description or "") .. (doom and doom.name or "Throw Stones") ..
            " throws a held adventurer. "
        return thrown
    end

    function resolver:resolveTitanSqueeze(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect or {}
        local sectionId = self:getTitanArmSection(action, doom)

        if not (actor and self:isTitanSporehulk(actor)) then
            result.success = false
            result.description = "Squeeze requires the Sporehulk."
            result.effects[#result.effects + 1] = "titan_squeeze_requires_sporehulk"
            return result
        end
        if not (action.greaterDoom or action.useGreaterDoom or action.cardlessGreaterDoom) then
            result.success = false
            result.description = "Sporehulk Squeeze requires a greater doom."
            result.effects[#result.effects + 1] = "titan_squeeze_requires_greater_doom"
            return result
        end
        if not self:titanSectionCanUseDoom(actor, doom, action) then
            result.success = false
            result.description = "That Sporehulk section cannot Squeeze."
            result.effects[#result.effects + 1] = "titan_section_doom_blocked"
            result.effects[#result.effects + 1] = "titan_" .. tostring(sectionId) .. "_doom_blocked"
            return result
        end

        local targets = self:getActiveTitanGrabbedTargets(actor)
        if #targets == 0 then
            result.success = false
            result.description = "No grabbed adventurers to squeeze."
            result.effects[#result.effects + 1] = "titan_squeeze_no_targets"
            return result
        end

        local wounds = action.wounds or effect.wounds or 1
        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.squeezedTargets = {}
        result.effects[#result.effects + 1] = "titan_sporehulk_squeeze"
        result.effects[#result.effects + 1] = "greater_doom"
        for _, target in ipairs(targets) do
            self:applyDamage(target, wounds, result.effects, action.weapon, action.allEntities,
                self:getActionWoundOptions(action, target), {
                    source = "titan_sporehulk_squeeze",
                    action = action,
                    useAegis = action.useAegis,
                })
            result.squeezedTargets[#result.squeezedTargets + 1] = target
        end
        result.description = (actor.name or "Sporehulk") .. " squeezes " ..
            tostring(#targets) .. " grabbed adventurer(s)."
        result.greaterDoom = doom
        action.result = result
        return result
    end

    function resolver:isSkeleton(entity)
        return entity and (entity.skeleton ~= nil or entityHasNormalizedTag(entity, "skeleton"))
    end

    function resolver:isSkeletonPiercingWeaponImmune(entity, weapon)
        return self:isSkeleton(entity) and weapon and M.isWeaponType(weapon, "PIERCING")
    end

    function resolver:isZombie(entity)
        return entity and (entity.zombie ~= nil or entityHasNormalizedTag(entity, "zombie"))
    end

    function resolver:undeadFearReady(action)
        local doom = action and (action.lesserDoom or action.doom)
        local effect = doom and doom.effect
        local doomPresent = doom ~= nil or (action and (action.discardedLesserDoom or
            action.useLesserDoom == true or action.undeadFear == true))
        return action and doomPresent and (
            (doom and (doom.id == "fear" or doom.id == "undead_fear")) or
            (effect and (effect.type == "undead_fear" or effect.type == "same_zone_fear_displace")) or
            action.useLesserDoom == true or action.undeadFear == true
        )
    end

    function resolver:getUndeadFearInitiative(action, target)
        local initiatives = action and (action.targetInitiatives or action.fearInitiatives)
        if initiatives and target then
            return initiatives[target.id] or initiatives[target.name] or initiatives[target]
        end
        return self:getZoneAttackTargetInitiative(action, target) or
            (target and (target.targetInitiative or target.initiative)) or
            (action and action.targetInitiative) or 10
    end

    function resolver:getUndeadFearDestination(target, action)
        local destinations = action and (action.destinationZones or action.destinationZoneById or
            action.fearDestinations)
        if destinations and target and target.id and destinations[target.id] then
            return destinations[target.id]
        end
        return action and (action.destinationZone or action.targetZone)
    end

    function resolver:moveUndeadFearTarget(target, destinationZone, action)
        if not target or not destinationZone then
            return false, "destination_missing"
        end
        local oldZone = target.zone
        if oldZone ~= destinationZone and action and action.validateAdjacent ~= false and
           not self:areZonesAdjacent(action, oldZone, destinationZone) then
            return false, "destination_not_adjacent"
        end
        if oldZone == destinationZone then
            return true
        end
        if self.zoneSystem and target.id then
            local placed = self.zoneSystem:placeEntity(target.id, destinationZone)
            if not placed then
                return false, "zone_sync_failed"
            end
        end
        target.zone = destinationZone
        self:clearAllEngagements(target, action and action.allEntities)
        self.eventBus:emit("entity_zone_changed", {
            entity = target,
            oldZone = oldZone,
            newZone = destinationZone,
            source = "undead_fear",
        })
        return true
    end

    function resolver:resolveUndeadFear(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No undead creature for Fear."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isUndeadTarget(actor) then
            result.success = false
            result.description = "Fear requires an undead creature."
            result.effects[#result.effects + 1] = "undead_fear_blocked"
            return result
        end
        if not self:undeadFearReady(action) then
            result.success = false
            result.description = "Undead Fear requires a lesser doom."
            result.effects[#result.effects + 1] = "undead_fear_requires_lesser_doom"
            return result
        end

        local card = action.lesserDoomCard or action.card or action.doomCard
        if not card then
            result.success = false
            result.description = "Undead Fear requires a lesser doom card."
            result.effects[#result.effects + 1] = "undead_fear_missing_card"
            return result
        end

        local doomValue = card.value or action.value or 0
        local onTurn = action.onUndeadTurn == true or action.onTurn == true or
            action.isTurnAction == true or action.isActorTurn == true
        local modifier = onTurn and (actor.wands or actor.attributes and actor.attributes[constants.SUITS.WANDS] or 0) or 0
        local fearValue = doomValue + modifier
        local actorZone = action.zone or actor.zone
        local candidates = action.targets or action.allEntities or {}
        local affected = {}
        local resisted = {}
        local pendingChoices = {}
        local skipped = {}

        for _, target in ipairs(candidates) do
            local conditions = target.conditions or {}
            local sameZone = target ~= actor and target.zone == actorZone
            if sameZone and target.isPC == true and not conditions.dead and not conditions.deaths_door then
                local initiative = self:getUndeadFearInitiative(action, target)
                if fearValue >= initiative then
                    local destination = self:getUndeadFearDestination(target, action)
                    local moved, moveReason = self:moveUndeadFearTarget(target, destination, action)
                    local entry = {
                        target = target,
                        initiative = initiative,
                        destinationZone = destination,
                    }
                    if moved then
                        affected[#affected + 1] = entry
                    else
                        entry.reason = moveReason
                        pendingChoices[#pendingChoices + 1] = entry
                    end
                else
                    resisted[#resisted + 1] = {
                        target = target,
                        initiative = initiative,
                    }
                end
            elseif target ~= actor then
                skipped[#skipped + 1] = {
                    target = target,
                    reason = sameZone and "not_adventurer" or "different_zone",
                }
            end
        end

        result.success = true
        result.cardValue = doomValue
        result.modifier = modifier
        result.fearValue = fearValue
        result.testValue = fearValue
        result.affected = affected
        result.resisted = resisted
        result.pendingDisplacementChoices = pendingChoices
        result.skipped = skipped
        result.effects[#result.effects + 1] = "undead_fear"
        if onTurn then
            result.effects[#result.effects + 1] = "undead_fear_wands_added"
        end
        if #affected > 0 then
            result.effects[#result.effects + 1] = "fear_displaced"
        end
        if #pendingChoices > 0 then
            result.effects[#result.effects + 1] = "undead_fear_displacement_choice_required"
        end
        result.description = (actor.name or "Undead") .. " terrifies " ..
            tostring(#affected + #pendingChoices) .. " same-zone adventurer(s)."

        self.eventBus:emit("undead_fear", {
            actor = actor,
            action = action,
            result = result,
            affected = affected,
            resisted = resisted,
            pendingChoices = pendingChoices,
        })

        action.result = result
        return result
    end

    function resolver:isPuppetMummy(entity)
        return entity and (entity.puppetMummy ~= nil or entityHasNormalizedTag(entity, "puppet_mummy"))
    end

    function resolver:zombieDoomReady(action, doomKey, effectType)
        local doom = action and (action[doomKey] or action.doom)
        local effect = doom and doom.effect
        return action and (action[doomKey .. "Card"] or action.card or action.discardedDoom or
            action.useDoom == true or (effect and effect.type == effectType))
    end

    function resolver:isLivingZombieDevourTarget(target)
        if not target or not target.conditions then
            return false
        end
        if target.undead or target.construct or target.automaton or entityHasNormalizedTag(target, "undead") then
            return false
        end
        local conditions = target.conditions
        return conditions.deaths_door or conditions.knocked_out or conditions.knockout
    end

    function resolver:healNPCHealth(entity, amount)
        if not entity or not amount or amount <= 0 then
            return 0
        end
        local before = entity.npcHealth or 0
        local maxHealth = entity.npcMaxHealth or before
        entity.npcHealth = math.min(maxHealth, before + amount)
        return entity.npcHealth - before
    end

    function resolver:resolveZombieDevourTheLiving(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target

        if not actor then
            result.success = false
            result.description = "No zombie for Devour the Living."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isZombie(actor) or actor.zombieLimb then
            result.success = false
            result.description = "Devour the Living requires a zombie."
            result.effects[#result.effects + 1] = "zombie_devour_the_living_blocked"
            return result
        end
        if not self:zombieDoomReady(action, "lesserDoom", "devour_living") then
            result.success = false
            result.description = "Zombie Devour the Living requires a lesser doom."
            result.effects[#result.effects + 1] = "zombie_devour_the_living_requires_lesser_doom"
            return result
        end
        if not self:isLivingZombieDevourTarget(target) then
            result.success = false
            result.description = "Zombie Devour the Living requires a living target at Death's Door or knocked out."
            result.effects[#result.effects + 1] = "zombie_devour_the_living_invalid_target"
            return result
        end

        local conditions = target.conditions
        conditions.dead = true
        conditions.deaths_door = false
        conditions.knocked_out = false
        conditions.knockout = false
        conditions.sleeping = false
        target.devouredByZombie = actor.id or true
        target.devouredBy = actor
        self:clearAllEngagements(target, action.allEntities)
        self.eventBus:emit(events.EVENTS.ENTITY_DEFEATED, {
            entity = target,
            reason = "zombie_devour_the_living",
            source = actor,
        })

        local doom = action.lesserDoom or action.doom
        local effect = doom and doom.effect or {}
        local healed = self:healNPCHealth(actor, action.healWounds or effect.healWounds or 2)

        result.success = true
        result.target = target
        result.healed = healed
        result.effects[#result.effects + 1] = "zombie_devour_the_living"
        result.effects[#result.effects + 1] = "devoured_living"
        if healed > 0 then
            result.effects[#result.effects + 1] = "healed"
        end
        result.description = (actor.name or "Zombie") .. " devours " .. (target.name or "the living") ..
            " and heals " .. tostring(healed) .. " Wound(s)."

        self.eventBus:emit("zombie_devour_the_living", {
            actor = actor,
            target = target,
            action = action,
            result = result,
            healed = healed,
        })

        action.result = result
        return result
    end

    function resolver:getZombieLastGraspDoom(entity, damageContext)
        damageContext = damageContext or {}
        local action = damageContext.action or {}
        local doom = damageContext.zombieLastGraspDoom or damageContext.targetGreaterDoom or
            action.zombieLastGraspDoom or action.targetGreaterDoom or action.lastGraspDoom
        if action.actor == entity then
            doom = doom or action.greaterDoom or action.doom
        end
        return doom
    end

    function resolver:zombieLastGraspReady(entity, damageContext)
        local lastGraspCapable = self:isZombie(entity) or self:isPuppetMummy(entity)
        if not lastGraspCapable or entity.zombieLimb or entity.puppetMummyLimb or
           entity.zombieLastGraspDisabled or entity.puppetMummyLastGraspDisabled then
            return false
        end
        damageContext = damageContext or {}
        local action = damageContext.action or {}
        local doom = self:getZombieLastGraspDoom(entity, damageContext)
        local effect = doom and doom.effect
        local requested = damageContext.useZombieLastGrasp == true or damageContext.zombieLastGrasp == true or
            action.useZombieLastGrasp == true or action.zombieLastGrasp == true
        return (effect and effect.type == "ignore_wound_spawn_limb") or (requested and doom ~= nil)
    end

    function resolver:createZombieSeveredLimb(zombie, damageContext)
        local isPuppetMummy = self:isPuppetMummy(zombie)
        local limb = entity_factory.createEntity(isPuppetMummy and "puppet_mummy" or "zombie", {
            name = (zombie.name or (isPuppetMummy and "Puppet-Mummy" or "Zombie")) .. " Severed Limb",
            location = zombie.location,
        })
        if not limb then
            return nil
        end
        limb.id = (zombie.id or "zombie") .. "_severed_limb_" .. tostring((zombie.severedLimbsSpawned or 0) + 1)
        limb.zone = zombie.zone
        limb.zombieLimb = not isPuppetMummy
        limb.puppetMummyLimb = isPuppetMummy
        limb.severedFrom = zombie.id
        if isPuppetMummy then
            limb.severedFromPuppetMummy = zombie
            limb.sameInitiativeAsPuppetMummy = true
        else
            limb.severedFromZombie = zombie
            limb.sameInitiativeAsZombie = true
        end
        limb.initiative = damageContext and (damageContext.zombieInitiative or damageContext.targetInitiative) or zombie.initiative
        limb.npcHealth = 1
        limb.npcMaxHealth = 1
        limb.npcDefense = 0
        limb.npcMaxDefense = 0
        limb.zombieLastGraspDisabled = true
        limb.puppetMummyLastGraspDisabled = true
        if isPuppetMummy then
            limb.puppetMummy = limb.puppetMummy or {}
            limb.puppetMummy.lastGrasp = nil
            limb.puppetMummy.severedLimb = true
        else
            limb.zombie = limb.zombie or {}
            limb.zombie.lastGrasp = nil
            limb.zombie.severedLimb = true
        end
        limb.tags = limb.tags or {}
        limb.tags[#limb.tags + 1] = isPuppetMummy and "puppet_mummy_limb" or "zombie_limb"
        return limb
    end

    function resolver:resolveZombieLastGraspWound(entity, amount, effects, allEntities, damageContext)
        if not self:zombieLastGraspReady(entity, damageContext) or (amount or 0) <= 0 then
            return nil
        end

        local limb = self:createZombieSeveredLimb(entity, damageContext)
        entity.severedLimbsSpawned = (entity.severedLimbsSpawned or 0) + 1
        entity.lastGraspLimbs = entity.lastGraspLimbs or {}
        if limb then
            entity.lastGraspLimbs[#entity.lastGraspLimbs + 1] = limb
            if allEntities then
                allEntities[#allEntities + 1] = limb
            end
        end

        local prefix = self:isPuppetMummy(entity) and "puppet_mummy" or "zombie"
        effects[#effects + 1] = prefix .. "_last_grasp"
        effects[#effects + 1] = "wound_prevented"
        effects[#effects + 1] = prefix .. "_severed_limb_spawned"

        self.eventBus:emit(prefix .. "_last_grasp", {
            entity = entity,
            limb = limb,
            damageContext = damageContext,
        })

        local remainingAmount = math.max((amount or 0) - 1, 0)
        return {
            result = prefix .. "_last_grasp",
            ignored = remainingAmount == 0,
            prevented = 1,
            remainingAmount = remainingAmount,
            limb = limb,
        }
    end

    function resolver:resolveZombieLastGrasp(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        if not actor then
            result.success = false
            result.description = "No zombie for Last Grasp."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isZombie(actor) or actor.zombieLimb then
            result.success = false
            result.description = "Last Grasp requires a zombie."
            result.effects[#result.effects + 1] = "zombie_last_grasp_blocked"
            return result
        end
        local context = {
            action = action,
            useZombieLastGrasp = true,
            targetGreaterDoom = action.greaterDoom or action.doom,
            targetInitiative = action.targetInitiative or actor.initiative,
        }
        local grasp = self:resolveZombieLastGraspWound(actor, action.incomingWounds or 1,
            result.effects, action.allEntities, context)
        if not grasp then
            result.success = false
            result.description = "Zombie Last Grasp requires a greater doom."
            result.effects[#result.effects + 1] = "zombie_last_grasp_requires_greater_doom"
            return result
        end

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.limb = grasp.limb
        result.prevented = grasp.prevented
        result.description = (actor.name or "Zombie") .. " loses a limb instead of taking a Wound."
        action.result = result
        return result
    end

    function resolver:isFungoid(entity)
        return entity and (entity.fungoid ~= nil or entityHasNormalizedTag(entity, "fungoid"))
    end

    function resolver:fungoidDoomReady(action, doomKey, effectType)
        local doom = action and (action[doomKey] or action.doom)
        local effect = doom and doom.effect
        return action and (action[doomKey .. "Card"] or action.card or action.discardedDoom or
            action.useDoom == true or (effect and effect.type == effectType))
    end

    function resolver:applyFungoidBrainSpores(action, result, target)
        local actor = action and action.actor
        if not (actor and actor.isPC == true and self:isFungoid(target)) then
            return false
        end
        local loss = target.fungoid and target.fungoid.brainSpores and
            target.fungoid.brainSpores.meleeAttackSuccessCostsLoreBids or 1
        local before = actor.loreBids or 0
        actor.loreBids = math.max(0, before - loss)
        result.fungoidBrainSpores = {
            actor = actor,
            target = target,
            before = before,
            after = actor.loreBids,
            lost = before - actor.loreBids,
        }
        result.effects[#result.effects + 1] = "fungoid_brain_spores"
        result.effects[#result.effects + 1] = "lore_bid_lost"
        self.eventBus:emit("fungoid_brain_spores", result.fungoidBrainSpores)
        return true
    end

    function resolver:getFungoidZoneTargets(actor, action)
        local actorZone = action and action.zone or actor and actor.zone
        local candidates = action and (action.targets or action.allEntities) or {}
        local targets = {}
        for _, candidate in ipairs(candidates) do
            local conditions = candidate.conditions or {}
            if candidate.zone == actorZone and not conditions.dead then
                targets[#targets + 1] = candidate
            end
        end
        return targets
    end

    function resolver:resolveFungoidChokingSpores(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        if not actor then
            result.success = false
            result.description = "No fungoid for Choking Spores."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isFungoid(actor) then
            result.success = false
            result.description = "Choking Spores requires a fungoid."
            result.effects[#result.effects + 1] = "fungoid_choking_spores_blocked"
            return result
        end
        if not self:fungoidDoomReady(action, "lesserDoom", "same_zone_condition") then
            result.success = false
            result.description = "Fungoid Choking Spores requires a lesser doom."
            result.effects[#result.effects + 1] = "fungoid_choking_spores_requires_lesser_doom"
            return result
        end

        local affected = {}
        for _, target in ipairs(self:getFungoidZoneTargets(actor, action)) do
            target.conditions = target.conditions or {}
            target.conditions.silenced = true
            target.silenced = true
            target.silencedByFungoid = actor.id or true
            affected[#affected + 1] = target
        end

        result.success = true
        result.affected = affected
        result.effects[#result.effects + 1] = "fungoid_choking_spores"
        result.effects[#result.effects + 1] = "same_zone_silence"
        result.effects[#result.effects + 1] = "silenced"
        result.description = (actor.name or "Fungoid") .. " releases choking spores, silencing " ..
            tostring(#affected) .. " creature(s)."
        self.eventBus:emit("fungoid_choking_spores", {
            actor = actor,
            action = action,
            result = result,
            affected = affected,
        })
        action.result = result
        return result
    end

    function resolver:fungoidMinorIllusionTargetValid(action)
        local kind = normalizeTalentKey(action.illusionKind or action.targetKind or action.subjectKind or
            action.creatureOrObject or "object")
        return kind == "" or kind == "object" or kind == "non_living_object" or kind == "item" or kind == "terrain"
    end

    function resolver:resolveFungoidMinorIllusion(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        if not actor then
            result.success = false
            result.description = "No fungoid for Minor Illusion."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isFungoid(actor) then
            result.success = false
            result.description = "Minor Illusion requires a fungoid."
            result.effects[#result.effects + 1] = "fungoid_minor_illusion_blocked"
            return result
        end
        if not self:fungoidDoomReady(action, "lesserDoom", "minor_illusion") then
            result.success = false
            result.description = "Fungoid Minor Illusion requires a lesser doom."
            result.effects[#result.effects + 1] = "fungoid_minor_illusion_requires_lesser_doom"
            return result
        end
        if not self:fungoidMinorIllusionTargetValid(action) then
            result.success = false
            result.description = "Fungoid Minor Illusion can only create an image of a non-living object."
            result.effects[#result.effects + 1] = "fungoid_minor_illusion_living_target_blocked"
            return result
        end

        local illusion = {
            id = action.illusionId or ("fungoid_minor_illusion_" .. tostring(#(actor.fungoidMinorIllusions or {}) + 1)),
            image = action.image or action.illusion or action.objectName or "non-living object",
            nonLivingObjectOnly = true,
            imageOnly = true,
            noWeight = true,
            noSubstance = true,
            noSound = true,
            noSmell = true,
            source = actor.id,
        }
        actor.fungoidMinorIllusions = actor.fungoidMinorIllusions or {}
        actor.fungoidMinorIllusions[#actor.fungoidMinorIllusions + 1] = illusion

        result.success = true
        result.illusion = illusion
        result.effects[#result.effects + 1] = "fungoid_minor_illusion"
        result.effects[#result.effects + 1] = "image_only_illusion"
        result.description = (actor.name or "Fungoid") .. " creates a silent, scentless, insubstantial image."
        self.eventBus:emit("fungoid_minor_illusion", {
            actor = actor,
            action = action,
            result = result,
            illusion = illusion,
        })
        action.result = result
        return result
    end

    function resolver:resolveFungoidFungalRegeneration(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        if not actor then
            result.success = false
            result.description = "No fungoid for Fungal Regeneration."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isFungoid(actor) then
            result.success = false
            result.description = "Fungal Regeneration requires a fungoid."
            result.effects[#result.effects + 1] = "fungoid_fungal_regeneration_blocked"
            return result
        end
        if not self:fungoidDoomReady(action, "greaterDoom", "heal") then
            result.success = false
            result.description = "Fungoid Fungal Regeneration requires a greater doom."
            result.effects[#result.effects + 1] = "fungoid_fungal_regeneration_requires_greater_doom"
            return result
        end

        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect or {}
        local healed = self:healNPCHealth(actor, action.healWounds or effect.wounds or 1)

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.healed = healed
        result.effects[#result.effects + 1] = "fungoid_fungal_regeneration"
        result.effects[#result.effects + 1] = "greater_doom"
        if healed > 0 then
            result.effects[#result.effects + 1] = "healed"
        end
        result.description = (actor.name or "Fungoid") .. " regenerates " .. tostring(healed) .. " Wound(s)."
        self.eventBus:emit("fungoid_fungal_regeneration", {
            actor = actor,
            action = action,
            result = result,
            healed = healed,
        })
        action.result = result
        return result
    end

    function resolver:resolveFungoidPerfectImitation(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local original = action.original or action.imitatedTarget or action.target
        if not actor then
            result.success = false
            result.description = "No fungoid for Perfect Imitation."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isFungoid(actor) then
            result.success = false
            result.description = "Perfect Imitation requires a fungoid."
            result.effects[#result.effects + 1] = "fungoid_perfect_imitation_blocked"
            return result
        end
        if not self:fungoidDoomReady(action, "greaterDoom", "perfect_imitation") then
            result.success = false
            result.description = "Fungoid Perfect Imitation requires a greater doom."
            result.effects[#result.effects + 1] = "fungoid_perfect_imitation_requires_greater_doom"
            return result
        end
        if not original then
            result.success = false
            result.description = "Fungoid Perfect Imitation requires a person to imitate."
            result.effects[#result.effects + 1] = "fungoid_perfect_imitation_missing_original"
            return result
        end

        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect or {}
        actor.fungoidPerfectImitation = {
            active = true,
            original = original,
            originalId = original.id,
            originalName = original.name,
            targetRedirectChance = action.targetRedirectChance or effect.targetRedirectChance or 0.5,
            endsOnWound = effect.endsOnWound ~= false,
        }
        actor.conditions = actor.conditions or {}
        actor.conditions.fungoid_perfect_imitation = true

        result.success = true
        result.imitation = actor.fungoidPerfectImitation
        result.effects[#result.effects + 1] = "fungoid_perfect_imitation"
        result.effects[#result.effects + 1] = "perfect_duplicate"
        result.description = (actor.name or "Fungoid") .. " becomes indistinguishable from " ..
            (original.name or "the original") .. "."
        self.eventBus:emit("fungoid_perfect_imitation", {
            actor = actor,
            original = original,
            action = action,
            result = result,
        })
        action.result = result
        return result
    end

    function resolver:maybeRedirectFungoidPerfectImitation(action, result)
        local target = action and action.target
        if action.ignoreFungoidPerfectImitation or not self:isFungoid(target) then
            return false
        end
        local imitation = target.fungoidPerfectImitation
        if not (imitation and imitation.active and imitation.original) then
            return false
        end
        local original = imitation.original
        if target.zone ~= original.zone then
            return false
        end
        local roll = action.perfectImitationRedirectRoll or action.redirectRoll or math.random()
        result.fungoidPerfectImitationRoll = roll
        if roll <= (imitation.targetRedirectChance or 0.5) then
            action.originalTarget = target
            action.target = original
            result.effects[#result.effects + 1] = "fungoid_perfect_imitation_redirected"
            result.description = (result.description or "") .. "Perfect Imitation redirects the target. "
            return true
        end
        result.effects[#result.effects + 1] = "fungoid_perfect_imitation_not_redirected"
        return false
    end

    function resolver:clearFungoidPerfectImitation(entity, effects)
        if not (self:isFungoid(entity) and entity.fungoidPerfectImitation and
                entity.fungoidPerfectImitation.active) then
            return false
        end
        entity.fungoidPerfectImitation.active = false
        entity.fungoidPerfectImitation.endedByWound = true
        if entity.conditions then
            entity.conditions.fungoid_perfect_imitation = false
        end
        effects[#effects + 1] = "fungoid_perfect_imitation_ended"
        self.eventBus:emit("fungoid_perfect_imitation_ended", {
            entity = entity,
            reason = "wound",
        })
        return true
    end

    function resolver:isElemental(entity)
        return entity and (entity.elemental ~= nil or entity.elementalImmunity == true or
            entityHasNormalizedTag(entity, "elemental"))
    end

    function resolver:elementalCanMeld(entity)
        if not self:isElemental(entity) then
            return false
        end
        if entity.elementalMeld == true then
            return true
        end
        if type(entity.elemental) == "table" and entity.elemental.elementalMeld ~= false then
            return entity.elemental.elementalMeld == true or entity.elemental.meld == true
        end
        return type(entity.nymph) == "table" and entity.nymph.elementalMeld == true
    end

    function resolver:getElementalMeldHome(entity, action)
        local nymph = entity and type(entity.nymph) == "table" and entity.nymph or {}
        local elemental = entity and type(entity.elemental) == "table" and entity.elemental or {}
        local home = firstNonNil(
            action and action.elementalHome,
            action and action.homeElement,
            action and action.home,
            entity and entity.elementalHome,
            entity and entity.homeElement,
            nymph.elementalHome,
            nymph.chosenElement,
            elemental.home,
            elemental.elementalHome,
            elemental.chosenElement
        )
        if home == nil then
            return nil
        end

        local normalized = normalizeTalentKey(home)
        if normalized == "" or normalized == "varies" or normalized == "variable" then
            return nil
        end
        return normalized
    end

    function resolver:elementalHomeAvailable(entity, action, home)
        if not home then
            return false
        end
        if action and (action.elementalHomePresent == true or action.homePresent == true or
           action.inElementalHome == true or action.atElementalHome == true) then
            return true
        end
        if entity and entity.inElementalHome == true then
            return true
        end

        local zone = action and (action.zone or action.currentZone or action.location) or entity and entity.zone
        local homeZone = action and (action.elementalHomeZone or action.homeZone)
        if homeZone and zone and tostring(homeZone) == tostring(zone) then
            return true
        end

        local features = action and (action.zoneFeatures or action.features or action.environmentTags)
        if type(features) == "table" then
            for key, value in pairs(features) do
                if value == true and normalizeTalentKey(key) == home then
                    return true
                end
                if normalizeTalentKey(value) == home then
                    return true
                end
            end
        end

        return false
    end

    function resolver:resolveElementalMeld(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:elementalCanMeld(actor) then
            result.success = false
            result.description = "Elemental Meld requires an elemental with an elemental home."
            result.effects[#result.effects + 1] = "elemental_meld_blocked"
            return result
        end

        if action.returnFromMeld == true or action.emerge == true or action.leaveElementalHome == true then
            if not (actor.elementalMelded or actor.elementalMeldState) then
                result.success = false
                result.description = "Elemental is not melded into its home."
                result.effects[#result.effects + 1] = "elemental_meld_not_active"
                return result
            end

            local destination = action.destinationZone or action.toZone or action.emergeZone or
                actor.elementalMeldReturnZone or actor.zone
            if self.zoneSystem and actor.id and destination then
                self.zoneSystem:placeEntity(actor.id, destination)
            end
            actor.zone = destination or actor.zone
            actor.elementalMelded = false
            actor.elementalMeldState = nil
            actor.intangible = false
            actor.offstage = false
            actor.inElementalHome = false
            actor.conditions = actor.conditions or {}
            actor.conditions.elemental_meld = false
            actor.conditions.intangible = false

            result.success = true
            result.destinationZone = actor.zone
            result.effects[#result.effects + 1] = "elemental_meld_ended"
            result.effects[#result.effects + 1] = "elemental_emerged"
            result.description = (actor.name or "Elemental") .. " emerges from its elemental home."
            return result
        end

        if not (action.card or action.anyCard or action.outOfChallenge == true or action.cardless == true) then
            result.success = false
            result.description = "Elemental Meld is a miscellaneous action and requires a card during a Challenge."
            result.effects[#result.effects + 1] = "elemental_meld_requires_card"
            return result
        end

        local home = self:getElementalMeldHome(actor, action)
        if not self:elementalHomeAvailable(actor, action, home) then
            result.success = false
            result.description = "Elemental home required."
            result.effects[#result.effects + 1] = "elemental_meld_home_required"
            return result
        end

        local oldZone = actor.zone
        self:clearAllEngagements(actor, action.allEntities)
        actor.elementalMelded = true
        actor.elementalMeldReturnZone = oldZone
        actor.elementalMeldState = {
            active = true,
            home = home,
            source = "elemental_meld",
            oldZone = oldZone,
        }
        actor.intangible = true
        actor.offstage = true
        actor.inElementalHome = true
        actor.conditions = actor.conditions or {}
        actor.conditions.elemental_meld = true
        actor.conditions.intangible = true

        result.success = true
        result.elementalHome = home
        result.oldZone = oldZone
        result.effects[#result.effects + 1] = "elemental_meld"
        result.effects[#result.effects + 1] = "elemental_home_entered"
        result.description = (actor.name or "Elemental") .. " becomes immaterial and steps into " ..
            tostring(home) .. "."

        self.eventBus:emit("elemental_meld", {
            actor = actor,
            home = home,
            oldZone = oldZone,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:getDamageElementTokens(effects, weapon, damageContext)
        local tokens = {}
        appendNormalizedKeys(tokens, effects)
        damageContext = damageContext or {}
        local action = damageContext.action or {}
        appendNormalizedKeys(tokens, damageContext.element)
        appendNormalizedKeys(tokens, damageContext.damageElement)
        appendNormalizedKeys(tokens, damageContext.damageType)
        appendNormalizedKeys(tokens, damageContext.source)
        appendNormalizedKeys(tokens, action.element)
        appendNormalizedKeys(tokens, action.damageElement)
        appendNormalizedKeys(tokens, action.damageType)

        local props = weapon and weapon.properties or {}
        appendNormalizedKeys(tokens, weapon and weapon.element)
        appendNormalizedKeys(tokens, props.element)
        appendNormalizedKeys(tokens, weapon and weapon.damageElement)
        appendNormalizedKeys(tokens, props.damageElement)
        if props.fire or props.flame or props.flaming or props.burning or props.heavenfire then
            tokens[#tokens + 1] = "fire"
        end
        if props.cold or props.ice or props.frost then
            tokens[#tokens + 1] = props.ice and "ice" or "cold"
        end

        return tokens
    end

    function resolver:getElementalImmunitySet(entity)
        if not self:isElemental(entity) then
            return nil
        end

        local set = {}
        local function add(value)
            local normalized = normalizeTalentKey(value)
            if normalized ~= "" and normalized ~= "varies" and normalized ~= "variable" then
                set[normalized] = true
            end
        end
        local function addMany(value)
            if type(value) == "string" or type(value) == "number" then
                add(value)
                return
            end
            if type(value) ~= "table" then
                return
            end
            for key, item in pairs(value) do
                if item == true then
                    add(key)
                elseif type(item) == "string" or type(item) == "number" then
                    add(item)
                elseif type(item) == "table" then
                    add(item.id or item.name or item.element or item.type)
                end
            end
        end

        add(entity.chosenElement)
        add(entity.elementalElement)
        local elemental = type(entity.elemental) == "table" and entity.elemental or {}
        add(elemental.chosenElement)
        add(elemental.element)
        addMany(elemental.immunityElements or elemental.immunities)
        local nymph = type(entity.nymph) == "table" and entity.nymph or {}
        add(nymph.chosenElement)

        if self:isWinterWolf(entity) then
            set.ice = true
            set.cold = true
            set.water = true
        end

        return next(set) and set or nil
    end

    function resolver:resolveElementalImmunityDamage(entity, amount, effects, weapon, damageContext)
        if (amount or 0) <= 0 then
            return nil
        end

        local immunities = self:getElementalImmunitySet(entity)
        if not immunities then
            return nil
        end

        for _, token in ipairs(self:getDamageElementTokens(effects, weapon, damageContext)) do
            if immunities[token] then
                effects[#effects + 1] = "elemental_immunity"
                effects[#effects + 1] = "elemental_immunity_" .. token
                self.eventBus:emit("elemental_immunity", {
                    entity = entity,
                    element = token,
                    weapon = weapon,
                    damageContext = damageContext,
                })
                return {
                    result = "immune",
                    immune = true,
                    reason = "elemental_immunity",
                    element = token,
                }
            end
        end

        return nil
    end

    function resolver:isNymph(entity)
        return entity and (entity.nymph ~= nil or entityHasNormalizedTag(entity, "nymph"))
    end

    function resolver:getTopMinorDiscardCard(action)
        action = action or {}
        local card = action.minorDiscardTop or action.discardTop or action.topDiscardCard or action.card
        if card then
            return card
        end

        for _, deck in ipairs({ action.minorDeck or false, action.playerDeck or false, self.playerDeck or false }) do
            if type(deck) == "table" then
                if deck.peekDiscard then
                    card = deck:peekDiscard()
                elseif type(deck.discard_pile) == "table" then
                    card = deck.discard_pile[#deck.discard_pile]
                end
                if card then
                    return card
                end
            end
        end

        return nil
    end

    function resolver:getMinorSuitKey(card)
        local suit = type(card) == "table" and card.suit or card
        if suit == constants.SUITS.SWORDS or normalizeTalentKey(suit) == "swords" then
            return "swords"
        end
        if suit == constants.SUITS.PENTACLES or normalizeTalentKey(suit) == "pentacles" or
           normalizeTalentKey(suit) == "disks" then
            return "pentacles"
        end
        if suit == constants.SUITS.CUPS or normalizeTalentKey(suit) == "cups" then
            return "cups"
        end
        if suit == constants.SUITS.WANDS or normalizeTalentKey(suit) == "wands" or
           normalizeTalentKey(suit) == "batons" then
            return "wands"
        end
        return nil
    end

    function resolver:resolveNymphWant(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No nymph to consult."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isNymph(actor) then
            result.success = false
            result.description = "Nymph wants require a nymph."
            result.effects[#result.effects + 1] = "nymph_want_blocked"
            return result
        end

        local card = self:getTopMinorDiscardCard(action)
        local suitKey = self:getMinorSuitKey(card)
        if not suitKey then
            result.success = false
            result.description = "No suited minor discard card to determine what the nymphs want."
            result.effects[#result.effects + 1] = "nymph_want_no_minor_discard"
            return result
        end

        local wants = actor.nymph and actor.nymph.wantsByMinorSuit or {}
        local request = wants[suitKey]
        if not request then
            result.success = false
            result.description = "No nymph want is authored for " .. tostring(suitKey) .. "."
            result.effects[#result.effects + 1] = "nymph_want_missing"
            return result
        end

        result.success = true
        result.nymphWant = {
            suit = suitKey,
            request = request,
            card = card,
        }
        actor.currentWant = result.nymphWant
        result.effects[#result.effects + 1] = "nymph_want_revealed"
        result.effects[#result.effects + 1] = "nymph_want_" .. suitKey
        result.description = (actor.name or "Nymph") .. " wants: " .. request

        self.eventBus:emit("nymph_want_revealed", {
            actor = actor,
            card = card,
            suit = suitKey,
            request = request,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:nymphGreaterDoomReady(action, effectType)
        local doom = action and (action.greaterDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            (effect and effect.type == effectType))
    end

    function resolver:nymphCanSeeTarget(actor, target, action)
        if not (actor and target) then
            return false
        end
        if target == actor or target.isPC ~= true then
            return false
        end

        local conditions = target.conditions or {}
        if conditions.dead or conditions.deaths_door or conditions.blind or conditions.blinded then
            return false
        end
        if target.canSeeNymph == false or target.canSee == false then
            return false
        end

        local visibility = action and (action.visibilityById or action.canSeeNymphById)
        if visibility and target.id and visibility[target.id] == false then
            return false
        end

        return true
    end

    function resolver:nymphBeautyShouldResist(target, action)
        if not (target and action) then
            return false
        end

        local byId = action.resistResolveById or action.resistNymphBeautyById or action.resistById
        if byId and target.id and byId[target.id] ~= nil then
            return byId[target.id] == true
        end

        return self:entityInList(action.resistTargets or action.resistingTargets or {}, target)
    end

    function resolver:getNymphBeautyDestination(actor, target, action)
        local destinations = action and (action.destinationZones or action.destinationZoneById or action.nymphBeautyDestinations)
        if destinations and target and target.id and destinations[target.id] then
            return destinations[target.id]
        end
        return action and (action.destinationZone or action.targetZone) or actor.zone
    end

    function resolver:moveNymphBeautyTarget(actor, target, destinationZone, action, result)
        if not (target and destinationZone) then
            return false, "missing_destination"
        end

        local oldZone = target.zone
        local parting = nil
        if target.is_engaged and oldZone ~= destinationZone then
            parting = self:checkPartingBlows(target, action.allEntities, action)
            if parting.wounds > 0 then
                result.effects[#result.effects + 1] = "parting_blows"
            end
            if parting.blocked then
                result.effects[#result.effects + 1] = "nymph_bewitching_beauty_parting_blocked"
                return false, "parting_blow_blocked", parting
            end
        end

        if self.zoneSystem and target.id and destinationZone then
            local placed, err = self.zoneSystem:placeEntity(target.id, destinationZone)
            if not placed then
                result.effects[#result.effects + 1] = "zone_sync_failed"
                return false, err or "zone_sync_failed", parting
            end
        end

        target.zone = destinationZone
        target.nymphBewitchedBy = actor.id or true
        if oldZone ~= destinationZone then
            self:clearAllEngagements(target, action.allEntities)
            self.eventBus:emit("entity_zone_changed", {
                entity = target,
                oldZone = oldZone,
                newZone = destinationZone,
                source = "nymph_bewitching_beauty",
            })
        end

        return true, nil, parting
    end

    function resolver:resolveNymphBewitchingBeauty(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No nymph for Bewitching Beauty."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isNymph(actor) then
            result.success = false
            result.description = "Bewitching Beauty requires a nymph."
            result.effects[#result.effects + 1] = "nymph_bewitching_beauty_blocked"
            return result
        end
        if not (action.card or action.discardedCard or action.anyCard or action.lesserDoom or action.lesserDoomCard) then
            result.success = false
            result.description = "Nymph Bewitching Beauty requires any discarded card."
            result.effects[#result.effects + 1] = "nymph_bewitching_beauty_requires_card"
            return result
        end

        local affected = {}
        local resisted = {}
        local skipped = {}
        local failedResistance = {}
        local blocked = {}

        for _, target in ipairs(action.targets or action.allEntities or {}) do
            if self:nymphCanSeeTarget(actor, target, action) then
                if self:nymphBeautyShouldResist(target, action) then
                    local spent, reason = self:spendResolveForFavor(target)
                    if spent then
                        resisted[#resisted + 1] = target
                    else
                        failedResistance[#failedResistance + 1] = {
                            target = target,
                            reason = reason,
                        }
                    end
                end

                if not self:entityInList(resisted, target) then
                    local destination = self:getNymphBeautyDestination(actor, target, action)
                    local moved, reason, parting = self:moveNymphBeautyTarget(actor, target, destination, action, result)
                    if moved then
                        affected[#affected + 1] = {
                            target = target,
                            destinationZone = destination,
                            partingBlows = parting,
                        }
                    else
                        blocked[#blocked + 1] = {
                            target = target,
                            reason = reason,
                            partingBlows = parting,
                        }
                    end
                end
            elseif target ~= actor and target.isPC == true then
                skipped[#skipped + 1] = target
            end
        end

        result.success = true
        result.affected = affected
        result.resisted = resisted
        result.skipped = skipped
        result.failedResistance = failedResistance
        result.blockedMovement = blocked
        result.effects[#result.effects + 1] = "nymph_bewitching_beauty"
        result.effects[#result.effects + 1] = "displaced_visible_adventurers"
        if #resisted > 0 then
            result.effects[#result.effects + 1] = "nymph_bewitching_beauty_resisted"
        end
        if #failedResistance > 0 then
            result.effects[#result.effects + 1] = "nymph_bewitching_beauty_resist_failed"
        end
        result.description = (actor.name or "Nymph") .. " draws " .. tostring(#affected) ..
            " visible adventurer(s) toward her beauty."

        self.eventBus:emit("nymph_bewitching_beauty", {
            actor = actor,
            affected = affected,
            resisted = resisted,
            skipped = skipped,
            blocked = blocked,
        })

        action.result = result
        return result
    end

    function resolver:resolveNymphExpeditiousRetreat(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No nymph for Expeditious Retreat."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isNymph(actor) then
            result.success = false
            result.description = "Expeditious Retreat requires a nymph."
            result.effects[#result.effects + 1] = "nymph_expeditious_retreat_blocked"
            return result
        end
        if not self:nymphGreaterDoomReady(action, "disengage_all") then
            result.success = false
            result.description = "Nymph Expeditious Retreat requires a greater doom."
            result.effects[#result.effects + 1] = "nymph_expeditious_retreat_requires_greater_doom"
            return result
        end

        self:clearAllEngagements(actor, action.allEntities)

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.effects[#result.effects + 1] = "nymph_expeditious_retreat"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "disengaged_all"
        result.description = (actor.name or "Nymph") ..
            " disengages from all adventurers without spending her turn card."

        self.eventBus:emit("nymph_expeditious_retreat", {
            actor = actor,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:resolveNymphSleepSong(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target

        if not actor then
            result.success = false
            result.description = "No nymph for Sleep Song."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isNymph(actor) then
            result.success = false
            result.description = "Sleep Song requires a nymph."
            result.effects[#result.effects + 1] = "nymph_sleep_song_blocked"
            return result
        end
        if not target then
            result.success = false
            result.description = "Sleep Song requires a target."
            result.effects[#result.effects + 1] = "nymph_sleep_song_missing_target"
            return result
        end
        if not self:nymphGreaterDoomReady(action, "sleep_song") then
            result.success = false
            result.description = "Nymph Sleep Song requires a greater doom."
            result.effects[#result.effects + 1] = "nymph_sleep_song_requires_greater_doom"
            return result
        end
        if not action.card then
            result.success = false
            result.description = "Nymph Sleep Song requires a Speak Incantations card."
            result.effects[#result.effects + 1] = "nymph_sleep_song_requires_card"
            return result
        end

        result.cardValue = action.card.value or 0
        result.modifier = actor.wands or (actor.getAttribute and actor:getAttribute(constants.SUITS.WANDS)) or 0
        result.testValue = result.cardValue + result.modifier
        result.difficulty = self:getTargetInitiative(target, action) or result.difficulty

        local contest = self:resolveInitiativeContest(action, result, { tieWins = false })
        if contest.dodged then
            return result
        end

        if result.success then
            target.conditions = target.conditions or {}
            target.conditions.knocked_out = true
            target.conditions.knockout = true
            target.conditions.sleeping = true
            target.sleep = {
                source = "nymph_sleep_song",
                wake = "sharp_slap",
                knockedOut = true,
            }
            result.effects[#result.effects + 1] = "nymph_sleep_song"
            result.effects[#result.effects + 1] = "knockout"
            result.effects[#result.effects + 1] = "sleeping"
            result.description = (actor.name or "Nymph") .. " lulls " ..
                (target.name or "the target") .. " to sleep."
        else
            result.effects[#result.effects + 1] = "nymph_sleep_song_failed"
            result.description = (actor.name or "Nymph") .. "'s Sleep Song fails."
        end

        self.eventBus:emit("nymph_sleep_song", {
            actor = actor,
            target = target,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:isWinterWolf(entity)
        return entity and (entity.winterWolf ~= nil or entityHasNormalizedTag(entity, "winter_wolf"))
    end

    function resolver:winterWolfGreaterDoomReady(action, effectType)
        local doom = action and (action.greaterDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            (effect and effect.type == effectType))
    end

    function resolver:isTorchOrLanternItem(item)
        if not item then
            return false
        end

        local name = normalizeTalentKey(item.name)
        local templateId = normalizeTalentKey(item.templateId)
        return name == "torch" or name == "lantern" or templateId == "torch" or templateId == "lantern"
    end

    function resolver:isWinterWolfFireDamage(effects, weapon, damageContext)
        damageContext = damageContext or {}
        local action = damageContext.action or {}
        if damageContext.fireDamage == true or action.fireDamage == true then
            return true
        end
        if normalizeTalentKey(damageContext.damageType) == "fire" or normalizeTalentKey(action.damageType) == "fire" then
            return true
        end

        for _, effect in ipairs(effects or {}) do
            local normalized = normalizeTalentKey(effect)
            if normalized == "fire" or normalized == "heat" or normalized == "flame" or
               normalized == "flames" or normalized == "burning" or normalized == "heavenfire" then
                return true
            end
        end

        if not weapon then
            return false
        end

        local props = weapon.properties or {}
        if props.fire == true or props.heat == true or props.flame == true or
           props.flaming == true or props.burning == true or props.heavenfire == true then
            return true
        end

        return self:isTorchOrLanternItem(weapon)
    end

    function resolver:applyWinterWolfFireVulnerability(entity, amount, effects, weapon, damageContext)
        if not (self:isWinterWolf(entity) and (amount or 0) > 0) then
            return amount
        end
        if not self:isWinterWolfFireDamage(effects, weapon, damageContext) then
            return amount
        end

        local boosted = math.max(amount or 0, 2)
        effects[#effects + 1] = "winter_wolf_vulnerable_to_fire"
        if boosted > (amount or 0) then
            effects[#effects + 1] = "fire_damage_deals_two_wounds"
        end

        if self:isTorchOrLanternItem(weapon) then
            local action = damageContext and damageContext.action or {}
            local owner = action and action.actor or damageContext and (damageContext.actor or damageContext.sourceActor)
            local breakResult = { effects = effects }
            if self:breakLightSourceItem(owner, weapon, "winter_wolf_fire_attack", breakResult) then
                effects[#effects + 1] = "torch_or_lantern_destroyed"
            end
        end

        return boosted
    end

    function resolver:getWinterWolfAuraTargets(actor, action)
        local targets = {}
        local seen = {}

        local function add(candidate)
            if not candidate or candidate == actor or seen[candidate] then
                return
            end
            local conditions = candidate.conditions or {}
            if candidate.isPC == true and not conditions.dead and not conditions.deaths_door then
                seen[candidate] = true
                targets[#targets + 1] = candidate
            end
        end

        if action and action.target then
            add(action.target)
        end
        for _, candidate in ipairs(action and action.targets or {}) do
            add(candidate)
        end

        local allEntities = action and action.allEntities or {}
        if #targets == 0 and self.zoneSystem and self.zoneSystem.getEngagedWith then
            local byId = {}
            for _, entity in ipairs(allEntities) do
                if entity.id then
                    byId[entity.id] = entity
                end
            end
            for _, id in ipairs(self.zoneSystem:getEngagedWith(actor.id) or {}) do
                add(byId[id])
            end
        end

        if #targets == 0 then
            for _, candidate in ipairs(allEntities) do
                if candidate.zone == actor.zone and candidate.is_engaged then
                    add(candidate)
                end
            end
        end

        return targets
    end

    function resolver:resolveWinterWolfAuraOfIce(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No winter wolf for Aura of Ice."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isWinterWolf(actor) then
            result.success = false
            result.description = "Aura of Ice requires a winter wolf."
            result.effects[#result.effects + 1] = "winter_wolf_aura_of_ice_blocked"
            return result
        end

        local rooted = {}
        for _, target in ipairs(self:getWinterWolfAuraTargets(actor, action)) do
            if self:applyRooted(target, {
                action = action,
                allEntities = action.allEntities,
                reason = "winter_wolf_aura_of_ice",
            }) then
                target.rootedBy = "winter_wolf_aura_of_ice"
                target.conditions.winter_wolf_ice_root = true
                rooted[#rooted + 1] = target
            end
        end

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.rooted = rooted
        result.effects[#result.effects + 1] = "winter_wolf_aura_of_ice"
        if #rooted > 0 then
            result.effects[#result.effects + 1] = "rooted"
        end
        result.description = (actor.name or "Winter Wolf") .. " freezes " .. tostring(#rooted) ..
            " engaged adventurer(s) in place."

        self.eventBus:emit("winter_wolf_aura_of_ice", {
            actor = actor,
            rooted = rooted,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:isWinterWolfLiquidBeltItem(item)
        if not item or item.destroyed then
            return false
        end

        local props = item.properties or {}
        local name = normalizeTalentKey(item.name)
        local templateId = normalizeTalentKey(item.templateId)
        local itemType = normalizeTalentKey(item.type)
        if props.liquid == true or props.potion == true or props.oil == true or props.fuel == true or
           props.water_container == true or props.waterContainer == true then
            return true
        end
        if itemType == "potion" or itemType == "oil" then
            return true
        end
        if name:find("potion", 1, true) or name:find("oil", 1, true) or
           name:find("waterskin", 1, true) or templateId:find("potion", 1, true) or
           templateId:find("oil", 1, true) or templateId == "waterskin" then
            return true
        end

        return props.hermeticBottle == true and props.empty ~= true and
            (props.contains ~= nil or props.contents ~= nil or props.alchemical == true)
    end

    function resolver:destroyWinterWolfLiquidBeltItems(target, result)
        local destroyed = {}
        local inv = target and target.inventory
        local belt = inv and inv.getItems and inv:getItems(inventory.LOCATIONS.BELT) or inv and inv.belt or {}
        for _, item in ipairs(belt or {}) do
            if self:isWinterWolfLiquidBeltItem(item) then
                item.destroyed = true
                item.properties = item.properties or {}
                item.properties.frozen = true
                item.properties.broken = true
                destroyed[#destroyed + 1] = item
                result.effects[#result.effects + 1] = "liquid_belt_item_destroyed"
                self.eventBus:emit(events.EVENTS.INVENTORY_CHANGED, {
                    entity = target,
                    item = item,
                    reason = "winter_wolf_breath_of_ice",
                })
            end
        end
        return destroyed
    end

    function resolver:getWinterWolfBreathTargets(actor, action)
        local targets = {}
        local seen = {}
        local actorZone = action and action.zone or actor and actor.zone

        local function add(candidate)
            if not candidate or candidate == actor or seen[candidate] then
                return
            end
            local conditions = candidate.conditions or {}
            if candidate.isPC == true and candidate.zone == actorZone and
               not conditions.dead and not conditions.deaths_door then
                seen[candidate] = true
                targets[#targets + 1] = candidate
            end
        end

        for _, candidate in ipairs(action and action.targets or {}) do
            add(candidate)
        end
        if #targets == 0 then
            for _, candidate in ipairs(action and action.allEntities or {}) do
                add(candidate)
            end
        end

        return targets
    end

    function resolver:resolveWinterWolfBreathOfIce(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No winter wolf for Breath of Ice."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isWinterWolf(actor) then
            result.success = false
            result.description = "Breath of Ice requires a winter wolf."
            result.effects[#result.effects + 1] = "winter_wolf_breath_of_ice_blocked"
            return result
        end
        if not self:winterWolfGreaterDoomReady(action, "zone_ice_attack") then
            result.success = false
            result.description = "Winter Wolf Breath of Ice requires a greater doom."
            result.effects[#result.effects + 1] = "winter_wolf_breath_of_ice_requires_greater_doom"
            return result
        end
        if not action.card then
            result.success = false
            result.description = "Winter Wolf Breath of Ice requires an Attack card."
            result.effects[#result.effects + 1] = "winter_wolf_breath_of_ice_requires_card"
            return result
        end

        local cardValue = action.card.value or 0
        local modifier = actor.swords or (actor.getAttribute and actor:getAttribute(constants.SUITS.SWORDS)) or 0
        local targets = self:getWinterWolfBreathTargets(actor, action)
        local hits = {}
        local misses = {}
        local destroyedItems = {}

        result.cardValue = cardValue
        result.modifier = modifier
        result.testValue = cardValue + modifier
        result.targets = targets
        result.effects[#result.effects + 1] = "winter_wolf_breath_of_ice"
        result.effects[#result.effects + 1] = "greater_doom"

        for _, target in ipairs(targets) do
            local difficulty = self:getZoneAttackTargetInitiative(action, target) or 0
            local targetAction = {
                actor = actor,
                target = target,
                card = action.card,
                type = M.ACTION_TYPES.MELEE,
                targetInitiative = difficulty,
                challengeController = action.challengeController,
                allEntities = action.allEntities,
            }
            local targetResult = {
                effects = {},
                cardValue = cardValue,
                modifier = modifier,
                testValue = result.testValue,
                difficulty = difficulty,
            }
            local contest = self:resolveInitiativeContest(targetAction, targetResult, {
                tieWins = true,
                considerShield = true,
            })
            for _, effect in ipairs(targetResult.effects or {}) do
                result.effects[#result.effects + 1] = effect
            end

            if contest.success then
                if self:doesElementProtectionBlock(target, "cold") then
                    result.effects[#result.effects + 1] = "element_protection_blocked"
                    result.effects[#result.effects + 1] = "protection_from_elements_water_block"
                    hits[#hits + 1] = {
                        target = target,
                        destroyedItems = {},
                        difficulty = difficulty,
                        protected = true,
                    }
                else
                    local destroyed = self:destroyWinterWolfLiquidBeltItems(target, result)
                    for _, item in ipairs(destroyed) do
                        destroyedItems[#destroyedItems + 1] = {
                            target = target,
                            item = item,
                        }
                    end

                    self:applyDamage(target, 1, result.effects, nil, action.allEntities,
                        self:getActionWoundOptions(action, target), {
                            source = "winter_wolf_breath_of_ice",
                            action = action,
                        })
                    hits[#hits + 1] = {
                        target = target,
                        destroyedItems = destroyed,
                        difficulty = difficulty,
                    }
                end
            else
                misses[#misses + 1] = {
                    target = target,
                    difficulty = difficulty,
                    dodged = contest.dodged,
                }
            end
        end

        result.success = #hits > 0
        result.hits = hits
        result.misses = misses
        result.destroyedLiquidItems = destroyedItems
        if #hits > 0 then
            result.effects[#result.effects + 1] = "winter_wolf_breath_hit"
        else
            result.effects[#result.effects + 1] = "winter_wolf_breath_missed"
        end
        result.description = (actor.name or "Winter Wolf") .. " breathes ice over " ..
            tostring(#targets) .. " adventurer(s), hitting " .. tostring(#hits) .. "."

        self.eventBus:emit("winter_wolf_breath_of_ice", {
            actor = actor,
            action = action,
            result = result,
            hits = hits,
            misses = misses,
            destroyedLiquidItems = destroyedItems,
        })

        action.result = result
        return result
    end

    function resolver:isYellowKingLich(entity)
        return entity and (entity.blueprintId == "yellow_king_lich" or
            entity.enemyType == "yellow_king_lich" or entityHasNormalizedTag(entity, "yellow_king") or
            (entity.lich and entity.lich.crownOfArchwood and entity.lich.phylactery))
    end

    function resolver:getYellowKingCrown(entity)
        return entity and entity.lich and entity.lich.crownOfArchwood or nil
    end

    function resolver:yellowKingHasActiveCrown(entity)
        if not self:isYellowKingLich(entity) then
            return false
        end
        local crown = self:getYellowKingCrown(entity)
        local conditions = entity.conditions or {}
        return crown ~= nil and crown.destroyed ~= true and crown.active ~= false and
            crown.disarmed ~= true and crown.worn ~= false and
            conditions.yellow_king_crown_disarmed ~= true
    end

    function resolver:yellowKingLesserDoomReady(action, effectType, doomId)
        local doom = action and (action.lesserDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.lesserDoomCard or action.discardedLesserDoom or action.useLesserDoom == true or
            action.card or (doomId and doom and doom.id == doomId) or (effect and effect.type == effectType))
    end

    function resolver:yellowKingGreaterDoomReady(action, effectType, doomId)
        local doom = action and (action.greaterDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            (doomId and doom and doom.id == doomId) or (effect and effect.type == effectType))
    end

    function resolver:isYellowKingArcaneAttack(action)
        if not (action and self:isYellowKingLich(action.actor)) then
            return false
        end
        local actionType = self:normalizeActionType(action.type or action.normalizedType)
        if actionType ~= M.ACTION_TYPES.MISSILE then
            return false
        end
        local doom = action.lesserDoom or action.attackDoom
        local effect = doom and doom.effect
        return action.yellowKingArcaneAttack == true or action.poisonWontTakeYou == true or
            (doom and doom.id == "poison_wont_take_you") or
            (effect and effect.type == "ranged_arcane_attack")
    end

    function resolver:validateYellowKingArcaneAttack(action, result)
        local actor = action and action.actor
        if not self:yellowKingHasActiveCrown(actor) then
            result.success = false
            result.description = "The Yellow King needs the Crown of Archwood for this attack."
            result.effects[#result.effects + 1] = "yellow_king_crown_required"
            return false
        end

        local doom = action.lesserDoom or action.attackDoom
        local effect = doom and doom.effect or {}
        local range = effect.rangeZones or action.rangeZones or 1
        local target = action.target
        local distance, err = self:getZoneDistance(action, actor and actor.zone, target and target.zone)
        if err or (distance and distance > range) then
            result.success = false
            result.description = "The Yellow King's arcane attack cannot reach that target."
            result.effects[#result.effects + 1] = err or "yellow_king_arcane_attack_out_of_range"
            return false
        end

        action.yellowKingArcaneAttack = true
        result.modifier = actor and actor.wands or 0
        result.testValue = (result.cardValue or (action.card and action.card.value) or 0) + result.modifier
        result.effects[#result.effects + 1] = "yellow_king_arcane_attack"
        result.effects[#result.effects + 1] = "arcane_energy"
        result.effects[#result.effects + 1] = "magic"
        result.effects[#result.effects + 1] = "wands_attack"
        return true
    end

    function resolver:resolveYellowKingSpiteAlone(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isYellowKingLich(actor) then
            result.success = false
            result.description = "Spite Alone Holds Me Aloft requires the Yellow King."
            result.effects[#result.effects + 1] = "yellow_king_spite_blocked"
            return result
        end
        if not self:yellowKingHasActiveCrown(actor) then
            result.success = false
            result.description = "Spite Alone Holds Me Aloft requires the Crown of Archwood."
            result.effects[#result.effects + 1] = "yellow_king_crown_required"
            return result
        end
        if not (action.card or action.discardedCard or action.anyCard or action.miscAction == true) then
            result.success = false
            result.description = "Spite Alone Holds Me Aloft is a miscellaneous action and requires a card."
            result.effects[#result.effects + 1] = "yellow_king_spite_requires_card"
            return result
        end

        actor.conditions = actor.conditions or {}
        actor.conditions.levitating = true
        actor.conditions.flying = true
        actor.conditions.upper_reaches = true
        actor.conditions.yellow_king_spite_alone = true
        actor.flying = true
        actor.yellowKingAloft = {
            active = true,
            source = "spite_alone_holds_me_aloft",
            onlyRangedAttacksCanHit = true,
        }

        result.success = true
        result.effects[#result.effects + 1] = "yellow_king_spite_alone"
        result.effects[#result.effects + 1] = "levitating"
        result.effects[#result.effects + 1] = "only_ranged_attacks_can_hit"
        result.description = (actor.name or "The Yellow King") .. " rises into the upper reaches of the room."

        self.eventBus:emit("yellow_king_spite_alone", {
            actor = actor,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:isYellowKingAloft(entity)
        if not self:isYellowKingLich(entity) then
            return false
        end
        local conditions = entity.conditions or {}
        local aloft = entity.yellowKingAloft
        return conditions.yellow_king_spite_alone == true or
            (aloft and aloft.active ~= false and aloft.onlyRangedAttacksCanHit == true)
    end

    function resolver:resolveYellowKingSorrow(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isYellowKingLich(actor) then
            result.success = false
            result.description = "Sorrow requires the Yellow King."
            result.effects[#result.effects + 1] = "yellow_king_sorrow_blocked"
            return result
        end
        if not self:yellowKingLesserDoomReady(action, "audible_zone_stun_test", "sorrow_sorrow_sorrow") then
            result.success = false
            result.description = "Sorrow requires a lesser doom."
            result.effects[#result.effects + 1] = "yellow_king_sorrow_requires_lesser_doom"
            return result
        end

        local card = action.lesserDoomCard or action.card
        if not card then
            result.success = false
            result.description = "Sorrow requires a lesser doom card."
            result.effects[#result.effects + 1] = "yellow_king_sorrow_missing_card"
            return result
        end

        local onTurn = action.onYellowKingTurn == true or action.onTurn == true or action.isTurnAction == true
        local modifier = onTurn and (actor.wands or 0) or 0
        local sorrowValue = (card.value or 0) + modifier
        local affected = {}
        local skipped = {}
        local candidates = action.targets or action.allEntities or {}

        for _, candidate in ipairs(candidates) do
            local conditions = candidate.conditions or {}
            local canHear = action.canHear == true or not (conditions.deaf or conditions.deafened or
                candidate.canHear == false or candidate.hearing == false)
            if candidate ~= actor and canHear and not conditions.dead and not conditions.deaths_door then
                local initiative = self:getZoneAttackTargetInitiative(action, candidate) or 0
                if sorrowValue >= initiative then
                    local stunDiscard = self:applyStun(candidate, {
                        action = action,
                        instant = true,
                        hand = candidate.challengeHand,
                        handData = candidate.challengeHandData,
                        playerHand = action.playerHand,
                        playerDeck = action.playerDeck,
                        gmDeck = action.gmDeck,
                        npcAI = action.npcAI,
                    })
                    affected[#affected + 1] = {
                        target = candidate,
                        initiative = initiative,
                        stunDiscard = stunDiscard,
                    }
                else
                    skipped[#skipped + 1] = {
                        target = candidate,
                        initiative = initiative,
                        reason = "initiative_not_beaten",
                    }
                end
            elseif candidate ~= actor then
                skipped[#skipped + 1] = {
                    target = candidate,
                    reason = canHear and "ineligible" or "cannot_hear",
                }
            end
        end

        result.success = true
        result.cardValue = card.value or 0
        result.modifier = modifier
        result.testValue = sorrowValue
        result.affected = affected
        result.skipped = skipped
        result.effects[#result.effects + 1] = "yellow_king_sorrow"
        result.effects[#result.effects + 1] = "audible_stun_test"
        if onTurn then
            result.effects[#result.effects + 1] = "wands_added"
        end
        if #affected > 0 then
            result.effects[#result.effects + 1] = "stunned"
        end
        result.description = (actor.name or "The Yellow King") .. " stuns " ..
            tostring(#affected) .. " listener(s) with Sorrow."

        self.eventBus:emit("yellow_king_sorrow", {
            actor = actor,
            action = action,
            result = result,
            affected = affected,
            skipped = skipped,
        })

        action.result = result
        return result
    end

    function resolver:resolveYellowKingFaithfulServant(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isYellowKingLich(actor) then
            result.success = false
            result.description = "Faithful Servant requires the Yellow King."
            result.effects[#result.effects + 1] = "yellow_king_clone_blocked"
            return result
        end
        if not self:yellowKingGreaterDoomReady(action, "summon_dead_guild_clone", "faithful_servant_tender_companion") then
            result.success = false
            result.description = "Faithful Servant requires a greater doom."
            result.effects[#result.effects + 1] = "yellow_king_clone_requires_greater_doom"
            return result
        end

        local cloneName = action.cloneName or action.deadPersonName or "Faithful Servant"
        local clone = base_entity.createEntity({
            id = action.cloneId or ((actor.id or "yellow_king") .. "_clone_" ..
                tostring(#(actor.yellowKingClones or {}) + 1)),
            name = cloneName,
            isPC = false,
            swords = action.swords or 0,
            pentacles = action.pentacles or 0,
            cups = action.cups or 0,
            wands = action.wands or 0,
            health = 1,
            defense = 0,
        })
        clone.blueprintId = "yellow_king_memory_clone"
        clone.enemyType = "memory_clone"
        clone.rank = "minion"
        clone.tags = { "summoned", "temporary", "clone", "dead_guild_member" }
        clone.aiTags = { "summoned", "clone" }
        clone.zone = action.zone or actor.zone
        clone.location = action.location or actor.location
        clone.temporary = true
        clone.knowsLifeMemories = true
        clone.deadPersonName = cloneName
        clone.summonedBy = actor
        clone.summonedById = actor.id

        actor.yellowKingClones = actor.yellowKingClones or {}
        actor.yellowKingClones[#actor.yellowKingClones + 1] = clone

        local controller = action.challengeController or self.challengeController
        if controller then
            controller.npcs = controller.npcs or {}
            controller.allCombatants = controller.allCombatants or {}
            controller.npcs[#controller.npcs + 1] = clone
            controller.allCombatants[#controller.allCombatants + 1] = clone
        end

        result.success = true
        result.summonedEntity = clone
        result.effects[#result.effects + 1] = "yellow_king_faithful_servant"
        result.effects[#result.effects + 1] = "dead_guild_clone_summoned"
        result.effects[#result.effects + 1] = "temporary_clone"
        result.description = (actor.name or "The Yellow King") .. " summons " .. cloneName .. " from memory."

        self.eventBus:emit("yellow_king_faithful_servant", {
            actor = actor,
            clone = clone,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:resolveYellowKingDoubtMeTraitor(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target or action.attacker or (action.incomingAction and action.incomingAction.actor)

        if not self:isYellowKingLich(actor) then
            result.success = false
            result.description = "Do You Doubt Me, Traitor? requires the Yellow King."
            result.effects[#result.effects + 1] = "yellow_king_doubt_blocked"
            return result
        end
        if not target then
            result.success = false
            result.description = "Do You Doubt Me, Traitor? needs the attacker."
            result.effects[#result.effects + 1] = "yellow_king_doubt_missing_target"
            return result
        end
        if not self:yellowKingGreaterDoomReady(action, "damage_reaction_temporary_character_sheet_loss",
            "do_you_doubt_me_traitor") then
            result.success = false
            result.description = "Do You Doubt Me, Traitor? requires a greater doom."
            result.effects[#result.effects + 1] = "yellow_king_doubt_requires_greater_doom"
            return result
        end

        target.conditions = target.conditions or {}
        target.conditions.yellow_king_sheet_loss = true
        target.temporarySheetLosses = target.temporarySheetLosses or {}
        local loss = {
            source = "yellow_king_do_you_doubt_me_traitor",
            sourceId = actor.id,
            lossType = action.lossType or action.crossOffType or "sheet_entry",
            label = action.lossLabel or action.crossOff or action.sheetEntry or "character sheet entry",
            restoredAt = "end_next_camp_phase",
            active = true,
        }
        target.temporarySheetLosses[#target.temporarySheetLosses + 1] = loss
        target.yellowKingSheetLoss = loss

        result.success = true
        result.countsTowardTurnCard = false
        result.sheetLoss = loss
        result.effects[#result.effects + 1] = "yellow_king_do_you_doubt_me_traitor"
        result.effects[#result.effects + 1] = "temporary_sheet_loss"
        result.effects[#result.effects + 1] = "restores_end_next_camp"
        result.description = (target.name or "The attacker") .. " crosses off " ..
            tostring(loss.label) .. " until the end of the next Camp Phase."

        self.eventBus:emit("yellow_king_do_you_doubt_me_traitor", {
            actor = actor,
            target = target,
            loss = loss,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:applyYellowKingEnchantAttack(target, effect, action, result, doom)
        result.effects = result.effects or {}
        result.damageDealt = 0
        result.effects[#result.effects + 1] = "yellow_king_enchant"
        result.effects[#result.effects + 1] = "wound_replaced"

        if isControlImmuneTarget(target) then
            result.yellowKingEnchantBlocked = "control_immune"
            result.effects[#result.effects + 1] = "control_immune"
            return nil
        end

        target.conditions = target.conditions or {}
        target.conditions.controlled = true
        target.conditions.yellow_king_enchanted = true
        target.controlledBy = action.actor
        target.controlOrder = {
            text = action.controlOrder or action.command or "irrational_task",
            source = "yellow_king_enchant",
            immediate = true,
        }
        target.controlCommandsRemaining = 1
        target.yellowKingEnchanted = {
            yellowKing = action.actor,
            yellowKingId = action.actor and action.actor.id,
            command = target.controlOrder.text,
            controlledActionValue = tonumber(action and action.card and action.card.value) or result.cardValue or 0,
            irrational = true,
        }

        result.controlledActionValue = target.yellowKingEnchanted.controlledActionValue
        result.yellowKingEnchant = target.yellowKingEnchanted
        result.effects[#result.effects + 1] = "controlled"
        result.effects[#result.effects + 1] = "irrational_task"
        if doom and doom.id == "enchant_insane_task" then
            result.effects[#result.effects + 1] = "yellow_king_enchant_greater_doom"
        end

        local priorCompletes = action.controlOrderCompletesAfterImmediate
        action.controlOrderCompletesAfterImmediate = false
        local immediateResult = self:resolveImmediateControlAction(action, result, action.actor, target)
        action.controlOrderCompletesAfterImmediate = priorCompletes

        if immediateResult and action.controlPersists ~= true then
            target.conditions.controlled = false
            target.conditions.yellow_king_enchanted = false
            target.controlledBy = nil
            target.controlOrder = nil
            target.controlCommandsRemaining = 0
            target.lastYellowKingEnchant = target.yellowKingEnchanted
            target.yellowKingEnchanted = nil
            result.effects[#result.effects + 1] = "yellow_king_enchant_released"
        end

        return result.yellowKingEnchant
    end

    function resolver:resolveYellowKingCrystalSkullDamage(entity, amount, effects, weapon, damageContext)
        local conditions = entity and entity.conditions or {}
        if not (self:isYellowKingLich(entity) and (amount or 0) > 0 and
            (conditions.yellow_king_crystal_skull or entity.yellowKingCrystalSkull)) then
            return nil
        end

        effects[#effects + 1] = "yellow_king_crystal_skull_invulnerable"
        effects[#effects + 1] = "damage_ignored"
        self.eventBus:emit("yellow_king_crystal_skull_invulnerable", {
            entity = entity,
            weapon = weapon,
            damageContext = damageContext,
        })
        return {
            result = "immune",
            immune = true,
            reason = "yellow_king_crystal_skull",
        }
    end

    function resolver:resolveYellowKingBodyDefeat(entity, effects, damageContext)
        if not self:isYellowKingLich(entity) or entity.yellowKingBodyDefeated then
            return nil
        end

        local phylactery = entity.lich and entity.lich.phylactery or {}
        local final = phylactery.destroyed == true or phylactery.active == false
        entity.yellowKingBodyDefeated = true
        entity.bodyCrumpledToCrystalSkull = not final
        entity.yellowKingFinalDefeat = final
        entity.conditions = entity.conditions or {}

        if final then
            effects[#effects + 1] = "yellow_king_final_defeat"
        else
            entity.conditions.yellow_king_crystal_skull = true
            entity.yellowKingCrystalSkull = {
                active = true,
                impenetrable = true,
                invulnerable = true,
                regrowsBodyUnlessPhylacteryDestroyed = true,
                phylactery = phylactery,
            }
            effects[#effects + 1] = "yellow_king_body_crumpled"
            effects[#effects + 1] = "yellow_king_crystal_skull"
            effects[#effects + 1] = "body_regrows_if_phylactery_intact"
        end

        self.eventBus:emit("yellow_king_body_defeated", {
            entity = entity,
            final = final,
            crystalSkull = entity.yellowKingCrystalSkull,
            damageContext = damageContext,
        })

        return entity.yellowKingCrystalSkull or {
            final = true,
        }
    end

    function resolver:disarmYellowKingCrown(entity, action, result)
        local crown = self:getYellowKingCrown(entity)
        if not crown then
            return nil
        end

        crown.worn = false
        crown.disarmed = true
        crown.active = false
        crown.dropped = true
        entity.conditions = entity.conditions or {}
        entity.conditions.yellow_king_crown_disarmed = true
        entity.conditions.disarmed = true
        entity.yellowKingCrownDropped = {
            crown = crown,
            reason = "disarm",
            by = action and action.actor,
        }

        if result then
            result.yellowKingCrown = crown
            result.effects[#result.effects + 1] = "yellow_king_crown_disarmed"
            result.effects[#result.effects + 1] = "crown_of_archwood_inactive"
            result.description = "Disarmed the Crown of Archwood!"
        end
        return crown
    end

    function resolver:recoverYellowKingCrown(entity, result)
        local crown = self:getYellowKingCrown(entity)
        if not crown or crown.destroyed then
            return nil
        end

        crown.worn = true
        crown.disarmed = false
        crown.active = true
        crown.dropped = false
        entity.conditions = entity.conditions or {}
        entity.conditions.yellow_king_crown_disarmed = false
        entity.conditions.disarmed = false
        entity.yellowKingCrownDropped = nil

        if result then
            result.yellowKingCrown = crown
            result.effects[#result.effects + 1] = "yellow_king_crown_recovered"
            result.effects[#result.effects + 1] = "crown_of_archwood_active"
            result.description = "Recovered the Crown of Archwood!"
        end
        return crown
    end

    function resolver:isYellowKingDayOfTears(action)
        if not (action and self:isYellowKingLich(action.actor)) then
            return false
        end
        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect
        return action.useYellowKingDayOfTears == true or action.dayOfTearsAndMourning == true or
            (doom and doom.id == "day_of_tears_and_mourning") or
            (effect and effect.type == "componentless_appendix_a_spellcasting")
    end

    function resolver:getYellowKingDayOfTearsResolve(action)
        local extraCards = action and (action.extraGreaterDoomCards or action.additionalGreaterDoomCards)
        local extra = action and (action.extraGreaterDoomCount or action.additionalGreaterDoomCount) or 0
        if type(extraCards) == "table" then
            extra = extra + #extraCards
        end
        return 1 + math.max(0, extra)
    end

    function resolver:validateYellowKingDayOfTears(action, result)
        if not self:isYellowKingDayOfTears(action) then
            return true
        end
        if not self:yellowKingHasActiveCrown(action.actor) then
            result.success = false
            result.description = "Day of Tears and Mourning requires the Crown of Archwood."
            result.effects[#result.effects + 1] = "yellow_king_crown_required"
            return false
        end
        if not self:yellowKingGreaterDoomReady(action, "componentless_appendix_a_spellcasting",
            "day_of_tears_and_mourning") then
            result.success = false
            result.description = "Day of Tears and Mourning requires a greater doom."
            result.effects[#result.effects + 1] = "yellow_king_day_of_tears_requires_greater_doom"
            return false
        end
        return true
    end

    function resolver:isJinn(entity)
        return entity and (entity.jinn ~= nil or entityHasNormalizedTag(entity, "jinn"))
    end

    function resolver:jinnAnyCardReady(action)
        return action and (action.card or action.discardedCard or action.anyCard == true or
            action.lesserDoomCard or action.discardedLesserDoom)
    end

    function resolver:setJinnTangibility(jinn, tangible, reason)
        if not jinn then
            return nil
        end

        jinn.conditions = jinn.conditions or {}
        jinn.tangible = tangible == true
        jinn.intangible = tangible ~= true
        jinn.incorporeal = tangible ~= true
        jinn.conditions.tangible = tangible == true
        jinn.conditions.intangible = tangible ~= true
        jinn.conditions.incorporeal = tangible ~= true
        jinn.conditions.jinn_smokeless_fire = tangible ~= true
        jinn.jinnTangibility = {
            tangible = tangible == true,
            intangible = tangible ~= true,
            reason = reason or "body_of_smokeless_fire",
        }
        return jinn.jinnTangibility
    end

    function resolver:resolveJinnBodyOfSmokelessFire(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isJinn(actor) then
            result.success = false
            result.description = "Body of Smokeless Fire requires a jinn."
            result.effects[#result.effects + 1] = "jinn_body_requires_jinn"
            return result
        end
        if not self:jinnAnyCardReady(action) then
            result.success = false
            result.description = "Body of Smokeless Fire requires any discarded card."
            result.effects[#result.effects + 1] = "jinn_body_requires_card"
            return result
        end

        local becomeTangible = action.becomeTangible
        if becomeTangible == nil then
            local conditions = actor.conditions or {}
            becomeTangible = actor.intangible == true or conditions.intangible == true or actor.tangible == false
        end

        result.success = true
        result.countsTowardTurnCard = false
        result.tangibility = self:setJinnTangibility(actor, becomeTangible == true, "body_of_smokeless_fire")
        result.effects[#result.effects + 1] = "jinn_body_of_smokeless_fire"
        if becomeTangible then
            result.effects[#result.effects + 1] = "jinn_tangible"
            result.description = (actor.name or "Jinn") .. " becomes tangible."
        else
            result.effects[#result.effects + 1] = "jinn_intangible"
            result.effects[#result.effects + 1] = "physical_objects_pass_through"
            result.description = (actor.name or "Jinn") .. " becomes intangible smokeless fire."
        end

        self.eventBus:emit("jinn_body_of_smokeless_fire", {
            actor = actor,
            tangibility = result.tangibility,
            action = action,
        })

        action.result = result
        return result
    end

    function resolver:resolveJinnInvisible(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isJinn(actor) then
            result.success = false
            result.description = "Invisible requires a jinn."
            result.effects[#result.effects + 1] = "jinn_invisible_requires_jinn"
            return result
        end
        if not self:jinnAnyCardReady(action) then
            result.success = false
            result.description = "Invisible requires any played card."
            result.effects[#result.effects + 1] = "jinn_invisible_requires_card"
            return result
        end

        actor.conditions = actor.conditions or {}
        actor.conditions.shrouded = true
        actor.conditions.invisible = true
        actor.conditions.jinn_invisible = true
        actor.shroudedBy = actor
        actor.jinnInvisibility = {
            source = "jinn_invisible",
            endsOnPhysicalInteraction = true,
            cannotBeDeliberatelyTargetedWhileStillQuiet = true,
            startedRound = action.round,
        }
        actor.shroud = {
            caster = actor,
            source = "jinn_invisible",
            jinnInvisible = true,
            endsOnPhysicalInteraction = true,
            cannotBeDeliberatelyTargetedWhileStillQuiet = true,
            vaguePresenceKnown = false,
        }

        result.success = true
        result.jinnInvisibility = actor.jinnInvisibility
        result.effects[#result.effects + 1] = "jinn_invisible"
        result.effects[#result.effects + 1] = "shrouded"
        result.effects[#result.effects + 1] = "invisible"
        result.description = (actor.name or "Jinn") .. " becomes Shrouded."

        self.eventBus:emit("jinn_invisible", {
            actor = actor,
            action = action,
            shroud = actor.shroud,
        })

        action.result = result
        return result
    end

    function resolver:clearJinnInvisibility(jinn, reason)
        if not self:isJinn(jinn) then
            return nil
        end
        local conditions = jinn.conditions or {}
        local shroud = jinn.shroud
        if not (conditions.jinn_invisible or jinn.jinnInvisibility or
           (shroud and shroud.source == "jinn_invisible")) then
            return nil
        end

        conditions.shrouded = false
        conditions.invisible = false
        conditions.jinn_invisible = false
        if shroud and shroud.source == "jinn_invisible" then
            jinn.shroud = nil
        end
        jinn.jinnInvisibility = nil
        jinn.shroudedBy = nil

        local cleared = {
            actor = jinn,
            reason = reason or "physical_interaction",
            source = "jinn_invisible",
        }
        jinn.lastJinnInvisibility = cleared
        self.eventBus:emit("jinn_invisibility_ended", cleared)
        return cleared
    end

    function resolver:isJinnPhysicalInteractionAction(actionType, action)
        if not action then
            return false
        end
        if action.physicalInteraction == true or action.interactsWithPhysicalWorld == true then
            return true
        end
        if action.physicalInteraction == false or action.interactsWithPhysicalWorld == false then
            return false
        end
        if actionType == M.ACTION_TYPES.JINN_BODY_OF_SMOKELESS_FIRE or
           actionType == M.ACTION_TYPES.JINN_INVISIBLE then
            return false
        end
        if isHarmfulChallengeAction(actionType, action) then
            return true
        end
        if actionType == M.ACTION_TYPES.TRIVIAL_ACTION then
            local intent = normalizeTrivialIntent(action)
            return intent == "open_door" or intent == "open" or
                intent == "throw_lever" or intent == "pull_lever" or intent == "lower_crossbar"
        end
        return false
    end

    function resolver:clearJinnInvisibilityForPhysicalInteraction(actor, actionType, action, result)
        if not (actor and self:isJinn(actor) and self:isJinnPhysicalInteractionAction(actionType, action)) then
            return nil
        end

        local cleared = self:clearJinnInvisibility(actor, "physical_interaction")
        if cleared and result then
            result.jinnInvisibilityEnded = cleared
            result.effects[#result.effects + 1] = "jinn_invisibility_ended"
            result.effects[#result.effects + 1] = "shroud_ended"
        end
        return cleared
    end

    function resolver:getJinnSecondSightMagicalEffects(actor, subjects)
        if not self:isJinn(actor) then
            return {}
        end

        local seen = {}
        for _, subject in ipairs(subjects or {}) do
            if subject then
                local effects = {}
                local conditions = subject.conditions or {}
                local props = subject.properties or {}
                if subject.magicEffects then
                    for _, effect in ipairs(subject.magicEffects) do
                        effects[#effects + 1] = effect
                    end
                end
                if subject.activeSpells and #subject.activeSpells > 0 then
                    effects[#effects + 1] = "active_spells"
                end
                if subject.shroud or conditions.shrouded or conditions.invisible then
                    effects[#effects + 1] = "shrouded"
                end
                if subject.intangible or conditions.intangible or props.intangible then
                    effects[#effects + 1] = "intangible"
                end
                if subject.magical == true or props.magical == true or props.magic == true then
                    effects[#effects + 1] = "magical"
                end
                if #effects > 0 then
                    seen[#seen + 1] = {
                        subject = subject,
                        effects = effects,
                    }
                end
            end
        end
        return seen
    end

    function resolver:isJinnIntangible(entity)
        if not self:isJinn(entity) then
            return false
        end
        local conditions = entity.conditions or {}
        return entity.intangible == true or entity.tangible == false or
            conditions.intangible == true or conditions.tangible == false
    end

    function resolver:resolveJinnBodyOfSmokelessFireDamage(entity, amount, effects, weapon, damageContext)
        if not (self:isJinnIntangible(entity) and (amount or 0) > 0) then
            return nil
        end

        damageContext = damageContext or {}
        if damageContext.magic == true or damageContext.spell == true or damageContext.fire == true then
            return nil
        end
        for _, effect in ipairs(effects or {}) do
            local normalized = normalizeTalentKey(effect)
            if normalized == "magic" or normalized == "spell" or normalized == "sorcery" or
               normalized == "fire" or normalized == "heavenfire" then
                return nil
            end
        end
        if not self:isWraithPhysicalDamage(effects, weapon, damageContext) then
            return nil
        end

        effects[#effects + 1] = "jinn_body_of_smokeless_fire_immune"
        effects[#effects + 1] = "physical_objects_pass_through"
        self.eventBus:emit("jinn_body_of_smokeless_fire_immune", {
            entity = entity,
            weapon = weapon,
            damageContext = damageContext,
        })
        return {
            result = "immune",
            immune = true,
            reason = "jinn_body_of_smokeless_fire",
        }
    end

    function resolver:applyJinnPossessAttack(target, effect, action, result, doom)
        result.effects = result.effects or {}
        result.damageDealt = 0
        result.controlledActionValue = tonumber(action and action.card and action.card.value) or
            result.cardValue or result.testValue or 0
        result.effects[#result.effects + 1] = "jinn_possess"
        result.effects[#result.effects + 1] = "wound_replaced"

        if isControlImmuneTarget(target) then
            result.jinnPossessBlocked = "control_immune"
            result.effects[#result.effects + 1] = "control_immune"
            return nil
        end

        target.conditions = target.conditions or {}
        target.conditions.controlled = true
        target.controlledBy = action.actor
        target.controlOrder = {
            text = action.controlOrder or action.command or "immediate_command",
            source = "jinn_possess",
            immediate = true,
        }
        target.controlCommandsRemaining = 1
        target.jinnPossession = {
            jinn = action.actor,
            jinnId = action.actor and action.actor.id,
            command = target.controlOrder.text,
            controlledActionValue = result.controlledActionValue,
        }

        result.jinnPossess = target.jinnPossession
        result.effects[#result.effects + 1] = "controlled"
        if doom and doom.id == "possess" then
            result.effects[#result.effects + 1] = "jinn_possess_greater_doom"
        end

        local priorCompletes = action.controlOrderCompletesAfterImmediate
        action.controlOrderCompletesAfterImmediate = false
        local immediateResult = self:resolveImmediateControlAction(action, result, action.actor, target)
        action.controlOrderCompletesAfterImmediate = priorCompletes

        if immediateResult and action.controlPersists ~= true then
            target.conditions.controlled = false
            target.controlledBy = nil
            target.controlOrder = nil
            target.controlCommandsRemaining = 0
            target.jinnPossession = nil
            target.lastJinnPossession = result.jinnPossess
            result.effects[#result.effects + 1] = "jinn_possession_released"
        end

        return result.jinnPossess
    end

    function resolver:isVampire(entity)
        return entity and (entity.vampire ~= nil or entityHasNormalizedTag(entity, "vampire"))
    end

    function resolver:actionAvoidsVampireGaze(action, actionType)
        if not action then
            return false
        end
        if not (action.avoidsVampireGaze == true or action.avoidVampireGaze == true or
           action.actorAvoidsVampireGaze == true or
           (action.actor and action.actor.avoidingVampireGaze == true)) then
            return false
        end
        return self:isVampire(action.target) and isHarmfulChallengeAction(actionType, action)
    end

    function resolver:isImp(entity)
        return entity and (entity.imp ~= nil or entityHasNormalizedTag(entity, "imp"))
    end

    function resolver:vampireLesserDoomReady(action, effectType, doomId)
        local doom = action and (action.lesserDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.lesserDoomCard or action.discardedLesserDoom or action.useLesserDoom == true or
            action.card or (doomId and doom and doom.id == doomId) or (effect and effect.type == effectType))
    end

    function resolver:vampireGreaterDoomReady(action, effectType, doomId)
        local doom = action and (action.greaterDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            (doomId and doom and doom.id == doomId) or (effect and effect.type == effectType))
    end

    function resolver:impGreaterDoomReady(action, effectType, doomId)
        local doom = action and (action.greaterDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            (doomId and doom and doom.id == doomId) or (effect and effect.type == effectType))
    end

    function resolver:getVampireDoomCard(action, kind)
        if not action then
            return nil
        end
        if kind == "greater" then
            return action.greaterDoomCard or action.card
        end
        return action.lesserDoomCard or action.card
    end

    function resolver:resolveVampireCallBats(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isVampire(actor) then
            result.success = false
            result.description = "Call Bats requires a vampire."
            result.effects[#result.effects + 1] = "vampire_call_bats_blocked"
            return result
        end
        if not self:vampireLesserDoomReady(action, "summon_bat_cloud", "call_bats") then
            result.success = false
            result.description = "Call Bats requires a lesser doom."
            result.effects[#result.effects + 1] = "vampire_call_bats_requires_lesser_doom"
            return result
        end

        local card = self:getVampireDoomCard(action, "lesser")
        local bat = base_entity.createEntity({
            id = action.batId or ((actor.id or "vampire") .. "_bat_cloud_" .. tostring(#(actor.batClouds or {}) + 1)),
            name = action.batName or "Cloud of Bats",
            isPC = false,
            swords = 0,
            pentacles = 0,
            cups = 0,
            wands = 0,
            health = 2,
            defense = 0,
        })
        bat.blueprintId = "vampire_bat_cloud"
        bat.enemyType = "bats"
        bat.rank = "minion"
        bat.tags = { "beast", "minion", "bats", "summoned" }
        bat.aiTags = { "beast", "bats", "summoned" }
        bat.zone = action.zone or actor.zone
        bat.location = action.location or actor.location
        bat.initiative = card and card.value or action.initiative
        bat.initiativeCard = card
        bat.gmChallengeCardsBonus = action.gmChallengeCardsBonus or 2
        bat.summonedBy = actor
        bat.summonedById = actor.id

        actor.batClouds = actor.batClouds or {}
        actor.batClouds[#actor.batClouds + 1] = bat

        local controller = action.challengeController or self.challengeController
        if controller then
            controller.npcs = controller.npcs or {}
            controller.allCombatants = controller.allCombatants or {}
            controller.npcs[#controller.npcs + 1] = bat
            controller.allCombatants[#controller.allCombatants + 1] = bat
        end

        result.success = true
        result.summonedEntity = bat
        result.gmChallengeCardsBonus = bat.gmChallengeCardsBonus
        result.effects[#result.effects + 1] = "vampire_call_bats"
        result.effects[#result.effects + 1] = "bat_cloud_summoned"
        result.effects[#result.effects + 1] = "gm_challenge_cards_bonus"
        result.description = (actor.name or "Vampire") .. " summons a cloud of bats."

        self.eventBus:emit("vampire_call_bats", {
            actor = actor,
            batCloud = bat,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:resolveVampireSupernaturalGrace(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local card = action.card or action.lesserDoomCard

        if not self:isVampire(actor) then
            result.success = false
            result.description = "Supernatural Grace requires a vampire."
            result.effects[#result.effects + 1] = "vampire_supernatural_grace_blocked"
            return result
        end
        if not self:vampireLesserDoomReady(action, "unlimited_facedown_dodge", "supernatural_grace") or not card then
            result.success = false
            result.description = "Supernatural Grace requires a Dodge card."
            result.effects[#result.effects + 1] = "vampire_supernatural_grace_requires_card"
            return result
        end

        local faceValue = card.value or 0
        local defenseValue = action.defenseValue or action.dodgeValue
        if not defenseValue then
            defenseValue = faceValue + (action.isMinorAction and 0 or (actor.cups or 0))
        end

        local defense = {
            type = "dodge",
            card = card,
            value = defenseValue,
            faceValue = faceValue,
            modifier = defenseValue - faceValue,
            vampireSupernaturalGrace = true,
            source = "vampire_supernatural_grace",
        }
        actor.vampireDodgeCards = actor.vampireDodgeCards or {}
        actor.vampireDodgeCards[#actor.vampireDodgeCards + 1] = defense

        result.success = true
        result.defense = defense
        result.effects[#result.effects + 1] = "vampire_supernatural_grace"
        result.effects[#result.effects + 1] = "dodge_prepared"
        result.effects[#result.effects + 1] = "unlimited_facedown_dodge"
        result.description = (actor.name or "Vampire") .. " prepares a Supernatural Grace Dodge."

        self.eventBus:emit("defense_prepared", {
            entity = actor,
            type = "dodge",
            value = defenseValue,
            faceValue = faceValue,
            modifier = defense.modifier,
            vampireSupernaturalGrace = true,
        })

        action.result = result
        return result
    end

    function resolver:consumeVampireGraceDefense(action, target)
        if not (self:isVampire(target) and target.vampireDodgeCards and #target.vampireDodgeCards > 0) then
            return nil
        end

        local index = action and action.vampireDodgeIndex
        if not index then
            local bestValue = -math.huge
            for i, defense in ipairs(target.vampireDodgeCards) do
                local value = defense.value or 0
                if value > bestValue then
                    bestValue = value
                    index = i
                end
            end
        end

        local defense = table.remove(target.vampireDodgeCards, index or 1)
        if #target.vampireDodgeCards == 0 then
            target.vampireDodgeCards = nil
        end
        return defense
    end

    function resolver:resolveVampireSupernaturalSpeed(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isVampire(actor) then
            result.success = false
            result.description = "Supernatural Speed requires a vampire."
            result.effects[#result.effects + 1] = "vampire_supernatural_speed_blocked"
            return result
        end

        local cards = action.lesserDoomCards or action.discardedLesserDoomCards or action.cards
        local cardCount = action.cardCount or action.lesserDoomCount or (cards and #cards) or
            ((action.lesserDoomCard or action.card) and 1 or 0)
        if cardCount <= 0 then
            result.success = false
            result.description = "Supernatural Speed requires at least one lesser doom."
            result.effects[#result.effects + 1] = "vampire_supernatural_speed_requires_lesser_doom"
            return result
        end

        local destination = action.destinationZone or action.targetZone
        if destination then
            local canMove, moveErr = self:canMoveBetweenZones(action, actor.zone, destination, {
                maxDistance = cardCount,
            })
            if not canMove then
                result.success = false
                result.description = "Supernatural Speed cannot reach that zone."
                result.effects[#result.effects + 1] = moveErr or "zones_too_far"
                return result
            end

            local oldZone = actor.zone
            if self.zoneSystem and actor.id then
                local placed, err = self.zoneSystem:placeEntity(actor.id, destination)
                if not placed then
                    result.success = false
                    result.description = "Supernatural Speed zone movement failed."
                    result.effects[#result.effects + 1] = err or "zone_sync_failed"
                    return result
                end
            end
            actor.zone = destination
            self:clearAllEngagements(actor, action.allEntities)
            self.eventBus:emit("entity_zone_changed", {
                entity = actor,
                oldZone = oldZone,
                newZone = destination,
                source = "vampire_supernatural_speed",
            })
        else
            self:clearAllEngagements(actor, action.allEntities)
        end

        result.success = true
        result.countsTowardTurnCard = false
        result.zonesMoved = cardCount
        result.effects[#result.effects + 1] = "vampire_supernatural_speed"
        result.effects[#result.effects + 1] = "moved"
        result.description = (actor.name or "Vampire") .. " moves with supernatural speed."

        action.result = result
        return result
    end

    function resolver:resolveVampireBatForm(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isVampire(actor) then
            result.success = false
            result.description = "Bat Form requires a vampire."
            result.effects[#result.effects + 1] = "vampire_bat_form_blocked"
            return result
        end
        if not self:vampireGreaterDoomReady(action, "bat_form", "bat_form") then
            result.success = false
            result.description = "Bat Form requires a greater doom."
            result.effects[#result.effects + 1] = "vampire_bat_form_requires_greater_doom"
            return result
        end

        actor.conditions = actor.conditions or {}
        actor.conditions.bat_form = true
        actor.conditions.flying = true
        actor.flying = true
        actor.vampireForm = "bat"
        actor.vampireBatForm = {
            active = true,
            flyMoveZones = action.flyMoveZones or 1,
        }

        result.success = true
        result.effects[#result.effects + 1] = "vampire_bat_form"
        result.effects[#result.effects + 1] = "flying"
        result.description = (actor.name or "Vampire") .. " becomes a monstrous bat."

        action.result = result
        return result
    end

    function resolver:resolveVampireMistForm(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not self:isVampire(actor) then
            result.success = false
            result.description = "Mist Form requires a vampire."
            result.effects[#result.effects + 1] = "vampire_mist_form_blocked"
            return result
        end
        if not self:vampireGreaterDoomReady(action, "mist_form", "mist_form") then
            result.success = false
            result.description = "Mist Form requires a greater doom."
            result.effects[#result.effects + 1] = "vampire_mist_form_requires_greater_doom"
            return result
        end

        actor.conditions = actor.conditions or {}
        actor.conditions.mist_form = true
        actor.conditions.vampire_mist = true
        actor.conditions.intangible = true
        actor.intangible = true
        actor.incorporeal = true
        actor.tangible = false
        actor.vampireForm = "mist"
        actor.vampireMistForm = {
            active = true,
            physicalObjectsPassThrough = true,
        }

        result.success = true
        result.effects[#result.effects + 1] = "vampire_mist_form"
        result.effects[#result.effects + 1] = "intangible"
        result.effects[#result.effects + 1] = "physical_objects_pass_through"
        result.description = (actor.name or "Vampire") .. " becomes intangible mist."

        action.result = result
        return result
    end

    function resolver:resolveVampireMistFormDamage(entity, amount, effects, weapon, damageContext)
        if not (entity and (amount or 0) > 0) then
            return nil
        end
        local conditions = entity.conditions or {}
        if not (conditions.mist_form or conditions.vampire_mist or entity.vampireForm == "mist") then
            return nil
        end
        damageContext = damageContext or {}
        if damageContext.bypassesMistForm == true or damageContext.strongWind == true or
           damageContext.extremeCold == true then
            return nil
        end
        if not self:isWraithPhysicalDamage(effects, weapon, damageContext) then
            return nil
        end

        effects[#effects + 1] = "vampire_mist_form_immune"
        effects[#effects + 1] = "physical_objects_pass_through"
        self.eventBus:emit("vampire_mist_form_immune", {
            entity = entity,
            weapon = weapon,
            damageContext = damageContext,
        })
        return {
            result = "immune",
            immune = true,
            reason = "vampire_mist_form",
        }
    end

    function resolver:isVampireInvulnerabilityNegated(entity, effects, damageContext)
        damageContext = damageContext or {}
        local conditions = entity and entity.conditions or {}
        if damageContext.sunlight == true or damageContext.wholesomeHerbs == true or
           damageContext.garlic == true or damageContext.freshHerbs == true or
           conditions.sunlight == true or conditions.vampire_weaknesses == true then
            return true
        end
        for _, effect in ipairs(effects or {}) do
            local normalized = normalizeTalentKey(effect)
            if normalized == "sunlight" or normalized == "wholesome_herbs" or
               normalized == "fresh_herbs" or normalized == "garlic" or
               normalized == "vampire_weaknesses" then
                return true
            end
        end
        return false
    end

    function resolver:isVampireAllowedDamage(effects, weapon, damageContext)
        damageContext = damageContext or {}
        if damageContext.magic == true or damageContext.spell == true or damageContext.fire == true then
            return true
        end
        for _, effect in ipairs(effects or {}) do
            local normalized = normalizeTalentKey(effect)
            if normalized == "magic" or normalized == "spell" or normalized == "sorcery" or
               normalized == "fire" or normalized == "heavenfire" or normalized == "silver" or
               normalized == "silver_weapon" or normalized == "silver_weapons" then
                return true
            end
        end
        return self:isSilverWeapon(weapon)
    end

    function resolver:resolveVampireInvulnerabilityDamage(entity, amount, effects, weapon, damageContext)
        if not (self:isVampire(entity) and (amount or 0) > 0) then
            return nil
        end
        if self:isVampireInvulnerabilityNegated(entity, effects, damageContext) then
            return nil
        end
        if self:isVampireAllowedDamage(effects, weapon, damageContext) then
            return nil
        end

        effects[#effects + 1] = "vampire_invulnerable"
        effects[#effects + 1] = "damage_ignored"
        self.eventBus:emit("vampire_invulnerable_damage_ignored", {
            entity = entity,
            weapon = weapon,
            damageContext = damageContext,
        })
        return {
            result = "immune",
            immune = true,
            reason = "vampire_invulnerable",
        }
    end

    function resolver:snapshotVampireFeedTarget(target)
        if not target then
            return nil
        end
        local conditions = target.conditions or {}
        return {
            woundedTalents = target.woundedTalents or 0,
            staggered = conditions.staggered == true,
            injured = conditions.injured == true,
            deathsDoor = conditions.deaths_door == true,
            dead = conditions.dead == true,
        }
    end

    function resolver:vampireAttackOpenedBlood(before, target)
        if not before or not target then
            return false
        end
        local conditions = target.conditions or {}
        return (target.woundedTalents or 0) > (before.woundedTalents or 0) or
            (not before.staggered and conditions.staggered == true) or
            (not before.injured and conditions.injured == true) or
            (not before.deathsDoor and conditions.deaths_door == true) or
            (not before.dead and conditions.dead == true)
    end

    function resolver:applyVampireFeedAfterAttack(action, result, target, before)
        local actor = action and action.actor
        if not (self:isVampire(actor) and target and result and result.success) then
            return nil
        end
        if not (action.useVampireFeed == true or action.vampireFeed == true or
           action.vampireFeedCard or action.discardedFeedCard) then
            return nil
        end
        if not self:vampireAttackOpenedBlood(before, target) then
            result.effects[#result.effects + 1] = "vampire_feed_no_condition_wound"
            return nil
        end

        local healed = self:healNPCHealth(actor, action.vampireFeedHeal or 1)
        actor.lastVampireFeed = {
            target = target,
            targetId = target.id,
            healed = healed,
            card = action.vampireFeedCard or action.discardedFeedCard,
        }
        result.vampireFeed = actor.lastVampireFeed
        result.effects[#result.effects + 1] = "vampire_feed"
        if healed > 0 then
            result.effects[#result.effects + 1] = "healed"
        end
        self.eventBus:emit("vampire_feed", {
            actor = actor,
            target = target,
            healed = healed,
            action = action,
        })
        return actor.lastVampireFeed
    end

    function resolver:applyVampireMesmerizeAttack(target, effect, action, result, doom)
        result.effects = result.effects or {}
        result.damageDealt = 0
        result.effects[#result.effects + 1] = "vampire_mesmerize"
        result.effects[#result.effects + 1] = "wound_replaced"

        local reflectedGaze = self:consumeMirrorGazeReflection(action.actor, action, result)
        if reflectedGaze then
            result.vampireMesmerizeBlocked = "mirror_reflected"
            result.vampireMesmerizeReflection = reflectedGaze
            result.effects[#result.effects + 1] = "vampire_mesmerize_mirror_reflected"

            local actor = action.actor
            if actor and not isControlImmuneTarget(actor) then
                actor.conditions = actor.conditions or {}
                actor.conditions.controlled = true
                actor.conditions.mesmerized = true
                actor.controlledBy = target
                actor.controlOrder = {
                    text = "reflected_gaze",
                    source = "mirror_reflected_vampire_mesmerize",
                    immediate = false,
                }
                actor.controlCommandsRemaining = 0
                actor.vampireMesmerizedByMirror = {
                    vampire = actor,
                    vampireId = actor.id,
                    reflectedBy = target,
                    reflectedById = target and target.id,
                    source = "mirror",
                }
                result.effects[#result.effects + 1] = "controlled"
                result.effects[#result.effects + 1] = "mesmerized"
                result.vampireMesmerize = actor.vampireMesmerizedByMirror
            else
                result.effects[#result.effects + 1] = "control_immune"
            end
            return nil
        end

        if action.avoidsVampireGaze == true or action.targetAvoidsGaze == true or
           action.eyeContact == false or action.targetLookingInEyes == false then
            result.vampireMesmerizeBlocked = "gaze_avoided"
            result.effects[#result.effects + 1] = "vampire_mesmerize_gaze_avoided"
            return nil
        end

        if isControlImmuneTarget(target) then
            result.vampireMesmerizeBlocked = "control_immune"
            result.effects[#result.effects + 1] = "control_immune"
            return nil
        end

        target.conditions = target.conditions or {}
        target.conditions.controlled = true
        target.conditions.mesmerized = true
        target.controlledBy = action.actor
        target.controlOrder = {
            text = action.controlOrder or action.command or "immediate_command",
            source = "vampire_mesmerize",
            immediate = true,
        }
        target.controlCommandsRemaining = 1
        target.vampireMesmerized = {
            vampire = action.actor,
            vampireId = action.actor and action.actor.id,
            command = target.controlOrder.text,
            controlledActionValue = tonumber(action and action.card and action.card.value) or result.cardValue or 0,
        }

        result.controlledActionValue = target.vampireMesmerized.controlledActionValue
        result.vampireMesmerize = target.vampireMesmerized
        result.effects[#result.effects + 1] = "controlled"
        result.effects[#result.effects + 1] = "mesmerized"
        if doom and doom.id == "mesmerize" then
            result.effects[#result.effects + 1] = "vampire_mesmerize_greater_doom"
        end

        local priorCompletes = action.controlOrderCompletesAfterImmediate
        action.controlOrderCompletesAfterImmediate = false
        local immediateResult = self:resolveImmediateControlAction(action, result, action.actor, target)
        action.controlOrderCompletesAfterImmediate = priorCompletes

        if immediateResult and action.controlPersists ~= true then
            target.conditions.controlled = false
            target.conditions.mesmerized = false
            target.controlledBy = nil
            target.controlOrder = nil
            target.controlCommandsRemaining = 0
            target.lastVampireMesmerize = target.vampireMesmerized
            target.vampireMesmerized = nil
            result.effects[#result.effects + 1] = "vampire_mesmerize_released"
        end

        return result.vampireMesmerize
    end

    function resolver:isImpVomitAttack(action)
        local actor = action and action.actor
        local doom = action and action.lesserDoom
        local effect = doom and doom.effect
        return self:isImp(actor) and doom and
            (doom.id == "vomit" or (effect and effect.type == "attack_notch_item_no_damage"))
    end

    function resolver:applyImpVomitAttack(action, result, target, doom)
        result.damageDealt = 0
        result.effects[#result.effects + 1] = "imp_vomit"
        result.effects[#result.effects + 1] = "damage_replaced"

        local item = self:getRoughhouseNotchItem(action)
        if item then
            local notchResult = inventory.addNotch(item)
            result.notchedItem = item
            result.itemNotchResult = notchResult
            result.effects[#result.effects + 1] = "item_notched"
            if notchResult == "destroyed" then
                result.effects[#result.effects + 1] = "item_destroyed"
            end
            result.description = result.description .. (doom and doom.name or "Vomit") ..
                "! Target item is Notched instead of wounded. "
        else
            result.effects[#result.effects + 1] = "no_item_to_notch"
            result.description = result.description .. (doom and doom.name or "Vomit") ..
                "! No target item was available to Notch. "
        end
    end

    function resolver:isImpPissAndShitRoughhouse(action)
        local actor = action and action.actor
        local doom = action and action.lesserDoom
        local effect = doom and doom.effect
        return self:isImp(actor) and doom and
            (doom.id == "piss_and_shit" or (effect and effect.type == "roughhouse_stress"))
    end

    function resolver:applyImpPissAndShitRoughhouse(action, result)
        if not (result and result.success and self:isImpPissAndShitRoughhouse(action) and action.target) then
            return nil
        end

        action.target.conditions = action.target.conditions or {}
        action.target.conditions.stressed = true
        action.target.impFilthStress = {
            source = "piss_and_shit",
            actor = action.actor,
            actorId = action.actor and action.actor.id,
        }
        result.effects[#result.effects + 1] = "imp_piss_and_shit"
        result.effects[#result.effects + 1] = "stressed"
        result.description = (result.description or "") .. " Piss and Shit makes the target Stressed."
        self.eventBus:emit("imp_piss_and_shit", {
            actor = action.actor,
            target = action.target,
            action = action,
            result = result,
        })
        return action.target.impFilthStress
    end

    function resolver:resolveImpBadLuckMachine(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local incoming = action.incomingAction or action.actionToRetarget
        local newTarget = action.newTarget or action.redirectTarget or action.target

        if not self:isImp(actor) then
            result.success = false
            result.description = "Bad Luck Machine requires an imp."
            result.effects[#result.effects + 1] = "imp_bad_luck_machine_blocked"
            return result
        end
        if not self:impGreaterDoomReady(action, "interrupt_retarget_action", "bad_luck_machine") then
            result.success = false
            result.description = "Bad Luck Machine requires a greater doom."
            result.effects[#result.effects + 1] = "imp_bad_luck_machine_requires_greater_doom"
            return result
        end
        if type(incoming) ~= "table" then
            result.success = false
            result.description = "Bad Luck Machine needs an incoming action."
            result.effects[#result.effects + 1] = "imp_bad_luck_machine_missing_action"
            return result
        end
        if not newTarget then
            result.success = false
            result.description = "Bad Luck Machine needs a same-zone replacement target."
            result.effects[#result.effects + 1] = "imp_bad_luck_machine_missing_target"
            return result
        end
        if newTarget.zone ~= actor.zone then
            result.success = false
            result.description = "Bad Luck Machine replacement target must be in the imp's zone."
            result.effects[#result.effects + 1] = "imp_bad_luck_machine_target_not_same_zone"
            return result
        end

        incoming.originalTarget = incoming.originalTarget or incoming.target
        incoming.target = newTarget
        incoming.disfavor = true
        incoming.impBadLuckMachine = {
            imp = actor,
            impId = actor.id,
            newTarget = newTarget,
            greaterDoomCard = action.greaterDoomCard,
        }

        result.success = true
        result.countsTowardTurnCard = false
        result.retargetedAction = incoming
        result.effects[#result.effects + 1] = "imp_bad_luck_machine"
        result.effects[#result.effects + 1] = "action_retargeted"
        result.effects[#result.effects + 1] = "disfavor"
        result.description = (actor.name or "Imp") .. " turns bad luck onto another target."

        self.eventBus:emit("imp_bad_luck_machine", {
            actor = actor,
            action = action,
            incomingAction = incoming,
            newTarget = newTarget,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:isWraith(entity)
        return entity and (entity.wraith ~= nil or entityHasNormalizedTag(entity, "wraith"))
    end

    function resolver:ensureWraithShadowForm(entity)
        if not self:isWraith(entity) then
            return false
        end

        entity.conditions = entity.conditions or {}
        if not (entity.wraithTangibleUntilRoundEnd and entity.wraithTangibleUntilRoundEnd.active ~= false) and
           not entity.tangible and entity.conditions.tangible ~= true then
            entity.intangible = true
            entity.incorporeal = true
            entity.tangible = false
            entity.conditions.intangible = true
            entity.conditions.incorporeal = true
            entity.conditions.tangible = false
        end
        entity.conditions.wraith_shadow_form = true
        entity.conditions.cannot_see_illusions = true
        return true
    end

    function resolver:isWraithTangible(entity, damageContext)
        if not self:isWraith(entity) then
            return false
        end
        damageContext = damageContext or {}
        local reveal = entity.wraithTangibleUntilRoundEnd
        local round = damageContext.round or damageContext.currentRound or
            (damageContext.action and damageContext.action.round)
        if reveal and reveal.active ~= false then
            if not round or not reveal.expiresAfterRound or reveal.expiresAfterRound >= round then
                return true
            end
        end
        local conditions = entity.conditions or {}
        return entity.tangible == true or conditions.tangible == true or
            damageContext.brightLight == true or damageContext.lightLevel == "bright" or
            damageContext.source == "bright_light"
    end

    function resolver:isWraithPhysicalDamage(effects, weapon, damageContext)
        damageContext = damageContext or {}
        if damageContext.magic == true or damageContext.spell == true or damageContext.brightLight == true then
            return false
        end
        for _, effect in ipairs(effects or {}) do
            local normalized = normalizeTalentKey(effect)
            if normalized == "magic" or normalized == "spell" or normalized == "sorcery" or
               normalized == "heavenfire" or normalized == "jinn_bomb" or
               normalized == "materialized" or normalized == "intangible_visible_tangible" or
               normalized == "bright_light" then
                return false
            end
        end

        local props = weapon and weapon.properties or {}
        if props.magic == true or props.sorcerous == true or props.heavenfire == true then
            return false
        end

        return true
    end

    function resolver:resolveEliteIntangibleDamage(entity, amount, effects, weapon, damageContext)
        local conditions = entity and entity.conditions or {}
        local intangible = entity and (entity.intangible == true or entity.tangible == false or
            conditions.intangible == true or conditions.tangible == false)
        local eliteIntangibleActive = entity and (entity.eliteIntangible == true or
            entity.eliteIntangibleActive == true)
        if not (self:isElite(entity) and eliteIntangibleActive and intangible and (amount or 0) > 0) then
            return nil
        end
        if not self:isWraithPhysicalDamage(effects, weapon, damageContext) then
            return nil
        end

        effects[#effects + 1] = "elite_intangible_immune"
        effects[#effects + 1] = "physical_objects_pass_through"
        self.eventBus:emit("elite_intangible_immune", {
            entity = entity,
            weapon = weapon,
            damageContext = damageContext,
        })
        return {
            result = "immune",
            immune = true,
            reason = "elite_intangible",
            amountPrevented = amount,
        }
    end

    function resolver:resolveWraithShadowFormDamage(entity, amount, effects, weapon, damageContext)
        if not (self:isWraith(entity) and (amount or 0) > 0) then
            return nil
        end

        self:ensureWraithShadowForm(entity)
        if self:isWraithTangible(entity, damageContext) then
            return nil
        end
        if not self:isWraithPhysicalDamage(effects, weapon, damageContext) then
            return nil
        end

        effects[#effects + 1] = "wraith_shadow_form_immune"
        effects[#effects + 1] = "physical_objects_pass_through"
        self.eventBus:emit("wraith_shadow_form_immune", {
            entity = entity,
            weapon = weapon,
            damageContext = damageContext,
        })
        return {
            result = "immune",
            immune = true,
            reason = "wraith_shadow_form",
        }
    end

    function resolver:getWraithRevealLightSource(actor, action)
        if not actor then
            return nil
        end

        local explicit = action and (action.item or action.weapon or action.lightSource)
        if explicit and self:isTorchOrLanternItem(explicit) and not explicit.destroyed then
            return explicit
        end

        local inv = actor.inventory
        if action and action.itemId and inv and inv.findItem then
            local item = inv:findItem(action.itemId)
            if item and self:isTorchOrLanternItem(item) and not item.destroyed then
                return item
            end
        end

        if inv and inv.getItems then
            for _, location in ipairs({ inventory.LOCATIONS.HANDS, inventory.LOCATIONS.BELT }) do
                for _, item in ipairs(inv:getItems(location) or {}) do
                    local props = item.properties or {}
                    if self:isTorchOrLanternItem(item) and not item.destroyed and props.isLit ~= false then
                        return item
                    end
                end
            end
        end

        return nil
    end

    function resolver:makeWraithTangibleUntilRoundEnd(wraith, action, sourceItem)
        self:ensureWraithShadowForm(wraith)
        local controller = action and (action.challengeController or self.challengeController)
        local currentRound = action and action.round or controller and controller.currentRound or 0

        wraith.wraithTangibleUntilRoundEnd = {
            active = true,
            source = "bright_light",
            sourceItemId = sourceItem and sourceItem.id,
            sourceItemName = sourceItem and sourceItem.name,
            startedRound = currentRound,
            expiresAfterRound = currentRound,
        }
        wraith.tangible = true
        wraith.intangible = false
        wraith.incorporeal = false
        wraith.conditions = wraith.conditions or {}
        wraith.conditions.tangible = true
        wraith.conditions.intangible = false
        wraith.conditions.incorporeal = false
        wraith.conditions.bright_light_tangible = true
        return wraith.wraithTangibleUntilRoundEnd
    end

    function resolver:resolveWraithShineLight(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target

        if not actor then
            result.success = false
            result.description = "No adventurer to shine light."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isWraith(target) then
            result.success = false
            result.description = "Shining light this way requires a wraith target."
            result.effects[#result.effects + 1] = "wraith_shine_light_missing_wraith"
            return result
        end
        if not (action.card or action.discardedCard or action.anyCard) then
            result.success = false
            result.description = "Shining light on a wraith requires any discarded card."
            result.effects[#result.effects + 1] = "wraith_shine_light_requires_card"
            return result
        end

        local lightSource = self:getWraithRevealLightSource(actor, action)
        if not lightSource then
            result.success = false
            result.description = "Shining light on a wraith requires a torch or lantern."
            result.effects[#result.effects + 1] = "wraith_shine_light_requires_light"
            return result
        end

        result.success = true
        result.lightSource = lightSource
        result.tangibility = self:makeWraithTangibleUntilRoundEnd(target, action, lightSource)
        result.effects[#result.effects + 1] = "wraith_shine_light"
        result.effects[#result.effects + 1] = "wraith_tangible_until_round_end"
        result.description = (actor.name or "Adventurer") .. " shines " ..
            (lightSource.name or "a light") .. " on " .. (target.name or "the wraith") .. "."

        self.eventBus:emit("wraith_tangible", {
            actor = actor,
            target = target,
            lightSource = lightSource,
            tangibility = result.tangibility,
        })

        action.result = result
        return result
    end

    function resolver:clearExpiredWraithTangibility(completedRound, entities)
        local cleared = {}
        local candidates = entities or
            (self.challengeController and self.challengeController.allCombatants) or {}
        completedRound = completedRound or 0

        for _, entity in ipairs(candidates) do
            local reveal = entity and entity.wraithTangibleUntilRoundEnd
            if reveal and reveal.active ~= false and (reveal.expiresAfterRound or 0) <= completedRound then
                reveal.active = false
                reveal.clearedRound = completedRound
                entity.lastWraithTangibility = reveal
                entity.wraithTangibleUntilRoundEnd = nil
                entity.conditions = entity.conditions or {}
                entity.tangible = false
                entity.intangible = true
                entity.incorporeal = true
                entity.conditions.tangible = false
                entity.conditions.bright_light_tangible = false
                entity.conditions.intangible = true
                entity.conditions.incorporeal = true
                cleared[#cleared + 1] = {
                    entity = entity,
                    round = completedRound,
                    result = "wraith_tangibility_expired",
                }
                self.eventBus:emit(events.EVENTS.CONDITION_EXPIRED, cleared[#cleared])
            end
        end

        return cleared
    end

    function resolver:wraithLesserDoomReady(action, effectType)
        local doom = action and (action.lesserDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.lesserDoomCard or action.discardedLesserDoom or action.useLesserDoom == true or
            (effect and effect.type == effectType))
    end

    function resolver:getWraithFearDestination(target, action)
        local destinations = action and (action.destinationZones or action.destinationZoneById or action.fearDestinations)
        if destinations and target and target.id and destinations[target.id] then
            return destinations[target.id]
        end
        return action and (action.destinationZone or action.targetZone) or target.zone
    end

    function resolver:moveWraithFearTarget(target, destinationZone, action)
        if not target or not destinationZone then
            return false
        end
        local oldZone = target.zone
        if oldZone == destinationZone then
            return true
        end
        if self.zoneSystem and target.id then
            local placed = self.zoneSystem:placeEntity(target.id, destinationZone)
            if not placed then
                return false
            end
        end
        target.zone = destinationZone
        self:clearAllEngagements(target, action and action.allEntities)
        self.eventBus:emit("entity_zone_changed", {
            entity = target,
            oldZone = oldZone,
            newZone = destinationZone,
            source = "wraith_fear",
        })
        return true
    end

    function resolver:resolveWraithFear(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No wraith for Fear."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isWraith(actor) then
            result.success = false
            result.description = "Fear requires a wraith."
            result.effects[#result.effects + 1] = "wraith_fear_blocked"
            return result
        end
        if not self:wraithLesserDoomReady(action, "same_zone_fear_displace") then
            result.success = false
            result.description = "Wraith Fear requires a lesser doom."
            result.effects[#result.effects + 1] = "wraith_fear_requires_lesser_doom"
            return result
        end

        local doomCard = action.lesserDoomCard or action.card or action.doomCard
        local doomValue = doomCard and doomCard.value or action.value or 0
        local onTurn = action.onWraithTurn == true or action.onOwnTurn == true or action.isActorTurn == true
        local modifier = onTurn and (actor.wands or (actor.getAttribute and actor:getAttribute(constants.SUITS.WANDS)) or 0) or 0
        local fearValue = doomValue + modifier
        local affected = {}
        local resisted = {}
        local actorZone = action.zone or actor.zone

        for _, target in ipairs(action.targets or action.allEntities or {}) do
            local conditions = target.conditions or {}
            if target ~= actor and target.isPC == true and target.zone == actorZone and
               not conditions.dead and not conditions.deaths_door then
                local initiative = self:getZoneAttackTargetInitiative(action, target) or 0
                if fearValue > initiative then
                    local destination = self:getWraithFearDestination(target, action)
                    if self:moveWraithFearTarget(target, destination, action) then
                        affected[#affected + 1] = {
                            target = target,
                            initiative = initiative,
                            destinationZone = destination,
                        }
                    end
                else
                    resisted[#resisted + 1] = {
                        target = target,
                        initiative = initiative,
                    }
                end
            end
        end

        result.success = true
        result.cardValue = doomValue
        result.modifier = modifier
        result.testValue = fearValue
        result.affected = affected
        result.resisted = resisted
        result.effects[#result.effects + 1] = "wraith_fear"
        if onTurn then
            result.effects[#result.effects + 1] = "wands_added"
        end
        if #affected > 0 then
            result.effects[#result.effects + 1] = "fear_displaced"
        end
        result.description = (actor.name or "Wraith") .. " terrifies " ..
            tostring(#affected) .. " same-zone adventurer(s)."

        self.eventBus:emit("wraith_fear", {
            actor = actor,
            action = action,
            result = result,
            affected = affected,
            resisted = resisted,
        })

        action.result = result
        return result
    end

    function resolver:resolveWraithRetreatIntoShadows(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No wraith for Retreat into the Shadows."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isWraith(actor) then
            result.success = false
            result.description = "Retreat into the Shadows requires a wraith."
            result.effects[#result.effects + 1] = "wraith_retreat_into_shadows_blocked"
            return result
        end
        if not (action.card or action.discardedCard or action.anyCard) then
            result.success = false
            result.description = "Wraith Retreat into the Shadows requires any discarded card."
            result.effects[#result.effects + 1] = "wraith_retreat_into_shadows_requires_card"
            return result
        end

        self:clearAllEngagements(actor, action.allEntities)
        self:ensureWraithShadowForm(actor)

        result.success = true
        result.countsTowardTurnCard = false
        result.effects[#result.effects + 1] = "wraith_retreat_into_shadows"
        result.effects[#result.effects + 1] = "disengaged_all"
        result.description = (actor.name or "Wraith") ..
            " retreats into shadow without spending its one-card turn limit."

        self.eventBus:emit("wraith_retreat_into_shadows", {
            actor = actor,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:drainWraithXP(wraith, target, amount, result)
        amount = math.max(0, amount or 1)
        if not (self:isWraith(wraith) and target and amount > 0) then
            return nil
        end

        local field = target.xp ~= nil and "xp" or target.experience ~= nil and "experience" or nil
        if not field then
            result.effects[#result.effects + 1] = "wraith_dolorous_kiss_no_xp"
            return nil
        end

        local before = tonumber(target[field]) or 0
        local lost = math.min(before, amount)
        target[field] = before - lost
        local record = {
            wraith = wraith,
            wraithId = wraith.id,
            target = target,
            targetId = target.id,
            field = field,
            before = before,
            after = target[field],
            lost = lost,
            restored = false,
        }

        target.wraithXPDrains = target.wraithXPDrains or {}
        target.wraithXPDrains[#target.wraithXPDrains + 1] = record
        wraith.wraithXPDrains = wraith.wraithXPDrains or {}
        wraith.wraithXPDrains[#wraith.wraithXPDrains + 1] = record

        result.wraithXPDrain = record
        result.effects[#result.effects + 1] = "wraith_dolorous_kiss"
        if lost > 0 then
            result.effects[#result.effects + 1] = "xp_drained"
        else
            result.effects[#result.effects + 1] = "wraith_dolorous_kiss_no_xp"
        end

        self.eventBus:emit("wraith_xp_drained", record)
        return record
    end

    function resolver:restoreWraithDrainedXP(wraith, effects)
        if not (self:isWraith(wraith) and wraith.wraithXPDrains) then
            return {}
        end

        local restored = {}
        for _, record in ipairs(wraith.wraithXPDrains) do
            if record and not record.restored and record.target and record.field and (record.lost or 0) > 0 then
                record.target[record.field] = (tonumber(record.target[record.field]) or 0) + record.lost
                record.restored = true
                record.restoredByWraithDestroyed = true
                restored[#restored + 1] = record
            end
        end

        if #restored > 0 then
            effects[#effects + 1] = "wraith_drained_xp_restored"
            self.eventBus:emit("wraith_drained_xp_restored", {
                wraith = wraith,
                restored = restored,
            })
        end

        return restored
    end

    function resolver:isWraithSpectralConditionImmune(target, condition)
        if not self:isWraith(target) then
            return false
        end

        local normalized = normalizeTalentKey(condition)
        return normalized == "poison" or normalized == "poisoned" or normalized == "bleeding" or
            normalized == "disease" or normalized == "diseased" or normalized == "sick" or
            normalized == "sickness" or normalized == "sleep" or normalized == "sleeping" or
            normalized == "charm" or normalized == "charmed" or normalized == "control" or
            normalized == "controlled" or normalized == "dominated" or normalized == "mesmerized" or
            normalized == "inspired" or normalized == "enraged"
    end

    function resolver:recordWraithSpectralBlocked(target, result, condition, source)
        result.wraithSpectralBlocked = result.wraithSpectralBlocked or {}
        result.wraithSpectralBlocked[#result.wraithSpectralBlocked + 1] = condition
        result.effects[#result.effects + 1] = "wraith_spectral_immunity"
        result.effects[#result.effects + 1] = "spectral_condition_blocked"
        self.eventBus:emit("wraith_spectral_condition_blocked", {
            target = target,
            condition = condition,
            source = source,
        })
    end

    function resolver:isDevil(entity)
        return entity and (entity.devil ~= nil or entityHasNormalizedTag(entity, "devil"))
    end

    function resolver:devilGreaterDoomReady(action, effectType)
        local doom = action and (action.greaterDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            (effect and effect.type == effectType))
    end

    function resolver:devilLesserDoomReady(action, effectType)
        local doom = action and (action.lesserDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.lesserDoomCard or action.discardedLesserDoom or action.useLesserDoom == true or
            (effect and effect.type == effectType))
    end

    function resolver:isDevilNaturalDamage(effects, weapon, damageContext)
        damageContext = damageContext or {}
        if damageContext.naturalDanger == true or damageContext.fire == true or
           damageContext.falling == true or damageContext.drowning == true then
            return true
        end

        for _, effect in ipairs(effects or {}) do
            local normalized = normalizeTalentKey(effect)
            if normalized == "fire" or normalized == "heat" or normalized == "falling" or
               normalized == "fall" or normalized == "drowning" or normalized == "water" or
               normalized == "natural_danger" then
                return true
            end
        end

        local props = weapon and weapon.properties or {}
        local weaponKey = normalizeTalentKey(weapon and (weapon.templateId or weapon.id or weapon.name or weapon.weaponType))
        return props.natural == true or props.improvisedNatural == true or props.improvised_natural == true or
            weaponKey == "branch" or weaponKey == "stone" or weaponKey == "rock" or weaponKey == "club_branch"
    end

    function resolver:isDevilCraftedWeaponDamage(entity, effects, weapon, damageContext)
        if not (self:isDevil(entity) and weapon) then
            return false
        end
        if self:isDevilNaturalDamage(effects, weapon, damageContext) then
            return false
        end

        local props = weapon.properties or {}
        local material = normalizeTalentKey(weapon.material or props.material or props.armorType)
        return weapon.isWeapon == true or weapon.weaponType ~= nil or props.weapon == true or
            props.crafted == true or props.forged == true or props.metal == true or
            material == "iron" or material == "steel" or material == "metal"
    end

    function resolver:resolveDevilUntouchedByHotIronDamage(entity, amount, effects, weapon, damageContext)
        if not (self:isDevil(entity) and (amount or 0) > 0) then
            return nil
        end
        if not self:isDevilCraftedWeaponDamage(entity, effects, weapon, damageContext) then
            return nil
        end

        effects[#effects + 1] = "devil_untouched_by_hot_iron"
        effects[#effects + 1] = "crafted_weapon_immune"
        self.eventBus:emit("devil_untouched_by_hot_iron", {
            entity = entity,
            weapon = weapon,
            damageContext = damageContext,
        })
        return {
            result = "immune",
            immune = true,
            reason = "devil_untouched_by_hot_iron",
        }
    end

    function resolver:getActiveDevilBiteHolds(devil)
        local holds = {}
        for _, hold in ipairs(devil and devil.devilBiteHolds or {}) do
            local target = hold.target
            local conditions = target and target.conditions or {}
            if hold.active ~= false and target and not conditions.dead then
                holds[#holds + 1] = hold
            end
        end
        return holds
    end

    function resolver:getDevilBiteHold(devil, target)
        for _, hold in ipairs(devil and devil.devilBiteHolds or {}) do
            if hold.active ~= false and hold.target == target then
                return hold
            end
        end
        return nil
    end

    function resolver:addDevilBiteHold(devil, target, action)
        local existing = self:getDevilBiteHold(devil, target)
        if existing then
            return existing
        end

        local hold = {
            devil = devil,
            devilId = devil.id,
            target = target,
            targetId = target.id,
            active = true,
            source = "devil_bite",
            enablesSwallow = true,
            missedAttacksHitHeldTarget = true,
            targetMovesWithDevil = true,
            createdRound = action and action.round,
        }
        devil.devilBiteHolds = devil.devilBiteHolds or {}
        devil.devilBiteHolds[#devil.devilBiteHolds + 1] = hold
        target.devilBiteHold = hold
        target.devilBittenBy = devil
        target.devilBittenById = devil.id
        target.devilMovesWith = devil
        target.conditions = target.conditions or {}
        target.conditions.devil_bitten = true
        target.conditions.rooted = true
        return hold
    end

    function resolver:releaseDevilBiteHold(devil, target, reason)
        local hold = self:getDevilBiteHold(devil, target)
        if not hold then
            return nil
        end
        hold.active = false
        hold.releaseReason = reason or "released"
        if target then
            target.devilBiteHold = nil
            target.devilBittenBy = nil
            target.devilBittenById = nil
            target.devilMovesWith = nil
            if target.conditions then
                target.conditions.devil_bitten = false
                if reason ~= "swallowed" then
                    target.conditions.rooted = false
                end
            end
        end
        return hold
    end

    function resolver:resolveDevilBite(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target

        if not actor then
            result.success = false
            result.description = "No devil for Bite."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isDevil(actor) then
            result.success = false
            result.description = "Bite requires a devil."
            result.effects[#result.effects + 1] = "devil_bite_blocked"
            return result
        end
        if not target then
            result.success = false
            result.description = "Devil Bite requires a target."
            result.effects[#result.effects + 1] = "devil_bite_missing_target"
            return result
        end
        if not self:devilLesserDoomReady(action, "roughhouse_bite_hold") then
            result.success = false
            result.description = "Devil Bite requires a lesser doom."
            result.effects[#result.effects + 1] = "devil_bite_requires_lesser_doom"
            return result
        end
        if #self:getActiveDevilBiteHolds(actor) >= (actor.devil and actor.devil.bite and actor.devil.bite.maxBittenTargets or 4) and
           not self:getDevilBiteHold(actor, target) then
            result.success = false
            result.description = "The devil already has four victims in its mouths."
            result.effects[#result.effects + 1] = "devil_bite_capacity_full"
            return result
        end
        if not action.card then
            result.success = false
            result.description = "Devil Bite requires a Roughhouse card."
            result.effects[#result.effects + 1] = "devil_bite_requires_card"
            return result
        end

        result.cardValue = action.card.value or 0
        result.modifier = actor.pentacles or (actor.getAttribute and actor:getAttribute(constants.SUITS.PENTACLES)) or 0
        result.testValue = result.cardValue + result.modifier
        result.difficulty = self:getTargetInitiative(target, action) or result.difficulty

        local contest = self:resolveInitiativeContest(action, result, { tieWins = false })
        if contest.dodged then
            return result
        end
        if not result.success then
            result.effects[#result.effects + 1] = "devil_bite_failed"
            result.description = (actor.name or "Devil") .. " fails to bite " .. (target.name or "the target") .. "."
            return result
        end

        local hold = self:addDevilBiteHold(actor, target, action)
        self:applyRooted(target, {
            action = action,
            allEntities = action.allEntities,
            reason = "devil_bite",
        })
        target.conditions.devil_bitten = true
        target.devilBiteHold = hold

        result.hold = hold
        result.effects[#result.effects + 1] = "devil_bite"
        result.effects[#result.effects + 1] = "rooted"
        result.effects[#result.effects + 1] = "devil_bite_hold"
        result.description = (actor.name or "Devil") .. " bites and holds " .. (target.name or "the target") .. "."

        self.eventBus:emit("devil_bite", {
            actor = actor,
            target = target,
            hold = hold,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:moveDevilBiteTargets(devil, oldZone, newZone, action, result)
        if not (self:isDevil(devil) and newZone) then
            return {}
        end

        local moved = {}
        for _, hold in ipairs(self:getActiveDevilBiteHolds(devil)) do
            local target = hold.target
            if target and hold.targetMovesWithDevil and not target.swallowedByDevil then
                local targetOldZone = target.zone
                if self.zoneSystem and target.id then
                    self.zoneSystem:placeEntity(target.id, newZone)
                end
                target.zone = newZone
                moved[#moved + 1] = {
                    target = target,
                    oldZone = targetOldZone or oldZone,
                    newZone = newZone,
                }
                self.eventBus:emit("entity_zone_changed", {
                    entity = target,
                    oldZone = targetOldZone or oldZone,
                    newZone = newZone,
                    reason = "devil_bite_moves_with_devil",
                })
            end
        end

        if #moved > 0 and result then
            result.devilBiteMovedTargets = moved
            result.effects[#result.effects + 1] = "devil_bite_targets_moved"
        end

        return moved
    end

    function resolver:redirectMissedAttackToDevilBiteVictim(action, result)
        local devil = action and action.target
        if not self:isDevil(devil) then
            return false
        end

        local holds = self:getActiveDevilBiteHolds(devil)
        local hold = action.devilBiteRedirectHold or holds[1]
        local victim = hold and hold.target
        if not victim then
            return false
        end

        local damage = action.devilBiteRedirectDamage or 1
        result.devilBiteRedirect = {
            devil = devil,
            victim = victim,
            damage = damage,
        }
        result.effects[#result.effects + 1] = "miss_redirected_to_devil_bitten_target"
        result.effects[#result.effects + 1] = "devil_bite_victim_hit"
        result.description = (result.description or "Miss!") .. " The missed Attack hits a bitten victim."

        if damage > 0 then
            self:applyDamage(victim, damage, result.effects, action.weapon, action.allEntities,
                self:getActionWoundOptions(action, victim), {
                    source = "devil_bite_missed_attack",
                    action = action,
                    useAegis = action.useAegis,
                })
        end

        return true
    end

    function resolver:resolveDevilFiendishRetreat(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target

        if not actor then
            result.success = false
            result.description = "No devil for Fiendish Retreat."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isDevil(actor) then
            result.success = false
            result.description = "Fiendish Retreat requires a devil."
            result.effects[#result.effects + 1] = "devil_fiendish_retreat_blocked"
            return result
        end
        if not target then
            result.success = false
            result.description = "Fiendish Retreat requires an adventurer to disengage from."
            result.effects[#result.effects + 1] = "devil_fiendish_retreat_missing_target"
            return result
        end
        if not self:devilGreaterDoomReady(action, "disengage_one") then
            result.success = false
            result.description = "Devil Fiendish Retreat requires a greater doom."
            result.effects[#result.effects + 1] = "devil_fiendish_retreat_requires_greater_doom"
            return result
        end

        self:breakEngagement(actor, target)

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.effects[#result.effects + 1] = "devil_fiendish_retreat"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "disengaged"
        result.description = (actor.name or "Devil") .. " disengages from " ..
            (target.name or "one adventurer") .. " without spending its turn card."

        self.eventBus:emit("devil_fiendish_retreat", {
            actor = actor,
            target = target,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:resolveDevilStinkingCloud(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No devil for Stinking Cloud."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isDevil(actor) then
            result.success = false
            result.description = "Stinking Cloud requires a devil."
            result.effects[#result.effects + 1] = "devil_stinking_cloud_blocked"
            return result
        end
        if not self:devilGreaterDoomReady(action, "cast_spell_like_effect") then
            result.success = false
            result.description = "Devil Stinking Cloud requires a greater doom."
            result.effects[#result.effects + 1] = "devil_stinking_cloud_requires_greater_doom"
            return result
        end

        local zoneIds = action.zoneIds or { action.targetZone or action.zone or actor.zone }
        local cloud = {
            spellId = "stinking_cloud",
            caster = actor,
            casterId = actor.id,
            active = true,
            devilStinkingCloud = true,
            zoneIds = zoneIds,
            zoneCount = #zoneIds,
            stunPenaltyPerRound = 1,
            knockoutAtStacks = 4,
            exposureCounts = {},
            excludedEntityIds = actor.id and { [actor.id] = true } or {},
        }
        local activeSpell = {
            spellId = "stinking_cloud",
            caster = actor,
            active = true,
            devilStinkingCloud = true,
            concentration = false,
            stinkingCloud = cloud,
        }
        actor.activeSpells = actor.activeSpells or {}
        actor.activeSpells[#actor.activeSpells + 1] = activeSpell

        result.success = true
        result.stinkingCloud = cloud
        result.zoneIds = zoneIds
        result.zoneCount = #zoneIds
        result.effects[#result.effects + 1] = "devil_stinking_cloud"
        result.effects[#result.effects + 1] = "stinking_cloud"
        result.effects[#result.effects + 1] = "greater_doom"
        result.description = (actor.name or "Devil") .. " fills " .. tostring(#zoneIds) ..
            " zone(s) with Stinking Cloud."

        self.eventBus:emit("devil_stinking_cloud", {
            actor = actor,
            action = action,
            result = result,
            cloud = cloud,
        })

        action.result = result
        return result
    end

    function resolver:getDevilSwallowTarget(devil, action)
        local explicit = action and action.target
        if explicit and self:getDevilBiteHold(devil, explicit) then
            return explicit
        end
        local holds = self:getActiveDevilBiteHolds(devil)
        return holds[1] and holds[1].target or nil
    end

    function resolver:resolveDevilSwallow(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No devil for Swallow."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isDevil(actor) then
            result.success = false
            result.description = "Swallow requires a devil."
            result.effects[#result.effects + 1] = "devil_swallow_blocked"
            return result
        end
        if not self:devilGreaterDoomReady(action, "swallow_held_target") then
            result.success = false
            result.description = "Devil Swallow requires a greater doom."
            result.effects[#result.effects + 1] = "devil_swallow_requires_greater_doom"
            return result
        end

        local target = self:getDevilSwallowTarget(actor, action)
        if not target then
            result.success = false
            result.description = "Devil Swallow requires a bitten target."
            result.effects[#result.effects + 1] = "devil_swallow_requires_bitten_target"
            return result
        end

        self:releaseDevilBiteHold(actor, target, "swallowed")
        target.conditions = target.conditions or {}
        target.conditions.swallowed = true
        target.conditions.devil_swallowed = true
        target.conditions.rooted = true
        target.swallowedByDevil = actor
        target.swallowedByDevilId = actor.id
        target.devilSwallowEscape = {
            devil = actor,
            devilId = actor.id,
            successes = 0,
            failures = 0,
            successesToEscape = 3,
            failuresToAnnihilation = 3,
        }
        actor.swallowedCreatures = actor.swallowedCreatures or {}
        actor.swallowedCreatures[#actor.swallowedCreatures + 1] = target

        result.success = true
        result.target = target
        result.effects[#result.effects + 1] = "devil_swallow"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "extradimensional_swallow"
        result.description = (actor.name or "Devil") .. " swallows " .. (target.name or "the target") .. "."

        self.eventBus:emit("devil_swallow", {
            actor = actor,
            target = target,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:releaseDevilSwallowedCreature(devil, target, reason)
        if not (devil and target and target.swallowedByDevil == devil) then
            return nil
        end
        target.swallowedByDevil = nil
        target.swallowedByDevilId = nil
        if target.conditions then
            target.conditions.swallowed = false
            target.conditions.devil_swallowed = false
            target.conditions.rooted = false
        end
        target.devilSwallowEscape = nil
        target.barfedUpByDevil = reason or "released"
        if devil.zone then
            if self.zoneSystem and target.id then
                self.zoneSystem:placeEntity(target.id, devil.zone)
            end
            target.zone = devil.zone
        end
        return {
            devil = devil,
            target = target,
            reason = reason or "released",
        }
    end

    function resolver:releaseDevilSwallowedCreatures(devil, effects, reason)
        effects = effects or {}
        reason = reason or "devil_defeated"
        local released = {}
        for _, target in ipairs(devil and devil.swallowedCreatures or {}) do
            local record = self:releaseDevilSwallowedCreature(devil, target, reason)
            if record then
                released[#released + 1] = record
            end
        end
        if #released > 0 then
            effects[#effects + 1] = "devil_swallowed_creatures_released"
            self.eventBus:emit("devil_swallowed_creatures_released", {
                devil = devil,
                released = released,
                reason = reason,
            })
        end
        return released
    end

    function resolver:resolveDevilSwallowTestFate(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local target = action.actor or action.target
        local escape = target and target.devilSwallowEscape
        local devil = action.devil or escape and escape.devil

        if not (target and escape and devil) then
            result.success = false
            result.description = "No swallowed victim is testing fate."
            result.effects[#result.effects + 1] = "devil_swallow_test_missing_victim"
            return result
        end

        local success = action.success == true or action.testSuccess == true
        local great = action.greatSuccess == true or action.greatFailure == true
        local amount = great and 2 or 1
        if success then
            escape.successes = (escape.successes or 0) + amount
            result.effects[#result.effects + 1] = "devil_swallow_escape_success"
        else
            escape.failures = (escape.failures or 0) + amount
            result.effects[#result.effects + 1] = "devil_swallow_escape_failure"
        end

        result.success = true
        result.escape = escape
        result.effects[#result.effects + 1] = "devil_swallow_test_fate"
        if escape.successes >= (escape.successesToEscape or 3) then
            result.released = self:releaseDevilSwallowedCreature(devil, target, "escape_test")
            result.effects[#result.effects + 1] = "devil_vomits_victim"
            result.description = (target.name or "Victim") .. " makes the devil vomit them up."
        elseif escape.failures >= (escape.failuresToAnnihilation or 3) then
            target.conditions = target.conditions or {}
            target.conditions.dead = true
            target.conditions.swallowed = false
            target.conditions.devil_swallowed = false
            target.annihilatedInDevilStomach = true
            result.effects[#result.effects + 1] = "devil_stomach_annihilation"
            result.description = (target.name or "Victim") .. " falls into the devil's stomach and is annihilated."
        else
            result.description = (target.name or "Victim") .. " struggles inside the devil."
        end

        self.eventBus:emit("devil_swallow_test_fate", {
            devil = devil,
            target = target,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:isUngoat(entity)
        return entity and (entity.ungoat ~= nil or entityHasNormalizedTag(entity, "ungoat"))
    end

    function resolver:isUngoatRummage(action, effect)
        if effect ~= "rummage" then
            return false
        end
        if not (action and self:isUngoat(action.actor)) then
            return false
        end
        local doom = action.lesserDoom or action.doom
        local doomEffect = doom and doom.effect
        return action.ungoatRummage == true or (doomEffect and doomEffect.type == "pull_item_from_backpack")
    end

    function resolver:getUngoatRummageItem(action)
        local target = action and action.target
        local inv = target and target.inventory
        if not (inv and inv.getItems) then
            return nil, "no_inventory"
        end

        if action.itemId and inv.findItem then
            local explicit = inv:findItem(action.itemId)
            if explicit then
                return explicit, nil
            end
        end

        local pack = inv:getItems(inventory.LOCATIONS.PACK) or {}
        for _, item in ipairs(pack) do
            if item and not item.destroyed then
                return item, nil
            end
        end
        return nil, "pack_empty"
    end

    function resolver:resolveUngoatRummage(action, result)
        local actor = action.actor
        local target = action.target
        if not (actor and target) then
            result.success = false
            result.description = "No target to rummage."
            result.effects[#result.effects + 1] = "ungoat_rummage_blocked"
            return
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = false,
        })
        if contest.dodged then
            return
        end

        if result.success then
            local item, reason = self:getUngoatRummageItem(action)
            if not item then
                result.success = false
                result.description = "No backpack item to rummage."
                result.effects[#result.effects + 1] = "ungoat_rummage_no_pack_item"
                result.rummageFailure = reason
            else
                local dropped = self:dropCarriedItem(target, item, "ungoat_rummage", action)
                result.droppedItem = dropped
                result.ungoatRummage = {
                    actor = actor,
                    target = target,
                    item = dropped,
                    recoverable = true,
                    ungoatCanPickUpWithAnyCard = true,
                }
                result.description = "Ungoat rummages [" .. (dropped.name or "pack item") .. "] onto the ground."
                result.effects[#result.effects + 1] = "ungoat_rummage"
                result.effects[#result.effects + 1] = "pack_item_dropped"
                result.effects[#result.effects + 1] = "recoverable_dropped_item"
            end
        else
            result.description = "Failed to rummage."
        end

        self:appendRoughhouseRiposte(action, result, contest)
    end

    function resolver:resolveUngoatPickUpDroppedItem(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local owner = action.target or action.itemOwner or action.droppedItemOwner

        if not self:isUngoat(actor) then
            result.success = false
            result.description = "Only an ungoat can use this pick-up shortcut."
            result.effects[#result.effects + 1] = "ungoat_pickup_requires_ungoat"
            return result
        end
        if not (action.card or action.anyCard or action.discardedCard) then
            result.success = false
            result.description = "Ungoat pick-up requires any card."
            result.effects[#result.effects + 1] = "ungoat_pickup_requires_card"
            return result
        end
        if not (owner and owner.droppedItems and #owner.droppedItems > 0) then
            result.success = false
            result.description = "No dropped item to pick up."
            result.effects[#result.effects + 1] = "ungoat_pickup_no_dropped_item"
            return result
        end

        local picked = nil
        if action.itemId then
            for index, item in ipairs(owner.droppedItems) do
                if item.id == action.itemId then
                    picked = table.remove(owner.droppedItems, index)
                    break
                end
            end
        end
        picked = picked or table.remove(owner.droppedItems)

        actor.inventory = actor.inventory or inventory.createInventory()
        local ok = actor.inventory:addItem(picked, action.pickupLocation or inventory.LOCATIONS.HANDS)
        if not ok then
            owner.droppedItems[#owner.droppedItems + 1] = picked
            result.success = false
            result.description = "Ungoat cannot carry the dropped item."
            result.effects[#result.effects + 1] = "ungoat_pickup_failed"
            return result
        end

        result.success = true
        result.pickedUpItem = picked
        result.effects[#result.effects + 1] = "ungoat_pickup_dropped_item"
        result.effects[#result.effects + 1] = "dropped_item_recovered_by_ungoat"
        result.description = "Ungoat picks up [" .. (picked.name or "dropped item") .. "]."
        self.eventBus:emit(events.EVENTS.INVENTORY_CHANGED, {
            entity = actor,
            item = picked,
            reason = "ungoat_pickup_dropped_item",
        })
        action.result = result
        return result
    end

    function resolver:getUngoatSmelledMagic(actor, subjects)
        if not self:isUngoat(actor) then
            return {}
        end
        return getMagicScentSubjects(subjects)
    end

    function resolver:isUngoatSaltDamage(effects, damageContext)
        damageContext = damageContext or {}
        if damageContext.salt == true or damageContext.source == "salt" then
            return true
        end
        for _, effect in ipairs(effects or {}) do
            local normalized = normalizeTalentKey(effect)
            if normalized == "salt_reactive" or normalized == "salt" then
                return true
            end
        end
        return false
    end

    function resolver:applyUngoatMaleficentRetribution(entity, effects, damageContext)
        if not self:isUngoat(entity) then
            return nil
        end
        damageContext = damageContext or {}
        if damageContext.nonDirect == true or damageContext.indirect == true or damageContext.trap == true or
           damageContext.environmental == true or damageContext.source == "trap" then
            return nil
        end
        if self:isUngoatSaltDamage(effects, damageContext) then
            return nil
        end

        local action = damageContext.action
        local attacker = damageContext.attacker or damageContext.sourceActor or action and action.actor
        if not attacker or attacker == entity then
            return nil
        end
        if damageContext.direct == false then
            return nil
        end

        local branch = damageContext.maleficenceBranch or action and action.maleficenceBranch or "random"
        local opts = {
            resolve = damageContext.resolveMaleficence == true or damageContext.maleficenceValue ~= nil or
                damageContext.maleficenceCard ~= nil,
            card = damageContext.maleficenceCard,
            value = damageContext.maleficenceValue,
            suit = damageContext.maleficenceSuit,
            source = entity,
            allEntities = damageContext.allEntities or action and action.allEntities,
            environmentManager = damageContext.environmentManager,
            watchManager = damageContext.watchManager,
            roomManager = damageContext.roomManager,
        }
        local record = self:triggerMaleficence(attacker, branch, "ungoat_maleficent_retribution", opts)
        effects[#effects + 1] = "ungoat_maleficent_retribution"
        effects[#effects + 1] = "maleficence_triggered"
        return record
    end

    function resolver:isSlime(entity)
        return entity and (entity.slime ~= nil or entityHasNormalizedTag(entity, "slime"))
    end

    function resolver:isSlimeImpermeableWeapon(entity, weapon)
        if not self:isSlime(entity) or not weapon then
            return false
        end
        if M.isWeaponType(weapon, "PIERCING") then
            return false
        end
        local weaponType = normalizeTalentKey(weapon.weaponType or weapon.type or weapon.name)
        local props = weapon.properties or {}
        return props.slashing == true or props.crushing == true or
            weaponType == "sword" or weaponType == "axe" or weaponType == "mace" or
            weaponType == "hammer" or weaponType == "staff" or weaponType == "club" or
            weaponType == "flail"
    end

    function resolver:applySlimeAcidicWeaponNotch(entity, weapon, effects)
        if not (self:isSlime(entity) and weapon) then
            return nil
        end
        weapon.notches = weapon.notches or 0
        weapon.durability = weapon.durability or 1
        local notchResult = inventory.addNotch(weapon)
        effects[#effects + 1] = "slime_acidic_weapon_notched"
        if notchResult == "destroyed" then
            effects[#effects + 1] = "weapon_destroyed"
        end
        self.eventBus:emit("slime_acidic_weapon_notched", {
            entity = entity,
            weapon = weapon,
            notchResult = notchResult,
        })
        return notchResult
    end

    function resolver:syncSlimeDynamicAttributes(entity)
        if not self:isSlime(entity) then
            return false
        end
        local value = math.max(entity.npcHealth or 0, 0)
        entity.swords = value
        entity.pentacles = value
        entity.attributes = entity.attributes or {}
        entity.attributes[constants.SUITS.SWORDS] = value
        entity.attributes[constants.SUITS.PENTACLES] = value
        return true
    end

    function resolver:isSlimeShapelessImmune(target, effect)
        if not self:isSlime(target) then
            return false
        end
        local slime = target.slime or {}
        return (effect == "displace" and slime.immuneToDisplaced) or
            (effect == "root" and slime.immuneToRooted) or
            (effect == "trip" and slime.immuneToTripped)
    end

    function resolver:blockSlimeShapelessAction(result, effect)
        result.success = false
        result.description = "Slime's shapeless body ignores " .. tostring(effect) .. "."
        result.effects[#result.effects + 1] = "slime_shapeless_body_immune"
        result.effects[#result.effects + 1] = "slime_" .. tostring(effect) .. "_immune"
        return result
    end

    function resolver:slimeGreaterDoomReady(action, effectType, doomId)
        local doom = action and (action.greaterDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            (doomId and doom and doom.id == doomId) or (effect and effect.type == effectType))
    end

    function resolver:getSlimeEngulfEffect(action)
        local actor = action and action.actor
        if not self:isSlime(actor) then
            return nil, nil
        end
        local doom = action.lesserDoom or action.doom
        local effect = doom and doom.effect
        if effect and effect.type == "engulf" then
            return effect, doom
        end
        return nil, nil
    end

    function resolver:isSlimeProtoplasmicRoughhouse(action)
        local effect = self:getSlimeEngulfEffect(action)
        return effect ~= nil
    end

    function resolver:isSlimeEngulfEscapeTestFate(action)
        if not action or self:normalizeActionType(action.type) ~= M.ACTION_TYPES.TEST_FATE then
            return false
        end
        local actor = action.actor
        if not (actor and actor.slimeEngulfed) then
            return false
        end
        if action.escapeSlimeEngulf == true or action.slimeEngulfEscape == true or
           action.escapeSlime == true or action.escapeEngulfed == true then
            return true
        end
        local requested = normalizeTalentKey(action.reason or action.testFateReason or action.objective or
            action.context or action.recoverEffect or action.effect)
        return requested == "slime_engulf_escape" or requested == "escape_slime_engulf" or
            requested == "escape_slime" or requested == "escape_engulfed" or
            requested == "slime_engulfed"
    end

    function resolver:addSlimeEngulfedTarget(slime, target)
        slime.slimeEngulfedTargets = slime.slimeEngulfedTargets or {}
        for _, existing in ipairs(slime.slimeEngulfedTargets) do
            if existing == target then
                return
            end
        end
        slime.slimeEngulfedTargets[#slime.slimeEngulfedTargets + 1] = target
    end

    function resolver:notchSlimeEngulfedGear(target, result)
        local notched = {}
        local function notchItem(item)
            if not item or item.destroyed then
                return
            end
            item.notches = item.notches or 0
            item.durability = item.durability or 1
            local notchResult = inventory.addNotch(item)
            notched[#notched + 1] = {
                item = item,
                result = notchResult,
            }
            if notchResult == "destroyed" then
                result.effects[#result.effects + 1] = "engulfed_item_destroyed"
            end
        end

        if target.inventory and target.inventory.getItems then
            for _, location in ipairs({ inventory.LOCATIONS.BELT }) do
                for _, item in ipairs(target.inventory:getItems(location) or {}) do
                    notchItem(item)
                end
            end
        end

        for _, field in ipairs({ "wornGear", "wornItems" }) do
            for _, item in ipairs(target[field] or {}) do
                notchItem(item)
            end
        end
        if target.wornArmor then
            notchItem(target.wornArmor)
        end

        if #notched > 0 then
            result.effects[#result.effects + 1] = "slime_engulfed_gear_notched"
            result.notchedItems = result.notchedItems or {}
            for _, record in ipairs(notched) do
                result.notchedItems[#result.notchedItems + 1] = record
            end
        end

        return notched
    end

    function resolver:releaseSlimeEngulfedTarget(slime, target, reason)
        if not target then
            return false
        end
        local engulf = target.slimeEngulfed
        slime = slime or target.slimeEngulfedBy or engulf and engulf.slime
        if target.conditions then
            target.conditions.rooted = false
        end
        if target.rootedBy == "slime_engulfed" then
            target.rootedBy = nil
        end
        target.slimeEngulfed = nil
        target.slimeEngulfedBy = nil
        target.slimeEngulfedById = nil
        target.slimeEngulfEscapeReason = reason or "escape_test"

        if slime and slime.slimeEngulfedTargets then
            for index = #slime.slimeEngulfedTargets, 1, -1 do
                if slime.slimeEngulfedTargets[index] == target then
                    table.remove(slime.slimeEngulfedTargets, index)
                end
            end
        end
        return true
    end

    function resolver:resolveSlimeProtoplasmicAttack(action, result)
        result.effects = result.effects or {}
        local actor = action.actor
        local target = action.target
        local effect, doom = self:getSlimeEngulfEffect(action)

        if not (self:isSlime(actor) and target and effect) then
            result.success = false
            result.description = "Protoplasmic Attack requires a slime and target."
            result.effects[#result.effects + 1] = "slime_protoplasmic_attack_blocked"
            return
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = true,
            considerShield = true,
        })
        if contest.dodged then
            return
        end

        if result.success then
            self:applyRooted(target, { action = action, reason = "slime_engulfed" })
            target.rootedBy = "slime_engulfed"
            target.slimeEngulfedBy = actor
            target.slimeEngulfedById = actor.id
            target.slimeEngulfed = {
                slime = actor,
                slimeId = actor.id,
                turnStartWounds = effect.turnStartWounds or 1,
                notchWornAndBeltGear = effect.notchWornAndBeltGear ~= false,
                escapeTest = effect.escapeTest or "swords",
                source = "slime_protoplasmic_attack",
            }
            self:addSlimeEngulfedTarget(actor, target)

            result.effects[#result.effects + 1] = "slime_protoplasmic_attack"
            result.effects[#result.effects + 1] = "slime_engulfed"
            result.effects[#result.effects + 1] = "rooted"
            result.description = (doom and doom.name or "Protoplasmic Attack") ..
                " engulfs " .. (target.name or "the target") .. "."
        else
            result.description = (doom and doom.name or "Protoplasmic Attack") .. " fails to engulf the target."
        end

        self:appendRoughhouseRiposte(action, result, contest)
    end

    function resolver:resolveSlimeEngulfEscapeTestFate(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local engulf = actor and actor.slimeEngulfed
        local slime = action.slime or actor and actor.slimeEngulfedBy or engulf and engulf.slime

        if not (actor and engulf and self:isSlime(slime)) then
            result.success = false
            result.description = "No slime engulf effect to escape."
            result.effects[#result.effects + 1] = "slime_engulf_missing"
            return
        end

        result.testedAttribute = "swords"
        result.slimeEngulfEscape = {
            slime = slime,
            slimeId = slime.id,
            target = actor,
            targetId = actor.id,
            escapeTest = engulf.escapeTest or "swords",
        }

        if result.success then
            self:releaseSlimeEngulfedTarget(slime, actor, "test_fate")
            result.effects[#result.effects + 1] = "slime_engulf_escape"
            result.effects[#result.effects + 1] = "slime_engulf_released"
            result.description = (actor.name or "Target") .. " escapes the slime."
        else
            result.effects[#result.effects + 1] = "slime_engulf_escape_failed"
            result.description = (actor.name or "Target") .. " fails to escape the slime."
        end

        self.eventBus:emit("slime_engulf_escape", {
            actor = actor,
            slime = slime,
            success = result.success,
            result = result,
        })
    end

    function resolver:getSlimeEngulfedTargets(slime)
        local targets = {}
        for _, target in ipairs(slime and slime.slimeEngulfedTargets or {}) do
            if target and target.slimeEngulfedBy == slime then
                targets[#targets + 1] = target
            end
        end
        return targets
    end

    function resolver:moveSlimeEngulfedTargets(slime, oldZone, destZone, action, result)
        if not self:isSlime(slime) then
            return false
        end
        local moved = {}
        for _, target in ipairs(self:getSlimeEngulfedTargets(slime)) do
            if target.zone == oldZone or target.slimeEngulfed then
                target.zone = destZone
                if self.zoneSystem and target.id then
                    self.zoneSystem:placeEntity(target.id, destZone)
                end
                moved[#moved + 1] = target
            end
        end
        if #moved > 0 then
            result.effects[#result.effects + 1] = "slime_engulfed_targets_moved"
            result.slimeMovedEngulfedTargets = moved
        end
        return #moved > 0
    end

    function resolver:resolveSlimeEngulfTurnStart(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local target = action.actor or action.target
        local engulf = target and target.slimeEngulfed
        local slime = action.slime or target and target.slimeEngulfedBy or engulf and engulf.slime

        if not (target and engulf and self:isSlime(slime)) then
            result.success = false
            result.description = "No slime engulf effect to resolve."
            result.effects[#result.effects + 1] = "slime_engulf_missing"
            return result
        end

        local wounds = action.wounds or engulf.turnStartWounds or 1
        result.success = true
        result.damageDealt = wounds
        result.effects[#result.effects + 1] = "slime_engulf_turn_start"
        result.effects[#result.effects + 1] = "slime_engulfed_wound"
        self:applyDamage(target, wounds, result.effects, nil, action.allEntities,
            self:getActionWoundOptions(action, target), {
                source = "slime_engulf_turn_start",
                action = action,
            })
        if engulf.notchWornAndBeltGear ~= false then
            self:notchSlimeEngulfedGear(target, result)
        end
        result.description = (target.name or "Target") .. " is crushed inside the slime."
        action.result = result
        return result
    end

    function resolver:resolveSlimeGrind(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect or {}

        if not self:isSlime(actor) then
            result.success = false
            result.description = "Grind requires a slime."
            result.effects[#result.effects + 1] = "slime_grind_blocked"
            return result
        end
        if not self:slimeGreaterDoomReady(action, "wound_engulfed_targets", "grind") then
            result.success = false
            result.description = "Slime Grind requires a greater doom."
            result.effects[#result.effects + 1] = "slime_grind_requires_greater_doom"
            return result
        end

        local targets = self:getSlimeEngulfedTargets(actor)
        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.affected = targets
        result.effects[#result.effects + 1] = "slime_grind"
        result.effects[#result.effects + 1] = "greater_doom"
        for _, target in ipairs(targets) do
            self:applyDamage(target, effect.wounds or 1, result.effects, nil, action.allEntities,
                self:getActionWoundOptions(action, target), {
                    source = "slime_grind",
                    action = action,
                })
        end
        result.description = (actor.name or "Slime") .. " grinds " .. tostring(#targets) .. " engulfed target(s)."
        action.result = result
        return result
    end

    function resolver:resolveSlimeRegenerate(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local doom = action.greaterDoom or action.doom

        if not self:isSlime(actor) then
            result.success = false
            result.description = "Regenerate requires a slime."
            result.effects[#result.effects + 1] = "slime_regenerate_blocked"
            return result
        end
        if not self:slimeGreaterDoomReady(action, "heal_self", "regenerate") then
            result.success = false
            result.description = "Slime Regenerate requires a greater doom."
            result.effects[#result.effects + 1] = "slime_regenerate_requires_greater_doom"
            return result
        end
        if actor.slimeSaltedThisTurn or actor.saltSpreadThisTurn or action.saltSpreadThisTurn then
            result.success = false
            result.description = "Salt spread on the slime prevents Regenerate this turn."
            result.effects[#result.effects + 1] = "slime_regenerate_blocked_by_salt"
            return result
        end

        local healed = self:healNPCHealth(actor, action.healWounds or 1)
        self:syncSlimeDynamicAttributes(actor)
        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.healed = healed
        result.effects[#result.effects + 1] = "slime_regenerate"
        result.effects[#result.effects + 1] = "greater_doom"
        if healed > 0 then
            result.effects[#result.effects + 1] = "healed"
        end
        result.description = (actor.name or "Slime") .. " regenerates " .. tostring(healed) .. " Wound(s)."
        action.result = result
        return result
    end

    function resolver:ogreGreaterDoomReady(action, effectType)
        local doom = action and (action.greaterDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            (effect and effect.type == effectType))
    end

    function resolver:getOgreEatObject(action)
        action = action or {}
        if action.item then
            return action.item, action.itemLocation
        end
        local actor = action.actor
        if actor and actor.inventory and action.itemId then
            local item, location = actor.inventory:findItem(action.itemId)
            return item, location
        end
        if type(action.target) == "table" and (action.target.isItem or action.target.itemType or
           action.target.objectType or action.target.scenery or action.target.obstacleType) then
            return action.target, action.targetLocation
        end
        return nil, nil
    end

    function resolver:resolveOgreEatObject(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No ogre to eat the object."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isOgre(actor) then
            result.success = false
            result.description = "Eat-Eat-Eat requires an ogre."
            result.effects[#result.effects + 1] = "ogre_eat_object_blocked"
            return result
        end
        if not action.card then
            result.success = false
            result.description = "Ogre Eat-Eat-Eat requires any card."
            result.effects[#result.effects + 1] = "ogre_eat_object_requires_card"
            return result
        end

        local item, location = self:getOgreEatObject(action)
        if not item then
            result.success = false
            result.description = "No object for the ogre to eat."
            result.effects[#result.effects + 1] = "ogre_eat_object_missing"
            return result
        end
        if actor.inventory and item.id and location and location ~= inventory.LOCATIONS.HANDS and not action.givenTime then
            result.success = false
            result.description = "Ogre Eat-Eat-Eat requires a held object unless the ogre has time to chew through it."
            result.effects[#result.effects + 1] = "ogre_eat_object_not_held"
            return result
        end

        if actor.inventory and item.id then
            actor.inventory:removeItem(item.id)
        end
        item.destroyed = true
        item.eatenByOgre = actor.id or true
        item.eaten = true
        actor.ogreEatenObjects = actor.ogreEatenObjects or {}
        actor.ogreEatenObjects[#actor.ogreEatenObjects + 1] = item

        result.success = true
        result.eatenItem = item
        result.effects[#result.effects + 1] = "ogre_eat_eat_eat"
        result.effects[#result.effects + 1] = "eaten_object_destroyed"
        result.effects[#result.effects + 1] = "ogre_eating_no_harm"
        result.description = (actor.name or "Ogre") .. " eats " .. (item.name or "an object") ..
            " and destroys it."

        self.eventBus:emit("ogre_eat_object", {
            actor = actor,
            item = item,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:resolveOgreHideousStrength(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target or action.obstacle

        if not actor then
            result.success = false
            result.description = "No ogre for Hideous Strength."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isOgre(actor) then
            result.success = false
            result.description = "That Hideous Strength requires an ogre."
            result.effects[#result.effects + 1] = "ogre_hideous_strength_blocked"
            return result
        end
        if not action.card then
            result.success = false
            result.description = "Ogre Hideous Strength requires any card."
            result.effects[#result.effects + 1] = "ogre_hideous_strength_requires_card"
            return result
        end

        local task = normalizeTalentKey(action.strengthTask or action.task or action.intent or
            action.obstacleType or (target and (target.obstacleType or target.objectType or target.name)) or "strength_feat")

        result.success = true
        result.strengthTask = task
        result.effects[#result.effects + 1] = "ogre_hideous_strength"
        result.effects[#result.effects + 1] = "incredible_strength"
        if task ~= "" then
            result.effects[#result.effects + 1] = "ogre_strength_" .. task
        end

        if type(target) == "table" then
            target.overcomeByOgreStrength = true
            if task:find("portcullis", 1, true) or task:find("lift", 1, true) then
                target.lifted = true
                target.open = true
                result.effects[#result.effects + 1] = "portcullis_lifted"
            elseif task:find("door", 1, true) or task:find("smash", 1, true) then
                target.smashed = true
                target.open = true
                result.effects[#result.effects + 1] = "door_smashed"
            elseif task:find("stone", 1, true) or task:find("wall", 1, true) or task:find("pull", 1, true) then
                target.stonePulled = true
                target.open = true
                result.effects[#result.effects + 1] = "stone_pulled"
            end
        end

        result.description = (actor.name or "Ogre") .. " performs an incredible feat of strength."
        self.eventBus:emit("ogre_hideous_strength", {
            actor = actor,
            target = target,
            task = task,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:getChargedBondTargetId(entity, requested)
        if not entity or not entity.bonds then
            return nil
        end
        if requested then
            local bond = entity.bonds[requested]
            if bond and bond.charged then
                return requested
            end
            return nil
        end
        for targetId, bond in pairs(entity.bonds) do
            if bond.charged then
                return targetId
            end
        end
        return nil
    end

    function resolver:resolveOgreBully(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local target = action.target

        if not actor then
            result.success = false
            result.description = "No ogre for Bully."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isOgre(actor) then
            result.success = false
            result.description = "Bully requires an ogre."
            result.effects[#result.effects + 1] = "ogre_bully_blocked"
            return result
        end
        if not target then
            result.success = false
            result.description = "No adventurer to bully."
            result.effects[#result.effects + 1] = "ogre_bully_missing_target"
            return result
        end
        if not self:ogreGreaterDoomReady(action, "erase_charged_bond") then
            result.success = false
            result.description = "Ogre Bully requires a greater doom."
            result.effects[#result.effects + 1] = "ogre_bully_requires_greater_doom"
            return result
        end

        local bondTargetId = self:getChargedBondTargetId(target, action.bondTargetId or action.chargedBondTargetId)
        if not bondTargetId then
            result.success = false
            result.description = (target.name or "Target") .. " has no matching charged Bond to erase."
            result.effects[#result.effects + 1] = "ogre_bully_no_charged_bond"
            return result
        end

        target.bonds[bondTargetId].charged = false
        target.erasedBonds = target.erasedBonds or {}
        target.erasedBonds[#target.erasedBonds + 1] = {
            bondTargetId = bondTargetId,
            source = actor.id,
            reason = "ogre_bully",
        }

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.target = target
        result.erasedBondTargetId = bondTargetId
        result.effects[#result.effects + 1] = "ogre_bully"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "charged_bond_erased"
        result.description = (actor.name or "Ogre") .. " bullies " .. (target.name or "an adventurer") ..
            " into erasing a charged Bond."

        self.eventBus:emit("ogre_bully", {
            actor = actor,
            target = target,
            bondTargetId = bondTargetId,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:resolveOgreOverwhelmingAttack(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No ogre for Overwhelming Attack."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isOgre(actor) then
            result.success = false
            result.description = "Overwhelming Attack requires an ogre."
            result.effects[#result.effects + 1] = "ogre_overwhelming_attack_blocked"
            return result
        end
        if not self:ogreGreaterDoomReady(action, "greater_doom_attack") then
            result.success = false
            result.description = "Ogre Overwhelming Attack requires its greater doom."
            result.effects[#result.effects + 1] = "ogre_overwhelming_attack_requires_greater_doom"
            return result
        end

        local card = action.greaterDoomCard or action.card
        if not card then
            result.success = false
            result.description = "Ogre Overwhelming Attack requires a greater doom card."
            result.effects[#result.effects + 1] = "ogre_overwhelming_attack_missing_card"
            return result
        end

        local attackAction = {}
        for key, value in pairs(action) do
            attackAction[key] = value
        end
        attackAction.card = card
        attackAction.type = M.ACTION_TYPES.MELEE
        attackAction.normalizedType = nil
        attackAction.ogreOverwhelmingAttack = true
        attackAction.allowGreaterDoomAction = true

        local attackResult = self:resolve(attackAction)
        attackResult.effects = attackResult.effects or {}
        attackResult.effects[#attackResult.effects + 1] = "ogre_overwhelming_attack"
        attackResult.effects[#attackResult.effects + 1] = "greater_doom_attack"
        attackResult.greaterDoomAttack = {
            actor = actor,
            card = card,
            doom = action.greaterDoom or action.doom,
        }
        attackResult.description = (attackResult.description or "") .. " Ogre Overwhelming Attack uses a greater doom."

        action.result = attackResult
        return attackResult
    end

    function resolver:skeletonDoomReady(action, doomKey, effectType)
        local doom = action and (action[doomKey] or action.doom)
        local effect = doom and doom.effect
        return action and (action[doomKey .. "Card"] or action.card or action.discardedDoom or
            action.useDoom == true or (effect and effect.type == effectType))
    end

    function resolver:getSkeletonFearInitiative(action, target)
        local initiatives = action and (action.targetInitiatives or action.fearInitiatives)
        if initiatives and target then
            return initiatives[target.id] or initiatives[target.name] or initiatives[target]
        end
        return target and (target.targetInitiative or target.initiative) or action.targetInitiative or 10
    end

    function resolver:resolveSkeletonUnearthlyFear(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        if not actor then
            result.success = false
            result.description = "No skeleton for Unearthly Fear."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isSkeleton(actor) then
            result.success = false
            result.description = "Unearthly Fear requires a skeleton."
            result.effects[#result.effects + 1] = "skeleton_unearthly_fear_blocked"
            return result
        end
        if not self:skeletonDoomReady(action, "lesserDoom", "zone_stun_test") then
            result.success = false
            result.description = "Skeleton Unearthly Fear requires a lesser doom."
            result.effects[#result.effects + 1] = "skeleton_unearthly_fear_requires_lesser_doom"
            return result
        end

        local card = action.lesserDoomCard or action.card
        if not card then
            result.success = false
            result.description = "Skeleton Unearthly Fear requires a lesser doom card."
            result.effects[#result.effects + 1] = "skeleton_unearthly_fear_missing_card"
            return result
        end

        local fearValue = card.value or 0
        if action.onSkeletonTurn or action.onTurn or action.isTurnAction then
            fearValue = fearValue + (actor.wands or actor.attributes and actor.attributes[constants.SUITS.WANDS] or 0)
            result.effects[#result.effects + 1] = "skeleton_unearthly_fear_wands_added"
        end

        local actorZone = action.zone or actor.zone
        local candidates = action.targets or action.allEntities or {}
        local affected = {}
        local skipped = {}
        for _, candidate in ipairs(candidates) do
            local sameZone = candidate ~= actor and candidate.zone == actorZone
            if sameZone and candidate.isPC == true then
                local initiative = self:getSkeletonFearInitiative(action, candidate)
                if fearValue >= initiative then
                    self:applyStun(candidate, {
                        action = action,
                        instant = true,
                        hand = candidate.challengeHand,
                        handData = candidate.challengeHandData,
                        playerHand = action.playerHand,
                        playerDeck = action.playerDeck,
                        gmDeck = action.gmDeck,
                        npcAI = action.npcAI,
                    })
                    affected[#affected + 1] = {
                        target = candidate,
                        initiative = initiative,
                    }
                else
                    skipped[#skipped + 1] = {
                        target = candidate,
                        initiative = initiative,
                        reason = "initiative_not_beaten",
                    }
                end
            elseif candidate ~= actor then
                skipped[#skipped + 1] = {
                    target = candidate,
                    reason = sameZone and "not_adventurer" or "different_zone",
                }
            end
        end

        result.success = true
        result.fearValue = fearValue
        result.affected = affected
        result.skipped = skipped
        result.effects[#result.effects + 1] = "skeleton_unearthly_fear"
        result.effects[#result.effects + 1] = "zone_stun_test"
        result.description = (actor.name or "Skeleton") .. " stuns " .. tostring(#affected) ..
            " adventurer(s) with Unearthly Fear."

        self.eventBus:emit("skeleton_unearthly_fear", {
            actor = actor,
            action = action,
            result = result,
            affected = affected,
            skipped = skipped,
        })

        action.result = result
        return result
    end

    function resolver:getSkeletonBoneSource(action)
        if action.boneSource then
            return action.boneSource
        end
        local actor = action.actor
        local actorZone = action.zone or actor and actor.zone
        for _, candidate in ipairs(action.allEntities or {}) do
            local conditions = candidate.conditions or {}
            local sameZone = candidate ~= actor and candidate.zone == actorZone
            local boneSource = sameZone and (candidate.bonesAvailable or candidate.isBoneSource or
                (self:isSkeleton(candidate) and (conditions.dead or candidate.defeated or candidate.destroyed)))
            if boneSource then
                return candidate
            end
        end
        if action.bonesAvailable then
            return {
                id = "available_bones",
                name = "Available Bones",
                zone = actorZone,
            }
        end
        return nil
    end

    function resolver:resolveSkeletonAbsorbBones(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        if not actor then
            result.success = false
            result.description = "No skeleton for Absorb Bones."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isSkeleton(actor) then
            result.success = false
            result.description = "Absorb Bones requires a skeleton."
            result.effects[#result.effects + 1] = "skeleton_absorb_bones_blocked"
            return result
        end
        if not self:skeletonDoomReady(action, "greaterDoom", "heal_from_bones") then
            result.success = false
            result.description = "Skeleton Absorb Bones requires a greater doom."
            result.effects[#result.effects + 1] = "skeleton_absorb_bones_requires_greater_doom"
            return result
        end

        local boneSource = self:getSkeletonBoneSource(action)
        if not boneSource then
            result.success = false
            result.description = "Skeleton Absorb Bones requires bones in the skeleton's zone."
            result.effects[#result.effects + 1] = "skeleton_absorb_bones_missing_source"
            return result
        end

        local previousHealth = actor.npcHealth or 0
        actor.npcHealth = math.min(actor.npcMaxHealth or previousHealth, previousHealth + (action.healAmount or 1))
        boneSource.consumedByAbsorbBones = true
        boneSource.removed = true

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.boneSource = boneSource
        result.healed = actor.npcHealth - previousHealth
        result.effects[#result.effects + 1] = "skeleton_absorb_bones"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "healed"
        result.description = (actor.name or "Skeleton") .. " absorbs bones and heals " ..
            tostring(result.healed) .. " Wound(s)."

        self.eventBus:emit("skeleton_absorb_bones", {
            actor = actor,
            action = action,
            result = result,
            boneSource = boneSource,
        })

        action.result = result
        return result
    end

    function resolver:getWeaponImmunityKey(weapon)
        if not weapon then
            return nil
        end
        return normalizeTalentKey(weapon.weaponType or weapon.type or weapon.name or weapon.templateId)
    end

    function resolver:isKelpieTarget(entity)
        return entity and (entity.kelpie ~= nil or entityHasNormalizedTag(entity, "kelpie"))
    end

    function resolver:isSilverWeapon(weapon)
        if not weapon then
            return false
        end
        local props = weapon.properties or {}
        local material = normalizeTalentKey(weapon.material or props.material)
        return weapon.silver == true or props.silver == true or material == "silver"
    end

    function resolver:resolveKelpieThreshold(entity, amount, effects, weapon, damageContext)
        amount = amount or 0
        if amount <= 0 then
            return nil
        end
        if not self:isKelpieTarget(entity) or entity.kelpieThresholdBroken then
            return nil
        end

        local threshold = entity.kelpie and entity.kelpie.threshold
        local ignoresDamageUntil = threshold and threshold.ignoresDamageUntil
        local requiredWounds = ignoresDamageUntil and ignoresDamageUntil.woundsInSingleTurn or 2
        if self:isSilverWeapon(weapon) then
            entity.kelpieThresholdBroken = true
            effects[#effects + 1] = "kelpie_threshold_broken_silver"
            self.eventBus:emit("kelpie_threshold_broken", {
                entity = entity,
                weapon = weapon,
                source = damageContext and damageContext.source,
                silver = true,
            })
            return nil
        end

        if amount < requiredWounds then
            entity.kelpieThreshold = entity.kelpieThreshold or {}
            entity.kelpieThreshold.lastIgnoredWounds = amount
            entity.kelpieThreshold.requiredWounds = requiredWounds
            entity.kelpieThreshold.source = damageContext and damageContext.source
            effects[#effects + 1] = "kelpie_threshold_ignored"
            self.eventBus:emit("kelpie_threshold_ignored", {
                entity = entity,
                amount = amount,
                requiredWounds = requiredWounds,
                source = damageContext and damageContext.source,
            })
            return {
                result = "ignored",
                ignored = true,
                reason = "kelpie_threshold",
                requiredWounds = requiredWounds,
                amount = amount,
            }
        end

        entity.kelpieThresholdBroken = true
        effects[#effects + 1] = "kelpie_threshold_broken"
        self.eventBus:emit("kelpie_threshold_broken", {
            entity = entity,
            amount = amount,
            source = damageContext and damageContext.source,
        })
        return nil
    end

    function resolver:resolveMimicHarden(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No mimic for Harden."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isMimicTarget(actor) then
            result.success = false
            result.description = "Harden requires a mimic."
            result.effects[#result.effects + 1] = "mimic_harden_blocked"
            return result
        end

        local doom = action.greaterDoom or action.doom
        local effect = doom and doom.effect
        if not (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
           (effect and effect.type == "mimic_harden_weapon_immunity")) then
            result.success = false
            result.description = "Mimic Harden requires a greater doom."
            result.effects[#result.effects + 1] = "mimic_harden_requires_greater_doom"
            return result
        end

        local weaponType = actor.lastWoundingWeaponType
        if not weaponType or weaponType == "" then
            result.success = false
            result.description = "Mimic Harden has no last wounding weapon type."
            result.effects[#result.effects + 1] = "mimic_harden_no_wounding_weapon"
            return result
        end

        actor.mimicWeaponImmunityType = weaponType
        actor.mimicWeaponImmunityName = actor.lastWoundingWeaponName or weaponType
        actor.mimicHarden = {
            weaponType = weaponType,
            weaponName = actor.mimicWeaponImmunityName,
            source = doom and doom.name or "Harden",
        }

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.effects[#result.effects + 1] = "mimic_harden"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "weapon_immunity"
        result.weaponImmunityType = weaponType
        result.description = (actor.name or "Mimic") .. " hardens against " ..
            tostring(actor.mimicWeaponImmunityName) .. " attacks."

        self.eventBus:emit("mimic_harden", {
            actor = actor,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:isQuestingBeast(entity)
        return entity and (entity.questingBeast ~= nil or entityHasNormalizedTag(entity, "questing_beast"))
    end

    function resolver:questingBeastGreaterDoomReady(action, effectType)
        local doom = action and (action.greaterDoom or action.doom)
        local effect = doom and doom.effect
        return action and (action.greaterDoomCard or action.discardedGreaterDoom or action.useGreaterDoom == true or
            (effect and effect.type == effectType))
    end

    function resolver:resolveQuestingBeastEvasive(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No questing beast for Evasive."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isQuestingBeast(actor) then
            result.success = false
            result.description = "Evasive requires a questing beast."
            result.effects[#result.effects + 1] = "questing_beast_evasive_blocked"
            return result
        end
        if not self:questingBeastGreaterDoomReady(action, "greater_doom_dodge") then
            result.success = false
            result.description = "Questing Beast Evasive requires a greater doom."
            result.effects[#result.effects + 1] = "questing_beast_evasive_requires_greater_doom"
            return result
        end

        local card = action.greaterDoomCard or action.card
        if not card then
            result.success = false
            result.description = "Questing Beast Evasive requires a greater doom card."
            result.effects[#result.effects + 1] = "questing_beast_evasive_missing_card"
            return result
        end

        local defenseValue = action.defenseValue or action.dodgeValue or card.value or 0
        local success, err, replacedDefense = actor:prepareDefense("dodge", card, defenseValue)
        if not success then
            result.success = false
            result.description = "Cannot prepare Evasive Dodge: " .. (err or "unknown")
            return result
        end

        if actor.pendingDefense then
            actor.pendingDefense.greaterDoom = action.greaterDoom or action.doom
            actor.pendingDefense.greaterDoomCard = card
            actor.pendingDefense.questingBeastEvasive = true
        end

        result.success = true
        result.replacedDefense = replacedDefense
        result.effects[#result.effects + 1] = "questing_beast_evasive"
        result.effects[#result.effects + 1] = "greater_doom_dodge"
        result.effects[#result.effects + 1] = "dodge_prepared"
        result.description = (actor.name or "Questing Beast") ..
            " prepares an Evasive Dodge with a greater doom."

        self.eventBus:emit("questing_beast_evasive", {
            actor = actor,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:resolveQuestingBeastExpeditiousRetreat(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No questing beast for Expeditious Retreat."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isQuestingBeast(actor) then
            result.success = false
            result.description = "Expeditious Retreat requires a questing beast."
            result.effects[#result.effects + 1] = "questing_beast_expeditious_retreat_blocked"
            return result
        end
        if not self:questingBeastGreaterDoomReady(action, "disengage_all") then
            result.success = false
            result.description = "Questing Beast Expeditious Retreat requires a greater doom."
            result.effects[#result.effects + 1] = "questing_beast_expeditious_retreat_requires_greater_doom"
            return result
        end

        self:clearAllEngagements(actor, action.allEntities)

        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.effects[#result.effects + 1] = "questing_beast_expeditious_retreat"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "disengaged_all"
        result.description = (actor.name or "Questing Beast") ..
            " disengages from all combatants without spending its turn card."

        self.eventBus:emit("questing_beast_expeditious_retreat", {
            actor = actor,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:clearQuestingBeastRecoverableEffects(actor)
        local cleared = {}
        actor.conditions = actor.conditions or {}
        local conditions = actor.conditions
        local names = {
            "rooted",
            "prone",
            "blind",
            "blinded",
            "deaf",
            "deafened",
            "silenced",
            "exhausted",
            "burning",
            "onFire",
            "disarmed",
            "webbed",
            "stunned",
            "stunnedInstant",
        }

        for _, name in ipairs(names) do
            if conditions[name] then
                cleared[#cleared + 1] = name
                conditions[name] = false
            end
        end

        actor.webbedLimbs = nil
        actor.silenced = false
        actor.exhausted = false
        actor.onFire = false

        return cleared
    end

    function resolver:resolveQuestingBeastResilient(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor

        if not actor then
            result.success = false
            result.description = "No questing beast for Resilient."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isQuestingBeast(actor) then
            result.success = false
            result.description = "Resilient requires a questing beast."
            result.effects[#result.effects + 1] = "questing_beast_resilient_blocked"
            return result
        end
        if not self:questingBeastGreaterDoomReady(action, "recover_all_effects") then
            result.success = false
            result.description = "Questing Beast Resilient requires a greater doom."
            result.effects[#result.effects + 1] = "questing_beast_resilient_requires_greater_doom"
            return result
        end

        local cleared = self:clearQuestingBeastRecoverableEffects(actor)
        result.success = true
        result.cardless = true
        result.countsTowardTurnCard = false
        result.clearedEffects = cleared
        result.effects[#result.effects + 1] = "questing_beast_resilient"
        result.effects[#result.effects + 1] = "greater_doom"
        result.effects[#result.effects + 1] = "recover_all_effects"
        result.description = (actor.name or "Questing Beast") ..
            " recovers from " .. tostring(#cleared) .. " effect(s) without spending its turn card."

        self.eventBus:emit("questing_beast_resilient", {
            actor = actor,
            action = action,
            result = result,
            cleared = cleared,
        })

        action.result = result
        return result
    end

    function resolver:resolveQuestingBeastSlippery(action, result)
        result.effects = result.effects or {}
        action = action or {}
        local actor = action.actor
        local hazard = action.hazard or action.target or action.obstacle

        if not actor then
            result.success = false
            result.description = "No questing beast for Slippery."
            result.effects[#result.effects + 1] = "missing_actor"
            return result
        end
        if not self:isQuestingBeast(actor) then
            result.success = false
            result.description = "Slippery requires a questing beast."
            result.effects[#result.effects + 1] = "questing_beast_slippery_blocked"
            return result
        end
        if not action.card then
            result.success = false
            result.description = "Questing Beast Slippery requires any discarded card."
            result.effects[#result.effects + 1] = "questing_beast_slippery_requires_card"
            return result
        end

        local hazardType = normalizeTalentKey(action.hazardType or action.task or action.intent or
            (type(hazard) == "table" and (hazard.hazardType or hazard.obstacleType or hazard.trapType or hazard.name)) or
            "hazard")

        result.success = true
        result.countsTowardTurnCard = false
        result.hazard = hazard
        result.hazardType = hazardType
        result.effects[#result.effects + 1] = "questing_beast_slippery"
        result.effects[#result.effects + 1] = "hazard_avoided"
        if hazardType ~= "" then
            result.effects[#result.effects + 1] = "questing_beast_slippery_" .. hazardType
        end

        if type(hazard) == "table" then
            hazard.avoidedByQuestingBeast = true
            if hazardType:find("trap", 1, true) or hazard.trap then
                hazard.triggered = true
                hazard.evaded = true
                hazard.triggeredByQuestingBeast = true
                result.effects[#result.effects + 1] = "trap_triggered_and_evaded"
            elseif hazardType:find("door", 1, true) then
                hazard.smashed = true
                hazard.open = true
                result.effects[#result.effects + 1] = "door_bashed_down"
            elseif hazardType:find("pit", 1, true) or hazardType:find("chasm", 1, true) then
                hazard.leapt = true
                hazard.crossed = true
                result.effects[#result.effects + 1] = "pit_leapt"
            end
        end

        result.description = (actor.name or "Questing Beast") ..
            " slips past the dungeon hazard without spending its turn card."
        self.eventBus:emit("questing_beast_slippery", {
            actor = actor,
            hazard = hazard,
            hazardType = hazardType,
            action = action,
            result = result,
        })

        action.result = result
        return result
    end

    function resolver:getSecondAttackAfterMissEffectName(actor, lesserDoom)
        local suffix = (lesserDoom and lesserDoom.id) or "second_attack"
        if self:isQuestingBeast(actor) then
            return "questing_beast_" .. suffix
        end
        if actor and (actor.kelpie ~= nil or entityHasNormalizedTag(actor, "kelpie")) then
            return "kelpie_" .. suffix
        end
        return "second_attack_after_miss_" .. suffix
    end

    function resolver:resolveSecondAttackAfterMiss(action, result)
        if not action or action.trampleFollowUp then
            return false
        end
        local actor = action.actor
        local lesserDoom = action.lesserDoom
        local effect = lesserDoom and lesserDoom.effect
        if not (effect and effect.type == "second_attack_after_miss") then
            return false
        end

        local effectName = self:getSecondAttackAfterMissEffectName(actor, lesserDoom)
        local secondTarget = action.secondTarget or action.trampleTarget
        if not secondTarget then
            result.effects[#result.effects + 1] = effectName .. "_missing_target"
            return false
        end
        if action.target and action.target.zone and secondTarget.zone and action.target.zone ~= secondTarget.zone then
            result.effects[#result.effects + 1] = effectName .. "_target_not_same_zone"
            return false
        end

        local followAction = {
            actor = actor,
            target = secondTarget,
            card = action.card,
            type = M.ACTION_TYPES.MELEE,
            weapon = action.weapon,
            targetInitiative = action.secondTargetInitiative or action.trampleTargetInitiative,
            allEntities = action.allEntities,
            challengeController = action.challengeController,
            playerDeck = action.playerDeck,
            gmDeck = action.gmDeck,
            playerHand = action.playerHand,
            npcAI = action.npcAI,
            trampleFollowUp = true,
        }

        local followResult = self:resolve(followAction)
        result.trampleResult = followResult
        result.effects[#result.effects + 1] = effectName
        result.effects[#result.effects + 1] = "second_attack_after_miss"
        result.description = (result.description or "") .. " " .. (lesserDoom.name or "Second attack") ..
            " follows through against " ..
            (secondTarget.name or "a second target") .. "."
        return true
    end

    function resolver:resolveQuestingBeastTrample(action, result)
        return self:resolveSecondAttackAfterMiss(action, result)
    end

    ----------------------------------------------------------------------------
    -- MAIN RESOLUTION ENTRY POINT
    ----------------------------------------------------------------------------

    --- Resolve an action
    -- @param action table: { actor, target, type, card, weapon, ... }
    -- @return table: { success, isGreat, damageDealt, effects, description }
    function resolver:resolve(action)
        local result = {
            success = false,
            isGreat = false,
            damageDealt = 0,
            effects = {},
            description = "",
            cardValue = 0,
            modifier = 0,
            testValue = 0,
            difficulty = 10,
        }

        action = action or {}
        local actionType = self:normalizeActionType(action.type or "generic")
        action.normalizedType = actionType

        if not self:validateDungeonLordDoomAvailable(action, result) then
            return result
        end
        if not self:validateTitanDoomAvailable(action, result) then
            return result
        end

        if actionType == M.ACTION_TYPES.FREE_ACTION then
            return self:resolveFreeAction(action, result)
        end

        if animal_companions.isAnimalCompanion(action.actor) and not (
            action.allowCompanionAction == true or
            action.allowAnimalCompanionAction == true or
            action.commandedByOwner == true or
            action.isControlledAction == true
        ) then
            result.success = false
            result.description = "Animal companions act only when commanded."
            result.effects[#result.effects + 1] = "animal_companion_needs_command"
            action.result = result
            return result
        end

        if actionType == M.ACTION_TYPES.CREATURE_GAZE or actionType == M.ACTION_TYPES.COCKATRICE_GAZE then
            return self:resolveCreatureGaze(action, result)
        end

        if actionType == M.ACTION_TYPES.COCKATRICE_FLUTTER then
            return self:resolveCockatriceFlutter(action, result)
        end

        if actionType == M.ACTION_TYPES.GRIFFIN_DROP then
            return self:resolveGriffinDrop(action, result)
        end

        if actionType == M.ACTION_TYPES.HARPY_SHRIEK then
            return self:resolveHarpyShriek(action, result)
        end

        if actionType == M.ACTION_TYPES.HARPY_FLUTTER_MOVE then
            return self:resolveHarpyFlutterMove(action, result)
        end

        if actionType == M.ACTION_TYPES.HARPY_FLIGHT_MOVE then
            return self:resolveHarpyFlightMove(action, result)
        end

        if actionType == M.ACTION_TYPES.HARPY_PELT_WITH_STONES then
            return self:resolveHarpyPeltWithStones(action, result)
        end

        if actionType == M.ACTION_TYPES.HARPY_PULL_INTO_AIR then
            return self:resolveHarpyPullIntoAir(action, result)
        end

        if actionType == M.ACTION_TYPES.BEAST_FLEET_MOVE then
            return self:resolveBeastFleetMove(action, result)
        end

        if actionType == M.ACTION_TYPES.CENTIPEDE_FLEET_MOVE then
            return self:resolveCentipedeFleetMove(action, result)
        end

        if actionType == M.ACTION_TYPES.LION_FLEET_MOVE then
            return self:resolveLionFleetMove(action, result)
        end

        if actionType == M.ACTION_TYPES.LION_CAUTIOUS_RETREAT then
            return self:resolveLionCautiousRetreat(action, result)
        end

        if actionType == M.ACTION_TYPES.STRATEGIST_CAUTIOUS_RETREAT then
            return self:resolveStrategistCautiousRetreat(action, result)
        end

        if actionType == M.ACTION_TYPES.ELITE_INTANGIBLE then
            return self:resolveEliteIntangible(action, result)
        end

        if actionType == M.ACTION_TYPES.ELITE_REGENERATE then
            return self:resolveEliteRegenerate(action, result)
        end

        if actionType == M.ACTION_TYPES.ELITE_POTENCE then
            return self:resolveElitePotence(action, result)
        end

        if actionType == M.ACTION_TYPES.ELITE_SHAPESHIFTER then
            return self:resolveEliteShapeshifter(action, result)
        end

        if actionType == M.ACTION_TYPES.LION_ROAR_OF_LIFE then
            return self:resolveLionRoarOfLife(action, result)
        end

        if actionType == M.ACTION_TYPES.MIMIC_HARDEN then
            return self:resolveMimicHarden(action, result)
        end

        if self:isMimicCamouflageInteraction(action, actionType) then
            return self:resolveMimicCamouflageInteraction(action, result)
        end

        if actionType == M.ACTION_TYPES.QUESTING_BEAST_EVASIVE then
            return self:resolveQuestingBeastEvasive(action, result)
        end

        if actionType == M.ACTION_TYPES.QUESTING_BEAST_EXPEDITIOUS_RETREAT then
            return self:resolveQuestingBeastExpeditiousRetreat(action, result)
        end

        if actionType == M.ACTION_TYPES.QUESTING_BEAST_RESILIENT then
            return self:resolveQuestingBeastResilient(action, result)
        end

        if actionType == M.ACTION_TYPES.QUESTING_BEAST_SLIPPERY then
            return self:resolveQuestingBeastSlippery(action, result)
        end

        if actionType == M.ACTION_TYPES.OGRE_EAT_OBJECT then
            return self:resolveOgreEatObject(action, result)
        end

        if actionType == M.ACTION_TYPES.OGRE_HIDEOUS_STRENGTH then
            return self:resolveOgreHideousStrength(action, result)
        end

        if actionType == M.ACTION_TYPES.OGRE_BULLY then
            return self:resolveOgreBully(action, result)
        end

        if actionType == M.ACTION_TYPES.OGRE_OVERWHELMING_ATTACK then
            return self:resolveOgreOverwhelmingAttack(action, result)
        end

        if actionType == M.ACTION_TYPES.SKELETON_UNEARTHLY_FEAR then
            return self:resolveSkeletonUnearthlyFear(action, result)
        end

        if actionType == M.ACTION_TYPES.SKELETON_ABSORB_BONES then
            return self:resolveSkeletonAbsorbBones(action, result)
        end

        if actionType == M.ACTION_TYPES.ZOMBIE_DEVOUR_THE_LIVING then
            return self:resolveZombieDevourTheLiving(action, result)
        end

        if actionType == M.ACTION_TYPES.ZOMBIE_LAST_GRASP then
            return self:resolveZombieLastGrasp(action, result)
        end

        if actionType == M.ACTION_TYPES.UNDEAD_FEAR then
            return self:resolveUndeadFear(action, result)
        end

        if actionType == M.ACTION_TYPES.FUNGOID_CHOKING_SPORES then
            return self:resolveFungoidChokingSpores(action, result)
        end

        if actionType == M.ACTION_TYPES.FUNGOID_MINOR_ILLUSION then
            return self:resolveFungoidMinorIllusion(action, result)
        end

        if actionType == M.ACTION_TYPES.FUNGOID_FUNGAL_REGENERATION then
            return self:resolveFungoidFungalRegeneration(action, result)
        end

        if actionType == M.ACTION_TYPES.FUNGOID_PERFECT_IMITATION then
            return self:resolveFungoidPerfectImitation(action, result)
        end

        if actionType == M.ACTION_TYPES.ELEMENTAL_MELD then
            return self:resolveElementalMeld(action, result)
        end

        if actionType == M.ACTION_TYPES.NYMPH_BEWITCHING_BEAUTY then
            return self:resolveNymphBewitchingBeauty(action, result)
        end

        if actionType == M.ACTION_TYPES.NYMPH_EXPEDITIOUS_RETREAT then
            return self:resolveNymphExpeditiousRetreat(action, result)
        end

        if actionType == M.ACTION_TYPES.NYMPH_SLEEP_SONG then
            return self:resolveNymphSleepSong(action, result)
        end

        if actionType == M.ACTION_TYPES.NYMPH_WANT then
            return self:resolveNymphWant(action, result)
        end

        if actionType == M.ACTION_TYPES.WINTER_WOLF_AURA_OF_ICE then
            return self:resolveWinterWolfAuraOfIce(action, result)
        end

        if actionType == M.ACTION_TYPES.WINTER_WOLF_BREATH_OF_ICE then
            return self:resolveWinterWolfBreathOfIce(action, result)
        end

        if actionType == M.ACTION_TYPES.WRAITH_SHINE_LIGHT then
            return self:resolveWraithShineLight(action, result)
        end

        if actionType == M.ACTION_TYPES.WRAITH_FEAR then
            return self:resolveWraithFear(action, result)
        end

        if actionType == M.ACTION_TYPES.WRAITH_RETREAT_INTO_SHADOWS then
            return self:resolveWraithRetreatIntoShadows(action, result)
        end

        if actionType == M.ACTION_TYPES.SLIME_GRIND then
            return self:resolveSlimeGrind(action, result)
        end

        if actionType == M.ACTION_TYPES.SLIME_REGENERATE then
            return self:resolveSlimeRegenerate(action, result)
        end

        if actionType == M.ACTION_TYPES.SLIME_ENGULF_TURN_START then
            return self:resolveSlimeEngulfTurnStart(action, result)
        end

        if actionType == M.ACTION_TYPES.JINN_BODY_OF_SMOKELESS_FIRE then
            return self:resolveJinnBodyOfSmokelessFire(action, result)
        end

        if actionType == M.ACTION_TYPES.JINN_INVISIBLE then
            return self:resolveJinnInvisible(action, result)
        end

        if actionType == M.ACTION_TYPES.YELLOW_KING_SPITE_ALONE then
            return self:resolveYellowKingSpiteAlone(action, result)
        end

        if actionType == M.ACTION_TYPES.YELLOW_KING_SORROW then
            return self:resolveYellowKingSorrow(action, result)
        end

        if actionType == M.ACTION_TYPES.YELLOW_KING_FAITHFUL_SERVANT then
            return self:resolveYellowKingFaithfulServant(action, result)
        end

        if actionType == M.ACTION_TYPES.YELLOW_KING_DOUBT_ME_TRAITOR then
            return self:resolveYellowKingDoubtMeTraitor(action, result)
        end

        if actionType == M.ACTION_TYPES.VAMPIRE_CALL_BATS then
            return self:resolveVampireCallBats(action, result)
        end

        if actionType == M.ACTION_TYPES.VAMPIRE_SUPERNATURAL_GRACE then
            return self:resolveVampireSupernaturalGrace(action, result)
        end

        if actionType == M.ACTION_TYPES.VAMPIRE_SUPERNATURAL_SPEED then
            return self:resolveVampireSupernaturalSpeed(action, result)
        end

        if actionType == M.ACTION_TYPES.VAMPIRE_BAT_FORM then
            return self:resolveVampireBatForm(action, result)
        end

        if actionType == M.ACTION_TYPES.VAMPIRE_MIST_FORM then
            return self:resolveVampireMistForm(action, result)
        end

        if actionType == M.ACTION_TYPES.IMP_BAD_LUCK_MACHINE then
            return self:resolveImpBadLuckMachine(action, result)
        end

        if actionType == M.ACTION_TYPES.ANIMATE_STATUE_SQUEEZE then
            return self:resolveAnimateStatueSqueeze(action, result)
        end

        if actionType == M.ACTION_TYPES.TITAN_SQUEEZE then
            return self:resolveTitanSqueeze(action, result)
        end

        if actionType == M.ACTION_TYPES.UNGOAT_PICK_UP_DROPPED_ITEM then
            return self:resolveUngoatPickUpDroppedItem(action, result)
        end

        if actionType == M.ACTION_TYPES.DEVIL_BITE then
            return self:resolveDevilBite(action, result)
        end

        if actionType == M.ACTION_TYPES.DEVIL_FIENDISH_RETREAT then
            return self:resolveDevilFiendishRetreat(action, result)
        end

        if actionType == M.ACTION_TYPES.DEVIL_STINKING_CLOUD then
            return self:resolveDevilStinkingCloud(action, result)
        end

        if actionType == M.ACTION_TYPES.DEVIL_SWALLOW then
            return self:resolveDevilSwallow(action, result)
        end

        if actionType == M.ACTION_TYPES.DEVIL_SWALLOW_TEST_FATE then
            return self:resolveDevilSwallowTestFate(action, result)
        end

        if actionType == M.ACTION_TYPES.SNEAK then
            return self:resolveSneak(action, result)
        end

        if not action.actor or not action.card then
            result.description = "Invalid action"
            return result
        end

        -- Cache action definition early so registry-level requirements apply
        -- even when callers pass only a raw action type.
        local actionDef = self:getActionDef(action)
        if actionDef then
            action.actionDef = actionDef
        end

        -- S12.2: Pre-resolution validation
        local canPerform, blockReason = self:canPerformAction(action.actor, action.type, actionDef, action)
        if not canPerform then
            result.success = false
            result.description = blockReason or "Action blocked"
            result.effects[#result.effects + 1] = "action_blocked"

            -- Emit blocked event
            self.eventBus:emit("action_blocked", {
                actor = action.actor,
                actionType = action.type,
                reason = blockReason,
            })

            return result
        end

        if actionType == M.ACTION_TYPES.TEST_FATE and self:lionUntrackableBlocksTracking(action, result) then
            return result
        end

        if self:lionNobleMercyBlocksAction(action, result, actionType) then
            return result
        end

        if not self:applySceneRuleBlocks(action, result, actionType) then
            action.result = result
            return result
        end

        self:clearJinnInvisibilityForPhysicalInteraction(action.actor, actionType, action, result)

        -- Get card info
        local card = action.card
        result.cardValue = card.value or 0
        local suit = card.suit

        if isGMEntity(action.actor) and isGreaterDoomCard(card) and actionDef and
           actionDef.suit ~= action_registry.SUITS.MISC and
           not (action.allowGreaterDoomAction == true or action.greaterDoomAsChallengeAction == true or
                action.useGreaterDoomAsChallengeAction == true or self:greaterDoomAllowsChallengeAction(action)) then
            result.success = false
            result.description = "GM Challenge Actions require a lesser doom card unless a greater-doom ability says otherwise."
            result.effects[#result.effects + 1] = "greater_doom_standard_action_blocked"
            action.result = result
            return result
        end

        -- S4.9: Check for The Fool interrupt
        if M.isFool(card) then
            return self:resolveFoolInterrupt(action, result)
        end

        -- S7.x: Non-combat actions during Challenges can trigger Test of Fate
        local controller = action.challengeController or self.challengeController
        if actionDef and actionDef.testOfFate and controller and controller.isActive and controller:isActive() then
            local areteResult = self:resolveAreteAutoSuccessTestOfFate(action, actionDef, result)
            if areteResult then
                return areteResult
            end
            return self:requestTestOfFate(action, actionDef, result)
        end

        -- Bid Lore resolves asynchronously through the Bid Lore modal.
        if actionType == M.ACTION_TYPES.BID_LORE and controller and controller.isActive and controller:isActive() then
            return self:requestBidLore(action, actionDef, result)
        end

        -- Calculate modifier from action's associated attribute (or card-only rules)
        local statMod = self:getActionModifier(action, actionDef)
        result.modifier = statMod

        -- Total test value
        result.testValue = result.cardValue + result.modifier

        self:applyTwoHandedFocusMinorAttackMetadata(action, result, actionDef, actionType)

        local favorOk = self:applyChallengeActionFavor(action, result, actionDef, actionType)
        if not favorOk then
            action.result = result
            return result
        end

        self:maybeRedirectFungoidPerfectImitation(action, result)

        -- Get difficulty (target's defense or fixed value)
        result.difficulty = self:getDifficulty(action, actionDef)
        if action.dragonArmoredScalesInitiative then
            result.armoredScalesInitiative = action.dragonArmoredScalesInitiative
            result.effects[#result.effects + 1] = "dragon_armored_scales"
            result.effects[#result.effects + 1] = "greater_doom_as_initiative"
        end
        if action.bruteUntouchableInitiative then
            result.bruteUntouchableInitiative = action.bruteUntouchableInitiative
            result.effects[#result.effects + 1] = "brute_untouchable"
            result.effects[#result.effects + 1] = "greater_doom_as_initiative"
        end
        if action.titanRampageInitiative then
            result.titanRampageInitiative = action.titanRampageInitiative
            result.effects[#result.effects + 1] = "titan_sporehulk_rampage"
            result.effects[#result.effects + 1] = "greater_doom_as_initiative"
        end
        if action.heavyMetalMachineApplied then
            result.heavyMetalMachineApplied = action.heavyMetalMachineApplied
            result.effects[#result.effects + 1] = "heavy_metal_machine_interrupt"
            result.effects[#result.effects + 1] = "initiative_boosted"
        end

        -- Check for success
        result.success = result.testValue >= result.difficulty

        -- Ordinary Challenge Actions do not have a generic Great Success branch.
        result.isGreat = self:isGreatSuccess(card, action.actor)

        -- Route to specific resolution based on ACTION TYPE (not card suit)
        -- This allows using any card for any action on primary turns
        -- Swords actions (combat)
        if actionType == M.ACTION_TYPES.MELEE or
           actionType == M.ACTION_TYPES.MISSILE or
           actionType == M.ACTION_TYPES.AIM then
            self:resolveSwordsAction(action, result)
        -- Pentacles actions (agility/technical)
        elseif actionType == M.ACTION_TYPES.ROUGHHOUSE or
               actionType == M.ACTION_TYPES.TRIP or actionType == M.ACTION_TYPES.DISARM or
               actionType == M.ACTION_TYPES.DISPLACE or actionType == M.ACTION_TYPES.GRAPPLE or
               actionType == M.ACTION_TYPES.AVOID or actionType == M.ACTION_TYPES.DASH then
            self:resolvePentaclesAction(action, result)
        -- Cups actions (defense/social)
        elseif actionType == M.ACTION_TYPES.DODGE or actionType == M.ACTION_TYPES.RIPOSTE or
               actionType == M.ACTION_TYPES.HEAL or actionType == M.ACTION_TYPES.SHIELD or
               actionType == M.ACTION_TYPES.AID or actionType == M.ACTION_TYPES.COMMAND or
               actionType == M.ACTION_TYPES.PARLEY or actionType == M.ACTION_TYPES.RALLY or
               actionType == M.ACTION_TYPES.PULL_ITEM or actionType == M.ACTION_TYPES.USE_ITEM then
            self:resolveCupsAction(action, result)
        -- Wands actions (magic/perception)
        elseif actionType == M.ACTION_TYPES.BANTER or actionType == M.ACTION_TYPES.SPEAK_INCANTATION or
               actionType == M.ACTION_TYPES.COUNTER_SPELL or actionType == M.ACTION_TYPES.RECOVER then
            self:resolveWandsAction(action, result)
        -- Movement and misc
        elseif actionType == M.ACTION_TYPES.MOVE then
            self:resolveMove(action, result, action.allEntities)
        elseif actionType == M.ACTION_TYPES.GUARD then
            self:resolveGuard(action, result)
        elseif actionType == M.ACTION_TYPES.HEAVY_METAL_MACHINE then
            self:resolveHeavyMetalMachine(action, result)
        elseif actionType == M.ACTION_TYPES.UP_MY_SLEEVE then
            local sleeve = self:resolveUpMySleeve(
                action.actor,
                action.upMySleeveItem or action.itemSpec or action.itemTemplateId or action.item or action.itemId,
                {
                    location = action.upMySleeveLocation or action.itemLocation or action.location,
                }
            )
            result.success = sleeve.success == true
            result.description = sleeve.description
            result.reason = sleeve.reason
            result.upMySleeve = sleeve
            result.item = sleeve.item
            result.location = sleeve.location
            result.templateId = sleeve.templateId
            result.uses = sleeve.uses
            result.usesRemaining = sleeve.usesRemaining
            result.resolveSpent = sleeve.resolveSpent
            result.upMySleeveCreation = sleeve.upMySleeveCreation
            for _, effect in ipairs(sleeve.effects or {}) do
                result.effects[#result.effects + 1] = effect
            end
        elseif actionType == M.ACTION_TYPES.VIGILANCE then
            self:resolveVigilance(action, result)
        elseif actionType == M.ACTION_TYPES.DWIMMERCRAFT then
            self:resolveDwimmercraft(action, result)
        elseif actionType == M.ACTION_TYPES.FLEE then
            self:resolveFlee(action, result)
        elseif actionType == M.ACTION_TYPES.BID_LORE or
               actionType == M.ACTION_TYPES.TRIVIAL_ACTION or
               actionType == M.ACTION_TYPES.TEST_FATE or
               actionType == M.ACTION_TYPES.INTERACT then
            if actionType == M.ACTION_TYPES.TEST_FATE and self:isSlimeEngulfEscapeTestFate(action) then
                self:resolveSlimeEngulfEscapeTestFate(action, result)
            else
                self:resolveGenericAction(action, result)
            end
        elseif actionType == M.ACTION_TYPES.PULL_ITEM_BELT then
            self:resolvePullItemFromBelt(action, result)
        elseif actionType == M.ACTION_TYPES.RELOAD then
            -- S7.8: Reload crossbow
            self:resolveReload(action, result)
        else
            -- Unknown action type - fall back to action definition suit when available
            local fallbackSuit = actionDef and actionDef.suit

            if fallbackSuit == action_registry.SUITS.SWORDS then
                self:resolveSwordsAction(action, result)
            elseif fallbackSuit == action_registry.SUITS.PENTACLES then
                self:resolvePentaclesAction(action, result)
            elseif fallbackSuit == action_registry.SUITS.CUPS then
                self:resolveCupsAction(action, result)
            elseif fallbackSuit == action_registry.SUITS.WANDS then
                self:resolveWandsAction(action, result)
            elseif suit == constants.SUITS.SWORDS then
                self:resolveSwordsAction(action, result)
            elseif suit == constants.SUITS.PENTACLES then
                self:resolvePentaclesAction(action, result)
            elseif suit == constants.SUITS.CUPS then
                self:resolveCupsAction(action, result)
            elseif suit == constants.SUITS.WANDS then
                self:resolveWandsAction(action, result)
            else
                self:resolveGenericAction(action, result)
            end
        end

        if actionType == M.ACTION_TYPES.BANTER or actionType == M.ACTION_TYPES.PARLEY then
            self:applyRoomSocialEncounterOutcome(action, result)
        end

        self:applyStrategistTactics(action, result, actionType)

        if action.isQuickInterrupt or action.quickInterrupt then
            result.quickInterrupt = true
            result.effects[#result.effects + 1] = "quick_interrupt"
            if action.quickTalentInterrupt == true then
                local context = action.quickInterruptContext or {}
                result.quickInterruptResolution = {
                    actor = context.actor or action.actor,
                    actorId = context.actorId or (action.actor and action.actor.id),
                    actionType = context.actionType or actionType,
                    card = context.card or action.card,
                    cardName = context.cardName or (action.card and action.card.name),
                    cardSuit = context.cardSuit or (action.card and action.card.suit),
                    cardValue = context.cardValue or (action.card and action.card.value),
                    round = context.round or action.round,
                    count = context.count or action.count,
                    previousState = context.previousState,
                    previousActive = context.previousActive,
                    previousActiveId = context.previousActiveId or
                        (context.previousActive and context.previousActive.id),
                    target = action.target,
                    targetId = action.target and action.target.id,
                    destinationZone = action.destinationZone,
                    success = result.success == true,
                    description = result.description,
                }
            end
        end

        self:spendActionInspirationCard(action, result)

        -- Attach result to action for event emission
        action.result = result

        return result
    end

    ----------------------------------------------------------------------------
    -- STAT MODIFIER CALCULATION
    ----------------------------------------------------------------------------

    --- Get the stat modifier for a given suit
    function resolver:getStatModifier(entity, suit)
        if not entity then return 0 end

        if suit == constants.SUITS.SWORDS then
            return entity.swords or 0
        elseif suit == constants.SUITS.PENTACLES then
            return entity.pentacles or 0
        elseif suit == constants.SUITS.CUPS then
            return entity.cups or 0
        elseif suit == constants.SUITS.WANDS then
            return entity.wands or 0
        end

        return 0
    end

    ----------------------------------------------------------------------------
    -- S7.1: AID ANOTHER SYSTEM
    ----------------------------------------------------------------------------

    function resolver:normalizeAidTriggerAction(actionType)
        if type(actionType) == "table" then
            actionType = actionType.type or actionType.action or actionType.id
        end
        if not actionType then
            return nil
        end
        local normalized = tostring(actionType):lower():gsub("^%s+", ""):gsub("%s+$", ""):gsub("[%s%-]+", "_")
        if normalized == "attack" or normalized == "attacks" then
            return "attack"
        end
        return self:normalizeActionType(normalized)
    end

    function resolver:aidTriggerSpec(action)
        local trigger = action and (action.trigger or action.aidTrigger or action.actionTrigger or action.triggeredAction)
        local triggerAction = action and (
            action.triggerAction or action.triggerActionType or action.triggerType or action.forAction or
            action.actionToAid or action.aidedAction
        )
        local triggerTarget = action and (
            action.triggerTarget or action.triggerTargetId or action.targetToAid or action.aidedTarget
        )
        local objective = action and (action.objective or action.aidObjective or action.triggerObjective)

        if type(trigger) == "table" then
            triggerAction = triggerAction or trigger.action or trigger.type or trigger.actionType or trigger.id
            triggerTarget = triggerTarget or trigger.target or trigger.targetId
            objective = objective or trigger.objective or trigger.description
        elseif trigger ~= nil then
            triggerAction = triggerAction or trigger
        end

        if type(triggerAction) == "table" then
            triggerTarget = triggerTarget or triggerAction.target or triggerAction.targetId
            objective = objective or triggerAction.objective or triggerAction.description
            triggerAction = triggerAction.type or triggerAction.action or triggerAction.actionType or triggerAction.id
        end

        local targetId = nil
        if type(triggerTarget) == "table" then
            targetId = triggerTarget.id or triggerTarget.name
        else
            targetId = triggerTarget
        end

        return {
            action = self:normalizeAidTriggerAction(triggerAction),
            target = triggerTarget,
            targetId = targetId,
            objective = objective,
        }
    end

    function resolver:aidHasTrigger(aid)
        return aid and (aid.triggerAction ~= nil or aid.triggerTargetId ~= nil or aid.objective ~= nil)
    end

    function resolver:aidMatchesAction(aid, action)
        if not aid then
            return false, "no_aid"
        end
        if not self:aidHasTrigger(aid) then
            return true
        end

        local actualAction = self:normalizeActionType(action and (action.normalizedType or action.type))
        if aid.triggerAction then
            if aid.triggerAction == "attack" then
                if actualAction ~= M.ACTION_TYPES.MELEE and actualAction ~= M.ACTION_TYPES.MISSILE then
                    return false, "action_mismatch"
                end
            elseif actualAction ~= aid.triggerAction then
                return false, "action_mismatch"
            end
        end

        if aid.triggerTargetId then
            local target = action and action.target
            local targetId = target and (target.id or target.name) or action and action.targetId
            if tostring(targetId or "") ~= tostring(aid.triggerTargetId) then
                return false, "target_mismatch"
            end
        end

        if aid.objective then
            local actionObjective = action and (action.objective or action.aidObjective or action.triggerObjective)
            if type(action and action.trigger) == "table" then
                actionObjective = actionObjective or action.trigger.objective or action.trigger.description
            end
            if actionObjective == nil and action then
                action.objective = aid.objective
                actionObjective = aid.objective
            end
            local expected = tostring(aid.objective):gsub("^%s+", ""):gsub("%s+$", "")
            local actual = tostring(actionObjective or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if expected ~= actual then
                return false, "objective_mismatch"
            end
        end

        return true
    end

    --- Apply any active aids to an actor's result
    -- @param actor table: The acting entity
    -- @param result table: Result to modify
    -- @param action table: Action currently being resolved
    function resolver:applyActiveAids(actor, result, action, opts)
        if not actor or not actor.id then return end

        local aid = self.activeAids[actor.id]
        if aid and opts and opts.requireSpecificTrigger and not self:aidHasTrigger(aid) then
            return false, "specific_trigger_required"
        end

        local matches, mismatch = self:aidMatchesAction(aid, action)
        if aid and matches then
            result.modifier = (result.modifier or 0) + aid.val
            result.testValue = result.cardValue + result.modifier
            result.description = (result.description or "") .. "(Aided by " .. aid.source .. " +" .. aid.val .. ") "
            result.effects[#result.effects + 1] = "aided"
            result.aidApplied = {
                source = aid.source,
                sourceActor = aid.sourceActor,
                sourceActorId = aid.sourceActorId,
                value = aid.val,
                triggerAction = aid.triggerAction,
                triggerTarget = aid.triggerTarget,
                triggerTargetId = aid.triggerTargetId,
                objective = aid.objective,
            }

            -- Clear the aid (one-time use)
            self.activeAids[actor.id] = nil
            if aid.card and discardChallengeCardToDeck(aid.discardDeck or self.playerDeck, aid.card) then
                result.aidApplied.discarded = true
                result.effects[#result.effects + 1] = "aid_card_discarded"
            end
            print("[AID] " .. (actor.name or actor.id) .. " used aid bonus +" .. aid.val .. " from " .. aid.source)
            return true
        elseif aid and mismatch then
            return false, mismatch
        end

        return false, "no_aid"
    end

    function resolver:aidSourceMatchesActor(aid, actor)
        if not aid or not actor then
            return false
        end
        if aid.sourceActor and aid.sourceActor == actor then
            return true
        end

        local actorId = actor.id
        if actorId and aid.sourceActorId and tostring(aid.sourceActorId) == tostring(actorId) then
            return true
        end
        if actorId and aid.sourceActor and aid.sourceActor.id and
           tostring(aid.sourceActor.id) == tostring(actorId) then
            return true
        end

        return aid.sourceActorId == nil and aid.sourceActor == nil and
            aid.source and actor.name and tostring(aid.source) == tostring(actor.name)
    end

    --- Register an aid for a target
    -- @param target table: Entity receiving the aid
    -- @param value number: Bonus value (card value + cups)
    -- @param source string: Name of the aiding entity
    function resolver:registerAid(target, value, source, opts)
        if not target or not target.id then return end
        opts = opts or {}

        local replacedAid = self.activeAids[target.id]
        if replacedAid and replacedAid.card then
            discardChallengeCardToDeck(replacedAid.discardDeck or self.playerDeck, replacedAid.card)
        end

        -- Overwrite any existing aid (per S7.1 design notes)
        self.activeAids[target.id] = {
            val = value,
            source = source,
            sourceActor = opts.sourceActor,
            sourceActorId = opts.sourceActorId or (opts.sourceActor and opts.sourceActor.id),
            card = opts.card,
            discardDeck = opts.discardDeck,
            triggerAction = opts.triggerAction,
            triggerTarget = opts.triggerTarget,
            triggerTargetId = opts.triggerTargetId,
            objective = opts.objective,
        }
        print("[AID] " .. source .. " aids " .. (target.name or target.id) .. " with +" .. value .. " bonus")
    end

    function resolver:discardActiveAidCards(reason)
        local discarded = {}
        for targetId, aid in pairs(self.activeAids or {}) do
            if aid.card then
                local discardedToDeck = discardChallengeCardToDeck(aid.discardDeck or self.playerDeck, aid.card)
                discarded[#discarded + 1] = {
                    targetId = targetId,
                    aid = aid,
                    card = aid.card,
                    discarded = discardedToDeck,
                    reason = reason or "clear_active_aid",
                }
            end
        end
        self.activeAids = {}
        return discarded
    end

    ----------------------------------------------------------------------------
    -- DIFFICULTY CALCULATION
    ----------------------------------------------------------------------------

    function resolver:getTargetMorale(target, action)
        local moraleBand = explicitMoraleBandKey(target, action)
        if moraleBand then
            local morale = RULEBOOK_MORALE_BANDS[moraleBand]
            morale = morale + (target and target.moraleModifier or 0)
            return math.max(1, morale), moraleBand
        end

        local context = action and (action.moraleContext or action.socialContext or action.context) or nil
        if target and target.getMorale then
            return target:getMorale(context), nil
        end
        if target and target.baseMorale then
            return target.baseMorale + (target.moraleModifier or 0), nil
        end
        if target then
            return (target.morale or (10 + (target.wands or 0))) + (target.moraleModifier or 0), nil
        end
        return 10, nil
    end

    --- Get the difficulty for an action
    function resolver:getDifficulty(action, actionDef)
        local target = action.target
        local actionType = self:normalizeActionType(action.type)

        -- Default difficulty
        local difficulty = 10

        if target then
            -- Initiative-opposed actions compare against target Initiative
            if self:isInitiativeOpposed(actionType) then
                local initValue = self:getTargetInitiative(target, action)
                if initValue then
                    return initValue
                end

                -- Fallback: legacy defense if initiative unavailable
                return 10 + (target.pentacles or 0)
            end

            if actionType == M.ACTION_TYPES.BANTER then
                -- S12.3: Banter vs dynamic Morale
                difficulty = self:getTargetMorale(target, action)
            elseif actionType == M.ACTION_TYPES.PARLEY then
                -- Parley is intentionally slightly harder than Banter
                difficulty = self:getTargetMorale(target, action) + 1
            end
        end

        return difficulty
    end

    ----------------------------------------------------------------------------
    -- GREAT SUCCESS CHECK
    ----------------------------------------------------------------------------

    --- Ordinary Challenge Actions do not use the Test of Fate Great Success rules.
    -- Test of Fate and named procedures set their own great-success metadata.
    function resolver:isGreatSuccess(card, actor)
        return false
    end

    ----------------------------------------------------------------------------
    -- SWORDS RESOLUTION (Melee & Missile)
    ----------------------------------------------------------------------------

    function resolver:resolveSwordsAction(action, result)
        local actionType = self:normalizeActionType(action.type or M.ACTION_TYPES.MELEE)

        if actionType == M.ACTION_TYPES.MISSILE then
            self:resolveMissile(action, result)
        elseif actionType == M.ACTION_TYPES.AIM then
            self:resolveAimPrepare(action, result)
        else
            self:resolveMelee(action, result)
        end
    end

    function resolver:wantsReaver(action)
        return action and (action.useReaver == true or action.reaver == true or action.reaverCharge == true)
    end

    function resolver:resolveReaverCharge(action, result)
        if not self:wantsReaver(action) then
            return true
        end

        local actor = action and action.actor
        if not entityHasUsableTalent(actor, "reaver") then
            result.success = false
            result.description = "Requires Reaver"
            result.effects[#result.effects + 1] = "reaver_blocked"
            return false
        end
        if not self:isActiveChallengeAction(action) then
            result.success = false
            result.description = "Reaver requires an active Challenge"
            result.effects[#result.effects + 1] = "reaver_blocked"
            return false
        end
        if actor.conditions and actor.conditions.rooted then
            result.success = false
            result.description = "Cannot Reaver charge while rooted"
            result.effects[#result.effects + 1] = "reaver_blocked"
            return false
        end

        local oldZone = actor and actor.zone
        local destinationZone = action.reaverDestinationZone or action.chargeDestinationZone or
            (action.target and action.target.zone)
        if not destinationZone or oldZone == destinationZone then
            return true
        end

        local canMove, moveError = self:canMoveBetweenZones(action, oldZone, destinationZone, { maxDistance = 1 })
        if not canMove then
            result.success = false
            result.description = "Reaver charge failed: destination zone is not adjacent."
            result.effects[#result.effects + 1] = "reaver_blocked"
            if moveError then
                result.effects[#result.effects + 1] = moveError
            end
            return false
        end

        local moveResult = {
            success = false,
            effects = {},
            description = "",
        }
        self:resolveMove({
            actor = actor,
            destinationZone = destinationZone,
            challengeController = action.challengeController,
            maxMoveDistance = 1,
        }, moveResult, action.allEntities)

        if not moveResult.success then
            result.success = false
            result.description = "Reaver charge failed: " .. (moveResult.description or "movement failed")
            result.effects[#result.effects + 1] = "reaver_blocked"
            for _, effect in ipairs(moveResult.effects or {}) do
                result.effects[#result.effects + 1] = effect
            end
            return false
        end

        result.reaverCharge = {
            actor = actor,
            oldZone = oldZone,
            newZone = destinationZone,
        }
        for _, effect in ipairs(moveResult.effects or {}) do
            result.effects[#result.effects + 1] = effect
        end
        result.effects[#result.effects + 1] = "reaver_charge"
        result.description = (result.description or "") .. "Reaver charge! "

        if actor.conditions and (actor.conditions.dead or actor.conditions.deaths_door) then
            result.success = false
            result.description = "Reaver charge failed: the actor fell during movement."
            result.effects[#result.effects + 1] = "reaver_blocked"
            return false
        end

        return true
    end

    function resolver:wantsDoomEye(action)
        return action and (action.useDoomEye == true or action.doomEye == true or action.perfectShot == true)
    end

    function resolver:getDoomEyeMissileWeapon(action)
        local weapon = action and action.weapon
        if weapon and (weapon.isRanged or M.isWeaponType(weapon, "BOW") or M.isWeaponType(weapon, "CROSSBOW")) then
            return weapon
        end

        local inv = action and action.actor and action.actor.inventory
        if inv and inv.getWieldedWeapon then
            weapon = inv:getWieldedWeapon()
            if weapon and (weapon.isRanged or M.isWeaponType(weapon, "BOW") or M.isWeaponType(weapon, "CROSSBOW")) then
                return weapon
            end
        end

        return nil
    end

    function resolver:isArchwoodWand(item)
        if not item or item.destroyed then
            return false
        end

        local props = item.properties or {}
        if props.wand and props.archwood then
            return true
        end

        local id = normalizeTalentKey(item.templateId or item.id or item.name)
        return id == "wand_archwood" or id == "wand_of_archwood"
    end

    function resolver:breakPactForItemContact(action, result, item, pactId, reason)
        local actor = action and action.actor
        local pact = camp_actions.findUnbrokenActivePact(actor, pactId)
        if not pact then
            return nil
        end

        local ok, breakResult, detail = camp_actions.breakPact(actor, pact, {
            eventBus = self.eventBus,
            actionResolver = self,
            reason = reason,
        })
        result.pactBreaks = result.pactBreaks or {}
        result.pactBreaks[#result.pactBreaks + 1] = {
            ok = ok,
            result = breakResult,
            detail = detail,
            pact = pact,
            pactId = pactId,
            reason = reason,
            item = item,
        }
        result.effects[#result.effects + 1] = "pact_broken_" .. pactId
        return detail
    end

    function resolver:applyPactItemObligations(action, result, item, reason)
        if not item or not action or not action.actor then
            return {}
        end

        local breaks = {}
        if itemIsArmorOrShieldForPact(item) then
            local detail = self:breakPactForItemContact(action, result, item, "forego_armor",
                reason or "forego_armor_item_contact")
            if detail then
                breaks[#breaks + 1] = detail
            end
        end
        if itemIsWeaponForPact(item) then
            local detail = self:breakPactForItemContact(action, result, item, "forego_weapons",
                reason or "forego_weapons_item_contact")
            if detail then
                breaks[#breaks + 1] = detail
            end
        end
        if itemIsFelledWoodForPact(item) then
            local detail = self:breakPactForItemContact(action, result, item, "forego_wood",
                reason or "forego_wood_item_contact")
            if detail then
                breaks[#breaks + 1] = detail
            end
        end
        if itemIsSkinOrFurForPact(item) then
            local detail = self:breakPactForItemContact(action, result, item, "forego_skins",
                reason or "forego_skins_item_contact")
            if detail then
                breaks[#breaks + 1] = detail
            end
        end

        return breaks
    end

    function resolver:getActionWeapon(action)
        if not action then
            return nil
        end
        if action.weapon then
            return action.weapon
        end
        local inv = action.actor and action.actor.inventory
        return inv and inv.getWieldedWeapon and inv:getWieldedWeapon() or nil
    end

    function resolver:isBowAttackWeapon(weapon)
        return weapon and M.isWeaponType(weapon, "BOW")
    end

    function resolver:getAimTargetId(action)
        local target = action and action.target
        return target and (target.id or target.name) or action and action.targetId or nil
    end

    function resolver:resolveAimPrepare(action, result)
        local actor = action and action.actor
        local card = action and action.card
        if not actor or not card then
            result.success = false
            result.description = "Invalid Aim attempt."
            result.effects[#result.effects + 1] = "aim_blocked"
            return
        end

        local weapon = self:getActionWeapon(action)
        if not self:isBowAttackWeapon(weapon) then
            result.success = false
            result.description = "Aim requires a bow."
            result.effects[#result.effects + 1] = "aim_blocked"
            return
        end
        action.weapon = weapon

        local target = action.target
        if not target and not action.targetId then
            result.success = false
            result.description = "Aim requires a declared target."
            result.effects[#result.effects + 1] = "aim_blocked"
            return
        end

        self:discardActorFacedownActions(actor, action, result, {
            skipAim = true,
            newType = "aim",
            reason = "facedown_replaced_by_aim",
        })

        local faceValue = card.value or result.cardValue or 0
        actor.pendingAim = {
            type = "aim",
            card = card,
            value = faceValue,
            faceValue = faceValue,
            target = target,
            targetId = self:getAimTargetId(action),
            weapon = weapon,
            isMinorAction = action.isMinorAction == true,
        }

        result.success = true
        result.aim = actor.pendingAim
        result.aimBonus = faceValue
        result.facedownAction = {
            actor = actor,
            type = "aim",
            card = card,
            value = faceValue,
            faceValue = faceValue,
            target = target,
            targetId = actor.pendingAim.targetId,
            weapon = weapon,
            isMinorAction = action.isMinorAction == true,
            replacedFacedownActions = result.replacedFacedownActions,
        }
        result.description = "Aiming at " .. (target and (target.name or target.id) or tostring(action.targetId)) ..
            " with bow. (+" .. tostring(faceValue) .. " to next bow Attack)"
        result.effects[#result.effects + 1] = "aim_prepared"
        result.effects[#result.effects + 1] = "bow_aim_prepared"

        self.eventBus:emit("aim_prepared", {
            entity = actor,
            target = target,
            targetId = actor.pendingAim.targetId,
            card = card,
            value = faceValue,
            weapon = weapon,
            isMinorAction = action.isMinorAction == true,
        })
    end

    function resolver:applyPendingAim(action, result, weapon)
        local actor = action and action.actor
        local aim = actor and actor.pendingAim
        if not aim then
            return nil
        end
        if action.useAim == false or action.revealAim == false then
            return nil
        end
        if not self:isBowAttackWeapon(weapon) then
            return nil
        end

        local targetId = self:getAimTargetId(action)
        if aim.targetId and targetId and tostring(aim.targetId) ~= tostring(targetId) then
            result.effects[#result.effects + 1] = "aim_target_mismatch"
            return nil
        end

        actor.pendingAim = nil
        local bonus = aim.value or aim.faceValue or (aim.card and aim.card.value) or 0
        result.modifier = (result.modifier or 0) + bonus
        result.testValue = (result.testValue or 0) + bonus
        result.aim = aim
        result.aimBonus = bonus
        result.aimCardDiscarded = self:discardFacedownCard(action, actor, aim.card)
        result.effects[#result.effects + 1] = "aim_revealed"
        result.effects[#result.effects + 1] = "aim_bonus"
        if result.aimCardDiscarded then
            result.effects[#result.effects + 1] = "aim_card_discarded"
        end
        appendResultSentence(result, "Aim +" .. tostring(bonus) .. ".")

        self.eventBus:emit("aim_revealed", {
            entity = actor,
            target = action.target,
            targetId = targetId,
            card = aim.card,
            value = bonus,
            discarded = result.aimCardDiscarded,
        })

        return aim
    end

    function resolver:getGramaryWand(action)
        if not action then
            return nil
        end

        if self:isArchwoodWand(action.weapon) then
            return action.weapon
        end

        local inv = action.actor and action.actor.inventory
        local weapon = inv and inv.getWieldedWeapon and inv:getWieldedWeapon()
        if self:isArchwoodWand(weapon) then
            return weapon
        end
        local hands = inv and inv.getItems and inv:getItems(inventory.LOCATIONS.HANDS) or {}
        for _, item in ipairs(hands or {}) do
            if self:isArchwoodWand(item) then
                return item
            end
        end

        return nil
    end

    function resolver:isActiveChallengeAction(action)
        if not action then
            return false
        end

        local controller = action.challengeController or self.challengeController
        if controller and controller.isActive then
            return controller:isActive() == true
        end

        return action.inChallenge == true or action.challenge == true
    end

    function resolver:isGramaryWandAttack(action)
        return action and
            self:normalizeActionType(action.type) == M.ACTION_TYPES.MISSILE and
            self:isActiveChallengeAction(action) and
            entityHasUsableTalent(action.actor, "gramarye") and
            self:getGramaryWand(action) ~= nil
    end

    function resolver:canUseDoomEye(action)
        local actor = action and action.actor
        if not entityHasUsableTalent(actor, "doom_eye") then
            return false, "Requires Doom Eye"
        end
        if self:normalizeActionType(action.type) ~= M.ACTION_TYPES.MISSILE then
            return false, "Doom Eye requires a missile Attack"
        end
        if not action.card or action.card.suit ~= constants.SUITS.SWORDS then
            return false, "Doom Eye requires a Sword card"
        end

        if not self:isActiveChallengeAction(action) then
            return false, "Doom Eye requires an active Challenge"
        end

        local weapon = self:getDoomEyeMissileWeapon(action)
        if not weapon then
            return false, "Doom Eye requires a missile weapon"
        end

        return true, nil, weapon
    end

    function resolver:applyMaledictionWeaponRust(action, result)
        local actor = action and action.actor
        local weapon = action and action.weapon
        if not actor or not actor.weaponRustMalediction or not weapon then
            return nil
        end

        local cardValue = action.card and action.card.value or result.cardValue or 0
        local threshold = actor.maledictionWeaponNotchThreshold or 10
        if cardValue < threshold then
            return nil
        end

        local inventory = require('logic.inventory')
        local capacity, material = self:getMaledictionWeaponRustCapacity(weapon)
        if capacity then
            weapon.durability = capacity
            weapon.properties = weapon.properties or {}
            weapon.properties.notchCapacity = capacity
            weapon.maledictionRustCapacity = capacity
            result.maledictionWeaponRust = {
                material = material,
                notchCapacity = capacity,
                threshold = threshold,
            }
        end
        weapon.notches = weapon.notches or 0
        weapon.durability = weapon.durability or 1
        local notchResult = inventory.addNotch(weapon)
        result.weaponNotchResult = notchResult
        result.effects[#result.effects + 1] = "malediction_weapon_notched"
        if notchResult == "destroyed" then
            result.effects[#result.effects + 1] = "weapon_destroyed"
        end
        return notchResult
    end

    function resolver:getMaledictionWeaponRustCapacity(weapon)
        local props = weapon and weapon.properties or {}
        local material = spell_registry.normalizeId(weapon and (weapon.material or weapon.substance or props.material or
            props.substance or props.weaponMaterial))
        local weaponType = spell_registry.normalizeId(weapon and (weapon.weaponType or weapon.type or weapon.itemType))

        if material == "wooden" then
            material = "wood"
        end

        if material == "wood" or props.wood == true or props.wooden == true or
           weaponType == "bow" or weaponType == "staff" then
            return 1, "wood"
        end
        if material == "iron" or props.iron == true then
            return 2, "iron"
        end
        if material == "steel" or props.steel == true then
            return 3, "steel"
        end

        return nil, material
    end

    function resolver:applyAttackAffliction(target, effect, action, result)
        if not target then
            return nil
        end

        local afflictionId = effect.affliction or effect.afflictionId or "affliction"
        target.afflictions = target.afflictions or {}
        local affliction = target.afflictions[afflictionId]
        if not affliction then
            affliction = {
                id = afflictionId,
                name = effect.afflictionName or (afflictionId == "face_rat_disease" and "Face Rat Disease") or afflictionId,
                source = effect.source or "greater_doom_attack",
                sourceId = action and action.actor and action.actor.id or nil,
                stage = 1,
                maxStage = 3,
                stageCosts = {
                    [1] = 1,
                    [2] = 1,
                    [3] = 2,
                },
                stages = {
                    {
                        id = "featureless_mask",
                        cureCharges = 1,
                        wandsInfluenceDisfavor = true,
                    },
                    {
                        id = "skin_over_nose_and_mouth",
                        cureCharges = 1,
                        condition = "silenced",
                    },
                    {
                        id = "skin_over_eyes",
                        cureCharges = 2,
                        condition = "blind",
                    },
                },
            }
            target.afflictions[afflictionId] = affliction
        else
            affliction.stage = math.max(affliction.stage or 1, 1)
        end

        if afflictionId == "face_rat_disease" then
            target.faceRatDisease = affliction
            target.faceRatDiseaseWandsDisfavor = true
        end

        result.attackAffliction = affliction
        result.effects[#result.effects + 1] = "attack_affliction"
        result.effects[#result.effects + 1] = afflictionId
        return affliction
    end

    function resolver:applyStealFaceAttack(target, effect, action, result)
        if not target then
            return nil
        end

        target.conditions = target.conditions or {}
        target.conditions.blind = effect.blind ~= false
        target.conditions.blinded = effect.blind ~= false
        target.conditions.silenced = effect.silence ~= false
        target.silenced = effect.silence ~= false
        target.faceStolen = true
        target.faceStolenBy = action and action.actor
        target.faceStolenById = action and action.actor and action.actor.id or nil

        local actor = action and action.actor
        if actor then
            actor.stolenFaces = actor.stolenFaces or {}
            actor.stolenFaces[#actor.stolenFaces + 1] = {
                victim = target,
                victimId = target.id,
                victimName = target.name,
                permanent = effect.copiesFacePermanently ~= false,
            }
            actor.currentFace = target.name or target.id
        end

        if effect.replacesWound ~= false then
            result.damageDealt = 0
            result.effects[#result.effects + 1] = "wound_replaced"
        end
        result.stealFace = {
            actor = actor,
            target = target,
            blind = effect.blind ~= false,
            silence = effect.silence ~= false,
        }
        result.effects[#result.effects + 1] = "steal_face"
        result.effects[#result.effects + 1] = "blind"
        result.effects[#result.effects + 1] = "silenced"
        return result.stealFace
    end

    function resolver:getActionLesserDoomEffect(action)
        local doom = action and (action.lesserDoom or action.attackDoom)
        if not doom then
            return nil, nil
        end
        return doom.effect or {}, doom
    end

    function resolver:applyAttackConditionChoice(target, effect, action, result, doom)
        local choice = action.lesserDoomChoice or action.doomChoice or action.conditionChoice or
            action.greaterDoomChoice or action.choice or effect.choice or effect.defaultChoice or
            (effect.choices and effect.choices[1])
        choice = self:normalizeRoughhouseEffect(choice)
        local lionBite = doom and doom.id == "bite" and entityHasNormalizedTag(action.actor, "lion")
        local dragonBite = doom and doom.id == "overwhelming_bite" and self:isDragon(action.actor)

        result.attackConditionChoice = choice
        result.effects[#result.effects + 1] = "attack_condition_choice"
        if lionBite then
            result.effects[#result.effects + 1] = "lion_bite"
        elseif dragonBite then
            result.effects[#result.effects + 1] = "dragon_overwhelming_bite"
        elseif doom and doom.id == "bite" and self:isBeast(action.actor) then
            result.effects[#result.effects + 1] = "beast_bite"
        end

        if choice == "disarmed" or choice == "disarm" then
            local droppedItem = nil
            local requestedItemId = action.disarmItemId or action.disarmedItemId or action.droppedItemId or
                action.targetHeldItemId
            if target.inventory and target.inventory.getItems then
                local handsItems = target.inventory:getItems(inventory.LOCATIONS.HANDS) or {}
                if requestedItemId then
                    for _, item in ipairs(handsItems) do
                        if tostring(item.id) == tostring(requestedItemId) then
                            droppedItem = item
                            break
                        end
                    end
                else
                    droppedItem = handsItems[1]
                end
            elseif target.weapon and (not requestedItemId or tostring(target.weapon.id) == tostring(requestedItemId)) then
                droppedItem = target.weapon
            end

            if requestedItemId and not droppedItem then
                result.effects[#result.effects + 1] = "disarm_item_not_held"
                result.description = result.description .. (doom and doom.name or "Attack") ..
                    " cannot disarm the selected item because the target is not holding it. "
            elseif droppedItem then
                droppedItem = self:dropCarriedItem(target, droppedItem, "attack_condition_choice", action)
                target.conditions = target.conditions or {}
                target.conditions.disarmed = true
                result.droppedItem = droppedItem
                result.effects[#result.effects + 1] = "disarmed"
                result.effects[#result.effects + 1] = "attack_disarm"
                if lionBite then
                    result.effects[#result.effects + 1] = "lion_bite_disarm"
                elseif dragonBite then
                    result.effects[#result.effects + 1] = "dragon_overwhelming_bite_disarm"
                elseif doom and doom.id == "bite" and self:isBeast(action.actor) then
                    result.effects[#result.effects + 1] = "beast_bite_disarm"
                end
                result.description = result.description .. (doom and doom.name or "Attack") ..
                    " disarms [" .. (droppedItem.name or "item") .. "]! "
            else
                result.effects[#result.effects + 1] = "disarm_no_item"
                result.description = result.description .. (doom and doom.name or "Attack") ..
                    " tries to disarm, but the target holds nothing. "
            end
        elseif choice == "tripped" or choice == "trip" then
            target.conditions = target.conditions or {}
            target.conditions.prone = true
            self:clearAllEngagements(target, action.allEntities)
            result.effects[#result.effects + 1] = "prone"
            result.effects[#result.effects + 1] = "attack_trip"
            if lionBite then
                result.effects[#result.effects + 1] = "lion_bite_trip"
            elseif dragonBite then
                result.effects[#result.effects + 1] = "dragon_overwhelming_bite_trip"
            elseif doom and doom.id == "bite" and self:isBeast(action.actor) then
                result.effects[#result.effects + 1] = "beast_bite_trip"
            end
            result.description = result.description .. (doom and doom.name or "Attack") .. " trips the target! "
        end
    end

    function resolver:applyDoubleInitiativeAttackBonus(target, effect, action, result, doom)
        local targetInitiative = result.difficulty or self:getTargetInitiative(target, action) or 0
        if targetInitiative <= 0 then
            return
        end
        if (result.testValue or 0) < targetInitiative * 2 then
            return
        end

        local previousDamage = result.damageDealt or 0
        result.damageDealt = math.max(previousDamage, effect.wounds or 2)
        result.doubleInitiativeAttackBonus = {
            previousDamage = previousDamage,
            damageDealt = result.damageDealt,
            targetInitiative = targetInitiative,
            attackValue = result.testValue,
        }
        result.effects[#result.effects + 1] = "double_initiative_attack_bonus"
        if doom and doom.id == "claw" and entityHasNormalizedTag(action.actor, "lion") then
            result.effects[#result.effects + 1] = "lion_claw_double_initiative"
        elseif doom and doom.id == "claw" and self:isDragon(action.actor) then
            result.effects[#result.effects + 1] = "dragon_claw_double_initiative"
        elseif doom and doom.id == "claw" and self:isBeast(action.actor) then
            result.effects[#result.effects + 1] = "beast_claw_double_initiative"
        end
        if result.damageDealt > previousDamage then
            result.effects[#result.effects + 1] = "damage_increased"
            result.description = result.description .. (doom and doom.name or "Attack") ..
                " lands with overwhelming force! "
        end
    end

    function resolver:applyBruteDeadlyAttack(target, effect, action, result, doom)
        if not (self:isBrute(action and action.actor) or effect.bruteTemplate == true) then
            return false
        end

        local previousDamage = result.damageDealt or 0
        result.damageDealt = math.max(previousDamage, effect.wounds or 2)
        result.effects[#result.effects + 1] = "brute_deadly_attack"
        if result.damageDealt > previousDamage then
            result.effects[#result.effects + 1] = "damage_increased"
        end
        result.description = result.description .. (doom and doom.name or "Deadly Attack") ..
            " makes the hit deal " .. tostring(result.damageDealt) .. " Wound(s). "
        return true
    end

    function resolver:getBruteCorrosiveAttackItem(action, target)
        if action and action.targetItem then
            return action.targetItem
        end
        if action and action.corrosiveItem then
            return action.corrosiveItem
        end
        return self:getRoughhouseNotchItem(action)
    end

    function resolver:destroyBruteCorrosiveAttackItem(target, item, result, action)
        if not item then
            return false
        end

        item.destroyed = true
        item.broken = true
        item.notches = math.max(item.notches or 0, item.durability or 1)
        item.properties = item.properties or {}
        item.properties.destroyed = true
        item.properties.broken = true
        item.destroyedBy = action and action.actor
        item.destroyedById = action and action.actor and action.actor.id or nil
        item.destroyedByReason = "brute_corrosive_attack"

        result.destroyedItem = item
        result.effects[#result.effects + 1] = "item_destroyed"
        self.eventBus:emit(events.EVENTS.INVENTORY_CHANGED, {
            entity = target,
            item = item,
            reason = "brute_corrosive_attack",
        })
        return true
    end

    function resolver:applyBruteCorrosiveAttack(target, effect, action, result, doom)
        if not (self:isBrute(action and action.actor) or effect.bruteTemplate == true) then
            return false
        end

        result.damageDealt = 0
        result.effects[#result.effects + 1] = "brute_corrosive_attack"
        result.effects[#result.effects + 1] = "wound_replaced"

        local item = self:getBruteCorrosiveAttackItem(action, target)
        if self:destroyBruteCorrosiveAttackItem(target, item, result, action) then
            result.description = result.description .. (doom and doom.name or "Corrosive Attack") ..
                " destroys " .. (item.name or "an item") .. " instead of wounding. "
        else
            result.effects[#result.effects + 1] = "brute_corrosive_attack_no_item"
            result.description = result.description .. (doom and doom.name or "Corrosive Attack") ..
                " finds no item to destroy. "
        end
        return true
    end

    function resolver:applyAttackLesserDoom(action, result, target)
        local effect, doom = self:getActionLesserDoomEffect(action)
        if not target then
            return
        end
        if not effect and not self:isImpVomitAttack(action) then
            return
        end

        if effect and effect.type == "attack_plus_condition_choice" then
            self:applyAttackConditionChoice(target, effect, action, result, doom)
        elseif effect and effect.type == "attack_double_initiative_bonus" then
            self:applyDoubleInitiativeAttackBonus(target, effect, action, result, doom)
        elseif effect and effect.type == "attack_wound_and_displace" then
            self:applyCockatriceTailBite(action, result, target, effect, doom)
        elseif effect and effect.type == "throw_heavy_object" then
            self:applyAnimateStatueThrowStones(action, result, effect, doom)
            self:applyTitanThrowStones(action, result, effect, doom)
        elseif effect and effect.type == "melee_attack" and effect.damageType == "piercing" then
            result.effects[#result.effects + 1] = "piercing"
            if self:isYellowKingLich(action.actor) and doom and doom.id == "death_dealer" then
                result.effects[#result.effects + 1] = "yellow_king_death_dealer"
            end
        elseif effect and effect.type == "ranged_arcane_attack" then
            result.effects[#result.effects + 1] = "yellow_king_arcane_attack"
            result.effects[#result.effects + 1] = "arcane_energy"
            result.effects[#result.effects + 1] = "magic"
        elseif self:isImpVomitAttack(action) then
            self:applyImpVomitAttack(action, result, target, doom)
        end
    end

    function resolver:applyDragonBreathOfFire(action, result, target, effect, doom)
        local actor = action and action.actor
        if not (self:isDragon(actor) and target) then
            return false
        end

        result.effects[#result.effects + 1] = "dragon_breath_of_fire"
        result.effects[#result.effects + 1] = "fire"

        local rangeZones = effect.rangeZones or 1
        local distance, err = self:getZoneDistance(action, actor.zone, target.zone)
        if err or (distance and distance > rangeZones) then
            result.success = false
            result.damageDealt = 0
            result.description = result.description .. (doom and doom.name or "Breath of Fire") ..
                " cannot reach the target. "
            result.effects[#result.effects + 1] = "dragon_breath_of_fire_out_of_range"
            return true
        end

        if self:doesElementProtectionBlock(target, "fire") then
            result.damageDealt = 0
            result.effects[#result.effects + 1] = "element_protection_blocked"
            result.effects[#result.effects + 1] = "protection_from_elements_fire_block"
            result.description = result.description .. (doom and doom.name or "Breath of Fire") ..
                " is blocked by elemental protection. "
            return true
        end

        if self:targetWearsMetalArmor(target) then
            result.damageDealt = math.max(result.damageDealt or 0, 1)
            result.effects[#result.effects + 1] = effect.metalArmorDamageType or "critical"
            result.effects[#result.effects + 1] = "dragon_breath_metal_armor"
            result.description = result.description .. (doom and doom.name or "Breath of Fire") ..
                " superheats metal armor. "
        else
            result.damageDealt = math.max(result.damageDealt or 0, effect.unarmoredWounds or 3)
            result.effects[#result.effects + 1] = "dragon_breath_unarmored"
            result.description = result.description .. (doom and doom.name or "Breath of Fire") ..
                " engulfs the target in flame. "
        end

        return true
    end

    function resolver:applyAttackGreaterDoom(action, result, target)
        local doom = action.greaterDoom
        if not doom or not target then
            return
        end

        local effect = doom.effect or {}
        result.effects[#result.effects + 1] = "greater_doom"
        result.greaterDoom = {
            name = doom.name,
            card = action.greaterDoomCard,
        }

        if effect.type == "web" then
            target.conditions = target.conditions or {}
            target.conditions.webbed = true
            self:applyRooted(target, { action = action, reason = "web" })
            target.webbedLimbs = math.max(target.webbedLimbs or 0, effect.limbs or 4)

            result.effects[#result.effects + 1] = "webbed"
            result.effects[#result.effects + 1] = "rooted"
            result.description = result.description .. (doom.name or "Greater doom") .. "! Target is webbed and rooted. "

            if effect.suppressDamage or effect.noDamage then
                result.damageDealt = 0
            end
        elseif effect.type == "attack_affliction" then
            self:applyAttackAffliction(target, effect, action, result)
            result.description = result.description .. (doom.name or "Greater doom") .. "! Target contracts " ..
                tostring(effect.afflictionName or effect.affliction or "an affliction") .. ". "
        elseif effect.type == "attack_blind_and_silence" then
            self:applyStealFaceAttack(target, effect, action, result)
            result.description = result.description .. (doom.name or "Greater doom") ..
                "! Target is Blinded and Silenced instead of wounded. "
        elseif effect.type == "brute_deadly_attack" or effect.type == "deadly_attack" or
            effect.type == "attack_deals_two_wounds" then
            self:applyBruteDeadlyAttack(target, effect, action, result, doom)
        elseif effect.type == "brute_corrosive_attack" or effect.type == "corrosive_attack" or
            effect.type == "destroy_item_instead_of_damage" then
            self:applyBruteCorrosiveAttack(target, effect, action, result, doom)
        elseif effect.type == "attack_piercing" then
            result.effects[#result.effects + 1] = "piercing"
            if doom.id == "riot_of_teeth" or entityHasNormalizedTag(action.actor, "mimic") then
                result.effects[#result.effects + 1] = "mimic_riot_of_teeth"
            end
            result.description = result.description .. (doom.name or "Greater doom") ..
                "! Attack deals Piercing damage. "
        elseif effect.type == "attack_xp_drain" then
            self:drainWraithXP(action.actor, target, effect.xpLost or 1, result)
            result.description = result.description .. (doom.name or "Greater doom") ..
                "! Target loses " .. tostring(effect.xpLost or 1) .. " XP. "
        elseif effect.type == "elite_command" or
            (effect.type == "attack_control_command" and self:isElite(action.actor) and
                (doom.id == "command" or effect.eliteTemplate == true)) then
            self:applyEliteCommandAttack(target, effect, action, result, doom)
            result.description = result.description .. (doom.name or "Greater doom") ..
                "! Target is Controlled into an immediate command. "
        elseif effect.type == "attack_control_command" then
            self:applyJinnPossessAttack(target, effect, action, result, doom)
            result.description = result.description .. (doom.name or "Greater doom") ..
                "! Target is Controlled into an immediate command. "
        elseif effect.type == "mesmerize_on_attack" then
            self:applyVampireMesmerizeAttack(target, effect, action, result, doom)
            result.description = result.description .. (doom.name or "Greater doom") ..
                "! Target is Mesmerized instead of wounded. "
        elseif effect.type == "attack_control_task" then
            self:applyYellowKingEnchantAttack(target, effect, action, result, doom)
            result.description = result.description .. (doom.name or "Greater doom") ..
                "! Target is Controlled into an irrational task. "
        elseif effect.type == "attack_fire_breath" then
            self:applyDragonBreathOfFire(action, result, target, effect, doom)
        elseif effect.type == "greater_doom_attack_action" then
            if self:isDragon(action.actor) and doom.id == "overwhelming_bite" then
                result.effects[#result.effects + 1] = "dragon_overwhelming_bite"
            end
            if self:isTitanSporehulk(action.actor) and doom.id == "smash" then
                result.effects[#result.effects + 1] = "titan_sporehulk_smash"
            end
            if effect.choices then
                self:applyAttackConditionChoice(target, effect, action, result, doom)
            end
            result.description = result.description .. (doom.name or "Greater doom") .. "! "
        else
            result.description = result.description .. (doom.name or "Greater doom") .. "! "
        end
    end

    function resolver:getZoneAttackTargetInitiative(action, target)
        local initiatives = action and (action.targetInitiatives or action.zoneTargetInitiatives)
        if initiatives and target then
            return initiatives[target.id] or initiatives[target.name] or initiatives[target]
        end
        return target and (target.targetInitiative or target.initiative) or action.zoneTargetInitiative
    end

    function resolver:resolveZoneAttackFollowUps(action, result)
        if not action or action.zoneAttackFollowUp then
            return false
        end
        local actor = action.actor
        local effect, doom = self:getActionLesserDoomEffect(action)
        if not (actor and effect and
           (effect.type == "zone_attack" or effect.type == "attack_all_adventurers_in_zone" or
            effect.type == "attack_all_in_zone")) then
            return false
        end

        local actorZone = action.zone or actor.zone
        local candidates = action.targets or action.allEntities or {}
        local followResults = {}
        for _, candidate in ipairs(candidates) do
            local conditions = candidate.conditions or {}
            local sameZone = candidate.zone == actorZone
            local eligible = candidate ~= actor and candidate ~= action.target and candidate.isPC == true and
                sameZone and not conditions.dead and not conditions.deaths_door
            if eligible then
                local followAction = {
                    actor = actor,
                    target = candidate,
                    card = action.card,
                    type = action.normalizedType or action.type or M.ACTION_TYPES.MELEE,
                    weapon = action.weapon,
                    targetInitiative = self:getZoneAttackTargetInitiative(action, candidate),
                    allEntities = action.allEntities,
                    challengeController = action.challengeController,
                    playerDeck = action.playerDeck,
                    gmDeck = action.gmDeck,
                    playerHand = action.playerHand,
                    npcAI = action.npcAI,
                    zoneAttackFollowUp = true,
                }
                followResults[#followResults + 1] = {
                    target = candidate,
                    result = self:resolve(followAction),
                }
            end
        end

        if #followResults == 0 then
            return false
        end

        result.zoneAttackResults = followResults
        result.effects[#result.effects + 1] = "zone_attack"
        if self:isOgre(actor) and doom and doom.id == "sweeping_club" then
            result.effects[#result.effects + 1] = "ogre_sweeping_club"
        end
        if self:isAnimateStatue(actor) and doom and doom.id == "haymaker" then
            result.effects[#result.effects + 1] = "animate_statue_haymaker"
        end
        if self:isDragon(actor) and doom and doom.id == "tail_whip" then
            result.effects[#result.effects + 1] = "dragon_tail_whip"
        end
        if self:isTitanSporehulk(actor) and doom and doom.id == "kick" then
            result.effects[#result.effects + 1] = "titan_sporehulk_kick"
        end
        result.description = (result.description or "") .. " " .. (doom and doom.name or "Zone attack") ..
            " sweeps through " .. tostring(#followResults) .. " additional target(s)."
        return true
    end

    --- Resolve melee attack
    function resolver:resolveMelee(action, result)
        local target = action.target

        -- S7.1: Apply any active aids to this attack
        self:applyActiveAids(action.actor, result, action)

        -- S12.7: Apply Mob Rule bonuses (swarm attack bonuses)
        if action.mobRuleBonus then
            local mobBonus = action.mobRuleBonus
            if mobBonus.favor then
                result.effects[#result.effects + 1] = "mob_favor"
            end
            if mobBonus.piercing then
                result.effects[#result.effects + 1] = "piercing"
                result.effects[#result.effects + 1] = "mob_piercing"
            end
            if mobBonus.critical then
                result.effects[#result.effects + 1] = "critical"
                result.effects[#result.effects + 1] = "mob_critical"
            end
        end

        if not self:resolveReaverCharge(action, result) then
            return
        end
        if not self:validateTitanMeleeTargeting(action, result) then
            return
        end

        local attackValue = result.testValue
        local baseInitiative = result.difficulty
        local defenderHasShield = target and self:entityHasShield(target)
        local targetRequiresExceed = self:targetRequiresExceedInitiative(target, action)

        -- Check engagement (must be in same zone as target)
        if self.zoneSystem and target then
            local actorZone = action.actor.zone
            local targetZone = target.zone

            if actorZone ~= targetZone and not self:isDragonFlyByAttack(action) then
                result.success = false
                result.description = "Target is not engaged (different zone)"
                result.effects[#result.effects + 1] = "not_engaged"
                return
            elseif actorZone ~= targetZone then
                result.effects[#result.effects + 1] = "dragon_fly_by_reach"
            end
        end

        if self:isYellowKingAloft(target) then
            result.success = false
            result.description = "The Yellow King hovers beyond melee reach."
            result.effects[#result.effects + 1] = "yellow_king_spite_alone"
            result.effects[#result.effects + 1] = "only_ranged_attacks_can_hit"
            return
        end

        if self:isHarpyOutOfMeleeReach(target) then
            result.success = false
            result.description = "The flying harpy circles beyond melee reach."
            result.effects[#result.effects + 1] = "harpy_flight"
            result.effects[#result.effects + 1] = "only_ranged_attacks_can_hit"
            return
        end

        self:breakLightSourceWeaponIfNeeded(action, result)
        self:applyPactItemObligations(action, result, self:getActionWeapon(action), "weapon_attack")

        -- S4.9: Check for and handle defensive actions
        local riposteTriggered = false
        local riposteDefense = nil

        local defense = self:consumeIncomingDefense(action, target, result)
        if defense then
            if defense.guardianAngel then
                result.effects[#result.effects + 1] = "guardian_angel_used"
            end
            if defense.source == "ally" then
                result.effects[#result.effects + 1] = "ally_defense_used"
            end
            if defense.type == "dodge" then
                -- Dodge: add card value to Initiative; if higher than attack value, miss
                local dodgeValue = defense.value or 0
                local newInitiative = baseInitiative + dodgeValue
                result.effects[#result.effects + 1] = "dodge_used"

                if newInitiative > attackValue then
                    result.success = false
                    result.description = "Dodged! "
                    result.effects[#result.effects + 1] = "dodged"
                    if not self:redirectMissedAttackToAnimateStatueGrabbedTarget(action, result) then
                        if not self:redirectMissedAttackToTitanGrabbedTarget(action, result) then
                            if not self:redirectMissedAttackToGrabbedVictim(action, result) then
                                self:redirectMissedAttackToDevilBiteVictim(action, result)
                            end
                        end
                    end
                    return
                else
                    result.effects[#result.effects + 1] = "dodge_failed"
                end
            elseif defense.type == "riposte" then
                local handled, stopped = self:resolvePolearmRiposteInterrupt(action, result, defense, attackValue, target)
                if stopped then
                    return
                end
                if not handled then
                    -- Riposte: will counter-attack after resolution
                    riposteTriggered = true
                    riposteDefense = defense
                    result.effects[#result.effects + 1] = "riposte_ready"
                end
            end
        end

        -- Resolve hit against Initiative (ties go to attacker unless defender has shield)
        result.success = (attackValue > baseInitiative) or
                         (attackValue == baseInitiative and not defenderHasShield and not targetRequiresExceed)
        if targetRequiresExceed and attackValue == baseInitiative then
            result.effects[#result.effects + 1] = self:getExceedInitiativeEffect(target, action)
        end

        -- S7.6: Flail specialization - ties count as success
        if not result.success and not targetRequiresExceed and action.weapon and M.isWeaponType(action.weapon, "FLAIL") then
            if attackValue == baseInitiative then
                result.success = true
                result.description = "Flail tie-breaker! "
                result.effects[#result.effects + 1] = "flail_tie"
            end
        end

        if result.success then
            result.damageDealt = 1
            result.description = (result.description or "") .. "Hit! "
            if self:breakTargetLightSourceHitInCombat(action, result) then
                result.damageDealt = 0
                result.description = result.description .. "Light source breaks and goes out! "
            end

            -- S6.3: Form engagement on successful melee attack
            if target and action.actor then
                if self:isDragonFlyByAttack(action) then
                    action.actor.dragonFlight = action.actor.dragonFlight or {}
                    action.actor.dragonFlight.flyByAttackThisTurn = true
                    action.actor.dragonMeleeTargetableThisTurn = true
                    result.effects[#result.effects + 1] = "dragon_fly_by_attack"
                    result.effects[#result.effects + 1] = "melee_no_engagement"
                elseif self:isHarpyFlyByAttack(action) then
                    action.actor.harpyFlight = action.actor.harpyFlight or {}
                    action.actor.harpyFlight.flyByAttackThisTurn = true
                    action.actor.harpyMeleeTargetableThisTurn = true
                    result.effects[#result.effects + 1] = "harpy_fly_by_attack"
                    result.effects[#result.effects + 1] = "melee_no_engagement"
                elseif self:isThrownDaggerAttack(action) then
                    result.effects[#result.effects + 1] = "thrown_dagger"
                    result.effects[#result.effects + 1] = "melee_no_engagement"
                else
                    self:formEngagement(action.actor, target)
                end
            end

            -- S7.6: Hammer/Mace specialization - double damage on overwhelming hit
            if action.weapon and M.isWeaponType(action.weapon, "HAMMER") then
                if result.testValue >= (result.difficulty * 2) then
                    result.damageDealt = 2
                    result.description = result.description .. "Crushing blow! "
                    result.effects[#result.effects + 1] = "hammer_crush"
                end
            end

            -- S7.6: Dagger specialization - piercing vs vulnerable targets
            if action.weapon and M.isWeaponType(action.weapon, "DAGGER") then
                if target then
                    local targetConditions = target.conditions or {}
                    if targetConditions.rooted or targetConditions.prone or targetConditions.disarmed or
                       self:entityLacksMeleeWeaponAndShield(target) then
                        result.effects[#result.effects + 1] = "piercing"
                        result.description = result.description .. "Exploits vulnerability! "
                    end
                end
            end

            self:applyAttackLesserDoom(action, result, target)
            self:applyAttackGreaterDoom(action, result, target)
            self:applyAmbusherDamageBonus(action, result)

            if self:isUnarmedAdventurerAttackingLargerTarget(action) then
                result.damageDealt = 0
                result.effects[#result.effects + 1] = "unarmed_no_damage_larger_target"
                result.description = result.description .. "Bare fists cannot harm the larger creature. "
            end

            self:applyCharmTrustedFriendFightRider(action, result)

            -- Apply damage to target (with weapon for cleave check)
            if target and result.damageDealt > 0 then
                local vampireFeedBefore = self:snapshotVampireFeedTarget(target)
                local damageResult = self:applyDamage(target, result.damageDealt, result.effects, action.weapon, action.allEntities,
                    self:getActionWoundOptions(action, target), {
                        source = "attack",
                        action = action,
                        result = result,
                        attackValue = attackValue,
                        useAegis = action.useAegis,
                        promptWoundChoice = action.promptWoundChoice,
                    })
                if damageResult and damageResult.prevented and damageResult.shield then
                    result.aegisResult = damageResult
                elseif damageResult and damageResult.pendingWoundChoice then
                    result.pendingWoundChoice = damageResult
                end
                self:applyVampireFeedAfterAttack(action, result, target, vampireFeedBefore)
            end
            self:applyFungoidBrainSpores(action, result, target)
        else
            result.description = "Miss!"
            if not self:redirectMissedAttackToAnimateStatueGrabbedTarget(action, result) then
                if not self:redirectMissedAttackToTitanGrabbedTarget(action, result) then
                    if not self:redirectMissedAttackToGrabbedVictim(action, result) then
                        self:redirectMissedAttackToDevilBiteVictim(action, result)
                    end
                end
            end
            if action.greaterDoom then
                result.description = result.description .. " " .. (action.greaterDoom.name or "Greater doom") .. " wasted."
                result.effects[#result.effects + 1] = "greater_doom_wasted"
            end
            self:resolveSecondAttackAfterMiss(action, result)
        end

        self:resolveZoneAttackFollowUps(action, result)
        self:applyMaledictionWeaponRust(action, result)

        -- S4.9: Resolve Riposte counter-attack
        if riposteTriggered and riposteDefense and target then
            local riposteResult = self:resolveRiposte(target, action.actor, riposteDefense, attackValue)
            result.riposteResult = riposteResult
            result.description = result.description .. " Riposte! "
            if riposteResult.success then
                result.description = result.description .. "Counter-attack hits!"
            else
                result.description = result.description .. "Counter-attack misses."
            end
        end
    end

    function resolver:getMissileAmmoType(weapon)
        if weapon and weapon.ammoType then
            return weapon.ammoType
        end
        if weapon and M.isWeaponType(weapon, "CROSSBOW") then
            return "bolt"
        end
        if weapon and M.isWeaponType(weapon, "BOW") then
            return "arrow"
        end
        return "ammo"
    end

    function resolver:hasTypedAmmunition(actor)
        return type(actor and actor.ammunition) == "table"
    end

    function resolver:getMissileAmmoCount(actor, ammoType)
        if not actor then
            return 0
        end
        if self:hasTypedAmmunition(actor) and ammoType then
            return math.max(0, math.floor(tonumber(actor.ammunition[ammoType]) or 0))
        end
        return math.max(0, math.floor(tonumber(actor.ammo) or 0))
    end

    function resolver:setMissileAmmoCount(actor, ammoType, count)
        if not actor then
            return 0
        end
        count = math.max(0, math.floor(tonumber(count) or 0))
        if self:hasTypedAmmunition(actor) and ammoType then
            actor.ammunition[ammoType] = count
        end
        actor.ammo = count
        return count
    end

    function resolver:spendMissileAmmo(actor, ammoType)
        local ammo = self:getMissileAmmoCount(actor, ammoType)
        if ammo <= 0 then
            return false, ammo
        end
        self:setMissileAmmoCount(actor, ammoType, ammo - 1)
        return true, ammo - 1
    end

    function resolver:recordMissileAmmoOutcome(actor, weapon, result)
        if not actor or not weapon or not weapon.uses_ammo then
            return nil
        end

        local ammoType = self:getMissileAmmoType(weapon)
        local outcome = {
            type = ammoType,
            destroyed = result.success == true,
            recoverable = result.success ~= true,
        }
        result.ammoOutcome = outcome

        if outcome.destroyed then
            result.effects[#result.effects + 1] = "ammo_destroyed"
        else
            actor.recoverableAmmo = (actor.recoverableAmmo or 0) + 1
            actor.recoverableAmmunition = actor.recoverableAmmunition or {}
            actor.recoverableAmmunition[ammoType] = (actor.recoverableAmmunition[ammoType] or 0) + 1
            result.effects[#result.effects + 1] = "ammo_recoverable"
        end

        return outcome
    end

    function resolver:recoverMissileAmmunition(actor, ammoType)
        if not actor then
            return 0
        end

        local recovered = 0
        local recoveredByType = {}
        local recoverable = actor.recoverableAmmunition
        if type(recoverable) == "table" then
            if ammoType then
                recovered = recoverable[ammoType] or 0
                recoveredByType[ammoType] = recovered
                recoverable[ammoType] = nil
            else
                for key, count in pairs(recoverable) do
                    local typedRecovered = tonumber(count) or 0
                    recovered = recovered + typedRecovered
                    recoveredByType[key] = typedRecovered
                    recoverable[key] = nil
                end
            end
        else
            recovered = actor.recoverableAmmo or 0
        end

        if recovered > 0 then
            if self:hasTypedAmmunition(actor) and next(recoveredByType) then
                for key, count in pairs(recoveredByType) do
                    actor.ammunition[key] = (actor.ammunition[key] or 0) + count
                end
                if ammoType then
                    actor.ammo = actor.ammunition[ammoType] or 0
                else
                    actor.ammo = (actor.ammo or 0) + recovered
                end
            else
                actor.ammo = (actor.ammo or 0) + recovered
            end
        end

        actor.recoverableAmmo = 0
        return recovered
    end

    --- Resolve missile attack
    function resolver:resolveMissile(action, result)
        -- S7.1: Apply any active aids to this attack
        self:applyActiveAids(action.actor, result, action)

        if not self:resolveReaverCharge(action, result) then
            return
        end

        -- Engaged combatants cannot bring missile weapons to bear.
        if action.actor.is_engaged and not self:isDragonBreathOfFireAction(action) and
           not self:isYellowKingArcaneAttack(action) then
            result.success = false
            result.description = "Cannot use ranged weapons while engaged."
            result.effects[#result.effects + 1] = "engaged_ranged_blocked"
            return
        end

        local attackValue = result.testValue
        local baseInitiative = result.difficulty
        local target = action.target
        local defenderHasShield = target and self:entityHasShield(target)
        local targetRequiresExceed = self:targetRequiresExceedInitiative(target, action)
        local dodged = false
        local riposteTriggered = false
        local riposteDefense = nil
        local doomEyeActive = false
        local gramaryWandAttack = self:isGramaryWandAttack(action)
        local harpyStoneAttack = self:isHarpyStoneMissileAttack(action)

        if gramaryWandAttack then
            action.weapon = action.weapon or self:getGramaryWand(action)
            result.effects[#result.effects + 1] = "gramary_wand_attack"
            result.effects[#result.effects + 1] = "gramary_wands_action"
        end

        if self:isYellowKingArcaneAttack(action) then
            if not self:validateYellowKingArcaneAttack(action, result) then
                return
            end
            attackValue = result.testValue
        end

        if harpyStoneAttack and not self:prepareHarpyStoneMissileAttack(action, result) then
            return
        end

        if self:wantsDoomEye(action) then
            local canUseDoomEye, doomEyeReason, doomEyeWeapon = self:canUseDoomEye(action)
            if not canUseDoomEye then
                result.success = false
                result.description = doomEyeReason
                result.effects[#result.effects + 1] = "doom_eye_blocked"
                return
            end

            doomEyeActive = true
            action.weapon = action.weapon or doomEyeWeapon
            result.doomEyeAutoHit = true
            result.effects[#result.effects + 1] = "doom_eye_auto_hit"
        end

        local actionWeapon = self:getActionWeapon(action)
        if actionWeapon and not action.weapon then
            action.weapon = actionWeapon
        end
        local actionAmmoType = actionWeapon and self:getMissileAmmoType(actionWeapon)
        local hasAmmoForAimReveal = not (actionWeapon and actionWeapon.uses_ammo and
            self:getMissileAmmoCount(action.actor, actionAmmoType) <= 0)
        if hasAmmoForAimReveal then
            self:applyPendingAim(action, result, actionWeapon)
        end
        attackValue = result.testValue

        self:applyPactItemObligations(action, result, actionWeapon, "weapon_attack")

        -- Dodge can negate missile attacks
        local defense = self:consumeIncomingDefense(action, target, result)
        if defense then
            if defense.guardianAngel then
                result.effects[#result.effects + 1] = "guardian_angel_used"
            end
            if defense.source == "ally" then
                result.effects[#result.effects + 1] = "ally_defense_used"
            end
            if defense.type == "dodge" then
                local dodgeValue = defense.value or 0
                local newInitiative = baseInitiative + dodgeValue
                result.effects[#result.effects + 1] = "dodge_used"

                if newInitiative > attackValue and not doomEyeActive then
                    dodged = true
                    result.success = false
                    result.description = "Dodged! "
                    result.effects[#result.effects + 1] = "dodged"
                elseif newInitiative > attackValue and doomEyeActive then
                    result.effects[#result.effects + 1] = "dodge_failed"
                    result.effects[#result.effects + 1] = "doom_eye_ignores_dodge"
                else
                    result.effects[#result.effects + 1] = "dodge_failed"
                end
            elseif defense.type == "riposte" then
                riposteTriggered = true
                riposteDefense = defense
                result.effects[#result.effects + 1] = "riposte_ready"
            end
        end

        if doomEyeActive then
            result.success = true
            result.effects[#result.effects + 1] = "doom_eye_ignores_initiative"
        elseif not dodged then
            -- Resolve hit against Initiative (ties go to attacker unless defender has shield)
            result.success = (attackValue > baseInitiative) or
                             (attackValue == baseInitiative and not defenderHasShield and not targetRequiresExceed)
            if targetRequiresExceed and attackValue == baseInitiative then
                result.effects[#result.effects + 1] = self:getExceedInitiativeEffect(target, action)
            end
        end

        -- S7.8: Crossbow must be loaded
        if action.weapon and M.isWeaponType(action.weapon, "CROSSBOW") then
            if not action.weapon.isLoaded then
                result.success = false
                result.description = (result.description or "") .. "Reload required!"
                result.effects[#result.effects + 1] = "not_loaded"
                return
            end
        end

        -- Check ammo
        if action.weapon and action.weapon.uses_ammo then
            local ammoType = self:getMissileAmmoType(action.weapon)
            local ammo = self:getMissileAmmoCount(action.actor, ammoType)
            if ammo <= 0 then
                result.success = false
                result.description = "Out of ammo!"
                result.effects[#result.effects + 1] = "no_ammo"
                return
            end

            -- Consume ammo
            self:spendMissileAmmo(action.actor, ammoType)
            result.effects[#result.effects + 1] = "ammo_used"
            self:recordMissileAmmoOutcome(action.actor, action.weapon, result)
        end

        -- Missile bypasses engagement - no zone check needed

        -- S7.8: Unload crossbow after firing
        if action.weapon and M.isWeaponType(action.weapon, "CROSSBOW") then
            action.weapon.isLoaded = false
            result.effects[#result.effects + 1] = "crossbow_fired"
        end

        if result.success then
            result.damageDealt = 1
            result.description = (result.description or "") .. "Hit! "
            if self:breakTargetLightSourceHitInCombat(action, result) then
                result.damageDealt = 0
                result.description = result.description .. "Light source breaks and goes out! "
            end
            if action.weapon and M.isWeaponType(action.weapon, "CROSSBOW") then
                result.effects[#result.effects + 1] = "piercing"
                result.effects[#result.effects + 1] = "crossbow_piercing"
            end

            self:applyAttackLesserDoom(action, result, target)
            self:applyAttackGreaterDoom(action, result, target)
            self:applyAmbusherDamageBonus(action, result)
            self:applyCharmTrustedFriendFightRider(action, result)

            if action.target and (result.damageDealt > 0 or not result.charmTrustedFriendFight) then
                local vampireFeedBefore = self:snapshotVampireFeedTarget(action.target)
                local damageResult = self:applyDamage(action.target, result.damageDealt, result.effects, action.weapon, nil,
                    self:getActionWoundOptions(action, action.target), {
                        source = "attack",
                        action = action,
                        result = result,
                        useAegis = action.useAegis,
                        promptWoundChoice = action.promptWoundChoice,
                    })
                if damageResult and damageResult.prevented and damageResult.shield then
                    result.aegisResult = damageResult
                elseif damageResult and damageResult.pendingWoundChoice then
                    result.pendingWoundChoice = damageResult
                end
                self:applyVampireFeedAfterAttack(action, result, action.target, vampireFeedBefore)
            end
        else
            if not result.description or result.description == "" then
                result.description = "Miss!"
            end
            if not self:redirectMissedAttackToAnimateStatueGrabbedTarget(action, result) then
                if not self:redirectMissedAttackToTitanGrabbedTarget(action, result) then
                    if not self:redirectMissedAttackToGrabbedVictim(action, result) then
                        self:redirectMissedAttackToDevilBiteVictim(action, result)
                    end
                end
            end
        end

        if harpyStoneAttack then
            self:finishHarpyStoneMissileAttack(action, result)
        end

        self:applyMaledictionWeaponRust(action, result)

        if riposteTriggered and riposteDefense and target then
            local riposteResult = self:resolveRiposte(target, action.actor, riposteDefense, attackValue)
            result.riposteResult = riposteResult
            result.description = result.description .. " Riposte! "
            if riposteResult.success then
                result.description = result.description .. "Counter-attack hits!"
            else
                result.description = result.description .. "Counter-attack misses."
            end
        end
    end

    ----------------------------------------------------------------------------
    -- RIPOSTE COUNTER-ATTACK (S4.9)
    ----------------------------------------------------------------------------

    function resolver:getRiposteWeapon(defender, defense)
        if defense and defense.weapon then
            return defense.weapon
        end
        if defender and defender.weapon then
            return defender.weapon
        end
        local inv = defender and defender.inventory
        return inv and inv.getWieldedWeapon and inv:getWieldedWeapon() or nil
    end

    function resolver:isPolearmRiposteDefense(defender, defense)
        return defense and defense.type == "riposte" and
            M.isWeaponType(self:getRiposteWeapon(defender, defense), "POLEARM")
    end

    function resolver:resolvePolearmRiposteInterrupt(action, result, defense, attackerValue, defender)
        defender = (defense and defense.defender) or defender
        if not self:isPolearmRiposteDefense(defender, defense) then
            return false, false
        end

        local riposteResult = self:resolveRiposte(defender, action and action.actor, defense, attackerValue)
        result.riposteResult = riposteResult
        result.effects[#result.effects + 1] = "riposte_ready"
        result.effects[#result.effects + 1] = "polearm_riposte_interrupt"
        result.description = (result.description or "") .. "Polearm Riposte interrupt! "
        if riposteResult.success then
            result.description = result.description .. "Counter-attack hits! "
        else
            result.description = result.description .. "Counter-attack misses. "
        end

        if riposteResult.success and self:isDefeatedForDefense(action and action.actor) then
            result.success = false
            result.damageDealt = 0
            result.interruptedByRiposte = true
            result.effects[#result.effects + 1] = "interrupted_by_polearm_riposte"
            result.description = result.description .. "The attacker is stopped before the action resolves."
            return true, true
        end

        return true, false
    end

    --- Resolve a Riposte counter-attack
    -- @param defender table: Entity performing the riposte
    -- @param attacker table: Original attacker being counter-attacked
    -- @param defense table: The consumed defense { type, card, value }
    -- @return table: Result of the riposte attack
    function resolver:resolveRiposte(defender, attacker, defense, attackerValue)
        defender = (defense and defense.defender) or defender
        local riposteResult = {
            success = false,
            isGreat = false,
            damageDealt = 0,
            effects = {},
            description = "",
        }

        if not defender or not attacker or not defense then
            return riposteResult
        end

        -- Riposte uses the card that was prepared
        local card = defense.card
        local cardValue = defense.value or (card and card.value) or 0

        -- The prepared defense value already encodes the timing rule:
        -- turn actions include the attribute; minor actions use face value only.
        local testValue = cardValue

        local compareValue = attackerValue
        if not compareValue and attacker then
            compareValue = 10 + (attacker.pentacles or 0)
        end

        local attackerHasShield = attacker and self:entityHasShield(attacker)
        riposteResult.success = (testValue > compareValue) or
                                (testValue == compareValue and not attackerHasShield)

        if riposteResult.success then
            riposteResult.damageDealt = 1

            local riposteWeapon = self:getRiposteWeapon(defender, defense)

            -- S7.6: Blade specialization - riposte deals 2 damage with swords
            if M.isWeaponType(riposteWeapon, "BLADE") then
                riposteResult.damageDealt = 2
                riposteResult.effects[#riposteResult.effects + 1] = "blade_riposte"
                riposteResult.effects[#riposteResult.effects + 1] = "riposte_damage_bonus"
                riposteResult.description = "Riposte connects with blade! (2 wounds)"
            else
                riposteResult.description = "Riposte connects!"
            end

            local lesserDoom = defense.lesserDoom
            local lesserEffect = lesserDoom and lesserDoom.effect
            if self:isQuestingBeast(defender) and lesserEffect and lesserEffect.type == "riposte_damage" then
                riposteResult.damageDealt = math.max(riposteResult.damageDealt, lesserEffect.wounds or 2)
                riposteResult.effects[#riposteResult.effects + 1] = "questing_beast_nip"
                riposteResult.effects[#riposteResult.effects + 1] = "riposte_damage_bonus"
                riposteResult.description = "Nip! Riposte deals " .. tostring(riposteResult.damageDealt) .. " Wounds."
            end

            -- Apply damage to the original attacker
            self:applyDamage(attacker, riposteResult.damageDealt, riposteResult.effects, riposteWeapon, nil, nil, {
                source = "attack",
                defense = defense,
                useAegis = attacker.autoUseAegis,
            })

            -- Emit event for visual feedback
            self.eventBus:emit("riposte_hit", {
                defender = defender,
                attacker = attacker,
                damage = riposteResult.damageDealt,
            })
        else
            riposteResult.description = "Riposte parried!"
        end

        return riposteResult
    end

    ----------------------------------------------------------------------------
    -- PENTACLES RESOLUTION (Roughhouse)
    ----------------------------------------------------------------------------

    function resolver:resolvePentaclesAction(action, result)
        local actionType = self:normalizeActionType(action.type or M.ACTION_TYPES.TRIP)

        if actionType == M.ACTION_TYPES.ROUGHHOUSE then
            self:resolveRoughhouse(action, result)
        elseif actionType == M.ACTION_TYPES.TRIP then
            self:resolveTrip(action, result)
        elseif actionType == M.ACTION_TYPES.DISARM then
            self:resolveDisarm(action, result)
        elseif actionType == M.ACTION_TYPES.DISPLACE then
            self:resolveDisplace(action, result)
        elseif actionType == M.ACTION_TYPES.GRAPPLE then
            -- S7.2: Grapple sets rooted condition
            self:resolveGrapple(action, result)
        elseif actionType == M.ACTION_TYPES.AVOID then
            -- S6.3: Avoid action to escape engagement
            self:resolveAvoid(action, result)
        elseif actionType == M.ACTION_TYPES.DASH then
            -- S6.3: Dash is a Pentacles-based quick move
            self:resolveDash(action, result, action.allEntities)
        else
            self:resolveTrip(action, result)  -- Default
        end
    end

    function resolver:normalizeRoughhouseEffect(effect)
        effect = tostring(effect or ""):lower()
        effect = effect:gsub("[’']", "")
        effect = effect:gsub("%s+", "_")
        effect = effect:gsub("[^%w_]", "")

        if effect == "grapple" or effect == "rooted" then
            return "root"
        end
        if effect == "griffin_grab" then
            return "grab"
        end
        if effect == "bad_little_hands" or effect == "roughhouse_steal_belt_item" or
           effect == "steal_belt" or effect == "steal_belt_item" then
            return "steal_belt_item"
        end
        if effect == "rummage" or effect == "pull_item_from_backpack" or effect == "steal_pack_item" then
            return "rummage"
        end
        if effect == "push" or effect == "push_back" then
            return "displace"
        end
        if effect == "exhausted" then
            return "exhaust"
        end
        if effect == "notch_item" or effect == "damage_item" or effect == "break_item" then
            return "notch"
        end
        if effect == "silenced" then
            return "silence"
        end
        if effect == "" then
            return "trip"
        end

        return effect
    end

    function resolver:isFightDirtyRoughhouseEffect(effect)
        return effect == "exhaust" or effect == "notch" or effect == "silence"
    end

    function resolver:resolveGriffinGrab(action, result)
        local actor = action.actor
        local target = action.target

        if not actor or not target then
            result.success = false
            result.description = "No target to grab!"
            result.effects[#result.effects + 1] = "griffin_grab_blocked"
            return
        end
        if self:requiresGreaterDoomForGriffinGrab(action) then
            result.success = false
            result.description = "Griffin Grab requires a greater doom."
            result.effects[#result.effects + 1] = "griffin_grab_requires_greater_doom"
            return
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = false,
        })

        if contest.dodged then
            return
        end

        if result.success then
            self:applyRooted(target, { action = action, reason = "griffin_grab" })

            local heightFeet = action.heightFeet or action.roomHeightFeet or action.fallHeightFeet
            local isFlying = actor.flying == true or action.flying == true or action.flyByAttack == true or
                (actor.conditions and actor.conditions.flying == true)
            actor.grabbedVictim = target
            actor.griffinGrab = {
                victim = target,
                targetMovesWithActor = true,
                missedAttacksHitGrabbedVictim = true,
                flying = isFlying,
                heightFeet = heightFeet,
            }

            target.griffinGrabbedBy = actor
            target.griffinGrabbedById = actor.id
            target.griffinGrabbedByName = actor.name
            target.griffinGrabMovesWith = actor
            target.griffinGrabRecoverCausesFallingDamage = isFlying
            target.griffinGrabFallHeightFeet = heightFeet
            target.rootedBy = "griffin_grab"

            result.description = "Grabbed! Target is Rooted and moves with the griffin."
            result.effects[#result.effects + 1] = "griffin_grab"
            result.effects[#result.effects + 1] = "rooted"
            result.effects[#result.effects + 1] = "target_moves_with_griffin"
            if isFlying then
                result.effects[#result.effects + 1] = "griffin_grab_flying"
            end
        else
            result.description = "Failed to grab!"
        end

        self:appendRoughhouseRiposte(action, result, contest)
    end

    function resolver:resolveStealBeltItem(action, result)
        local actor = action.actor
        local target = action.target

        if not actor or not target then
            result.success = false
            result.description = "No target to steal from!"
            result.effects[#result.effects + 1] = "bad_little_hands_blocked"
            return
        end
        if not self:isBadLittleHandsRoughhouse(action, "steal_belt_item") then
            result.success = false
            result.description = "Bad Little Hands is a Face Rat lesser doom."
            result.effects[#result.effects + 1] = "bad_little_hands_requires_face_rat"
            return
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = false,
        })

        if contest.dodged then
            return
        end

        if result.success then
            local item, location, itemReason = self:getBadLittleHandsTargetItem(action)
            if not item then
                result.success = false
                result.description = "No belt item to steal!"
                result.effects[#result.effects + 1] = "bad_little_hands_no_belt_item"
                result.badLittleHandsFailure = itemReason
            else
                local stolen = nil
                if target.inventory and target.inventory.removeItem and item.id then
                    stolen = target.inventory:removeItem(item.id)
                end
                stolen = stolen or item

                local record = self:recordBadLittleHandsItem(actor, target, stolen, location, action)
                result.description = "Bad Little Hands steals [" .. (stolen.name or "belt item") .. "]!"
                result.effects[#result.effects + 1] = "bad_little_hands"
                result.effects[#result.effects + 1] = "belt_item_stolen"
                result.stolenItem = stolen
                result.stolenItemRecord = record

                self.eventBus:emit(events.EVENTS.INVENTORY_CHANGED, {
                    entity = target,
                    item = stolen,
                    reason = "bad_little_hands_stolen",
                    source = actor,
                })
            end
        else
            result.description = "Failed to steal belt item!"
        end

        self:appendRoughhouseRiposte(action, result, contest)
    end

    function resolver:resolveRoughhouse(action, result)
        self:applyActiveAids(action.actor, result, action, {
            requireSpecificTrigger = true,
        })

        local effect = self:normalizeRoughhouseEffect(
            action.roughhouseEffect or action.effect or action.maneuver or action.outcome
        )
        result.roughhouseEffect = effect
        result.effects[#result.effects + 1] = "roughhouse"
        result.effects[#result.effects + 1] = "roughhouse_" .. effect

        local targetOldZone = action.target and action.target.zone
        if self:isTitanShakeRoughhouse(action, effect) then
            return self:resolveTitanShake(action, result)
        end
        if self:isTitanGrabRoughhouse(action, effect) then
            return self:resolveTitanGrab(action, result)
        end
        if self:isAnimateStatueGrabRoughhouse(action, effect) then
            return self:resolveAnimateStatueGrab(action, result)
        end
        if self:isGriffinGrabRoughhouse(action, effect) then
            return self:resolveGriffinGrab(action, result)
        end
        if self:isUngoatRummage(action, effect) then
            return self:resolveUngoatRummage(action, result)
        end
        if self:isSlimeProtoplasmicRoughhouse(action) then
            return self:resolveSlimeProtoplasmicAttack(action, result)
        end
        if effect == "steal_belt_item" then
            return self:resolveStealBeltItem(action, result)
        end

        if self:isFightDirtyRoughhouseEffect(effect) and not entityHasUsableTalent(action.actor, "fight_dirty") then
            result.success = false
            result.description = "Requires Fight Dirty."
            result.effects[#result.effects + 1] = "fight_dirty_required"
            return
        end

        if targetRequiresGiantSizeToRoughhouse(action.target) and not actionCanAffectGiantSizedTarget(action) then
            result.success = false
            result.description = "Target is too huge to Roughhouse."
            result.effects[#result.effects + 1] = "roughhouse_target_too_huge"
            result.effects[#result.effects + 1] = "roughhouse_requires_giant_size"
            return
        end

        if effect == "trip" then
            self:resolveTrip(action, result)
        elseif effect == "disarm" then
            self:resolveDisarm(action, result)
        elseif effect == "displace" then
            self:resolveDisplace(action, result)
        elseif effect == "root" then
            self:resolveRoot(action, result)
        elseif effect == "exhaust" then
            self:resolveExhaust(action, result)
        elseif effect == "notch" then
            self:resolveNotch(action, result)
        elseif effect == "silence" then
            self:resolveSilence(action, result)
        else
            result.success = false
            result.description = "Unknown Roughhouse effect: " .. tostring(effect)
            result.effects[#result.effects + 1] = "roughhouse_effect_unknown"
        end

        self:applyImpPissAndShitRoughhouse(action, result)

        local targetNewZone = action.target and action.target.zone
        result.roughhouseTarget = action.target
        result.roughhouseActionValue = result.testValue
        result.roughhouseTargetInitiative = result.difficulty
        result.roughhouseDestinationZone = action.destinationZone
        result.roughhouseDroppedItem = result.droppedItem
        result.roughhouseNotchedItem = result.notchedItem
        result.roughhouseItemNotchResult = result.itemNotchResult
        result.roughhouse = {
            actor = action.actor,
            target = action.target,
            effect = effect,
            roughhouseEffect = effect,
            actionValue = result.roughhouseActionValue,
            targetInitiative = result.roughhouseTargetInitiative,
            success = result.success == true,
            oldZone = targetOldZone,
            newZone = targetNewZone,
            destinationZone = action.destinationZone,
            droppedItem = result.droppedItem,
            recoveredItem = result.recoveredItem,
            notchedItem = result.notchedItem,
            itemNotchResult = result.itemNotchResult,
            riposteResult = result.riposteResult,
        }
    end

    function resolver:resolveTrip(action, result)
        if self:isSlimeShapelessImmune(action.target, "trip") then
            self:blockSlimeShapelessAction(result, "trip")
            return
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = true,
            considerShield = true,
        })

        if contest.dodged then
            return
        end

        if result.success then
            result.description = "Knocked down!"
            result.effects[#result.effects + 1] = "prone"

            if action.target then
                action.target.conditions = action.target.conditions or {}
                action.target.conditions.prone = true
            end
            self:clearAllEngagements(action.target, action.allEntities)
        else
            result.description = "Failed to trip!"
        end

        if contest.riposteTriggered and contest.riposteDefense and action.target then
            local riposteResult = self:resolveRiposte(action.target, action.actor, contest.riposteDefense, contest.attackValue)
            result.riposteResult = riposteResult
            result.description = result.description .. " Riposte! "
            if riposteResult.success then
                result.description = result.description .. "Counter-attack hits!"
            else
                result.description = result.description .. "Counter-attack misses."
            end
        end
    end

    --- S7.3: Disarm with inventory drop
    function resolver:resolveDisarm(action, result)
        local target = action.target

        if not target then
            result.success = false
            result.description = "No target to disarm!"
            return
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = true,
            considerShield = true,
        })

        if contest.dodged then
            return
        end

        -- Check if target has anything in hands or Face Rat Bad Little Hands.
        local droppedItem = nil
        local badLittleHandsItem = self:peekBadLittleHandsItem(target)
        local requestedItemId = action.disarmItemId or action.disarmedItemId or action.droppedItemId or
            action.targetHeldItemId
        if target.inventory and target.inventory.getItems then
            local handsItems = target.inventory:getItems("hands")
            if handsItems and #handsItems > 0 then
                if requestedItemId then
                    for _, item in ipairs(handsItems) do
                        if tostring(item.id) == tostring(requestedItemId) then
                            droppedItem = item
                            break
                        end
                    end
                else
                    droppedItem = handsItems[1]
                end
            end
        elseif target.weapon and (not requestedItemId or tostring(target.weapon.id) == tostring(requestedItemId)) then
            droppedItem = target.weapon
        end

        if result.success then
            if requestedItemId and not droppedItem and not badLittleHandsItem then
                result.success = false
                result.description = "Selected disarm item is not held by the target."
                result.effects[#result.effects + 1] = "disarm_item_not_held"
                return
            end
            if badLittleHandsItem then
                local recovery = self:releaseBadLittleHandsItem(target, "disarm")
                local recoveredItem = recovery and recovery.item or badLittleHandsItem
                result.description = "Disarmed stolen [" .. (recoveredItem.name or "item") .. "] from Bad Little Hands!"
                result.effects[#result.effects + 1] = "disarmed"
                result.effects[#result.effects + 1] = "bad_little_hands_item_recovered"
                result.effects[#result.effects + 1] = "belt_item_recovered"
                result.recoveredItem = recoveredItem
                result.recovery = recovery

                -- Set disarmed condition on target
                if target.conditions then
                    target.conditions.disarmed = true
                end
            elseif droppedItem then
                droppedItem = self:dropCarriedItem(target, droppedItem, "disarm", action)
                result.description = "Disarmed [" .. (droppedItem.name or "item") .. "]!"
                result.effects[#result.effects + 1] = "disarmed"
                result.droppedItem = droppedItem

                -- Set disarmed condition on target
                if target.conditions then
                    target.conditions.disarmed = true
                end
            elseif self:yellowKingHasActiveCrown(target) then
                self:disarmYellowKingCrown(target, action, result)
                result.effects[#result.effects + 1] = "disarmed"
            else
                -- Can't disarm someone with nothing in hands
                result.success = false
                result.description = "Target has nothing to disarm!"
            end
        else
            result.description = "Failed to disarm!"
        end

        if contest.riposteTriggered and contest.riposteDefense and target then
            local riposteResult = self:resolveRiposte(target, action.actor, contest.riposteDefense, contest.attackValue)
            result.riposteResult = riposteResult
            result.description = result.description .. " Riposte! "
            if riposteResult.success then
                result.description = result.description .. "Counter-attack hits!"
            else
                result.description = result.description .. "Counter-attack misses."
            end
        end
    end

    --- S7.2: Grapple sets rooted condition
    function resolver:resolveGrapple(action, result)
        local target = action.target

        if not target then
            result.success = false
            result.description = "No target to grapple!"
            return
        end
        if self:isSlimeShapelessImmune(target, "root") then
            self:blockSlimeShapelessAction(result, "root")
            return
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = true,
            considerShield = true,
        })

        if contest.dodged then
            return
        end

        if result.success then
            result.description = "Grappled! Target is rooted."
            result.effects[#result.effects + 1] = "grappled"
            result.effects[#result.effects + 1] = "rooted"

            -- Set rooted condition on target
            if target.conditions then
                target.conditions.rooted = true
            else
                target.conditions = { rooted = true }
            end

            -- Also form engagement
            self:formEngagement(action.actor, target)
        else
            result.description = "Failed to grapple!"
        end

        if contest.riposteTriggered and contest.riposteDefense and target then
            local riposteResult = self:resolveRiposte(target, action.actor, contest.riposteDefense, contest.attackValue)
            result.riposteResult = riposteResult
            result.description = result.description .. " Riposte! "
            if riposteResult.success then
                result.description = result.description .. "Counter-attack hits!"
            else
                result.description = result.description .. "Counter-attack misses."
            end
        end
    end

    function resolver:resolveRoot(action, result)
        local target = action.target

        if not target then
            result.success = false
            result.description = "No target to root!"
            return
        end
        if self:isSlimeShapelessImmune(target, "root") then
            self:blockSlimeShapelessAction(result, "root")
            return
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = true,
            considerShield = true,
        })

        if contest.dodged then
            return
        end

        if result.success then
            result.description = "Rooted!"
            result.effects[#result.effects + 1] = "rooted"
            self:applyRooted(target, { action = action, reason = "roughhouse_root" })
        else
            result.description = "Failed to root!"
        end

        if contest.riposteTriggered and contest.riposteDefense and target then
            local riposteResult = self:resolveRiposte(target, action.actor, contest.riposteDefense, contest.attackValue)
            result.riposteResult = riposteResult
            result.description = result.description .. " Riposte! "
            if riposteResult.success then
                result.description = result.description .. "Counter-attack hits!"
            else
                result.description = result.description .. "Counter-attack misses."
            end
        end
    end

    function resolver:appendRoughhouseRiposte(action, result, contest)
        if contest.riposteTriggered and contest.riposteDefense and action.target then
            local riposteResult = self:resolveRiposte(action.target, action.actor, contest.riposteDefense, contest.attackValue)
            result.riposteResult = riposteResult
            result.description = result.description .. " Riposte! "
            if riposteResult.success then
                result.description = result.description .. "Counter-attack hits!"
            else
                result.description = result.description .. "Counter-attack misses."
            end
        end
    end

    function resolver:resolveFightDirtyCondition(action, result, condition, effectName, successText, failureText)
        local target = action.target

        if not target then
            result.success = false
            result.description = "No target!"
            return
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = true,
            considerShield = true,
        })

        if contest.dodged then
            return
        end

        if result.success then
            target.conditions = target.conditions or {}
            target.conditions[condition] = true
            result.description = successText
            result.effects[#result.effects + 1] = effectName
        else
            result.description = failureText
        end

        self:appendRoughhouseRiposte(action, result, contest)
    end

    function resolver:resolveExhaust(action, result)
        self:resolveFightDirtyCondition(action, result, "exhausted", "exhausted", "Exhausted!", "Failed to exhaust!")
    end

    function resolver:resolveSilence(action, result)
        self:resolveFightDirtyCondition(action, result, "silenced", "silenced", "Silenced!", "Failed to silence!")
    end

    function resolver:getRoughhouseNotchItem(action)
        local target = action and action.target
        if not target then
            return nil
        end
        if action.targetItem then
            return action.targetItem
        end

        local itemId = action.targetItemId or action.itemId
        if itemId and target.inventory and target.inventory.findItem then
            local item = target.inventory:findItem(itemId)
            if item then
                return item
            end
        end

        if target.inventory and target.inventory.getItems then
            local handItems = target.inventory:getItems("hands")
            if handItems and #handItems > 0 then
                return handItems[1]
            end
        end

        return target.weapon
    end

    function resolver:resolveNotch(action, result)
        local target = action.target

        if not target then
            result.success = false
            result.description = "No target to Notch!"
            return
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = true,
            considerShield = true,
        })

        if contest.dodged then
            return
        end

        if result.success then
            local constructWounds, woundEffect, notchEffect, constructLabel = self:getConstructNotchWounds(target)
            if constructWounds then
                local wounds = constructWounds
                result.description = "Notched " .. constructLabel .. " for " .. tostring(wounds) .. " Wounds!"
                result.effects[#result.effects + 1] = woundEffect
                result.effects[#result.effects + 1] = notchEffect
                result.damageDealt = wounds
                self:applyDamage(target, wounds, result.effects, nil, action.allEntities, nil, {
                    source = "notch",
                    action = action,
                })
                self:appendRoughhouseRiposte(action, result, contest)
                return
            end

            local item = self:getRoughhouseNotchItem(action)
            if item then
                if self:isLightSourceItem(item) and self:breakTargetLightSourceHitInCombat(action, result) then
                    result.description = "Broke " .. (item.name or "light source") .. "!"
                else
                    local notchResult = inventory.addNotch(item)
                    result.description = "Notched " .. (item.name or "item") .. "!"
                    result.effects[#result.effects + 1] = "item_notched"
                    if notchResult == "destroyed" then
                        result.effects[#result.effects + 1] = "item_destroyed"
                    end
                    result.itemNotchResult = notchResult
                    result.notchedItem = item
                end
            else
                result.success = false
                result.description = "No target item to Notch!"
                result.effects[#result.effects + 1] = "no_item_to_notch"
            end
        else
            result.description = "Failed to Notch!"
        end

        self:appendRoughhouseRiposte(action, result, contest)
    end

    function resolver:resolveDisplace(action, result)
        if self:isSlimeShapelessImmune(action.target, "displace") then
            self:blockSlimeShapelessAction(result, "displace")
            return
        end

        local contest = self:resolveInitiativeContest(action, result, {
            tieWins = true,
            considerShield = true,
        })

        if contest.dodged then
            return
        end

        if result.success then
            result.description = "Pushed back!"
            result.effects[#result.effects + 1] = "displaced"

            -- Would move target to adjacent zone
            if action.target and action.destinationZone then
                action.target.zone = action.destinationZone
            end

            self:clearAllEngagements(action.target, action.allEntities)
        else
            result.description = "Failed to push!"
        end

        if contest.riposteTriggered and contest.riposteDefense and action.target then
            local riposteResult = self:resolveRiposte(action.target, action.actor, contest.riposteDefense, contest.attackValue)
            result.riposteResult = riposteResult
            result.description = result.description .. " Riposte! "
            if riposteResult.success then
                result.description = result.description .. "Counter-attack hits!"
            else
                result.description = result.description .. "Counter-attack misses."
            end
        end
    end

    ----------------------------------------------------------------------------
    -- CUPS RESOLUTION (Support/Social)
    ----------------------------------------------------------------------------

    function resolver:resolveCupsAction(action, result)
        local actionType = self:normalizeActionType(action.type or M.ACTION_TYPES.AID)

        if actionType == M.ACTION_TYPES.DODGE then
            -- S4.9: Prepare Dodge defense
            self:resolveDodge(action, result)
        elseif actionType == M.ACTION_TYPES.RIPOSTE then
            -- S4.9: Prepare Riposte defense
            self:resolveRipostePrepare(action, result)
        elseif actionType == M.ACTION_TYPES.HEAL then
            self:resolveHeal(action, result)
        elseif actionType == M.ACTION_TYPES.COMMAND then
            self:resolveCommand(action, result)
        elseif actionType == M.ACTION_TYPES.PARLEY then
            self:resolveParley(action, result)
        elseif actionType == M.ACTION_TYPES.RALLY then
            self:resolveRally(action, result)
        elseif actionType == M.ACTION_TYPES.USE_ITEM then
            self:resolveUseItem(action, result)
        elseif actionType == M.ACTION_TYPES.PULL_ITEM then
            self:resolvePullItemFromPack(action, result)
        elseif actionType == M.ACTION_TYPES.SHIELD then
            result.success = true
            result.description = "Shielding " .. (action.target and action.target.name or "ally")
            result.effects[#result.effects + 1] = "shielding"
        elseif actionType == M.ACTION_TYPES.AID then
            -- S7.1: Aid Another
            self:resolveAidAnother(action, result)
        else
            self:resolveGenericAction(action, result)
        end
    end

    --- S7.1: Aid Another - bank a bonus for an ally's next action
    function resolver:resolveAidAnother(action, result)
        local actor = action.actor
        local target = action.target

        if not target then
            result.success = false
            result.description = "No ally to aid!"
            return
        end

        local sameEntity = actor == target
        if not sameEntity and actor and target and actor.id and target.id then
            sameEntity = actor.id == target.id
        end
        if sameEntity then
            result.success = false
            result.description = "Cannot aid yourself!"
            result.effects[#result.effects + 1] = "aid_self_blocked"
            return
        end

        if actor and actor.isPC ~= nil and target.isPC ~= nil and actor.isPC ~= target.isPC then
            result.success = false
            result.description = "Can only aid allies!"
            result.effects[#result.effects + 1] = "aid_ally_required"
            return
        end

        -- Aid always succeeds (no test required)
        result.success = true

        -- Calculate bonus from resolved action value (respects minor-action rules)
        local totalBonus = result.testValue or (action.card and action.card.value) or 0
        local trigger = self:aidTriggerSpec(action)

        self:discardActorFacedownActions(actor, action, result, {
            newType = "aid",
            reason = "facedown_replaced_by_aid",
        })

        -- Register the aid for the target
        self:registerAid(target, totalBonus, actor.name or "ally", {
            sourceActor = actor,
            card = action.card,
            discardDeck = action.discardDeck or action.playerDeck or self.playerDeck,
            triggerAction = trigger.action,
            triggerTarget = trigger.target,
            triggerTargetId = trigger.targetId,
            objective = trigger.objective,
        })

        result.aid = {
            target = target,
            value = totalBonus,
            triggerAction = trigger.action,
            triggerTargetId = trigger.targetId,
            objective = trigger.objective,
        }
        result.description = "Aided " .. (target.name or "ally") .. "! (+" .. totalBonus .. " to " ..
            (trigger.action or "next action") .. ")"
        result.effects[#result.effects + 1] = "aid_banked"
    end

    function resolver:normalizeCommandName(commandName)
        return animal_companions.normalizeCommandName(commandName)
    end

    function resolver:getCommandCompanion(actor, action)
        if not actor then
            return nil
        end

        if action.companion then
            return action.companion
        end

        local companionId = action.companionId
        for _, collection in ipairs({ actor.companions or false, actor.animalCompanions or false }) do
            if type(collection) == "table" then
                for key, companion in pairs(collection) do
                    if type(companion) == "table" then
                        if not companionId or companion.id == companionId or key == companionId then
                            return companion
                        end
                    end
                end
            end
        end

        return actor.companion
    end

    function resolver:companionKnowsCommand(companion, commandName)
        if not commandName or commandName == "" then
            return true
        end
        if companion and (companion.commandsAny or companion.obeysMostCommands) then
            return true
        end

        local commands = companion and (companion.knownCommands or companion.commands)
        if not commands then
            return true
        end

        for key, value in pairs(commands) do
            if type(value) == "string" then
                if self:normalizeCommandName(value) == commandName then
                    return true
                end
            elseif type(value) == "table" then
                if self:normalizeCommandName(animal_companions.getCommandEntryName(value, key)) == commandName then
                    return true
                end
            elseif value and self:normalizeCommandName(key) == commandName then
                return true
            end
        end

        return false
    end

    function resolver:companionAllowsSpokenCommand(companion, rawCommand)
        if not companion or not companion.oneWordCommandsOnly then
            return true
        end

        local text = tostring(rawCommand or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if text == "" then
            return false
        end
        return text:find("[%s_]") == nil
    end

    function resolver:canCommandCompanion(companion)
        if not companion then
            return false, "No companion to command."
        end

        local conditions = companion.conditions or {}
        if conditions.dead then
            return false, "Companion is dead."
        end
        if companion.abandoned or conditions.abandoned then
            return false, "Companion has abandoned the guild."
        end
        if companion.weak or companion.starving or conditions.weak or conditions.starving then
            return false, "Companion is weak and cannot be commanded."
        end

        return true, nil
    end

    local function removeCompanionFromActor(actor, companion)
        if not actor or not companion or type(actor.companions) ~= "table" then
            return false
        end

        local removed = false
        for key, entry in pairs(actor.companions) do
            if entry == companion then
                actor.companions[key] = nil
                removed = true
            end
        end
        if actor.companion == companion then
            actor.companion = nil
        end
        return removed
    end

    function resolver:recordBoundZombieService(companion, action, result)
        local binding = companion and companion.raiseZombie
        if not binding or binding.active == false then
            return nil
        end

        binding.servicesCompleted = (binding.servicesCompleted or 0) + 1
        binding.servicesRemaining = math.max(0, (binding.servicesRemaining or 0) - 1)
        companion.zombieServicesCompleted = binding.servicesCompleted
        companion.zombieServicesRemaining = binding.servicesRemaining
        result.effects[#result.effects + 1] = "bound_zombie_service_spent"
        result.boundZombieServicesRemaining = binding.servicesRemaining

        if binding.servicesRemaining <= 0 then
            binding.completed = true
            local ended = self:endOngoingSpell(binding.caster, binding.spellEntry or {
                spellId = "raise_zombie",
                target = companion,
                raisedZombie = companion,
            }, "raise_zombie_services_completed", {
                source = action,
            })
            result.endedSpell = ended
            result.effects[#result.effects + 1] = "raise_zombie_services_completed"
            return ended
        end

        return nil
    end

    function resolver:isCommandCombatantTarget(target)
        if not target then
            return false
        end

        local props = target.properties or {}
        if target.combatant == true or target.creature == true or target.npc == true or target.monster == true or
           props.combatant == true or props.creature == true or props.npc == true or props.monster == true then
            return true
        end
        if animal_companions.isAnimalCompanion(target) then
            return true
        end
        if target.takeWound or target.isPC ~= nil or target.npcHealth ~= nil then
            return true
        end
        if target.isItem == true or target.itemType or target.objectType or target.scenery == true or
           target.inanimate == true or props.item == true or props.scenery == true or props.inanimate == true then
            return false
        end
        if target.health ~= nil then
            return true
        end
        return target.creatureType ~= nil or target.kin ~= nil or target.path ~= nil or target.enemyType ~= nil
    end

    function resolver:isContestedCommand(actor, target, action)
        if action and action.contestedCommand ~= nil then
            return action.contestedCommand
        end
        if not target or target == actor then
            return false
        end
        if actor and target and actor.isPC ~= nil and target.isPC ~= nil then
            return actor.isPC ~= target.isPC
        end
        return self:isCommandCombatantTarget(target)
    end

    function resolver:prepareCompanionTestOfFate(action, result, companion, commandName)
        if not (action.commandTestOfFate or action.companionTestOfFate or
                action.requiresTestOfFate or action.testOfFate) then
            return nil
        end

        local testTags = action.companionTestTags or action.testTags or action.fateTags or
            action.companionTest or action.testContext or action.activity or action.intent or commandName
        local favor = action.favor
        if action.disfavor == true then
            favor = combineFavorState(favor, false)
        end
        if animal_companions.isSuitedForTest(companion, testTags) then
            favor = combineFavorState(favor, true)
            result.effects[#result.effects + 1] = "companion_test_favor"
        else
            result.effects[#result.effects + 1] = "companion_test_no_bonus"
        end

        local attribute = action.companionTestAttribute or action.testAttribute or "companionFate"
        if companion[attribute] == nil then
            companion[attribute] = action.companionTestAttributeValue or action.testAttributeValue or 0
        end

        local request = {
            entity = companion,
            actor = action.actor,
            companion = companion,
            command = commandName,
            attribute = attribute,
            targetSuit = action.companionTestSuit or action.testSuit or action.targetSuit,
            favor = favor,
            description = action.companionTestDescription or action.testDescription or
                ((companion.name or "Companion") .. " attempts " .. tostring(commandName):gsub("_", " ")),
            action = action,
            actionCard = action.card,
            companionTest = true,
            testTags = testTags,
        }

        result.pendingTestOfFate = true
        result.companionTestOfFate = request
        self.eventBus:emit(events.EVENTS.REQUEST_TEST_OF_FATE, request)

        return request
    end

    function resolver:applyCompanionCommand(action, result, companion, commandName)
        local actor = action.actor
        local target = action.target
        local commandObjective = action.commandObjective or action.objective or action.commandText or
            action.instruction or action.order or action.task

        companion.lastCommand = commandName
        companion.commandedThisRound = true
        companion.currentCommand = {
            command = commandName,
            actor = actor,
            target = target,
            item = action.item,
            objective = commandObjective,
        }
        result.commandObjective = commandObjective

        if self:lionUntrackableBlocksTracking(action, result, commandName) then
            companion.currentCommand.blocked = "lion_untrackable"
            return
        end

        if commandName == "sic_em" then
            if not target then
                result.success = false
                result.description = "No target for Sic 'Em."
                result.effects[#result.effects + 1] = "command_target_missing"
                return
            end

            local damage = action.commandDamage or companion.damage or 1
            result.damageDealt = damage
            result.effects[#result.effects + 1] = "companion_attack"
            self:applyDamage(target, damage, action.commandDamageEffects or {}, nil, action.allEntities,
                self:getActionWoundOptions(action, target), {
                    source = "attack",
                    action = action,
                    useAegis = action.useAegis,
                })

            if companion.zone and target.zone then
                self:formEngagement(companion, target)
            end

            result.description = (companion.name or "Companion") .. " attacks " .. (target.name or "target") .. "."
        elseif commandName == "fetch" then
            result.fetchedItem = action.item
            result.effects[#result.effects + 1] = "companion_fetch"
            if action.item then
                result.description = (companion.name or "Companion") .. " fetches " .. (action.item.name or "item") .. "."
            else
                result.description = (companion.name or "Companion") .. " starts fetching."
            end
        elseif commandName == "guard" then
            companion.guarding = action.commandTarget or target or actor
            result.effects[#result.effects + 1] = "companion_guard"
            result.description = (companion.name or "Companion") .. " guards " .. (companion.guarding.name or "the area") .. "."
        elseif commandName == "hunt" then
            companion.hunting = action.huntTarget or target or action.trail or commandObjective or true
            result.huntTarget = companion.hunting
            result.effects[#result.effects + 1] = "companion_hunt"
            result.description = (companion.name or "Companion") .. " begins hunting."
        elseif commandName == "get_help" then
            companion.seekingHelp = action.helpTarget or target or commandObjective or true
            result.helpTarget = companion.seekingHelp
            result.effects[#result.effects + 1] = "companion_get_help"
            result.description = (companion.name or "Companion") .. " goes for help."
        elseif commandName == "do_a_trick" then
            companion.currentTrick = action.trick or action.trickName or commandObjective or true
            result.trick = companion.currentTrick
            result.effects[#result.effects + 1] = "companion_trick"
            result.description = (companion.name or "Companion") .. " performs a trick."
        elseif commandName == "heel" then
            companion.zone = actor and actor.zone or companion.zone
            companion.staying = nil
            companion.stayZone = nil
            result.effects[#result.effects + 1] = "companion_positioned"
            result.description = (companion.name or "Companion") .. " obeys heel."
        elseif commandName == "stay" then
            companion.staying = true
            companion.stayZone = companion.zone
            result.effects[#result.effects + 1] = "companion_positioned"
            result.description = (companion.name or "Companion") .. " stays put."
        elseif commandName == "track" then
            companion.tracking = {
                subject = action.trackSubject or action.trail or target or commandObjective,
                source = action,
            }
            result.trackSubject = companion.tracking.subject
            result.effects[#result.effects + 1] = "companion_track"
            result.description = (companion.name or "Companion") .. " follows the trail."
        else
            result.effects[#result.effects + 1] = "companion_command"
            result.description = (companion.name or "Companion") .. " follows the command."
        end

        self:prepareCompanionTestOfFate(action, result, companion, commandName)

        if result.success ~= false then
            self:recordBoundZombieService(companion, action, result)
        end
    end

    function resolver:resolveCommand(action, result)
        local actor = action.actor
        local target = action.target
        local companion = self:getCommandCompanion(actor, action)
        local canCommand, blockReason = self:canCommandCompanion(companion)

        if not canCommand then
            result.success = false
            result.description = blockReason
            result.effects[#result.effects + 1] = "command_blocked"
            return
        end

        local rawCommand = action.commandName or action.command or "command"
        if not self:companionAllowsSpokenCommand(companion, rawCommand) then
            result.success = false
            result.description = (companion.name or "Companion") .. " only understands one-word commands."
            result.effects[#result.effects + 1] = "command_too_complex"
            return
        end

        local commandName = self:normalizeCommandName(rawCommand)
        if not self:companionKnowsCommand(companion, commandName) then
            result.success = false
            result.description = (companion.name or "Companion") .. " does not know " .. commandName:gsub("_", " ") .. "."
            result.effects[#result.effects + 1] = "unknown_command"
            return
        end

        local contest = nil
        if self:isContestedCommand(actor, target, action) then
            contest = self:resolveInitiativeContest(action, result, {
                tieWins = true,
                considerShield = true,
            })
        else
            result.success = true
        end

        if result.success then
            result.effects[#result.effects + 1] = "commanded"
            result.companion = companion
            result.commandName = commandName
            self:applyCompanionCommand(action, result, companion, commandName)
        else
            result.description = "Command resisted."
        end

        if contest and contest.riposteTriggered and contest.riposteDefense and target then
            local riposteResult = self:resolveRiposte(target, actor, contest.riposteDefense, contest.attackValue)
            result.riposteResult = riposteResult
            result.description = result.description .. " Riposte! "
            if riposteResult.success then
                result.description = result.description .. "Counter-attack hits!"
            else
                result.description = result.description .. "Counter-attack misses."
            end
        end
    end

    function resolver:resolveParley(action, result)
        local target = action.target
        if not target then
            result.success = false
            result.description = "No target to parley with."
            return
        end
        if applyRhymedSpeechSocialGate(action, result) then
            return
        end
        if applyLockedSpeechSocialGate(action, result, target) then
            return
        end

        self:applyPreparedRoomSocialEffects(action, result, target)

        -- Parley requires exceeding the social difficulty, matching Banter semantics.
        local socialTags = collectSocialTags(action.socialTags or action.parleyTags or action.approach or action.socialApproach)
        local itemSocialTagStart = #socialTags
        self:collectActionSocialItemTags(action, socialTags)
        if #socialTags > itemSocialTagStart then
            result.socialItemTags = {}
            for i = itemSocialTagStart + 1, #socialTags do
                result.socialItemTags[#result.socialItemTags + 1] = socialTags[i]
            end
            result.effects[#result.effects + 1] = "social_item_tags"
        end
        local liked, likedTag = hasSocialTag(target.social and target.social.likes, socialTags)
        local disliked, dislikedTag = hasSocialTag(
            (target.social and (target.social.dislikes or target.social.hates)) or nil,
            socialTags
        )
        local preferenceModifier = 0
        if liked then
            preferenceModifier = preferenceModifier + 3
            result.effects[#result.effects + 1] = "social_favor"
        end
        if disliked then
            preferenceModifier = preferenceModifier - 3
            result.effects[#result.effects + 1] = "social_disfavor"
        end
        if preferenceModifier ~= 0 then
            result.testValue = result.testValue + preferenceModifier
        end
        result.socialModifier = (result.socialModifier or 0) + preferenceModifier
        result.socialFavorTag = likedTag
        result.socialDisfavorTag = dislikedTag
        applyMaledictionSocialModifier(action, result, target)
        applyPactSocialModifier(action, result)
        applySocialPactBreaks(self, action, result)
        result.success = result.testValue > result.difficulty

        self.eventBus:emit("social_discovery", {
            target = target,
            targetId = target.id,
            discoveries = { "disposition", "morale" },
        })

        if result.success then
            local oldDisposition = target.getDisposition and target:getDisposition() or target.disposition
            local oldDispositionSeverity = target.getDispositionSeverity and target:getDispositionSeverity()
                or target.dispositionSeverity
                or 2
            local newDisposition = oldDisposition or "distaste"
            local newDispositionSeverity = oldDispositionSeverity
            local dispositionChange = "held"

            if disposition_module and disposition_module.moveTowardState and disposition_module.DISPOSITIONS then
                newDisposition, newDispositionSeverity, dispositionChange = disposition_module.moveTowardState(
                    newDisposition,
                    oldDispositionSeverity,
                    disposition_module.DISPOSITIONS.TRUST,
                    1
                )
            elseif target.shiftDisposition then
                target:shiftDisposition(1, 1)
                newDisposition = target.getDisposition and target:getDisposition() or target.disposition
            end

            if target.setDisposition then
                target:setDisposition(newDisposition, newDispositionSeverity)
            else
                target.disposition = newDisposition
                target.dispositionSeverity = newDispositionSeverity
            end
            self:endCharmForDispositionChange(
                target,
                oldDisposition,
                newDisposition,
                action,
                oldDispositionSeverity,
                newDispositionSeverity)

            result.oldDisposition = oldDisposition
            result.oldDispositionSeverity = oldDispositionSeverity
            result.newDisposition = newDisposition
            result.newDispositionSeverity = newDispositionSeverity
            result.newDispositionLabel = disposition_module.getDispositionLabel(newDisposition, newDispositionSeverity)
            result.dispositionTarget = disposition_module.DISPOSITIONS.TRUST
            result.dispositionChange = dispositionChange
            applySocialOutcomeToResult(result, target,
                disposition_module.getSocialOutcome(newDisposition, newDispositionSeverity))

            result.description = "Parley gains ground."
            result.effects[#result.effects + 1] = "parley_progress"
        else
            local oldDisposition = target.getDisposition and target:getDisposition() or target.disposition or "distaste"
            local oldDispositionSeverity = target.getDispositionSeverity and target:getDispositionSeverity()
                or target.dispositionSeverity
                or 2
            local newDisposition, newDispositionSeverity, dispositionChange = disposition_module.moveTowardState(
                oldDisposition,
                oldDispositionSeverity,
                disposition_module.DISPOSITIONS.ANGER,
                1)
            if target.setDisposition then
                target:setDisposition(newDisposition, newDispositionSeverity)
            else
                target.disposition = newDisposition
                target.dispositionSeverity = newDispositionSeverity
            end
            self:endCharmForDispositionChange(
                target,
                oldDisposition,
                newDisposition,
                action,
                oldDispositionSeverity,
                newDispositionSeverity)
            result.oldDisposition = oldDisposition
            result.oldDispositionSeverity = oldDispositionSeverity
            result.newDisposition = newDisposition
            result.newDispositionSeverity = newDispositionSeverity
            result.newDispositionLabel = disposition_module.getDispositionLabel(newDisposition, newDispositionSeverity)
            result.dispositionTarget = disposition_module.DISPOSITIONS.ANGER
            result.dispositionChange = dispositionChange
            applySocialOutcomeToResult(result, target,
                disposition_module.getSocialOutcome(newDisposition, newDispositionSeverity))
            result.description = "Parley fails to persuade."
        end
    end

    function resolver:resolveRally(action, result)
        local target = action.target or action.actor
        if not target then
            result.success = false
            result.description = "No ally to rally."
            return
        end

        if not result.success then
            result.description = "Rally falters."
            return
        end

        local cleared = nil
        if target.conditions then
            if target.conditions.stressed then
                target.conditions.stressed = false
                cleared = "stressed"
            elseif target.conditions.frightened then
                target.conditions.frightened = false
                cleared = "frightened"
            elseif target.conditions.deaf then
                target.conditions.deaf = false
                cleared = "deaf"
            elseif target.conditions.blind then
                target.conditions.blind = false
                cleared = "blind"
            end
        end

        if target.modifyMorale then
            target:modifyMorale(1)
        end

        if cleared then
            result.description = "Rallied " .. (target.name or "ally") .. " (" .. cleared .. " cleared)."
            result.effects[#result.effects + 1] = "rally_" .. cleared
        else
            result.description = "Rallied " .. (target.name or "ally") .. "."
            result.effects[#result.effects + 1] = "rally_boost"
        end
    end

    function resolver:getItemUseEffect(item)
        local props = item and item.properties or {}
        if props.useEffect then
            return props.useEffect
        end
        if props.challengeEffect then
            return props.challengeEffect
        end

        if (props.exoticDrug or props.drug or props.dose) and props.affliction then
            return {
                type = "drug_affliction",
                target = "self",
                affliction = props.affliction,
                afflictionName = props.afflictionName,
                maxStage = props.maxStage,
                stageCosts = props.stageCosts,
                stageRecovery = props.stageRecovery,
                stageEffects = props.stageEffects,
                quitCharges = props.quitCharges,
                recentlyTakenEffect = props.recentlyTakenEffect,
                reexposureClearsCuredStage = props.reexposureClearsCuredStage,
            }
        end

        if props.effect == "heal_wound" then
            return { type = "heal_wound", target = "self_or_target" }
        elseif props.effect == "cure_poison" then
            return {
                type = "clear_conditions",
                target = "self_or_target",
                conditions = { "poisoned", "poison" },
                successMessage = "Poison cured.",
            }
        end

        return nil
    end

    function resolver:getActionZoneTarget(action, zoneRef)
        if not action then
            return nil
        end

        if type(zoneRef) == "table" then
            return zoneRef
        end

        if type(action.target) == "table" then
            local target = action.target
            if target.zoneHazard == true or target.isZone == true or target.special_rules or target.adjacent_to or
               target.hazards or target.caltrops then
                return target
            end
        end

        local zoneId = zoneRef or action.targetZoneId or action.targetZone or action.zoneId or action.zone or
            action.destinationZone or (action.actor and action.actor.zone)
        if type(zoneId) == "table" then
            return zoneId
        end
        if not zoneId then
            return nil
        end

        if self.zoneSystem and self.zoneSystem.getZone then
            local zone = self.zoneSystem:getZone(zoneId)
            if zone then
                return zone
            end
        end

        local zones = action.challengeController and action.challengeController.zones
        for _, zone in ipairs(zones or {}) do
            if zone.id == zoneId or zone.name == zoneId then
                return zone
            end
        end

        return nil
    end

    function resolver:getItemEffectTarget(action, effect)
        local targetMode = effect and effect.target or "self_or_target"

        if targetMode == "self" or targetMode == "actor" then
            return action.actor
        elseif targetMode == "target" then
            return action.target
        elseif targetMode == "zone" or targetMode == "target_zone" then
            return self:getActionZoneTarget(action)
        elseif targetMode == "self_or_target" then
            return action.target or action.actor
        end

        return action.target or action.actor
    end

    function resolver:isContestedItemUse(actor, target, item, action)
        if action and action.contestedUseItem ~= nil then
            return action.contestedUseItem
        end
        if not target or target == actor then
            return false
        end

        local props = item and item.properties or {}
        if props.bomb or props.offensive or props.hostileUse then
            return true
        end

        if actor and target and actor.isPC ~= nil and target.isPC ~= nil then
            return actor.isPC ~= target.isPC
        end

        return false
    end

    function resolver:resolveAegisItemUseSubstitution(action, result, item)
        if not (action and result and item and action.target) then
            return false
        end
        if not isAttackLikeItemUse(action) then
            return false
        end

        local target = action.target
        local aegisResult = self:resolveAegisDamageSubstitution(target, result.effects, item,
            self:getActionWoundOptions(action, target), {
                source = "attack",
                physical = true,
                action = action,
                result = result,
                useAegis = action.useAegis,
            })
        if not aegisResult then
            return false
        end

        result.aegisResult = aegisResult
        result.itemEffect = {
            type = "aegis_prevented_item_use",
            target = target,
            prevented = true,
            shield = aegisResult.shield,
        }
        result.effects[#result.effects + 1] = "item_attack_like_aegis_prevented"
        result.description = "Aegis prevents " .. (item.name or "the item") .. "."
        return true
    end

    function resolver:shouldConsumeItemOnUse(item, result, attempted)
        local props = item and item.properties or {}

        if props.consumeOnAttempt then
            return attempted
        end
        if props.consumeOnMiss and attempted and not result.success then
            return true
        end
        if props.consumable or props.potion or props.bomb or props.oil or props.alchemical then
            return result.success
        end

        return false
    end

    function resolver:consumeUsedItem(inventory, item, result)
        if not inventory or not item then
            return
        end

        local ok = false
        local status = nil
        if item.stackable and inventory.removeItemQuantity then
            ok, status = inventory:removeItemQuantity(item.id, 1)
        elseif inventory.removeItem then
            local removed = inventory:removeItem(item.id)
            ok = removed ~= nil
            status = ok and "removed" or nil
        end

        if ok then
            if status == "removed" or not item.stackable then
                item.destroyed = true
            end
            result.consumedItem = item
            result.consumedItemStatus = status
            result.effects[#result.effects + 1] = "item_consumed"
        end
    end

    function resolver:clearTargetConditions(target, conditionList)
        if not target then
            return nil
        end

        target.conditions = target.conditions or {}
        for _, condition in ipairs(conditionList or {}) do
            if target.conditions[condition] then
                target.conditions[condition] = false
                return condition
            end
        end

        return nil
    end

    function resolver:isPoisonImmune(target)
        if not target then
            return false
        end

        local conditions = target.conditions or {}
        local props = target.properties or {}
        return target.poisonImmune == true or target.cannotBePoisoned == true or
            conditions.poison_immunity == true or conditions.poisonImmune == true or
            props.poison_immunity == true or props.poisonImmune == true or
            entityHasNormalizedTag(target, "poison_immune") or
            (target.fungoid and target.fungoid.poisonImmune == true) or
            (target.ogre and target.ogre.cannotBePoisoned == true) or
            (target.lich and target.lich.body and target.lich.body.cannotBePoisoned == true) or
            (target.devil and target.devil.endlessGullet and target.devil.endlessGullet.poisonImmune == true)
    end

    function resolver:recordPoisonBlocked(target, result, condition, source)
        result.poisonBlocked = result.poisonBlocked or {}
        result.poisonBlocked[#result.poisonBlocked + 1] = condition

        local function hasEffect(effect)
            for _, existing in ipairs(result.effects or {}) do
                if existing == effect then
                    return true
                end
            end
            return false
        end

        if not hasEffect("poison_immunity") then
            result.effects[#result.effects + 1] = "poison_immunity"
        end
        if not hasEffect("poison_blocked") then
            result.effects[#result.effects + 1] = "poison_blocked"
        end

        self.eventBus:emit("poison_blocked", {
            target = target,
            condition = condition,
            source = source,
        })
    end

    function resolver:destroyTargetArmor(target, result)
        if not target then
            return false
        end

        local destroyed = false
        local destroyedItems = {}

        if target.isPC then
            if (target.armorSlots or 0) > 0 or (target.armorNotches or 0) > 0 then
                target.armorSlots = 0
                target.armorNotches = 0
                target.armorDestroyed = true
                destroyed = true
            end

            local armorCandidates = {}
            if target.armor then
                armorCandidates[#armorCandidates + 1] = target.armor
            end
            if target.wornArmor then
                armorCandidates[#armorCandidates + 1] = target.wornArmor
            end
            if target.equippedArmor then
                armorCandidates[#armorCandidates + 1] = target.equippedArmor
            end
            if target.inventory and target.inventory.belt then
                for _, item in ipairs(target.inventory.belt) do
                    armorCandidates[#armorCandidates + 1] = item
                end
            end

            for _, armor in ipairs(armorCandidates) do
                local armorProps = armor and armor.properties or {}
                if armor and armor.destroyed ~= true and (armor.isArmor == true or armorProps.armor == true) then
                    armor.destroyed = true
                    armor.notches = armor.durability or armor.notches or 0
                    armor.destroyedBySlimeBomb = true
                    armorProps.destroyed = true
                    armorProps.destroyedBySlimeBomb = true
                    destroyedItems[#destroyedItems + 1] = armor
                    destroyed = true
                end
            end
        else
            if (target.npcDefense or 0) > 0 or (target.npcMaxDefense or 0) > 0 then
                target.npcDefense = 0
                target.npcMaxDefense = 0
                destroyed = true
            end
        end

        if destroyed then
            result.effects[#result.effects + 1] = "armor_destroyed"
        end
        if #destroyedItems > 0 then
            target.armorDestroyed = true
            result.destroyedArmorItems = destroyedItems
            result.effects[#result.effects + 1] = "armor_item_destroyed"
        end

        return destroyed
    end

    local function tableContainsValue(list, value)
        if type(list) ~= "table" then
            return false
        end

        for _, entry in ipairs(list) do
            if entry == value then
                return true
            end
        end

        return false
    end

    local function hasTag(entity, tag)
        local tags = entity and entity.tags
        if type(tags) == "table" then
            if tags[tag] then
                return true
            end

            if tableContainsValue(tags, tag) then
                return true
            end
        end

        local aiTags = entity and entity.aiTags
        if type(aiTags) == "table" then
            if aiTags[tag] then
                return true
            end

            if tableContainsValue(aiTags, tag) then
                return true
            end
        end

        return false
    end

    local medicalMotifTerms = {
        "medical",
        "medicine",
        "medic",
        "doctor",
        "physician",
        "surgeon",
        "chirurgeon",
        "healer",
        "herbalist",
        "apothecary",
        "midwife",
    }

    local function motifContainsMedicalTerm(motif)
        local lower = string.lower(tostring(motif or ""))
        for _, term in ipairs(medicalMotifTerms) do
            if string.find(lower, term, 1, true) then
                return true
            end
        end
        return false
    end

    function resolver:getMedicalMotif(actor, declaredMotif)
        if not actor then
            return nil
        end

        if declaredMotif and actor.hasMotif then
            local hasDeclared, motif = actor:hasMotif(declaredMotif)
            if hasDeclared then
                return motif or declaredMotif
            end
        end

        for _, motif in ipairs(actor.motifs or {}) do
            if motifContainsMedicalTerm(motif) then
                return motif
            end
        end

        if actor.talents and actor.talents.chirurgeon then
            return "Chirurgeon"
        end

        return nil
    end

    function resolver:applyItemUseAttribute(action, result, effect)
        if not action or not result or not effect or not effect.attribute then
            return
        end

        local actor = action.actor
        local attribute = effect.attribute
        local modifier = actor and actor[attribute] or 0
        result.modifier = modifier
        result.testValue = (result.cardValue or (action.card and action.card.value) or 0) + modifier
        result.itemUseAttribute = attribute
    end

    function resolver:isWardAffectedTarget(target, affectedTags, effect)
        if not target then
            return false
        end

        if not (effect and effect.defaultUndeadSpirit == false) and (target.undead or target.spirit) then
            return true
        end

        for _, tag in ipairs(affectedTags or {}) do
            if hasTag(target, tag) then
                return true
            end
        end

        return false
    end

    function resolver:hasAnyTargetTag(target, tags)
        if not target then
            return false
        end

        for _, tag in ipairs(tags or {}) do
            if hasTag(target, tag) or target[tag] then
                return true
            end
        end

        return false
    end

    function resolver:getCaltropHazards(zone)
        local hazards = {}
        if not zone then
            return hazards
        end

        for _, hazard in ipairs(zone.caltrops or {}) do
            if hazard.active ~= false then
                hazards[#hazards + 1] = hazard
            end
        end

        for _, hazard in ipairs(zone.hazards or {}) do
            if hazard.type == "caltrops" and hazard.active ~= false then
                local duplicate = false
                for _, existing in ipairs(hazards) do
                    if existing == hazard then
                        duplicate = true
                        break
                    end
                end
                if not duplicate then
                    hazards[#hazards + 1] = hazard
                end
            end
        end

        local props = zone.properties or {}
        if props.caltrops == true and #hazards == 0 then
            hazards[#hazards + 1] = {
                type = "caltrops",
                wound = 1,
                affected = "unshod",
                active = true,
            }
        end

        return hazards
    end

    function resolver:getFrictionlessPuddleHazards(zone)
        local hazards = {}
        if not zone then
            return hazards
        end

        local function addHazard(hazard)
            if not hazard or hazard.active == false then
                return
            end
            hazards[#hazards + 1] = hazard
        end

        addHazard(zone.slipperyPuddle)
        addHazard(zone.frictionlessPuddle)

        for _, hazard in ipairs(zone.hazards or {}) do
            local hazardType = normalizeTalentKey(hazard.type or hazard.kind or hazard.hazard)
            if hazardType == "slippery_puddle" or hazardType == "frictionless_puddle" or
               hazardType == "frictionless" then
                addHazard(hazard)
            end
        end

        local props = zone.properties or {}
        if (props.slipperyPuddle == true or props.frictionlessPuddle == true) and #hazards == 0 then
            hazards[#hazards + 1] = {
                type = "slippery_puddle",
                diameterFeet = props.puddleDiameterFeet or 10,
                frictionless = true,
                active = true,
            }
        end

        return hazards
    end

    function resolver:isCaltropWalkingMovement(actor, action)
        action = action or {}
        local conditions = actor and actor.conditions or {}
        if action.ignoreCaltrops == true or action.caltropsIgnored == true then
            return false
        end
        if action.flying == true or action.flight == true or action.levitating == true or
           action.levitation == true or action.flyByAttack == true or
           (actor and (actor.flying == true or actor.levitating == true)) or
           conditions.flying == true or conditions.levitating == true then
            return false
        end

        local mode = normalizeTalentKey(action.movementMode or action.traversalMode or action.traversal or
            action.terrainMode)
        if mode == "fly" or mode == "flight" or mode == "flying" or mode == "levitate" or
           mode == "levitating" or mode == "water_walk" or mode == "water_walking" then
            return false
        end

        return action.walking ~= false
    end

    function resolver:isUnshodForCaltrops(entity)
        if not entity then
            return false
        end

        local conditions = entity.conditions or {}
        local props = entity.properties or {}
        if entity.shod == true or entity.wearingShoes == true or entity.wearingBoots == true or
           entity.boots == true or props.shod == true or props.wearingShoes == true or
           props.wearingBoots == true or props.boots == true or conditions.shod == true or
           conditions.wearingBoots == true then
            return false
        end

        if entity.unshod == true or entity.barefoot == true or entity.bareFooted == true or
           entity.shod == false or entity.wearingShoes == false or entity.wearingBoots == false or
           props.unshod == true or props.barefoot == true or props.bareFooted == true or
           props.shod == false or props.wearingShoes == false or props.wearingBoots == false or
           conditions.unshod == true or conditions.barefoot == true or hasTag(entity, "unshod") or
           hasTag(entity, "barefoot") then
            return true
        end

        return false
    end

    function resolver:applyCaltropZoneEntry(actor, zoneRef, action, result)
        local zone = type(zoneRef) == "table" and zoneRef or self:getActionZoneTarget(action, zoneRef)
        local hazards = self:getCaltropHazards(zone)
        if #hazards == 0 then
            return nil
        end

        local record = {
            zone = zone,
            zoneId = zone and zone.id or zoneRef,
            hazards = hazards,
            triggered = false,
        }

        result.caltrops = record

        if not self:isCaltropWalkingMovement(actor, action) then
            record.ignoredReason = "not_walking"
            result.effects[#result.effects + 1] = "caltrops_bypassed"
            return record
        end

        if not self:isUnshodForCaltrops(actor) then
            record.ignoredReason = "shod"
            result.effects[#result.effects + 1] = "caltrops_shod_ignored"
            return record
        end

        local hazard = hazards[1]
        local amount = hazard.wound or hazard.wounds or 1
        local damageEffects = { "caltrops", "hazard" }
        local damageResult = self:applyDamage(actor, amount, damageEffects, nil, action and action.allEntities,
            self:getActionWoundOptions(action, actor), {
                source = "hazard",
                physical = true,
                trap = true,
                itemHazard = true,
                action = action,
                result = result,
                useAegis = action and action.useAegis,
            })
        local preventedByAegis = damageResult and damageResult.prevented and damageResult.shield

        record.triggered = true
        record.hazard = hazard
        record.wounds = preventedByAegis and 0 or amount
        record.damageResult = damageResult
        if preventedByAegis then
            record.prevented = true
            record.aegisResult = damageResult
            result.aegisResult = damageResult
        end
        result.caltropWounds = (result.caltropWounds or 0) + record.wounds
        for _, effect in ipairs(damageEffects) do
            result.effects[#result.effects + 1] = effect
        end
        result.effects[#result.effects + 1] = "caltrops_triggered"
        if preventedByAegis then
            result.effects[#result.effects + 1] = "caltrops_wound_prevented"
        else
            result.effects[#result.effects + 1] = "caltrops_wound"
        end
        if result.description and result.description ~= "" then
            if preventedByAegis then
                result.description = result.description .. "; Aegis prevents the caltrops wound."
            else
                result.description = result.description .. "; caltrops wound " .. (actor.name or "the mover") .. "."
            end
        end
        return record
    end

    function resolver:getFrictionlessPuddleTestResult(action)
        if not action then
            return nil
        end
        local test = action.slipperyPuddleTestResult or action.frictionlessPuddleTestResult or
            action.puddleTestResult
        if type(test) == "table" then
            return test.success == true
        end
        if type(test) == "boolean" then
            return test
        end
        return nil
    end

    function resolver:applyFrictionlessPuddleZoneEntry(actor, zoneRef, action, result)
        local zone = type(zoneRef) == "table" and zoneRef or self:getActionZoneTarget(action, zoneRef)
        local hazards = self:getFrictionlessPuddleHazards(zone)
        if #hazards == 0 then
            return nil
        end

        local record = {
            zone = zone,
            zoneId = zone and zone.id or zoneRef,
            hazards = hazards,
            triggered = false,
        }
        result.frictionlessPuddle = record

        if not self:isCaltropWalkingMovement(actor, action) then
            record.ignoredReason = "not_walking"
            result.effects[#result.effects + 1] = "slippery_puddle_bypassed"
            return record
        end

        record.triggered = true
        record.hazard = hazards[1]
        result.effects[#result.effects + 1] = "slippery_puddle_entered"
        result.effects[#result.effects + 1] = "frictionless_traversal_hazard"

        local passed = self:getFrictionlessPuddleTestResult(action)
        if passed == nil then
            record.requiresTest = true
            result.effects[#result.effects + 1] = "slippery_puddle_test_required"
            return record
        end

        record.testPassed = passed
        if passed then
            result.effects[#result.effects + 1] = "slippery_puddle_crossed"
        else
            actor.conditions = actor.conditions or {}
            actor.conditions.prone = true
            record.slipped = true
            result.effects[#result.effects + 1] = "slippery_puddle_slip"
            result.effects[#result.effects + 1] = "prone"
            if result.description and result.description ~= "" then
                result.description = result.description .. "; " .. (actor.name or "the mover") ..
                    " slips and falls prone."
            end
        end
        return record
    end

    function resolver:resolveChirurgeonPoulticeHeal(action, result, item, effect, target)
        if not entityHasUsableTalent(action and action.actor, "chirurgeon") then
            result.success = false
            result.itemEffect = { type = "poultice_deaths_door", noEffect = true }
            result.description = effect.noEffectMessage or
                ((item.name or "Poultice") .. " can only save someone at Death's Door unless applied by a Chirurgeon.")
            result.effects[#result.effects + 1] = "poultice_no_effect"
            result.itemUseAttempted = false
            return false
        end

        if target.conditions and target.conditions.dead then
            result.success = false
            result.itemEffect = { type = "chirurgeon_poultice_heal", noEffect = true }
            result.description = "Too late for a poultice."
            result.effects[#result.effects + 1] = "poultice_too_late"
            result.itemUseAttempted = false
            return false
        end

        if not target.healWound and not animal_companions.isAnimalCompanion(target) then
            result.success = false
            result.itemEffect = { type = "chirurgeon_poultice_heal", noEffect = true }
            result.description = "No healable target."
            result.effects[#result.effects + 1] = "item_effect_failed"
            result.itemUseAttempted = false
            return false
        end
        if target.immuneToHealEffect or target.immuneToHeal then
            result.success = false
            result.itemEffect = { type = "chirurgeon_poultice_heal", noEffect = true }
            result.description = "Cannot heal: immune to the Heal effect."
            result.effects[#result.effects + 1] = "heal_immune"
            result.itemUseAttempted = false
            return false
        end

        local healResult, err = self:healTargetWound(target)
        if healResult then
            result.itemEffect = { type = "chirurgeon_poultice_heal", result = healResult }
            result.description = effect.chirurgeonSuccessMessage or "Poultice applied: " .. healResult
            result.effects[#result.effects + 1] = "chirurgeon_poultice"
            result.effects[#result.effects + 1] = "healed"
            return true
        end

        result.success = false
        result.itemEffect = { type = "chirurgeon_poultice_heal", failed = true, error = err }
        result.description = "Cannot heal: " .. (err or "unknown")
        if err == "healing_blocked" then
            result.effects[#result.effects + 1] = "healing_blocked"
        else
            result.effects[#result.effects + 1] = "item_effect_failed"
        end
        result.itemUseAttempted = false
        return false
    end

    function resolver:resolvePoulticeDeathsDoor(action, result, item, effect, target)
        if not target.conditions or not target.conditions.deaths_door then
            return self:resolveChirurgeonPoulticeHeal(action, result, item, effect, target)
        end

        if target.conditions.dead then
            result.success = false
            result.itemEffect = { type = "poultice_deaths_door", noEffect = true }
            result.description = "Too late for a poultice."
            result.effects[#result.effects + 1] = "poultice_too_late"
            return false
        end

        local card = action.poulticeCard or action.testCard or action.card or {}
        local woundedWands = target.getAttribute and target:getAttribute(constants.SUITS.WANDS) or (target.wands or 0)
        local medicalMotif = action.medicalFavor and (action.medicalMotif or "medical motif") or
                             self:getMedicalMotif(action.actor, action.medicalMotif)
        local favorModifier = medicalMotif and 3 or 0
        local total = (card.value or 0) + woundedWands + favorModifier
        local difficulty = effect.difficulty or action.poulticeDifficulty or 14
        local greatFailure = action.poulticeGreatFailure or action.greatFailure or
                             (action.testResult and action.testResult.isGreat and not action.testResult.success)
        local success = not greatFailure and total >= difficulty

        result.cardValue = card.value or result.cardValue or 0
        result.modifier = woundedWands + favorModifier
        result.testValue = total
        result.difficulty = difficulty
        result.favor = medicalMotif and true or nil
        result.poulticeTest = {
            card = card,
            attribute = "wands",
            targetSuit = constants.SUITS.WANDS,
            target = target,
            applier = action.actor,
            medicalMotif = medicalMotif,
            total = total,
            difficulty = difficulty,
            success = success,
            greatFailure = greatFailure,
        }

        if success then
            local healResult = self:healTargetWound(target)
            result.success = healResult ~= nil
            result.itemEffect = { type = "poultice_deaths_door", result = healResult }
            if result.success then
                result.description = effect.successMessage or "Poultice applied: Death's Door cleared."
                result.effects[#result.effects + 1] = "poultice_success"
                result.effects[#result.effects + 1] = "healed"
                return true
            end
        end

        target.conditions.dead = true
        result.success = false
        result.itemEffect = { type = "poultice_deaths_door", result = "dead" }
        result.description = effect.failureMessage or "Poultice failed: the character dies."
        result.effects[#result.effects + 1] = "poultice_failed"
        result.effects[#result.effects + 1] = "entity_dead"

        if greatFailure then
            local zombie = entity_factory.createUndeadFromAdventurer(target, "zombie", {
                location = target.location,
                zone = target.zone,
            })
            if zombie then
                if target.markUndeadRaised then
                    target:markUndeadRaised(zombie, action.currentWatch or action.watchNumber)
                end
                result.undeadRaised = zombie
                result.effects[#result.effects + 1] = "zombie_raised"
                result.description = "Poultice failed catastrophically: the character dies and instantly rises as a zombie."
                self.eventBus:emit(events.EVENTS.UNDEAD_RAISED, {
                    source = target,
                    undead = zombie,
                    undeadType = "zombie",
                    reason = "poultice_great_failure",
                    watchNumber = action.currentWatch or action.watchNumber,
                })
            end
        elseif target.scheduleUndeadRise then
            result.pendingUndeadRise = target:scheduleUndeadRise("zombie", action.currentWatch or action.watchNumber, {
                reason = "poultice_failed",
            })
            result.effects[#result.effects + 1] = "zombie_rise_scheduled"
        end

        self.eventBus:emit(events.EVENTS.ENTITY_DEFEATED, {
            entity = target,
            reason = greatFailure and "poultice_great_failure" or "poultice_failed",
            item = item,
        })

        return false
    end

    function resolver:potionHasNoEffect(target)
        if not target then
            return false
        end

        local props = target.properties or {}
        local conditions = target.conditions or {}
        if isNonLivingObjectTarget(target) or target.isItem or target.itemType or target.isObject or
           target.object or target.scenery or props.object or props.isObject or props.scenery then
            return true
        end

        return target.undead == true or target.isUndead == true or
            target.construct == true or target.automaton == true or
            target.livingProcesses == false or target.hasLivingProcesses == false or
            target.alive == false or target.dead == true or conditions.dead == true or
            props.undead == true or props.isUndead == true or
            props.construct == true or props.automaton == true or
            props.livingProcesses == false or props.hasLivingProcesses == false or
            hasTag(target, "undead")
            or hasTag(target, "construct")
            or hasTag(target, "automaton")
    end

    function resolver:copyDrugAfflictionMetadata(value)
        if type(value) ~= "table" then
            return value
        end
        local copy = {}
        for key, entry in pairs(value) do
            if type(entry) == "table" then
                local nested = {}
                for nestedKey, nestedValue in pairs(entry) do
                    nested[nestedKey] = nestedValue
                end
                copy[key] = nested
            else
                copy[key] = entry
            end
        end
        return copy
    end

    function resolver:applyGhostLotusAfflictionState(target, affliction, result)
        if not target or not affliction then
            return
        end

        local stage = tonumber(affliction.stage or affliction.currentStage or affliction.progressStage) or 1
        target.conditions = target.conditions or {}
        target.conditions.ghost_lotus_euphoria = stage >= 1
        target.ghostLotusEuphoria = stage >= 1

        if stage >= 2 then
            target.conditions.cannot_read = true
            target.conditions.cannot_write = true
            target.conditions.cannot_read_or_write = true
            target.conditions.illusionImmune = true
            target.conditions.immune_to_illusions = true
            target.cannotRead = true
            target.cannotWrite = true
            target.immuneToIllusions = true
            target.ghostLotusCannotReadWrite = true
            target.ghostLotusIllusionImmune = true
            if result then
                result.effects[#result.effects + 1] = "ghost_lotus_read_write_block"
                result.effects[#result.effects + 1] = "ghost_lotus_illusion_immune"
            end
        end

        if stage >= 3 then
            target.ghostLotusMotifRewritePending = true
            target.conditions.ghost_lotus_waking_dream = true
        end
    end

    function resolver:rewriteGhostLotusMotif(actor, opts)
        opts = opts or {}
        if not actor then
            return false, "missing_actor"
        end
        if not hasGhostLotusStage(actor, 3) then
            return false, "ghost_lotus_stage_3_required"
        end

        local motifs = actor.motifs
        local index = math.max(1, tonumber(opts.index or opts.motifIndex or opts.descriptorIndex) or 1)
        local oldMotif = type(motifs) == "table" and motifs[index]
        if not oldMotif then
            return false, "motif_missing"
        end

        local replacement = opts.newDescriptor or opts.replacementDescriptor or opts.descriptor
        local fullMotif = opts.newMotif or opts.rewrittenMotif
        if not fullMotif and (replacement == nil or tostring(replacement) == "") then
            return false, "replacement_descriptor_missing"
        end

        local tail = tostring(oldMotif):match("^%S+%s+(.+)$") or tostring(oldMotif)
        local rewritten = fullMotif or (tostring(replacement) .. " " .. tail)
        motifs[index] = rewritten

        local record = {
            source = "ghost_lotus",
            affliction = "ghost_lotus",
            stage = 3,
            index = index,
            oldMotif = oldMotif,
            newMotif = rewritten,
            replacementDescriptor = replacement,
        }
        actor.ghostLotusMotifRewrites = actor.ghostLotusMotifRewrites or {}
        actor.ghostLotusMotifRewrites[#actor.ghostLotusMotifRewrites + 1] = record
        actor.ghostLotusMotifRewritePending = false
        actor.lastGhostLotusMotifRewrite = record
        return true, record
    end

    function resolver:applyDrugAfflictionDose(action, result, item, effect, target)
        target = target or action.actor
        if not target then
            result.success = false
            result.description = "No target for drug dose."
            result.effects[#result.effects + 1] = "item_target_missing"
            return false
        end

        local props = item and item.properties or {}
        local afflictionId = effect.affliction or props.affliction or item.drugId or "drug_affliction"
        target.afflictions = target.afflictions or {}
        local affliction = target.afflictions[afflictionId]
        local reexposed = affliction ~= nil

        if not affliction then
            affliction = {
                id = afflictionId,
                name = effect.afflictionName or props.afflictionName or item.name or afflictionId,
                source = "exotic_drug",
                sourceItemId = item and item.id,
                stage = 1,
                maxStage = effect.maxStage or props.maxStage,
                stageCosts = self:copyDrugAfflictionMetadata(effect.stageCosts or props.stageCosts),
                stageRecovery = self:copyDrugAfflictionMetadata(effect.stageRecovery or props.stageRecovery),
                stageEffects = self:copyDrugAfflictionMetadata(effect.stageEffects or props.stageEffects),
                quitCharges = effect.quitCharges or props.quitCharges,
            }
            target.afflictions[afflictionId] = affliction
        else
            affliction.stage = math.max(affliction.stage or 1, 1)
            affliction.maxStage = affliction.maxStage or effect.maxStage or props.maxStage
            affliction.stageCosts = affliction.stageCosts or
                self:copyDrugAfflictionMetadata(effect.stageCosts or props.stageCosts)
            affliction.stageRecovery = affliction.stageRecovery or
                self:copyDrugAfflictionMetadata(effect.stageRecovery or props.stageRecovery)
            affliction.stageEffects = affliction.stageEffects or
                self:copyDrugAfflictionMetadata(effect.stageEffects or props.stageEffects)
            affliction.quitCharges = affliction.quitCharges or effect.quitCharges or props.quitCharges
        end

        local clearedStage = effect.reexposureClearsCuredStage or props.reexposureClearsCuredStage
        if clearedStage and affliction.curedStages then
            affliction.curedStages[clearedStage] = nil
            result.effects[#result.effects + 1] = "drug_reexposure_uncured_stage"
        end

        local recentlyTakenEffect = effect.recentlyTakenEffect or props.recentlyTakenEffect
        if recentlyTakenEffect then
            affliction.recentlyTaken = true
            affliction.recentlyTakenEffect = recentlyTakenEffect
            target.recentDrugEffects = target.recentDrugEffects or {}
            target.recentDrugEffects[afflictionId] = recentlyTakenEffect
            if afflictionId == "black_honey" then
                target.blackHoneyRecentlyTaken = true
                target.blackHoneyDrawFiveCards = true
            end
        end

        if afflictionId == "ghost_lotus" or afflictionId == "ghostLotus" then
            self:applyGhostLotusAfflictionState(target, affliction, result)
        end

        result.itemEffect = {
            type = "drug_affliction",
            affliction = afflictionId,
            afflictionRecord = affliction,
            reexposed = reexposed,
            recentlyTakenEffect = recentlyTakenEffect,
        }
        result.drugAffliction = affliction
        result.description = (item.name or "Drug") .. " taken; " .. (affliction.name or afflictionId) ..
            " affliction recorded."
        result.effects[#result.effects + 1] = "drug_affliction"
        result.effects[#result.effects + 1] = afflictionId
        return true
    end

    function resolver:materialIsImmune(target, materials)
        local props = target and target.properties or {}
        local material = props.material or target.material
        return material ~= nil and tableContainsValue(materials, material)
    end

    function resolver:destroyObjectTarget(target, effect, result)
        if not target then
            return false
        end

        local props = target.properties or {}
        if target.magical or props.magical then
            result.effects[#result.effects + 1] = "object_resisted"
            return false
        end

        if self:materialIsImmune(target, effect.immuneMaterials) then
            result.effects[#result.effects + 1] = "material_resisted"
            return false
        end

        if target.durability or target.notches then
            target.notches = target.durability or target.notches or 1
        end
        target.destroyed = true
        result.effects[#result.effects + 1] = "object_destroyed"
        return true
    end

    function resolver:isRestrainablePerson(target)
        if not target or target.isItem or target.itemType then
            return false
        end

        local props = target.properties or {}
        if props.object or props.scenery or target.construct or target.automaton or target.ooze or target.slime or
           target.animal or target.beast then
            return false
        end

        if target.isPC or target.person or target.humanoid or target.kith or target.kin or
           self:hasAnyTargetTag(target, { "person", "humanoid", "kith", "kin" }) then
            return true
        end

        return target.conditions ~= nil or target.isPC ~= nil
    end

    function resolver:applyManaclesRestraint(action, result, item, effect, target)
        if not self:isRestrainablePerson(target) then
            result.success = false
            result.itemEffect = { type = "restrain_person", noEffect = true }
            result.description = effect.noEffectMessage or ((item.name or "Manacles") .. " can only restrain people.")
            result.effects[#result.effects + 1] = "manacles_no_effect"
            return false
        end

        if item.restrainingTargetId and item.restrainingTargetId ~= target.id then
            result.success = false
            result.itemEffect = { type = "restrain_person", alreadyInUse = true }
            result.description = (item.name or "Manacles") .. " are already restraining someone."
            result.effects[#result.effects + 1] = "manacles_already_in_use"
            return false
        end

        target.conditions = target.conditions or {}
        target.conditions.restrained = true
        target.conditions.manacled = true
        target.conditions.rooted = true
        target.restrained = true
        target.manacled = true
        target.restrainedBy = action.actor
        target.restrainedById = action.actor and action.actor.id or nil
        target.restrainingItem = item
        target.restrainingItemId = item.id
        target.readyForCityReward = true
        target.canTurnInForReward = true

        item.restrainingTarget = target
        item.restrainingTargetId = target.id
        item.inUseAsRestraint = true
        item.committedAsRestraint = true

        result.itemEffect = {
            type = "restrain_person",
            target = target,
            item = item,
        }
        result.effects[#result.effects + 1] = "manacles_restrained"
        result.effects[#result.effects + 1] = "restrained"
        result.effects[#result.effects + 1] = "rooted"
        result.description = effect.successMessage or ((target.name or "Target") .. " is restrained in manacles.")
        return true
    end

    function resolver:isChainHaulTarget(target)
        if not target or target.isZone or target.zoneHazard then
            return false
        end

        local props = target.properties or {}
        if target.isItem or target.itemType or target.isObject or target.object or target.scenery or
           target.haulable or target.movable or props.object or props.scenery or props.haulable or
           props.movable then
            return true
        end

        local kind = normalizeSocialTag(target.type or target.kind or target.category) or ""
        return kind == "object" or kind == "feature" or kind == "door" or kind == "gate" or
            kind == "chest" or kind == "crate" or kind == "statue" or kind == "boulder" or
            kind == "portcullis" or kind == "mechanism"
    end

    function resolver:isSubduedForChainBinding(action, result, target)
        if not target then
            return false
        end

        if action and (action.contestedUseItem == true or action.chainContestSucceeded == true or
           action.allowChainOnActiveTarget == true) then
            return true
        end

        local actor = action and action.actor
        if actor and actor.isPC ~= nil and target.isPC ~= nil and actor.isPC ~= target.isPC and
           result and result.success then
            return true
        end

        local conditions = target.conditions or {}
        return target.defeated == true or target.beaten == true or target.subdued == true or
            target.knockedOut == true or conditions.knocked_out == true or conditions.knockedOut == true or
            conditions.unconscious == true or conditions.deaths_door == true or conditions.dead == true
    end

    function resolver:applyChainBindOrHaul(action, result, item, effect, target)
        if item.bindingTargetId and item.bindingTargetId ~= (target and target.id) then
            result.success = false
            result.itemEffect = { type = "bind_or_haul", alreadyInUse = true }
            result.description = (item.name or "Chain") .. " is already securing something."
            result.effects[#result.effects + 1] = "chain_already_in_use"
            return false
        end

        if self:isRestrainablePerson(target) then
            if not self:isSubduedForChainBinding(action, result, target) then
                result.success = false
                result.itemEffect = { type = "bind_or_haul", noEffect = true, reason = "not_subdued" }
                result.description = effect.noEffectMessage or ((item.name or "Chain") .. " needs a subdued target to bind.")
                result.effects[#result.effects + 1] = "chain_target_not_subdued"
                return false
            end

            target.conditions = target.conditions or {}
            target.conditions.restrained = true
            target.conditions.chain_bound = true
            target.conditions.rooted = true
            target.restrained = true
            target.chainBound = true
            target.restrainedBy = action.actor
            target.restrainedById = action.actor and action.actor.id or nil
            target.restrainingItem = item
            target.restrainingItemId = item.id
            target.haulableByChain = true

            item.bindingTarget = target
            item.bindingTargetId = target.id
            item.inUseAsBinding = true
            item.committedAsBinding = true

            result.itemEffect = {
                type = "bind_or_haul",
                target = target,
                item = item,
                bound = true,
            }
            result.effects[#result.effects + 1] = "chain_bound"
            result.effects[#result.effects + 1] = "restrained"
            result.effects[#result.effects + 1] = "rooted"
            result.description = effect.successMessage or ((target.name or "Target") .. " is secured with chain.")
            return true
        end

        if not self:isChainHaulTarget(target) then
            result.success = false
            result.itemEffect = { type = "bind_or_haul", noEffect = true }
            result.description = effect.noEffectMessage or ((item.name or "Chain") .. " needs a person or haulable object.")
            result.effects[#result.effects + 1] = "chain_no_effect"
            return false
        end

        target.properties = target.properties or {}
        target.properties.chainSecured = true
        target.properties.haulableByChain = true
        target.chainSecured = true
        target.tethered = true
        target.haulableByChain = true
        target.securedByChainId = item.id

        item.bindingTarget = target
        item.bindingTargetId = target.id
        item.inUseAsBinding = true
        item.committedAsBinding = true

        result.itemEffect = {
            type = "bind_or_haul",
            target = target,
            item = item,
            hauled = true,
        }
        result.effects[#result.effects + 1] = "chain_secured"
        result.effects[#result.effects + 1] = "chain_haulable"
        result.description = effect.successMessage or ((target.name or "Target") .. " is secured for hauling.")
        return true
    end

    function resolver:isCuttableMaterialTarget(target)
        if not target or type(target) ~= "table" then
            return false
        end

        local props = target.properties or {}
        if target.rope or target.vine or target.wood or target.wooden or target.tree or target.cuttable or
           props.rope or props.vine or props.wood or props.wooden or props.tree or props.cuttable then
            return true
        end

        local kind = normalizeSocialTag(target.type or target.kind or target.category) or ""
        local name = normalizeSocialTag(target.name or target.id) or ""
        return kind == "rope" or kind == "cord" or kind == "vine" or kind == "wood" or kind == "tree" or
            kind == "timber" or kind == "plant" or name:find("rope", 1, true) ~= nil or
            name:find("vine", 1, true) ~= nil or name:find("wood", 1, true) ~= nil or
            name:find("tree", 1, true) ~= nil or name:find("timber", 1, true) ~= nil
    end

    function resolver:applyCutMaterial(action, result, item, effect, target)
        if not self:isCuttableMaterialTarget(target) then
            result.success = false
            result.itemEffect = { type = "cut_material", noEffect = true }
            result.description = effect.noEffectMessage or ((item.name or "Hatchet") .. " needs rope, vines, or wood.")
            result.effects[#result.effects + 1] = "hatchet_no_effect"
            return false
        end

        target.properties = target.properties or {}
        target.cut = true
        target.severed = true
        target.properties.cut = true
        target.properties.severed = true
        target.cutByItemId = item and item.id or nil

        local props = target.properties
        local kind = normalizeSocialTag(target.type or target.kind or target.category) or ""
        local name = normalizeSocialTag(target.name or target.id) or ""
        local isWood = target.wood or target.wooden or target.tree or props.wood or props.wooden or props.tree or
            kind == "wood" or kind == "tree" or kind == "timber" or name:find("wood", 1, true) ~= nil or
            name:find("tree", 1, true) ~= nil or name:find("timber", 1, true) ~= nil

        if isWood then
            target.felled = true
            target.felledWood = true
            props.felled = true
            props.felledWood = true
            result.effects[#result.effects + 1] = "wood_felled"
        else
            result.effects[#result.effects + 1] = "rope_cut"
        end

        result.itemEffect = {
            type = "cut_material",
            target = target,
            item = item,
            felledWood = isWood,
        }
        result.effects[#result.effects + 1] = "hatchet_cut"
        result.description = effect.successMessage or ((item.name or "Hatchet") .. " cuts through the target.")
        return true
    end

    function resolver:spendOneItemUnit(action, result, item, reason)
        local actor = action and action.actor
        local inv = actor and actor.inventory
        if inv and item and item.stackable and item.id and inv.removeItemQuantity then
            local ok, status = inv:removeItemQuantity(item.id, 1)
            if ok then
                if status == "removed" then
                    item.quantity = 0
                    item.destroyed = true
                    result.itemDestroyed = true
                end
                result.spentItemUnit = {
                    item = item,
                    status = status,
                    reason = reason,
                }
                result.effects[#result.effects + 1] = "item_unit_spent"
                return true, status
            end
        end

        if item and item.stackable then
            local quantity = math.max(0, math.floor(tonumber(item.quantity) or 0))
            if quantity <= 0 then
                return false, "empty"
            end
            if quantity > 1 then
                item.quantity = quantity - 1
                result.spentItemUnit = {
                    item = item,
                    status = "decremented",
                    reason = reason,
                }
                result.effects[#result.effects + 1] = "item_unit_spent"
                return true, "decremented"
            end

            item.quantity = 0
            item.destroyed = true
            result.itemDestroyed = true
            result.spentItemUnit = {
                item = item,
                status = "removed",
                reason = reason,
            }
            result.effects[#result.effects + 1] = "item_unit_spent"
            return true, "removed"
        end

        return false, item and "not_stackable" or "missing_item"
    end

    function resolver:isDoorLikeTarget(target)
        if not target then
            return false
        end
        local props = target.properties or {}
        local kind = normalizeSocialTag(target.type or target.kind or target.category)
        local name = normalizeSocialTag(target.name or target.id) or ""
        return kind == "door" or kind == "gate" or kind == "portal" or props.door == true or props.gate == true or
            name:find("door", 1, true) ~= nil or name:find("gate", 1, true) ~= nil
    end

    function resolver:isPitonClimbingTarget(target)
        if not target then
            return false
        end
        local props = target.properties or {}
        local kind = normalizeSocialTag(target.type or target.kind or target.category)
        local name = normalizeSocialTag(target.name or target.id) or ""
        return target.climbable == true or target.requiresClimb == true or target.sheer == true or
            target.vertical == true or props.climbable == true or props.requiresClimb == true or
            props.sheer == true or props.vertical == true or kind == "climb" or kind == "climbing" or
            kind == "wall" or kind == "surface" or name:find("cliff", 1, true) ~= nil or
            name:find("wall", 1, true) ~= nil or name:find("shaft", 1, true) ~= nil or
            name:find("pit", 1, true) ~= nil
    end

    function resolver:applyIronSpikeWedge(action, result, item, effect, target)
        if not self:isDoorLikeTarget(target) then
            result.success = false
            result.itemEffect = { type = "iron_spike", noEffect = true }
            result.description = effect.noEffectMessage or "Iron spikes can only wedge a door or gate closed."
            result.effects[#result.effects + 1] = "iron_spike_no_effect"
            return false
        end
        if target.open == true or target.state == "open" then
            result.success = false
            result.itemEffect = { type = "iron_spike", open = true }
            result.description = "The " .. (target.name or "door") .. " must be closed before it can be wedged."
            result.effects[#result.effects + 1] = "iron_spike_requires_closed_door"
            return false
        end

        local spent, spendStatus = self:spendOneItemUnit(action, result, item, "iron_spike_wedge")
        if not spent then
            result.success = false
            result.itemEffect = { type = "iron_spike", empty = true }
            result.description = "No iron spike remains to wedge the " .. (target.name or "door") .. "."
            result.effects[#result.effects + 1] = "iron_spike_empty"
            return false
        end

        target.properties = target.properties or {}
        target.state = "wedged"
        target.wedgedClosed = true
        target.spikedClosed = true
        target.openBlocked = true
        target.canOpen = false
        target.spikesUsed = (target.spikesUsed or 0) + 1
        target.wedgedByItemId = item and item.id or nil
        target.properties.wedgedClosed = true
        target.properties.spikedClosed = true
        target.properties.openBlocked = true

        result.itemEffect = {
            type = "iron_spike",
            mode = "wedge",
            target = target,
            status = spendStatus,
        }
        result.effects[#result.effects + 1] = "iron_spike_wedged"
        result.effects[#result.effects + 1] = "door_wedged"
        result.description = effect.successMessage or
            ("You drive an iron spike into the " .. (target.name or "door") .. ", wedging it closed.")
        return true
    end

    function resolver:applyIronSpikePiton(action, result, item, effect, target)
        if not self:isPitonClimbingTarget(target) then
            result.success = false
            result.itemEffect = { type = "iron_spike", noEffect = true }
            result.description = effect.noEffectMessage or "There is no useful climbing surface to set a piton."
            result.effects[#result.effects + 1] = "iron_spike_no_effect"
            return false
        end

        local spent, spendStatus = self:spendOneItemUnit(action, result, item, "iron_spike_piton")
        if not spent then
            result.success = false
            result.itemEffect = { type = "iron_spike", empty = true }
            result.description = "No iron spike remains to use as a piton."
            result.effects[#result.effects + 1] = "iron_spike_empty"
            return false
        end

        target.properties = target.properties or {}
        target.pitonAnchors = (target.pitonAnchors or 0) + 1
        target.climbingAnchor = true
        target.climbAssisted = true
        target.properties.pitonAnchors = (target.properties.pitonAnchors or 0) + 1
        target.properties.climbingAnchor = true
        target.properties.climbAssisted = true
        target.properties.pitonItemId = item and item.id or nil

        result.itemEffect = {
            type = "iron_spike",
            mode = "piton",
            target = target,
            status = spendStatus,
        }
        result.effects[#result.effects + 1] = "iron_spike_piton"
        result.effects[#result.effects + 1] = "climbing_anchor"
        result.description = effect.successMessage or
            ("You drive an iron spike as a piton into the " .. (target.name or "surface") .. ".")
        return true
    end

    function resolver:isUndeadTarget(target)
        return target and (target.undead == true or target.isUndead == true or self:hasAnyTargetTag(target, { "undead" }))
    end

    function resolver:applyIronSpikeStakeUndead(action, result, item, effect, target)
        if not self:isUndeadTarget(target) then
            result.success = false
            result.itemEffect = { type = "iron_spike", noEffect = true }
            result.description = "Iron spikes can only be driven through the heart of the undead."
            result.effects[#result.effects + 1] = "iron_spike_no_effect"
            return false
        end

        local spent, spendStatus = self:spendOneItemUnit(action, result, item, "iron_spike_undead_heart")
        if not spent then
            result.success = false
            result.itemEffect = { type = "iron_spike", empty = true }
            result.description = "No iron spike remains to drive through the undead heart."
            result.effects[#result.effects + 1] = "iron_spike_empty"
            return false
        end

        target.conditions = target.conditions or {}
        target.conditions.staked = true
        target.conditions.undead_heart_staked = true
        target.conditions.rooted = true
        target.staked = true
        target.undeadHeartStaked = true
        target.rootedBy = target.rootedBy or "iron_spike"
        target.stakedBy = action.actor
        target.stakedById = action.actor and action.actor.id or nil
        target.stakingItemId = item and item.id or nil
        target.undeadRisePrevented = true
        target.preventUndeadRise = true
        target.cannotRiseAsUndead = true

        if target.undeadRise then
            target.undeadRise.prevented = true
            target.undeadRise.preventedBy = "iron_spike"
            target.undeadRise.bodyDestroyed = true
        end
        if self:isVampire(target) then
            target.vampireHeartStaked = true
            if type(target.vampire) == "table" then
                target.vampire.finalDeathRiteAttempted = "iron_spike"
            end
        end

        result.itemEffect = {
            type = "iron_spike",
            mode = "stake_undead",
            target = target,
            status = spendStatus,
        }
        result.effects[#result.effects + 1] = "iron_spike_undead_heart"
        result.effects[#result.effects + 1] = "undead_staked"
        result.effects[#result.effects + 1] = "rooted"
        result.description = effect.stakeMessage or
            ("You drive an iron spike through the heart of " .. (target.name or "the undead") .. ".")
        return true
    end

    function resolver:applyIronSpikeUse(action, result, item, effect, target)
        local mode = normalizeSocialTag(action.spikeUse or action.itemUse or action.intent or effect.mode or effect.defaultMode)
        if mode == "wedge_door" or mode == "door" or mode == "gate" then
            mode = "wedge"
        elseif mode == "anchor" or mode == "climb" or mode == "climbing" then
            mode = "piton"
        elseif mode == "stake" or mode == "stake_heart" or mode == "staking" or mode == "undead" or
               mode == "undead_heart" then
            mode = "stake_undead"
        end

        if not mode then
            if self:isDoorLikeTarget(target) then
                mode = "wedge"
            elseif self:isPitonClimbingTarget(target) then
                mode = "piton"
            elseif self:isUndeadTarget(target) then
                mode = "stake_undead"
            end
        end

        if mode == "wedge" then
            return self:applyIronSpikeWedge(action, result, item, effect, target)
        elseif mode == "piton" then
            return self:applyIronSpikePiton(action, result, item, effect, target)
        elseif mode == "stake_undead" then
            return self:applyIronSpikeStakeUndead(action, result, item, effect, target)
        end

        result.success = false
        result.itemEffect = { type = "iron_spike", noEffect = true }
        result.description = "Iron spikes can wedge doors, serve as climbing pitons, or stake undead hearts."
        result.effects[#result.effects + 1] = "iron_spike_no_effect"
        return false
    end

    function resolver:isFireStartTarget(target)
        if not target then
