        target.lit = true
        target.isLit = true
        target.fireStarted = true
        target.properties.isLit = true
        target.properties.lit = true
        target.properties.extinguished = false
        target.properties.fireStarted = true
        if target.properties.firewood or target.firewood or normalizeSocialTag(target.type) == "campfire" then
            target.campfire = true
            target.properties.campfire = true
        end

        result.itemEffect = {
            type = "start_fire",
            target = target,
            item = item,
        }
        result.effects[#result.effects + 1] = "fire_started"
        result.effects[#result.effects + 1] = "start_fire"
