    function resolver:isChalkMarkTarget(target)
        if not target or type(target) ~= "table" then
            return false
        end

        local props = target.properties or {}
        if target.isZone or target.zoneHazard or target.isObject or target.object or target.scenery or
           target.surface or props.object or props.scenery or props.surface or target.trap or target.hazard or
           target.hazards or target.caltrops then
            return true
        end

        local kind = normalizeSocialTag(target.type or target.kind or target.category) or ""
        return kind == "zone" or kind == "room" or kind == "feature" or kind == "surface" or
            kind == "door" or kind == "wall" or kind == "floor" or kind == "trap" or kind == "hazard" or
            kind == "passage" or kind == "corridor"
    end

    function resolver:applyChalkMark(action, result, item, effect, target)
        if not self:isChalkMarkTarget(target) then
            result.success = false
            result.itemEffect = { type = "mark_surface", noEffect = true }
            result.description = effect.noEffectMessage or ((item.name or "Chalk") .. " needs a markable surface.")
            result.effects[#result.effects + 1] = "chalk_no_effect"
            return false
        end

        local purpose = normalizeSocialTag(action.markPurpose or action.intent or effect.purpose) or "route"
        local label = action.markLabel or action.warning or action.note or effect.label
        target.properties = target.properties or {}
        target.chalkMarks = target.chalkMarks or {}
        local mark = {
            purpose = purpose,
            label = label,
            sourceItemId = item and item.id or nil,
            actorId = action.actor and action.actor.id or nil,
        }
        target.chalkMarks[#target.chalkMarks + 1] = mark
        target.chalkMarked = true
        target.properties.chalkMarked = true
        target.properties.lastChalkMarkPurpose = purpose

        local warnsHazard = purpose == "trap" or purpose == "trap_warning" or purpose == "warning" or
            target.trap ~= nil or target.hazard ~= nil or target.hazards ~= nil or target.caltrops ~= nil or
            target.properties.hiddenTrap == true or target.properties.hiddenHazard == true
        if warnsHazard then
            target.trapWarningMarked = true
            target.properties.trapWarningMarked = true
            result.effects[#result.effects + 1] = "chalk_trap_warning"
        else
            target.routeMarked = true
            target.properties.routeMarked = true
            result.effects[#result.effects + 1] = "chalk_route_mark"
        end

        result.itemEffect = {
            type = "mark_surface",
            target = target,
            item = item,
            mark = mark,
        }
        result.effects[#result.effects + 1] = "chalk_marked"
        result.description = effect.successMessage or "The chalk mark is left in place."
        return true
    end

    function resolver:isExcavationTarget(target)
        if not target or type(target) ~= "table" then
            return false
        end

        local props = target.properties or {}
        if target.diggable or target.buried or target.rubble or target.earth or target.soil or
           props.diggable or props.buried or props.rubble or props.earth or props.soil or
           props.blockedByRubble then
            return true
        end

        local kind = normalizeSocialTag(target.type or target.kind or target.category) or ""
        local name = normalizeSocialTag(target.name or target.id) or ""
        return kind == "earth" or kind == "soil" or kind == "ground" or kind == "rubble" or
            kind == "grave" or kind == "tunnel" or kind == "pit" or kind == "stone" or
            name:find("earth", 1, true) ~= nil or name:find("soil", 1, true) ~= nil or
            name:find("rubble", 1, true) ~= nil or name:find("grave", 1, true) ~= nil or
            name:find("tunnel", 1, true) ~= nil
    end

    function resolver:applyExcavate(action, result, item, effect, target)
        if not self:isExcavationTarget(target) then
            result.success = false
            result.itemEffect = { type = "excavate", noEffect = true }
            result.description = effect.noEffectMessage or ((item.name or "Tool") .. " needs earth, stone, or rubble to dig.")
            result.effects[#result.effects + 1] = "excavate_no_effect"
            return false
        end

        target.properties = target.properties or {}
        target.excavated = true
        target.digProgress = (target.digProgress or 0) + 1
        target.properties.excavated = true
        target.properties.digProgress = target.digProgress
        target.properties.dugBy = item and item.properties and item.properties.toolType or nil

        if target.buried or target.properties.buried then
            target.buried = false
            target.exposed = true
            target.properties.buried = false
            target.properties.exposed = true
            result.effects[#result.effects + 1] = "buried_target_exposed"
        end

        if target.rubble or target.properties.rubble or target.properties.blockedByRubble then
            target.rubbleCleared = true
            target.properties.rubbleCleared = true
            target.properties.blockedByRubble = false
            result.effects[#result.effects + 1] = "rubble_cleared"
        end

        result.itemEffect = {
            type = "excavate",
            target = target,
            item = item,
            toolType = item and item.properties and item.properties.toolType or nil,
            digProgress = target.digProgress,
        }
        result.effects[#result.effects + 1] = "excavated"
        result.effects[#result.effects + 1] = "digging_tool"
        result.description = effect.successMessage or ((item.name or "Tool") .. " digs into the target.")
        return true
    end

    function resolver:isPoleProbeTarget(target)
        if not target then
            return false
        end

        local props = target.properties or {}
        local kind = normalizeSocialTag(target.type or target.kind or target.category)
        if kind == "trap" or kind == "hazard" or kind == "pit" or kind == "pressure_plate" then
            return true
        end
        if target.trap or target.hazard or target.zoneHazard == true or target.hiddenTrap == true or
           target.hiddenHazard == true then
            return true
        end
        if props.trap or props.hazard or props.hiddenTrap or props.hiddenHazard or props.pressurePlate or
           props.pit or props.snare then
            return true
        end
        if type(target.hazards) == "table" and next(target.hazards) ~= nil then
            return true
        end
        if type(target.caltrops) == "table" and next(target.caltrops) ~= nil then
            return true
        end

        return false
    end

    function resolver:markPoleProbedRecord(record, sourceItem, reach)
        if type(record) ~= "table" then
            return false
        end

        record.detected = true
        record.probed = true
        record.probedByPole = true
        record.probedByItemId = sourceItem and sourceItem.id or nil
        record.probeReach = reach
        return true
    end

    function resolver:applyPoleProbe(action, result, item, effect, target)
        if not self:isPoleProbeTarget(target) then
            result.success = false
            result.itemEffect = { type = "probe_hazard", noEffect = true }
            result.description = effect.noEffectMessage or
                ((item.name or "Pole") .. " finds no obvious trap or hazard to probe.")
            result.effects[#result.effects + 1] = "pole_probe_no_effect"
            return false
        end

        local reach = effect.reach or "10ft"
        local props = target.properties or {}
        target.properties = props
        target.probed = true
        target.probedByPole = true
        target.detectedByPole = true
        target.probeReach = reach
        props.probed = true
        props.probedByPole = true
        props.detectedByPole = true
        props.probeReach = reach

        local probed = {}
        local trapDetected = false
        local hazardDetected = false

        local function recordProbe(kind, record)
            probed[#probed + 1] = {
                kind = kind,
                record = record,
            }
            if kind == "trap" then
                trapDetected = true
            else
                hazardDetected = true
            end
        end

        if self:markPoleProbedRecord(target.trap, item, reach) then
            recordProbe("trap", target.trap)
        elseif target.trap or target.hiddenTrap or props.trap or props.hiddenTrap then
            target.trapDetected = true
            props.trapDetected = true
            recordProbe("trap", target)
        end

        if self:markPoleProbedRecord(target.hazard, item, reach) then
            recordProbe("hazard", target.hazard)
        elseif target.hazard or target.hiddenHazard or target.zoneHazard or props.hazard or props.hiddenHazard then
            target.hazardDetected = true
            props.hazardDetected = true
            recordProbe("hazard", target)
        end

        for _, hazard in pairs(target.hazards or {}) do
            if self:markPoleProbedRecord(hazard, item, reach) then
                recordProbe("hazard", hazard)
            end
        end

        for _, hazard in pairs(target.caltrops or {}) do
            if self:markPoleProbedRecord(hazard, item, reach) then
                recordProbe("hazard", hazard)
            end
        end

        if #probed == 0 then
            recordProbe("hazard", target)
        end

        result.itemEffect = {
            type = "probe_hazard",
            target = target,
            reach = reach,
            probed = probed,
        }
        result.poleProbe = result.itemEffect
        result.effects[#result.effects + 1] = "hazard_probed"
        if trapDetected then
            result.effects[#result.effects + 1] = "trap_detected"
        end
        if hazardDetected then
            result.effects[#result.effects + 1] = "hazard_detected"
        end
        result.description = effect.successMessage or
            ((item.name or "Pole") .. " probes the hazard from a safe distance.")
        return true
    end

    function resolver:isMirrorGazeImmuneTarget(target)
        if not target then
            return false
        end

        local props = target.properties or {}
        if target.mirrorGazeImmune == true or target.gazeNotReflectedByMirrors == true or
           props.mirrorGazeImmune == true or props.gazeNotReflectedByMirrors == true then
            return true
        end
        if self:isCockatrice(target) or entityHasNormalizedTag(target, "cockatrice") then
            return true
        end
        if target.cockatrice and target.cockatrice.gaze then
            return target.cockatrice.gaze.reflectedByMirrors == false
        end

        return false
    end

    function resolver:isMirrorReflectableGazeTarget(target)
        if not target or self:isMirrorGazeImmuneTarget(target) then
            return false
        end

        local props = target.properties or {}
        return target.gaze == true or target.dreadGaze == true or target.monsterGaze == true or
            props.gaze == true or props.dreadGaze == true or props.monsterGaze == true or
            hasTag(target, "gaze") or hasTag(target, "dread_gaze") or hasTag(target, "mesmerist") or
            self:isVampire(target)
    end

    function resolver:applyMirrorGazeReflection(action, result, item, effect, target)
        if self:isMirrorGazeImmuneTarget(target) then
            result.success = false
            result.itemEffect = { type = "reflect_gaze", noEffect = true, immune = true }
            result.description = effect.noEffectMessage or ((item.name or "Mirror") .. " cannot reflect that gaze.")
            result.effects[#result.effects + 1] = "mirror_gaze_not_reflected"
            return false
        end

        if not self:isMirrorReflectableGazeTarget(target) then
            result.success = false
            result.itemEffect = { type = "reflect_gaze", noEffect = true }
            result.description = effect.noEffectMessage or ((item.name or "Mirror") .. " finds no dread gaze to reflect.")
            result.effects[#result.effects + 1] = "mirror_gaze_no_effect"
            return false
        end

        target.conditions = target.conditions or {}
        target.conditions.mirror_gaze_reflected = true
        target.mirrorGazeReflection = {
            source = "mirror",
            sourceItemId = item and item.id,
            sourceItemName = item and item.name,
            reflectedBy = action.actor,
            reflectedById = action.actor and action.actor.id,
            reflectedToSelf = true,
            pending = true,
        }

        result.itemEffect = {
            type = "reflect_gaze",
            target = target,
            reflection = target.mirrorGazeReflection,
        }
        result.effects[#result.effects + 1] = "mirror_gaze_reflection_prepared"
        result.description = effect.successMessage or
            ((item.name or "Mirror") .. " turns the monster's dread gaze back on itself.")
        return true
    end

    function resolver:consumeMirrorGazeReflection(actor, action, result)
        if not actor then
            return nil
        end

        local conditions = actor.conditions or {}
        local reflection = actor.mirrorGazeReflection
        if not reflection and not conditions.mirror_gaze_reflected then
            return nil
        end

        reflection = reflection or {
            source = "mirror",
            reflectedToSelf = true,
            pending = true,
        }
        reflection.pending = false
        reflection.consumedByAction = action and action.type
        actor.lastMirrorGazeReflection = reflection
        actor.mirrorGazeReflection = nil
        conditions.mirror_gaze_reflected = false

        result.effects = result.effects or {}
        result.effects[#result.effects + 1] = "mirror_gaze_reflected"
        return reflection
    end

    function resolver:isLanternFuelTarget(target)
        local props = target and target.properties or {}
        return target and props.light_source == true and props.provides_belt_light == true
    end

    function resolver:isOilLubricationTarget(target)
        if not target then
            return false
        end
        local props = target.properties or {}
        return target.stuck == true or target.jammed == true or target.rusted == true or
            props.stuck == true or props.jammed == true or props.rusted == true or props.rusty == true or
            props.lubricatable == true or props.requiresLubrication == true
    end

    function resolver:isOilFireFuelTarget(target)
        if not target then
            return false
        end
        local props = target.properties or {}
        local kind = normalizeSocialTag(target.type or target.kind or target.category)
        local name = normalizeSocialTag(target.name or target.id) or ""
        return kind == "fire" or kind == "campfire" or kind == "brazier" or props.fire == true or
            props.campfire == true or props.flammable == true or props.light_source == true or
            name:find("fire", 1, true) ~= nil or name:find("brazier", 1, true) ~= nil
    end

    function resolver:applyOilUtility(action, result, item, effect, target)
        local mode = normalizeSocialTag(action.oilUse or action.itemUse or action.intent or effect.mode)
        if mode == "refuel" or mode == "lantern" then
            mode = "refuel_lantern"
        elseif mode == "lubrication" or mode == "grease" then
            mode = "lubricate"
        elseif mode == "fuel" or mode == "fire" then
            mode = "fuel_fire"
        end

        if not mode then
            if self:isLanternFuelTarget(target) then
                mode = "refuel_lantern"
            elseif self:isOilLubricationTarget(target) then
                mode = "lubricate"
            elseif self:isOilFireFuelTarget(target) then
                mode = "fuel_fire"
            end
        end

        local props = target and target.properties or {}
        if mode == "refuel_lantern" then
            if not self:isLanternFuelTarget(target) then
                result.success = false
                result.itemEffect = { type = "refuel_lantern", noEffect = true }
                result.description = effect.noEffectMessage or ((item.name or "Oil") .. " can only refill a lantern.")
                result.effects[#result.effects + 1] = "refuel_no_effect"
                return false
            end

            props.flicker_count = effect.flickers or 4
            props.extinguished = false
            props.isLit = true
            result.itemEffect = {
                type = "refuel_lantern",
                target = target,
                flickers = props.flicker_count,
            }
            result.description = effect.successMessage or "Lantern refilled."
            result.effects[#result.effects + 1] = "lantern_refueled"
            return true
        elseif mode == "lubricate" then
            if not (target and (self:isOilLubricationTarget(target) or action.forceLubricate == true)) then
                result.success = false
                result.itemEffect = { type = "oil_lubricate", noEffect = true }
                result.description = "Oil needs a stuck tool, surface, or mechanism to lubricate."
                result.effects[#result.effects + 1] = "oil_lubricate_no_effect"
                return false
            end

            target.properties = props
            target.lubricated = true
            target.stuck = false
            target.jammed = false
            target.movesFreely = true
            props.lubricated = true
            props.stuck = false
            props.jammed = false
            props.movesFreely = true
            result.itemEffect = {
                type = "oil_lubricate",
                target = target,
            }
            result.description = "Oil lubricates the " .. (target.name or "target") .. "."
            result.effects[#result.effects + 1] = "oil_lubricated"
            return true
        elseif mode == "fuel_fire" then
            if not self:isOilFireFuelTarget(target) then
                result.success = false
                result.itemEffect = { type = "oil_fuel_fire", noEffect = true }
                result.description = "Oil needs a fire or flammable fuel to feed."
                result.effects[#result.effects + 1] = "oil_fuel_no_effect"
                return false
            end

            target.properties = props
            local flickers = effect.flickers or 4
            props.oilFueled = true
            props.fueledByOil = true
            props.oilFuelFlickers = (props.oilFuelFlickers or 0) + flickers
            if props.flicker_count ~= nil then
                props.flicker_count = (props.flicker_count or 0) + flickers
            end
            target.oilFueled = true
            result.itemEffect = {
                type = "oil_fuel_fire",
                target = target,
                flickers = flickers,
            }
            result.description = "Oil fuels the " .. (target.name or "fire") .. "."
            result.effects[#result.effects + 1] = "oil_fueled_fire"
            return true
        end

        result.success = false
        result.itemEffect = { type = "oil_utility", noEffect = true }
        result.description = effect.noEffectMessage or "Oil can refill lanterns, fuel fires, or lubricate stuck things."
        result.effects[#result.effects + 1] = "oil_no_effect"
        return false
    end

    function resolver:canSeeThroughFaceRatIllusion(observer)
        if not observer then
            return false
        end

        local conditions = observer.conditions or {}
        return observer.illusionImmune == true or observer.immuneToIllusions == true or
            observer.cannotSeeIllusions == true or observer.trueSight == true or observer.secondSight == true or
            hasGhostLotusStage(observer, 2) or
            conditions.illusionImmune == true or conditions.immune_to_illusions == true or
            conditions.cannot_see_illusions == true or conditions.true_sight == true or
            conditions.second_sight == true or entityHasTagValue(observer, "illusion_immune") or
            entityHasTagValue(observer, "cannot_see_illusions")
    end

    function resolver:applyFaceRatPotionFirstSeen(actor, seenCreature, opts)
        opts = opts or {}
        if not actor or not seenCreature then
            return nil
        end

        actor.conditions = actor.conditions or {}
        local conditions = actor.conditions
        if not (conditions.face_rat_illusion or conditions.illusion_duplicate_pending or actor.faceRatIllusionPending) then
            return nil
        end

        local duration = opts.duration or
            (actor.conditionDurations and actor.conditionDurations.face_rat_illusion and
                actor.conditionDurations.face_rat_illusion.duration) or "watch"
        local illusion = {
            source = "face_rat_potion",
            sourceItemId = opts.item and opts.item.id or nil,
            sourceItemName = opts.item and opts.item.name or nil,
            active = true,
            duration = duration,
            duplicateOf = seenCreature,
            duplicateOfId = seenCreature.id,
            duplicateName = seenCreature.name or seenCreature.id,
            visualOnly = true,
            hologram = true,
            noSound = true,
            noSmell = true,
            noSubstance = true,
            seenThroughBy = {},
            seeThroughObservers = {},
        }

        conditions.illusion_duplicate_pending = false
        conditions.illusion_duplicate_active = true
        conditions.face_rat_duplicate = true
        conditions.visual_illusion = true
        actor.faceRatIllusion = illusion
        actor.faceRatVisualIllusion = illusion
        actor.apparentDuplicateOf = seenCreature
        actor.apparentDuplicateOfId = illusion.duplicateOfId
        actor.apparentDuplicateName = illusion.duplicateName

        actor.conditionDurations = actor.conditionDurations or {}
        actor.conditionDurations.illusion_duplicate_pending = nil
        for _, condition in ipairs({ "face_rat_illusion", "illusion_duplicate_active", "face_rat_duplicate", "visual_illusion" }) do
            actor.conditionDurations[condition] = {
                duration = duration,
                sourceItemId = illusion.sourceItemId,
                sourceItemName = illusion.sourceItemName,
            }
        end

        for _, observer in ipairs(opts.observers or {}) do
            if observer ~= actor and self:canSeeThroughFaceRatIllusion(observer) then
                illusion.seeThroughObservers[#illusion.seeThroughObservers + 1] = observer
                illusion.seenThroughBy[observer.id or observer.name or tostring(#illusion.seeThroughObservers)] = true
            end
        end

        local result = opts.result
        if result then
            result.faceRatIllusion = illusion
            result.effects[#result.effects + 1] = "face_rat_duplicate"
            result.effects[#result.effects + 1] = "visual_illusion_duplicate"
            if #illusion.seeThroughObservers > 0 then
                result.effects[#result.effects + 1] = "illusion_seen_through"
            end
            if result.itemEffect then
                result.itemEffect.faceRatIllusion = illusion
            end
        end

        return illusion
    end

    function resolver:applyItemUseEffect(action, result, item)
        local effect = self:getItemUseEffect(item)
        if not effect then
            return true
        end

        local target = self:getItemEffectTarget(action, effect)
        if not target then
            result.success = false
            result.description = "No valid target for " .. (item.name or "item") .. "."
            result.effects[#result.effects + 1] = "item_target_missing"
            return false
        end

        local props = item and item.properties or {}
        if props.potion and self:potionHasNoEffect(target) then
            result.itemEffect = {
                type = effect.type or "unknown",
                noEffect = true,
                reason = "no_living_processes",
                livingProcessesRequired = true,
            }
            result.description = effect.noEffectMessage or ((item.name or "Potion") .. " has no effect on the target.")
            result.effects[#result.effects + 1] = "potion_no_effect"
            result.effects[#result.effects + 1] = "potion_living_processes_required"
            return true
        end

        if effect.type == "drug_affliction" then
            return self:applyDrugAfflictionDose(action, result, item, effect, target)
        elseif effect.type == "poultice_deaths_door" then
            return self:resolvePoulticeDeathsDoor(action, result, item, effect, target)
        elseif effect.type == "salt_ooze" then
            if not self:hasAnyTargetTag(target, effect.affectedTags) then
                result.success = false
                result.itemEffect = { type = "salt_ooze", noEffect = true }
                result.description = effect.noEffectMessage or ((item.name or "Salt") .. " has no special effect.")
                result.effects[#result.effects + 1] = "salt_no_effect"
                return false
            end

            local damage = effect.damage or {}
            local amount = damage.amount or 2
            local damageEffects = damage.effects or { "salt_reactive" }
            result.damageDealt = (result.damageDealt or 0) + amount
            for _, damageEffect in ipairs(damageEffects) do
                result.effects[#result.effects + 1] = damageEffect
            end
            if self:isSlime(target) then
                target.slimeSaltedThisTurn = true
                target.saltSpreadThisTurn = true
                result.effects[#result.effects + 1] = "slime_salted_this_turn"
            end
            self:applyDamage(target, amount, damageEffects, nil, action.allEntities,
                self:getActionWoundOptions(action, target))
            result.itemEffect = { type = "salt_ooze", amount = amount }
            result.description = effect.successMessage or ((item.name or "Salt") .. " deals " .. amount .. " Wounds.")
            return true
        elseif effect.type == "refuel_lantern" then
            return self:applyOilUtility(action, result, item, effect, target)
        elseif effect.type == "ward_undead" then
            if not self:isWardAffectedTarget(target, effect.affectedTags, effect) then
                result.success = false
                result.itemEffect = { type = "ward_undead", noEffect = true }
                result.description = effect.noEffectMessage or ((item.name or "Ward") .. " has no effect.")
                result.effects[#result.effects + 1] = "ward_no_effect"
                return false
            end

            if action.destinationZone then
                target.zone = action.destinationZone
            end

            self:clearAllEngagements(target, action.allEntities)
            target.conditions = target.conditions or {}
            target.conditions.displaced = true
            result.itemEffect = {
                type = "ward_undead",
                target = target,
                destinationZone = action.destinationZone,
            }
            result.description = effect.successMessage or ((item.name or "Ward") .. " displaces the creature.")
            result.effects[#result.effects + 1] = "ward_success"
            result.effects[#result.effects + 1] = "displaced"
            return true
        elseif effect.type == "heal_wound" then
            if not target.healWound and not animal_companions.isAnimalCompanion(target) then
                result.success = false
                result.description = "No healable target."
                result.effects[#result.effects + 1] = "item_effect_failed"
                return false
            end
            if target.immuneToHealEffect or target.immuneToHeal then
                result.success = false
                result.description = "Cannot heal: immune to the Heal effect."
                result.effects[#result.effects + 1] = "heal_immune"
                return false
            end

            local healResult, err = self:healTargetWound(target)
            if healResult then
                result.itemEffect = { type = "heal_wound", result = healResult }
                result.description = (effect.successMessage or "Healed: " .. healResult)
                result.effects[#result.effects + 1] = "healed"
                return true
            end

            result.success = false
            result.description = "Cannot heal: " .. (err or "unknown")
            if err == "healing_blocked" then
                result.effects[#result.effects + 1] = "healing_blocked"
            else
                result.effects[#result.effects + 1] = "item_effect_failed"
            end
            return false
        elseif effect.type == "clear_conditions" then
            local cleared = self:clearTargetConditions(target, effect.conditions)
            result.itemEffect = { type = "clear_conditions", cleared = cleared }
            if cleared then
                result.description = effect.successMessage or ("Cleared " .. cleared .. ".")
                result.effects[#result.effects + 1] = "condition_cleared"
                result.effects[#result.effects + 1] = "cleared_" .. cleared
            else
                result.description = effect.noEffectMessage or ((item.name or "Item") .. " used, but no condition changed.")
                result.effects[#result.effects + 1] = "item_no_condition"
            end
            return true
        elseif effect.type == "restrain_person" then
            return self:applyManaclesRestraint(action, result, item, effect, target)
        elseif effect.type == "bind_or_haul" then
            return self:applyChainBindOrHaul(action, result, item, effect, target)
        elseif effect.type == "cut_material" then
            return self:applyCutMaterial(action, result, item, effect, target)
        elseif effect.type == "iron_spike" then
            return self:applyIronSpikeUse(action, result, item, effect, target)
        elseif effect.type == "start_fire" then
            return self:applyStartFire(action, result, item, effect, target)
        elseif effect.type == "build_campfire" then
            return self:applyBuildCampfire(action, result, item, effect, target)
        elseif effect.type == "mark_surface" then
            return self:applyChalkMark(action, result, item, effect, target)
        elseif effect.type == "excavate" then
            return self:applyExcavate(action, result, item, effect, target)
        elseif effect.type == "probe_hazard" then
            return self:applyPoleProbe(action, result, item, effect, target)
        elseif effect.type == "reflect_gaze" then
            return self:applyMirrorGazeReflection(action, result, item, effect, target)
        elseif effect.type == "apply_conditions" then
            target.conditions = target.conditions or {}
            if effect.requiresBreathing == true and isBreathlessTarget(target) then
                result.itemEffect = {
                    type = "apply_conditions",
                    noEffect = true,
                    requiresBreathing = true,
                    target = target,
                }
                result.effects[#result.effects + 1] = "breathless_unaffected"
                result.effects[#result.effects + 1] = "breathing_required"
                result.description = effect.noEffectMessage or
                    ((target.name or "Target") .. " does not breathe and ignores the effect.")
                return true
            end
            local appliedConditions = {}
            for condition, value in pairs(effect.conditions or {}) do
                if value and isPoisonCondition(condition) and self:isPoisonImmune(target) then
                    self:recordPoisonBlocked(target, result, condition, item)
                elseif value and self:isWraithSpectralConditionImmune(target, condition) then
                    self:recordWraithSpectralBlocked(target, result, condition, item)
                else
                    target.conditions[condition] = value
                    if (effect.duration or effect["until"]) and value then
                        target.conditionDurations = target.conditionDurations or {}
                        target.conditionDurations[condition] = {
                            duration = effect.duration,
                            ["until"] = effect["until"],
                            sourceItemId = item.id,
                            sourceItemName = item.name,
                        }
                    end
                    result.effects[#result.effects + 1] = condition
                    appliedConditions[condition] = value
                end
            end

            result.itemEffect = {
                type = "apply_conditions",
                conditions = appliedConditions,
                blockedConditions = result.poisonBlocked,
                duration = effect.duration,
                ["until"] = effect["until"],
            }
            if appliedConditions.cannot_hold_items then
                local dropped = self:dropHeldItemsForCannotHold(target, "harpy_potion", {
                    excludeItem = item,
                })
                if #dropped > 0 then
                    result.droppedItems = result.droppedItems or {}
                    for _, droppedItem in ipairs(dropped) do
                        result.droppedItems[#result.droppedItems + 1] = droppedItem
                    end
                    result.itemEffect.droppedItems = dropped
                    result.effects[#result.effects + 1] = "held_items_dropped"
                    result.effects[#result.effects + 1] = "cannot_hold_items_enforced"
                end
            end
            if appliedConditions.face_rat_illusion and appliedConditions.illusion_duplicate_pending then
                self:applyFaceRatPotionFirstSeen(target,
                    action.firstSeenCreature or action.firstSeen or action.seenCreature or action.duplicateSource, {
                        item = item,
                        duration = effect.duration,
                        observers = action.observers or action.allEntities,
                        result = result,
                    })
            end
            if (effect.affectsIncorporeal == true or effect.targetsIntangible == true) and
               isIntangibleTarget(target) and next(appliedConditions) then
                target.alchemyAffectedIncorporeal = target.alchemyAffectedIncorporeal or {}
                target.alchemyAffectedIncorporeal[#target.alchemyAffectedIncorporeal + 1] = {
                    sourceItemId = item.id,
                    sourceItemName = item.name,
                    effect = effect.type,
                }
                result.itemEffect.affectsIncorporeal = true
                result.effects[#result.effects + 1] = "incorporeal_affected"
            end
            if next(appliedConditions) then
                result.description = effect.successMessage or ((item.name or "Item") .. " effect lands.")
            elseif result.poisonBlocked then
                result.description = (target.name or "Target") .. " cannot be poisoned."
            elseif result.wraithSpectralBlocked then
                result.description = (target.name or "Target") .. " is spectral and ignores that condition."
            else
                result.description = effect.noEffectMessage or ((item.name or "Item") .. " used, but no condition changed.")
            end
            return true
        elseif effect.type == "apply_properties" then
            local props = target.properties or {}
            target.properties = props
            for property, value in pairs(effect.properties or {}) do
                props[property] = value
                if effect.duration and value then
                    props.effectDurations = props.effectDurations or {}
                    props.effectDurations[property] = {
                        duration = effect.duration,
                        sourceItemId = item.id,
                        sourceItemName = item.name,
                    }
                end
                result.effects[#result.effects + 1] = property
            end

            result.itemEffect = {
                type = "apply_properties",
                target = target,
                properties = effect.properties,
                duration = effect.duration,
            }
            if effect.waterPlatformDiameterFeet and isWaterSurfaceTarget(target) then
                target.kelpieOilPlatform = {
                    sourceItemId = item.id,
                    sourceItemName = item.name,
                    diameterFeet = effect.waterPlatformDiameterFeet,
                    softButSturdy = true,
                    duration = effect.duration or "watch",
                }
                props.oilIsland = true
                props.kelpieOilPlatform = true
                props.waterPlatformDiameterFeet = effect.waterPlatformDiameterFeet
                if effect.duration then
                    props.effectDurations = props.effectDurations or {}
                    props.effectDurations.kelpieOilPlatform = {
                        duration = effect.duration,
                        sourceItemId = item.id,
                        sourceItemName = item.name,
                    }
                end
                result.itemEffect.waterPlatform = target.kelpieOilPlatform
                result.effects[#result.effects + 1] = "kelpie_oil_platform"
                result.effects[#result.effects + 1] = "oil_island"
            end
            if effect.freezesWaterBodySize or effect.iceWallHeightFeet or props.winterWolfOil then
                if isWaterSurfaceTarget(target) then
                    local bodySize = effect.freezesWaterBodySize or "olympic_pool"
                    target.frozenWaterBody = {
                        sourceItemId = item.id,
                        sourceItemName = item.name,
                        size = bodySize,
                        frozen = true,
                    }
                    props.freezesWater = true
                    props.frozenWater = true
                    props.frozenWaterBody = true
                    props.frozenWaterBodySize = bodySize
                    result.itemEffect.frozenWaterBody = target.frozenWaterBody
                    result.effects[#result.effects + 1] = "winter_wolf_oil_freeze"
