                    creature.conditions.deafened = true
                    entry.stunned = true
                    entry.stunDiscard = stunDiscard
                    entry.stunDiscardedCard = stunDiscard.card
                    entry.deafened = true
                end
                creatureResults[#creatureResults + 1] = entry
            end

