            target.shroudedBy = actor
            target.shroud = {
                caster = actor,
                casterId = spellEntityKey(actor),
                spellId = spell.id,
                active = true,
                concentration = true,
                componentAction = effect.componentAction or "spread_funeral_winding_sheet_over_target",
                coversCarriedItems = effect.coversTargetAndCarriedGear ~= false,
                coversTargetAndCarriedGear = effect.coversTargetAndCarriedGear ~= false,
                cannotBeSeenWithoutMagic = effect.impossibleToSeeWithoutMagicOrSpecialSenses ~= false,
                impossibleToSeeWithoutMagicOrSpecialSenses =
                    effect.impossibleToSeeWithoutMagicOrSpecialSenses ~= false,
                stillAndQuietCannotBeTargeted = effect.stillAndQuietCannotBeDeliberatelyTargeted ~= false,
                stillAndQuietCannotBeDeliberatelyTargeted =
                    effect.stillAndQuietCannotBeDeliberatelyTargeted ~= false,
                movementCreatesVaguePresence = effect.movementCreatesVaguePresence ~= false,
                targetingVaguePresenceDisfavor = effect.targetingVaguePresenceDisfavor ~= false,
                harmfulActionsGainFavorAgainstUnseeing = effect.harmfulActionsGainFavorAgainstUnseeing ~= false,
                moved = false,
                vaguePresenceKnown = false,
                visibleObjectsRequireResolve = effect.visibleObjectInteractionRequiresResolve ~= false,
                visibleObjectInteractionRequiresResolve = effect.visibleObjectInteractionRequiresResolve ~= false,
                visibleInteractions = 0,
                maintenanceResolveSpent = 0,
            }

            result.shroud = target.shroud
            result.spellTargets = { target }
            result.effects[#result.effects + 1] = "shrouded"
            result.description = spell.name .. " makes " .. (target.name or "target") .. " and their carried gear Shrouded."
        elseif effect.type == "scry" then
            local valid, reason, effectName, scryDetails = validateScry(action, resolveSpent, actor, spell)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return false
            end

            local scrying = {
                spellId = spell.id,
                caster = actor,
                casterId = spellEntityKey(actor),
                active = true,
                concentration = true,
                location = scryDetails.location,
                locationId = scryDetails.locationId,
                locationName = scryDetails.locationName,
                currentArea = scryDetails.currentArea,
                targetArea = scryDetails.targetArea,
                outsideCurrentArea = scryDetails.outsideArea,
                componentAction = effect.componentAction or "peer_into_crystal_ball",
                canSeeLocation = effect.canSeeLocation ~= false,
                visitedLocationOnly = effect.visitedLocationOnly ~= false,
                defaultSameMetaphysicalAreaOnly = effect.defaultSameMetaphysicalAreaOnly ~= false,
                outsideAreaExtraResolve = scryDetails.outsideAreaExtraResolve or effect.outsideAreaExtraResolve or 1,
                crystalBall = result.component,
                resolveSpent = resolveSpent,
            }
            actor.scrying = scrying
            result.scrying = scrying
            result.effects[#result.effects + 1] = "scrying"
            if scrying.outsideCurrentArea then
                result.effects[#result.effects + 1] = "scry_cross_area"
            end
            result.description = spell.name .. " reveals " .. tostring(scrying.locationName) .. "."
        elseif effect.type == "circle_of_protection" then
            local valid, reason, effectName, realms = validateCircleProtection(action, spell, resolveSpent)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return false
            end

            local _, realmSet = collectCircleProtectionRealms(action)
            local circle = self:createCircleProtection(actor, action, spell, resolveSpent, realms, realmSet)
            result.circleProtection = circle
            result.spellTargets = { circle }
            result.effects[#result.effects + 1] = "circle_of_protection"
            if circle.trappedSpirits and #circle.trappedSpirits > 0 then
                result.trappedSpirits = circle.trappedSpirits
                result.effects[#result.effects + 1] = "circle_spirit_trapped"
            end
            result.description = spell.name .. " protects against " .. tostring(#realms) .. " far realm(s)."
        elseif effect.type == "feather" then
            if not target then
                result.success = false
                result.description = "No target for " .. spell.name .. "."
                result.effects[#result.effects + 1] = "spell_target_missing"
                return false
            end

            target.conditions = target.conditions or {}
            target.conditions.feather = true
            target.conditions.floating = true
            target.featherBy = actor
            target.feather = {
                caster = actor,
                casterId = actor and actor.id,
                concentration = true,
                componentAction = effect.componentAction or "hold_lamassu_feather",
                fallingInterrupted = target.falling == true or action.falling == true,
                weightReducedTo = effect.weightReducedTo or "feather",
                weightReducedToFeather = effect.weightReducedTo == nil or effect.weightReducedTo == "feather",
                floatsGentlyToGround = effect.floatsGentlyToGround ~= false,
                quickCastFallingRequiresHeldComponent = effect.quickCastFallingRequiresHeldComponent == true,
                preventsFallingDamage = effect.preventsFallingDamage ~= false,
                preventsHazardSceneryDamage = effect.preventsHazardSceneryDamage ~= false,
                preventsPressurePlateTrigger = effect.preventsPressurePlateTrigger ~= false,
                heavyObjectsEasyToMove = effect.heavyObjectsEasyToMove ~= false,
            }
            target.floating = true
            target.falling = false
            target.effectiveWeight = "feather"
            target.weightReducedToFeather = true
            target.immuneToFallingDamage = true
            target.immuneToHazardScenery = true
            target.ignorePressurePlates = true
            target.easyToMove = true

            if target.properties then
                target.properties.featherWeight = true
                target.properties.floating = true
                target.properties.easyToMove = true
                target.properties.ignorePressurePlates = true
                target.properties.immuneToHazardScenery = true
            end

            result.feather = target.feather
            result.spellTargets = { target }
            result.effects[#result.effects + 1] = "feather_weight"
            result.description = spell.name .. " makes " .. (target.name or "target") .. " light as a feather."
        elseif effect.type == "guardian_angel" then
            if not target then
                result.success = false
                result.description = "No target for " .. spell.name .. "."
                result.effects[#result.effects + 1] = "spell_target_missing"
                return false
            end
            if target.guardianAngel and not target.guardianAngel.used then
                result.success = false
                result.description = "Guardian Angel is already protecting " .. (target.name or "target") .. "."
                result.effects[#result.effects + 1] = "guardian_angel_already_active"
                return false
            end

            local card = action.card
            local angel = {
                caster = actor,
                casterId = actor and actor.id,
                target = target,
                targetId = target.id,
                card = card,
                value = card and card.value or 0,
                componentAction = effect.componentAction or "summon_invisible_minor_welkin_spirit",
                bindsSpiritToTarget = effect.bindsSpiritToTarget ~= false,
                speakIncantationCardBecomesDefense = effect.speakIncantationCardBecomesDefense ~= false,
                canDodge = effect.canDodge ~= false,
                canRiposte = effect.canRiposte ~= false,
                stacksWithSameDefenseType = effect.stacksWithSameDefenseType ~= false,
                doesNotCountDefenseSlot = effect.doesNotCountDefenseSlot ~= false,
                noMultipleInstances = effect.noMultipleInstances ~= false,
                lastsUntilUsed = effect.lastsUntilUsed ~= false,
                used = false,
            }

            target.conditions = target.conditions or {}
            target.conditions.guardianAngel = true
            target.guardianAngel = angel
            target.guardianAngelCard = card
            result.guardianAngel = angel
            result.effects[#result.effects + 1] = "guardian_angel_prepared"
            result.description = spell.name .. " waits to protect " .. (target.name or "target") .. " from one blow."
        elseif effect.type == "withering" then
            result.withering = {
                spellId = spell.id,
                componentAction = effect.componentAction or "invoke_decay_from_rune_etched_fingernails",
                livingCreatureWounds = effect.livingCreatureWounds or 1,
                livingAgingSigns = effect.livingAgingSigns,
                agingLastsUntilWoundHealed = effect.agingLastsUntilWoundHealed ~= false,
                undeadNotHarmed = effect.undeadNotHarmed ~= false,
                undeadBecomesMoreTerrible = effect.undeadBecomesMoreTerrible ~= false,
                zombieTransformsTo = effect.zombieTransformsTo or "skeleton",
                skeletonTransformsTo = effect.skeletonTransformsTo or "wraith",
                objectShowsDecay = effect.objectShowsDecay ~= false,
                objectDecayByMaterial = effect.objectDecayByMaterial,
                objectTakesNotch = effect.objectTakesNotch ~= false,
                destroyedAtResolve = effect.destroyedAtResolve or 2,
            }
            if target and target.takeWound and not (target.undead or hasTag(target, "undead")) then
                self:applyDamage(target, result.withering.livingCreatureWounds, {}, nil, action.allEntities)
                result.witheringAging = markWitheringAging(target)
                result.witheringAging.componentAction = result.withering.componentAction
                result.witheringAging.signs = effect.livingAgingSigns or result.witheringAging.signs
                result.witheringAging.agingLastsUntilWoundHealed =
                    result.withering.agingLastsUntilWoundHealed
                result.damageDealt = (result.damageDealt or 0) + 1
                result.effects[#result.effects + 1] = "withered"
                result.effects[#result.effects + 1] = "withering_aging"
                result.description = spell.name .. " withers " .. (target.name or "target") .. "."
            elseif target and (target.undead or hasTag(target, "undead")) then
                target.conditions = target.conditions or {}
                target.conditions.terrible = true
                local undeadKind = witheringUndeadKind(target)
                if undeadKind == "zombie" then
                    applyWitheringSkeletonForm(target)
                    result.effects[#result.effects + 1] = "zombie_transformed_skeleton"
                elseif undeadKind == "skeleton" then
                    applyWitheringWraithForm(target)
                    result.effects[#result.effects + 1] = "skeleton_transformed_wraith"
                end
                target.witheringEmpowered = true
                result.witheringTransformation = target.witheringTransformation
                if result.witheringTransformation then
                    result.witheringTransformation.componentAction = result.withering.componentAction
                    result.witheringTransformation.undeadNotHarmed = result.withering.undeadNotHarmed
                    result.witheringTransformation.undeadBecomesMoreTerrible =
                        result.withering.undeadBecomesMoreTerrible
                end
                result.effects[#result.effects + 1] = "undead_empowered"
                result.description = spell.name .. " makes the undead more terrible."
            elseif target then
                local material = getWitheringMaterial(target)
                local notchResult = nil
                result.witheringObjectDecay = markWitheringObjectDecay(target)
                result.witheringObjectDecay.componentAction = result.withering.componentAction
                result.witheringObjectDecay.objectShowsDecay = result.withering.objectShowsDecay
                result.witheringObjectDecay.objectDecayByMaterial = result.withering.objectDecayByMaterial
                result.witheringObjectDecay.objectTakesNotch = result.withering.objectTakesNotch
                result.witheringObjectDecay.destroyedAtResolve = result.withering.destroyedAtResolve
                if material == "stone" then
                    target.stoneUnaffectedByWithering = true
                    result.effects[#result.effects + 1] = "withering_stone_unaffected"
                elseif resolveSpent >= result.withering.destroyedAtResolve then
                    target.destroyed = true
                    if target.durability then
                        target.notches = target.durability
                    end
                    notchResult = "destroyed"
                    result.effects[#result.effects + 1] = "object_destroyed"
                else
                    target.durability = target.durability or 1
                    target.notches = target.notches or 0
                    notchResult = inventory.addNotch(target)
                    if notchResult == "destroyed" then
                        result.effects[#result.effects + 1] = "object_destroyed"
                    end
                end
                result.effects[#result.effects + 1] = "object_withered"
                result.itemNotchResult = notchResult
                result.description = spell.name .. " decays " .. (target.name or "object") .. "."
            else
                result.description = spell.name .. " manifests."
            end
        elseif effect.type == "stinking_cloud" then
            local valid, reason, effectName, zoneIds, zoneSet =
                self:validateStinkingCloud(action, target, actor, resolveSpent)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return false
            end
            local zoneCount = #zoneIds
            local cloud = {
                spellId = spell.id,
                caster = actor,
                casterId = spellEntityKey(actor),
                active = true,
                concentration = true,
                zoneIds = zoneIds,
                zoneSet = zoneSet,
                zoneCount = zoneCount,
                maximumZones = math.max(1, tonumber(resolveSpent) or 1),
                miasma = effect.miasma or "thousand_opened_coffins",
                expelledFrom = effect.expelledFrom or "sorcerer_mouth",
                mouthExpelled = true,
                breathingImmunity = effect.breathingImmunity ~= false,
                stunPenaltyPerRound = 1,
                knockoutAtStacks = 4,
                exposureCounts = {},
            }

            actor.activeStinkingClouds = actor.activeStinkingClouds or {}
            actor.activeStinkingClouds[#actor.activeStinkingClouds + 1] = cloud

            result.stinkingCloud = cloud
            result.zoneIds = zoneIds
            result.zoneCount = zoneCount
            result.stunPenalty = 1
            result.effects[#result.effects + 1] = "stinking_cloud"
            result.description = spell.name .. " fills " .. result.zoneCount .. " zone(s)."
        elseif effect.type == "life" then
            result.life = {
                spellId = spell.id,
                componentAction = effect.componentAction or "touch_with_phoenix_feather",
                noEffectOnHealthyLiving = effect.noEffectOnHealthyLiving == true,
                clearsDeathsDoor = effect.clearsDeathsDoor == true,
                deathsDoorTargetBecomesStressed = effect.deathsDoorTargetBecomesStressed == true,
                reducesAfflictionStage = effect.reducesAfflictionStage == true,
                removesFirstStageAffliction = effect.removesFirstStageAffliction == true,
                undeadTakesWound = effect.undeadTakesWound == true,
                plantGrowsQuickly = effect.plantGrowsQuickly == true,
                extraTargetResolve = effect.extraTargetResolve or 1,
            }
            local targets = collectSpellTargets(action, target, math.max(1, resolveSpent))
            local lifeResults = {}

            for _, lifeTarget in ipairs(targets) do
                local targetResult = {
                    target = lifeTarget,
                    result = "no_effect",
                    life = result.life,
                }

                if lifeTarget and lifeTarget.conditions and lifeTarget.conditions.deaths_door then
                    local healResult = self:healTargetWound(lifeTarget)
                    targetResult.result = healResult or "deaths_door_cleared"
                    targetResult.effect = "deaths_door_cleared"
                    result.effects[#result.effects + 1] = "deaths_door_cleared"
                elseif lifeTarget and (lifeTarget.undead or hasTag(lifeTarget, "undead")) then
                    if lifeTarget.takeWound then
                        self:applyDamage(lifeTarget, 1, {}, nil, action.allEntities,
                            self:getActionWoundOptions(action, lifeTarget))
                    end
                    targetResult.result = "undead_wounded"
                    targetResult.effect = "undead_wounded"
                    result.damageDealt = (result.damageDealt or 0) + 1
                    result.effects[#result.effects + 1] = "undead_wounded"
                elseif lifeTarget and (lifeTarget.plant or hasTag(lifeTarget, "plant")) then
                    lifeTarget.conditions = lifeTarget.conditions or {}
                    lifeTarget.conditions.growing = true
                    targetResult.result = "plant_grown"
                    targetResult.effect = "plant_grown"
                    result.effects[#result.effects + 1] = "plant_grown"
                else
                    local affliction, afflictionName = findTargetAffliction(
                        lifeTarget,
                        action.affliction or action.afflictionName or action.targetAffliction
                    )
                    if affliction then
                        local stage = math.max(1, tonumber(affliction.stage) or 1)
                        targetResult.affliction = afflictionName
                        targetResult.previousStage = stage
                        if stage <= 1 then
                            lifeTarget.afflictions[afflictionName] = nil
                            targetResult.result = "affliction_removed"
                            targetResult.effect = "affliction_removed"
                            result.effects[#result.effects + 1] = "affliction_removed"
                        else
                            affliction.stage = stage - 1
                            affliction.curedThisCamp = true
                            targetResult.result = "affliction_reduced"
                            targetResult.effect = "affliction_reduced"
                            targetResult.stage = affliction.stage
                            result.effects[#result.effects + 1] = "affliction_reduced"
                        end
                    end
                end

                lifeResults[#lifeResults + 1] = targetResult
            end

            result.lifeResults = lifeResults
            if #lifeResults == 0 then
                result.description = spell.name .. " has no target."
            else
                result.description = spell.name .. " touches " .. tostring(#lifeResults) .. " target(s)."
            end
        elseif effect.type == "veritas" then
            if not isPersonSpellTarget(target) then
                result.effects[#result.effects + 1] = "veritas_no_effect"
                result.description = spell.name .. " has no effect on " .. (target and target.name or "the target") .. "."
            else
                target.conditions = target.conditions or {}
                target.conditions.veritas = true
                target.veritas = {
                    active = true,
                    caster = actor,
                    casterId = actor and actor.id,
                    spellId = spell.id,
                    componentAction = effect.componentAction or "administer_sacramental_wine",
                    personOnly = effect.personOnly ~= false,
                    knowsKnowinglyToldLies = effect.casterKnowsKnowinglySpokenLies ~= false,
                    targetAware = effect.targetUnderstandsMagicalPolygraph ~= false,
                    targetUnderstandsMagicalPolygraph = effect.targetUnderstandsMagicalPolygraph ~= false,
                    concentration = true,
                }
                result.truthSense = target.veritas
                result.effects[#result.effects + 1] = "veritas"
                result.description = spell.name .. " reveals knowingly spoken lies from " .. (target.name or "target") .. "."
            end
        elseif effect.type == "seal_pact" then
            local parties = collectSealPactParties(action, target)
            local valid, reason, effectName = validateSealPactParties(action, spell, resolveSpent, parties)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return false
            end

            action.parties = parties
            local pact = self:createSealedPact(actor, parties, action, spell, resolveSpent)
            result.sealedPact = pact
            result.parties = parties
            result.effects[#result.effects + 1] = "sealed_pact"
            result.description = spell.name .. " binds " .. tostring(#parties) .. " willing parties."
        else
            result.description = (spell and spell.name or "Spell") .. " takes effect."
        end

        if spell and spell.ongoing and not result.skipOngoingSpell then
            actor.activeSpells = actor.activeSpells or {}
            local committedResolve = action.resolveCommitted
            if committedResolve == nil then
                committedResolve = resolveSpent
            end
            local activeSpell = {
                spellId = spell.id,
                name = spell.name,
                branch = spell.branch,
                caster = actor,
                casterId = actor and actor.id,
                target = target,
                resolveCommitted = committedResolve,
                concentration = spell.concentration == true,
                effectType = effect.type,
                zoneIds = result.zoneIds,
                zoneCount = result.zoneCount,
                targets = result.spellTargets or result.bindingTargets,
                binding = result.binding,
                cloakedTarget = result.cloakedTarget,
                circleProtection = result.circleProtection,
                elementWall = result.elementWall,
                totemForm = result.totemForm,
                animatedObject = result.animatedObject,
                fleshcraft = result.fleshcraft,
                raisedZombie = result.raisedZombie,
                malediction = result.malediction,
                scrying = result.scrying,
                giveForm = result.giveForm,
                portableHole = result.portableHole,
                mirrorMeld = result.mirrorMeld,
                visualIllusion = result.visualIllusion,
                truthSense = result.truthSense,
                stinkingCloud = result.stinkingCloud,
                instanceId = result.elementProtectionInstanceId,
                protectedElements = result.protectedElements,
            }
            actor.activeSpells[#actor.activeSpells + 1] = activeSpell
            result.activeSpell = activeSpell
            if result.spellcasting then
                result.spellcasting.activeSpell = activeSpell
                result.spellcasting.ongoingSpell = true
                result.spellcasting.resolveCommitted = committedResolve
                result.spellcasting.concentration = activeSpell.concentration
            end
            if result.animatedObject then
                result.animatedObject.spellEntry = activeSpell
            end
            if result.fleshcraft then
                result.fleshcraft.spellEntry = activeSpell
            end
            if result.raisedZombie and result.raisedZombie.raiseZombie then
                result.raisedZombie.raiseZombie.spellEntry = activeSpell
            end
            if result.malediction then
                result.malediction.spellEntry = activeSpell
            end
            if result.giveForm then
                result.giveForm.spellEntry = activeSpell
            end
            if result.portableHole then
                result.portableHole.spellEntry = activeSpell
            end
            if result.mirrorMeld then
                result.mirrorMeld.spellEntry = activeSpell
            end
            if result.visualIllusion then
                result.visualIllusion.spellEntry = activeSpell
            end
            if result.truthSense then
                result.truthSense.spellEntry = activeSpell
            end
            if result.stinkingCloud then
                result.stinkingCloud.spellEntry = activeSpell
            end
            actor.committedResolve = (actor.committedResolve or 0) + committedResolve
            result.effects[#result.effects + 1] = "ongoing_spell"

            if effect.type == "control" then
                self:resolveImmediateControlAction(action, result, actor, target)
            end
        end

        return true
    end

    function resolver:resolveProudAndAncientWarCry(action, result)
        local actor = action.actor
        if not entityHasUsableTalent(actor, "proud_and_ancient") then
            result.success = false
            result.description = "Requires Proud and Ancient."
            result.effects[#result.effects + 1] = "proud_and_ancient_required"
            return
        end

        local controller = action.challengeController or self.challengeController
        local inChallenge = action.inChallenge == true or
            (controller and controller.isActive and controller:isActive())
        if not inChallenge then
            result.success = false
            result.description = "Proud and Ancient war cry requires an active Challenge."
            result.effects[#result.effects + 1] = "challenge_required"
            return
        end

        local ok, reason = self:spendResolveForFavor(actor)
        if not ok then
            result.success = false
            result.description = "Cannot cry house motto: " .. (reason or "resolve unavailable") .. "."
            result.effects[#result.effects + 1] = "resolve_missing"
            return
        end

        local function normalizeHouse(value)
            return tostring(value or ""):lower():gsub("[’']", ""):gsub("[^%w]+", "_"):gsub("^_+", ""):gsub("_+$", "")
        end

        local house = normalizeHouse(action.house or actor.house or actor.humanHouse or actor.kinHouse or actor.family)
        local candidates = {}
        if type(action.heardBy or action.listeners) == "table" then
            candidates = action.heardBy or action.listeners
        elseif type(action.allEntities) == "table" then
            candidates = action.allEntities
        elseif type(action.guild) == "table" then
            candidates = action.guild
        else
            candidates = { actor }
        end

        local affected = {}
        local seen = {}
        local function canHear(entity)
            local conditions = entity and entity.conditions or {}
            return entity and not (conditions.dead or conditions.deaf or conditions.deafened or entity.canHearWarCry == false)
        end
        local function sameHouse(entity)
            if entity == actor then
                return true
            end
            if house == "" then
                return false
            end
            return normalizeHouse(entity.house or entity.humanHouse or entity.kinHouse or entity.family) == house
        end
        local function addAffected(entity)
            if entity and not seen[entity] and canHear(entity) and sameHouse(entity) then
                seen[entity] = true
                entity.nextActionFavor = true
                entity.nextActionFavorSource = "proud_and_ancient"
                affected[#affected + 1] = entity
            end
        end

        addAffected(actor)
        for _, entity in ipairs(candidates) do
            addAffected(entity)
        end

        result.success = true
        result.description = (actor.name or "The adventurer") .. " cries their house motto."
        result.effects[#result.effects + 1] = "proud_and_ancient_war_cry"
        result.effects[#result.effects + 1] = "resolve_spent_for_proud_and_ancient"
        result.affected = affected
        result.affectedCount = #affected
        result.house = house ~= "" and house or nil
        result.proudAndAncientWarCry = {
            actor = actor,
            actorId = actor and actor.id,
            card = action.card,
            cardName = action.card and action.card.name,
            cardSuit = action.card and action.card.suit,
            cardValue = action.card and action.card.value,
            house = house ~= "" and house or nil,
            houseName = action.house or actor.house or actor.humanHouse or actor.kinHouse or actor.family,
            motto = action.motto or action.houseMotto or actor.motto or actor.houseMotto,
            affected = affected,
            affectedCount = #affected,
            resolveSpent = true,
            description = result.description,
        }
    end

    function resolver:resolveSpeakIncantation(action, result)
        local actor = action.actor
        local target = action.target or (type(action.targets) == "table" and action.targets[1] or nil)
        action.target = target
        if action.countered or action.fizzled then
            result.success = false
            result.countered = true
            result.fizzled = true
            result.description = "The spell fizzles."
            result.effects[#result.effects + 1] = "counter_spell_fizzled"
            return
        end
        if action.proudAndAncientWarCry == true or action.proudAndAncient == true or
           action.warCry == "proud_and_ancient" then
            self:resolveProudAndAncientWarCry(action, result)
            return
        end

        local spell = self:getSpellFromAction(action)

        if not spell then
            result.success = false
            result.description = "No spell selected."
            result.effects[#result.effects + 1] = "spell_missing"
            return
        end

        if spell.targetMode == "self" or spell.targetMode == "actor" then
            target = actor
            action.target = target
        end

        if spell.id == "totem" and not target then
            target = actor
            action.target = target
        end

        if spell.id == "portable_hole" and not target then
            target = portableHoleTargetFromAction(action, target)
            action.target = target
        end

        if spell.id == "mirror_meld" and not target then
            target = mirrorMeld.targetFromAction(action, target)
            action.target = target
        end

        local yellowKingDayOfTears = self:isYellowKingDayOfTears(action)
        if yellowKingDayOfTears then
            if not self:validateYellowKingDayOfTears(action, result) then
                return
            end
            action.resolveSpent = action.resolveSpent or self:getYellowKingDayOfTearsResolve(action)
        end

        local resolveSpent = action.resolveSpent or 1
        local brainSpiderSorcery, sorceryReason, sorceryEffectName =
            self:getBrainSpiderSorceryPayment(action, spell, resolveSpent)
        if brainSpiderSorcery == false then
            result.success = false
            result.description = sorceryReason
            result.effects[#result.effects + 1] = sorceryEffectName
            return
        elseif brainSpiderSorcery then
            resolveSpent = brainSpiderSorcery.spellResolveValue
            action.resolveSpent = resolveSpent
        end
        local strategistSorcery = nil
        if not brainSpiderSorcery then
            local strategistSorceryReason, strategistSorceryEffectName = nil, nil
            strategistSorcery, strategistSorceryReason, strategistSorceryEffectName =
                self:getStrategistSorceryPayment(action, spell, resolveSpent)
            if strategistSorcery == false then
                result.success = false
                result.description = strategistSorceryReason
                result.effects[#result.effects + 1] = strategistSorceryEffectName
                return
            elseif strategistSorcery then
                resolveSpent = strategistSorcery.spellResolveValue
                action.resolveSpent = resolveSpent
                action.resolveCommitted = 0
            end
        end
        local spiritNaturalSorcery, naturalSorceryReason, naturalSorceryEffectName =
            self:getSpiritNaturalSorceryPayment(action, spell, resolveSpent)
        if spiritNaturalSorcery == false then
            result.success = false
            result.description = naturalSorceryReason
            result.effects[#result.effects + 1] = naturalSorceryEffectName
            return
        elseif spiritNaturalSorcery then
            resolveSpent = spiritNaturalSorcery.spellResolveValue
            action.resolveSpent = resolveSpent
            action.resolveCommitted = 0
        end
        local componentlessSpellcasting = yellowKingDayOfTears or spiritNaturalSorcery ~= nil
        local sealPactParties = nil

        if spell.targetMode == "willing_parties" then
            sealPactParties = collectSealPactParties(action, target)
            if not target and #sealPactParties > 0 then
                target = sealPactParties[1]
                action.target = target
            end

            local valid, reason, effectName = validateSealPactParties(action, spell, resolveSpent, sealPactParties)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end

            action.parties = sealPactParties
        end

        if spell.id == "animate_object" then
            local valid, reason, effectName = validateAnimateObject(action, spell, resolveSpent, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "necromancy" then
            local valid, reason, effectName = validateNecromancy(action, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "fleshcraft" then
            local valid, reason, effectName = validateFleshcraft(action, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "raise_zombie" then
            local valid, reason, effectName = validateRaiseZombie(action, target, resolveSpent)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "malediction" then
            local valid, reason, effectName = validateMalediction(action, target, self)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "circle_of_protection" then
            local valid, reason, effectName = validateCircleProtection(action, spell, resolveSpent)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "defy_depths" then
            local valid, reason, effectName = validateDefyDepths(action, spell, resolveSpent, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "gust_of_wind" then
            local valid, reason, effectName = self:validateGustOfWind(action, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "protection_from_elements" then
            local valid, reason, effectName = validateProtectionFromElements(action, spell, resolveSpent, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "thunderclap" then
            local valid, reason, effectName = self:validateThunderclap(action, actor)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "totem" then
            local valid, reason, effectName = validateTotem(action, target, self)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "scry" then
            local valid, reason, effectName = validateScry(action, resolveSpent, actor, spell)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "wall_of_elements" then
            local valid, reason, effectName = validateWallOfElements(action, resolveSpent)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "woodweave" then
            local valid, reason, effectName = validateWoodweave(action, actor, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "change_size" then
            local valid, reason, effectName = validateChangeSize(action, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "give_form_to_nothingness" then
            local valid, reason, effectName = validateGiveFormToNothingness(action, spell, resolveSpent, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "portable_hole" then
            local valid, reason, effectName, surface = validatePortableHole(action, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
            target = surface
            action.target = target
        end

        if spell.id == "mirror_meld" then
            local valid, reason, effectName, mirror = mirrorMeld.validate(action, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
            target = mirror
            action.target = target
        end

        if spell.id == "illusion" then
            local valid, reason, effectName = validateVisualIllusion(action)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "darklight" then
            local valid, reason, effectName = validateDarklight(action, spell, resolveSpent, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.id == "stinking_cloud" then
            local valid, reason, effectName = self:validateStinkingCloud(action, target, actor, resolveSpent)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if spell.effect and spell.effect.type == "control" then
            local valid, reason, effectName = validateControlSpell(action, spell, resolveSpent, target)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if not componentlessSpellcasting and not self:actorKnowsSpell(actor, spell) then
            result.success = false
            result.description = "Missing training for " .. (spell.name or "spell") .. "."
            result.effects[#result.effects + 1] = "spell_training_missing"
            return
        end

        if not target and spell.targetMode ~= "environment" and spell.targetMode ~= "environment_or_creature" and
           spell.targetMode ~= "willing_parties" and spell.targetMode ~= "self" and spell.targetMode ~= "actor" then
            result.success = false
            result.description = "No target for " .. (spell.name or "spell") .. "."
            result.effects[#result.effects + 1] = "spell_target_missing"
            return
        end

        if spell.multiTarget and type(action.targets) == "table" and #action.targets > math.max(1, resolveSpent) then
            result.success = false
            result.description = spell.name .. " needs more Resolve for that many targets."
            result.effects[#result.effects + 1] = "spell_too_many_targets"
            return
        end

        if spell.id == "guardian_angel" and target and target.guardianAngel and not target.guardianAngel.used then
            result.success = false
            result.description = "Guardian Angel is already protecting " .. (target.name or "target") .. "."
            result.effects[#result.effects + 1] = "guardian_angel_already_active"
            return
        end

        if not self:canSpeakSpell(actor) then
            result.success = false
            result.description = "Spellcasting requires loud, clear speech."
            result.effects[#result.effects + 1] = "spell_speech_blocked"
            return
        end

        if actor and ((actor.conditions or {}).cannot_cast_spells or actor.cannot_cast_spells or actor.cannotCastSpells) then
            result.success = false
            result.description = "This effect prevents spellcasting."
            result.effects[#result.effects + 1] = "spellcasting_blocked"
            return
        end

        if not self:canSeeOrTouchSpellTarget(action) then
            result.success = false
            result.description = "Spell target must be visible or touchable."
            result.effects[#result.effects + 1] = "spell_target_unreachable"
            return
        end

        if self:isAnimateStatueMagicNullBlocked(target, spell, action) then
            result.success = false
            result.description = (target.name or "Animate statue") .. " is Magically Null."
            result.effects[#result.effects + 1] = "animate_statue_magic_null"
            result.effects[#result.effects + 1] = "magic_null"
            return
        end

        local component = nil
        if not componentlessSpellcasting then
            component = self:findSpellComponent(actor, spell)
        end
        if not component and not componentlessSpellcasting then
            result.success = false
            result.description = "Missing held component for " .. (spell.name or "spell") .. "."
            result.effects[#result.effects + 1] = "spell_component_missing"
            return
        end

        if spell.id == "give_form_to_nothingness" then
            local valid, reason, effectName = validateGiveFormDrumUse(action, actor, component)
            if not valid then
                result.success = false
                result.description = reason
                result.effects[#result.effects + 1] = effectName
                return
            end
        end

        if self:hasSpellcastingBlockingIron(actor) then
            result.success = false
            result.description = "Iron or steel prevents spellcasting."
            result.effects[#result.effects + 1] = "iron_blocks_magic"
            return
        end

        if spell.targetMode == "willing_parties" then
            for _, party in ipairs(sealPactParties or {}) do
                if self:hasSignificantIron(party) then
                    result.success = false
                    result.description = "Iron on a pact party makes the spell fizzle."
                    result.effects[#result.effects + 1] = "iron_blocks_magic"
                    return
                end
            end
        elseif target and self:hasSignificantIron(target) then
            result.success = false
            result.description = "Iron on the target makes the spell fizzle."
            result.effects[#result.effects + 1] = "iron_blocks_magic"
            return
        end

        if spell.concentration then
            local activeConcentration = self:getConcentrationSpell(actor)
            if activeConcentration then
                if action.endCurrentConcentration then
                    self:endOngoingSpell(actor, activeConcentration, "replaced_by_new_concentration", {
                        source = action,
                    })
                else
                    result.success = false
                    result.description = "Already concentrating on a spell."
                    result.effects[#result.effects + 1] = "concentration_slot_full"
                    return
                end
            end
        end

        local needsTrainingXP = (not componentlessSpellcasting) and self:spellUsesTrainingXP(actor, spell)
        if needsTrainingXP and not self:hasTrainingXP(actor) then
            result.success = false
            result.description = "In-training spellcasting requires 1 XP."
            result.effects[#result.effects + 1] = "spell_training_xp_missing"
            return
        end

        local pactCharge = nil
        local resolveCost = yellowKingDayOfTears and 0 or resolveSpent
        if spiritNaturalSorcery then
            resolveCost = spiritNaturalSorcery.resolveCost
            action.resolveCommitted = 0
        end
        if action.usePactCharge or action.spendPactCharge then
            pactCharge = self:getPactChargeForSpell(component, spell)
            if not pactCharge then
                result.success = false
                result.description = "No pact charge is available for " .. (spell.name or "spell") .. "."
                result.effects[#result.effects + 1] = "pact_charge_missing"
                return
            end
            resolveCost = math.max(0, resolveSpent - 1)
        end
        if brainSpiderSorcery then
            resolveCost = brainSpiderSorcery.resolveCost
            action.resolveCommitted = 0
        end
        if strategistSorcery then
            resolveCost = strategistSorcery.resolveCost
            action.resolveCommitted = 0
        end

        local resolveOk, resolveReason = self:spendSpellResolve(actor, resolveCost)
        if not resolveOk then
            result.success = false
            result.description = "Cannot cast: " .. (resolveReason or "resolve unavailable") .. "."
            result.effects[#result.effects + 1] = "resolve_missing"
            return
        end

        if needsTrainingXP then
            if not self:spendTrainingXP(actor) then
                if actor and actor.resolve ~= nil then
                    actor.resolve = actor.resolve + resolveCost
                end
                result.success = false
                result.description = "In-training spellcasting requires 1 XP."
                result.effects[#result.effects + 1] = "spell_training_xp_missing"
                return
            end
            result.effects[#result.effects + 1] = "spell_training_xp_spent"
        end

        if pactCharge then
            self:spendPactCharge(component, pactCharge, spell, actor)
            action.resolveCommitted = resolveCost
            result.pactChargeSpent = true
            result.pactCharge = pactCharge
            result.effects[#result.effects + 1] = "pact_charge_spent"
        end

        result.spell = spell
        result.component = component
        result.resolveSpent = resolveCost
        result.spellResolveValue = resolveSpent
        result.spellcasting = {
            actor = actor,
            actorId = actor and actor.id,
            target = target,
            targetId = target and target.id,
            spell = spell,
            spellId = spell.id,
            spellName = spell.name,
            branch = spell.branch,
            component = component,
            componentId = component and component.id,
            componentName = component and (component.name or component.id),
            resolveSpent = resolveCost,
            spellResolveValue = resolveSpent,
            resolveCommitted = action.resolveCommitted,
            pactChargeSpent = result.pactChargeSpent == true,
            pactCharge = result.pactCharge,
            componentlessSpellcasting = componentlessSpellcasting == true,
            trainingXPSpent = needsTrainingXP == true,
            card = action.card,
        }
        if brainSpiderSorcery then
            result.brainSpiderSorcery = {
                greaterDoomCards = brainSpiderSorcery.greaterDoomCards,
                spellResolveValue = brainSpiderSorcery.spellResolveValue,
            }
            result.spellcasting.brainSpiderSorcery = result.brainSpiderSorcery
            result.effects[#result.effects + 1] = "brain_spider_sorcery"
            result.effects[#result.effects + 1] = "greater_doom_instead_of_resolve"
        end
        if strategistSorcery then
            result.strategistSorcery = {
                greaterDoomCards = strategistSorcery.greaterDoomCards,
                spellResolveValue = strategistSorcery.spellResolveValue,
            }
            result.spellcasting.strategistSorcery = result.strategistSorcery
            result.effects[#result.effects + 1] = "strategist_sorcery"
            result.effects[#result.effects + 1] = "greater_doom_instead_of_resolve"
        end
        if spiritNaturalSorcery then
            result.spiritNaturalSorcery = {
                doom = spiritNaturalSorcery.doom,
                spellResolveValue = spiritNaturalSorcery.spellResolveValue,
            }
            result.spellcasting.spiritNaturalSorcery = result.spiritNaturalSorcery
            result.effects[#result.effects + 1] = "spirit_natural_sorcery"
            result.effects[#result.effects + 1] = "componentless_spellcasting"
            result.effects[#result.effects + 1] = "no_resolve_spellcasting"
        end
        if yellowKingDayOfTears then
            result.yellowKingDayOfTears = {
                greaterDoomCards = 1 + math.max(0, resolveSpent - 1),
                spellResolveValue = resolveSpent,
            }
            result.spellcasting.yellowKingDayOfTears = result.yellowKingDayOfTears
            result.effects[#result.effects + 1] = "yellow_king_day_of_tears_and_mourning"
            result.effects[#result.effects + 1] = "componentless_spellcasting"
            result.effects[#result.effects + 1] = "greater_doom_instead_of_resolve"
        end

        if self:isSpellContestRequired(action, spell, target) then
            local originalTarget = action.target
            action.target = self:getSpellContestTarget(action, target)
            local contest = self:resolveInitiativeContest(action, result, {
                tieWins = true,
                considerShield = true,
            })
            action.target = originalTarget
            if contest.dodged then
                return
            end
        else
            result.success = true
        end

        if result.success then
            result.effects[#result.effects + 1] = "spell_cast"
            result.effects[#result.effects + 1] = "spell_" .. spell.id
            local applied = self:applySpellEffect(action, result, spell)
            if result.spellcasting then
                result.spellcasting.success = result.success
                result.spellcasting.description = result.description
                result.spellcasting.effects = result.effects
                result.spellcasting.targets = result.spellTargets or result.bindingTargets
                result.spellcasting.spellTargets = result.spellTargets
                result.spellcasting.bindingTargets = result.bindingTargets
                result.spellcasting.activeSpell = result.activeSpell
                result.spellcasting.ongoingSpell = result.activeSpell ~= nil
                result.spellcasting.animatedObject = result.animatedObject
                result.spellcasting.controlOrder = result.controlOrder
                result.spellcasting.malediction = result.malediction
                result.spellcasting.raisedZombie = result.raisedZombie
                result.spellcasting.fleshcraft = result.fleshcraft
                result.spellcasting.giveForm = result.giveForm
                result.spellcasting.portableHole = result.portableHole
                result.spellcasting.mirrorMeld = result.mirrorMeld
                result.spellcasting.visualIllusion = result.visualIllusion
                result.spellcasting.truthSense = result.truthSense
                result.spellcasting.stinkingCloud = result.stinkingCloud
            end
            if applied ~= false and result.success ~= false then
                self.eventBus:emit(events.EVENTS.SPELL_CAST, {
                    actor = actor,
                    spell = spell,
                    target = target,
                    resolveSpent = resolveSpent,
                    result = result,
                })
            end
        else
            result.description = "Incantation resisted."
        end
    end

    -- Backward-compatible wrapper
    function resolver:resolveCast(action, result)
        self:resolveSpeakIncantation(action, result)
    end

    function resolver:resolveGuard(action, result)
        local actor = action.actor
        if not actor then
            result.success = false
            result.description = "No actor for Guard."
            return
        end

        if not self:entityHasShield(actor) then
            result.success = false
            result.description = "Guard requires a shield."
            return
        end

        local controller = action.challengeController or self.challengeController
        if not controller or not controller.getInitiativeSlot then
            result.success = false
            result.description = "No initiative slot available."
            return
        end

        local slot = controller:getInitiativeSlot(actor.id)
        if not slot then
            result.success = false
            result.description = "No initiative to replace."
            return
        end

        local oldCard = slot.card
        local oldValue = slot.value or (oldCard and oldCard.value) or 0
        slot.card = action.card
        slot.value = action.card and action.card.value or oldValue
        slot.revealed = true

        result.oldInitiativeCard = oldCard
        result.oldInitiativeValue = oldValue
        result.newInitiativeCard = slot.card
        result.newInitiativeValue = slot.value

        local discardDeck = action.discardDeck or slot.discardDeck or slot.deck
        if not discardDeck then
            discardDeck = actor.isPC and
                (action.playerDeck or self.playerDeck or controller.playerDeck) or
                (action.gmDeck or self.gmDeck or controller.gmDeck)
        end
        if oldCard and oldCard ~= action.card and discardChallengeCardToDeck(discardDeck, oldCard) then
            result.oldInitiativeCardDiscarded = oldCard
            result.effects[#result.effects + 1] = "guard_old_initiative_discarded"
        end

        self.eventBus:emit(events.EVENTS.INITIATIVE_REVEALED, {
            entity = actor,
        })

        result.success = true
        result.description = "Guard set Initiative from " .. oldValue .. " to " .. slot.value .. "."
        result.effects[#result.effects + 1] = "guarded"
    end

    function resolver:getWornIronOrSteelArmor(actor)
        if not actor then
            return nil
        end

        local actorArmorType = normalizeSocialTag(actor.armorType or actor.wornArmorType)
        if actorArmorType == "iron" or actorArmorType == "steel" then
            return actor.armor or actor
        end

        local inv = actor.inventory
        local belt = inv and inv.getItems and inv:getItems(inventory.LOCATIONS.BELT) or inv and inv.belt or {}
        for _, item in ipairs(belt or {}) do
            local props = item.properties or {}
            local armorType = normalizeSocialTag(item.armorType or props.armorType)
            if (item.isArmor or props.armor) and not item.destroyed and
               (armorType == "iron" or armorType == "steel") then
                return item
            end
        end

        return nil
    end

    function resolver:resolveHeavyMetalMachine(action, result)
        local actor = action.actor
        if not actor then
            result.success = false
            result.description = "No actor for Heavy Metal Machine."
            return
        end

        if not entityHasUsableTalent(actor, "heavy_metal_machine") then
            result.success = false
            result.description = "Requires Heavy Metal Machine."
            result.effects[#result.effects + 1] = "heavy_metal_machine_blocked"
            return
        end
        if not self:isActiveChallengeAction(action) then
            result.success = false
            result.description = "Heavy Metal Machine requires an active Challenge."
            result.effects[#result.effects + 1] = "heavy_metal_machine_blocked"
            return
        end

        local armor = self:getWornIronOrSteelArmor(actor)
        if not armor then
            result.success = false
            result.description = "Requires worn iron or steel armor."
            result.effects[#result.effects + 1] = "heavy_metal_machine_blocked"
            return
        end

        local controller = action.challengeController or self.challengeController
        if not controller or not controller.getInitiativeSlot then
            result.success = false
            result.description = "No initiative slot available."
            result.effects[#result.effects + 1] = "heavy_metal_machine_blocked"
            return
        end

        local slot = controller:getInitiativeSlot(actor.id)
        if not slot then
            result.success = false
            result.description = "No initiative to boost."
            result.effects[#result.effects + 1] = "heavy_metal_machine_blocked"
            return
        end

        local round = controller.currentRound or action.currentRound or 1
        if actor.heavyMetalMachineUsedRound == round then
            result.success = false
            result.description = "Heavy Metal Machine already used this round."
            result.effects[#result.effects + 1] = "heavy_metal_machine_spent"
            return
        end

        local bonus = actor.swords or (actor.getAttribute and actor:getAttribute(constants.SUITS.SWORDS)) or 0
        actor.heavyMetalMachineUsedRound = round
        actor.heavyMetalMachineInterrupt = {
            round = round,
            bonus = bonus,
            card = action.card,
            armor = armor,
            againstAction = action.againstAction,
            againstActionId = action.againstActionId,
            againstActorId = action.againstActorId,
        }

        result.success = true
        result.heavyMetalMachine = actor.heavyMetalMachineInterrupt
        result.description = "Heavy Metal Machine readied +" .. tostring(bonus) .. " Initiative."
        result.effects[#result.effects + 1] = "heavy_metal_machine_readied"
    end

    local function resolveFollowUpActionType(followUpAction)
        if type(followUpAction) == "table" then
            return followUpAction.id or followUpAction.type
        end
        return followUpAction
    end

    --- Pick a sensible same-suit follow-up when UI did not provide one.
    function resolver:selectDefaultVigilanceFollowUp(action)
        if not action or not action.card then
            return nil
        end

        local cardActionSuit = action_registry.cardSuitToActionSuit(action.card.suit)
        if cardActionSuit == action_registry.SUITS.MISC then
            return nil
        end

        local options = action_registry.getActionsForSuit(cardActionSuit, {
            challengeOnly = true,
        })

        for _, option in ipairs(options) do
            local optionType = self:normalizeActionType(option.id)
            if optionType ~= M.ACTION_TYPES.VIGILANCE then
                return optionType
            end
        end

        return nil
    end

    function resolver:resolveVigilance(action, result)
        local actor = action.actor
        if not actor then
            result.success = false
            result.description = "No actor for Vigilance."
            return
        end

        local followUpActionType = resolveFollowUpActionType(action.followUpAction)
        followUpActionType = self:normalizeActionType(followUpActionType)
        if not followUpActionType then
            followUpActionType = self:selectDefaultVigilanceFollowUp(action)
        end
        if not followUpActionType then
            result.success = false
            result.description = "Vigilance needs a follow-up action."
            return
        end

        local followUpActionDef = action_registry.getAction(followUpActionType)
        if not followUpActionDef then
            result.success = false
            result.description = "Unknown Vigilance follow-up action."
            return
        end

        local allowedMiscFollowUp = isAllowedMiscVigilanceFollowUp(followUpActionType, followUpActionDef)

        if followUpActionDef.suit == action_registry.SUITS.MISC and not allowedMiscFollowUp then
            result.success = false
            result.description = "Vigilance follow-up must be a suited action."
            return
        end

        if not action.card or not action.card.suit then
            result.success = false
            result.description = "Vigilance requires a suited card."
            return
        end

        local cardActionSuit = action_registry.cardSuitToActionSuit(action.card.suit)
        if cardActionSuit == action_registry.SUITS.MISC then
            result.success = false
            result.description = "Vigilance requires a non-misc suit card."
            return
        end

        if not allowedMiscFollowUp and followUpActionDef.suit ~= cardActionSuit then
            result.success = false
            result.description = "Vigilance follow-up suit must match card suit."
            return
        end

        self:discardActorFacedownActions(actor, action, result, {
            newType = "vigilance",
            reason = "facedown_replaced_by_vigilance",
        })

        local followUpTargetPolicy = action.followUpTargetPolicy
        if not followUpTargetPolicy then
            if followUpActionDef.targetType == "enemy" then
                followUpTargetPolicy = "trigger_actor"
            elseif followUpActionDef.targetType == "ally" then
                followUpTargetPolicy = "self"
            else
                followUpTargetPolicy = "none"
            end
        end

        self.vigilanceCounter = (self.vigilanceCounter or 0) + 1

        actor.pendingVigilance = {
            card = action.card,
            trigger = action.trigger or action.triggerAction or {
                mode = "targeted_by_hostile_action",
                target = "self",
                hostileOnly = true,
                excludeSelf = true,
            },
            followUpAction = followUpActionType,
            followUpTargetPolicy = followUpTargetPolicy,
            followUpTarget = action.followUpTarget or action.target,
            followUpDestinationZone = action.followUpDestinationZone,
            weapon = action.weapon,
            declaredOrder = self.vigilanceCounter,
        }

        self.eventBus:emit("vigilance_prepared", {
            actor = actor,
            trigger = actor.pendingVigilance.trigger,
            followUpAction = actor.pendingVigilance.followUpAction,
        })

        result.success = true
        result.vigilance = actor.pendingVigilance
        result.facedownAction = {
            actor = actor,
            type = "vigilance",
            card = action.card,
            value = action.card.value or 0,
            faceValue = action.card.value or 0,
            trigger = actor.pendingVigilance.trigger,
            followUpAction = actor.pendingVigilance.followUpAction,
            followUpActionName = followUpActionDef.name or followUpActionType,
            followUpTargetPolicy = actor.pendingVigilance.followUpTargetPolicy,
            followUpTarget = actor.pendingVigilance.followUpTarget,
            followUpDestinationZone = actor.pendingVigilance.followUpDestinationZone,
            weapon = actor.pendingVigilance.weapon,
            declaredOrder = actor.pendingVigilance.declaredOrder,
            isMinorAction = action.isMinorAction == true,
            replacedFacedownActions = result.replacedFacedownActions,
        }
        result.description = "Vigilance prepared: " ..
            (followUpActionDef.name or followUpActionType) .. "."
        result.effects[#result.effects + 1] = "vigilance_prepared"
    end

    ----------------------------------------------------------------------------
    -- GENERIC RESOLUTION
    ----------------------------------------------------------------------------

    function resolver:getRetreatParticipants(action)
        if type(action.participants) == "table" then
            return action.participants
        end
        if type(action.guild) == "table" then
            return action.guild
        end

        local controller = action.challengeController or self.challengeController
        if controller and type(controller.pcs) == "table" then
            return controller.pcs
        end

        if action.actor then
            return { action.actor }
        end
        return {}
    end

    function resolver:getRetreatPentacles(participant)
        if not participant then
            return 0
        end
        if participant.getAttribute then
            local value = participant:getAttribute(constants.SUITS.PENTACLES)
            if value ~= nil then
                return tonumber(value) or 0
            end
        end
        if participant.pentacles ~= nil then
            return tonumber(participant.pentacles) or 0
        end
        local attributes = participant.attributes or {}
        return tonumber(attributes[constants.SUITS.PENTACLES] or attributes.pentacles or 0) or 0
    end

    function resolver:getRetreatGroupTesters(participants)
        local highest = nil
        local lowest = nil
        local highestPentacles = nil
        local lowestPentacles = nil

        for _, participant in ipairs(participants or {}) do
            if participant then
                local pentacles = self:getRetreatPentacles(participant)
                if not highest or pentacles > highestPentacles then
                    highest = participant
                    highestPentacles = pentacles
                end
                if not lowest or pentacles < lowestPentacles then
                    lowest = participant
                    lowestPentacles = pentacles
                end
            end
        end

        local testers = {}
        local function addTester(role, participant, pentacles)
            testers[#testers + 1] = {
                role = role,
                actor = participant,
                actorId = participant and (participant.id or participant.name),
                actorName = participant and participant.name,
                pentacles = pentacles or 0,
            }
        end

        if highest then
            addTester("highest", highest, highestPentacles)
        end
        if lowest and lowest ~= highest then
            addTester("lowest", lowest, lowestPentacles)
        elseif lowest and highest and testers[1] then
            testers[1].alsoLowest = true
        end

        return testers
    end

    function resolver:getRetreatCleverTactics(action)
        local source = action.cleverTactics or action.escapeTactics or action.retreatTactics
        local tactics = {}

        if type(source) == "table" then
            for _, tactic in ipairs(source) do
                if type(tactic) == "table" then
                    tactics[#tactics + 1] = {
                        description = tactic.description or tactic.summary or tactic.name or tostring(tactic.id or "clever tactic"),
                        actorId = tactic.actorId or (tactic.actor and tactic.actor.id),
                        target = tactic.target or tactic.favorTarget or tactic.testTarget,
                    }
                elseif tactic ~= nil then
                    tactics[#tactics + 1] = {
                        description = tostring(tactic),
                    }
                end
            end
        elseif source ~= nil then
            tactics[#tactics + 1] = {
                description = tostring(source),
            }
        end

        if action.cleverEscape == true or action.cleverRetreat == true or action.cleverTactic == true then
            tactics[#tactics + 1] = {
                description = action.cleverTacticDescription or action.escapeTacticDescription or "clever retreat tactic",
            }
        end

        return tactics
    end

    function resolver:normalizeRetreatComplicationId(value)
        if value == nil then
            return nil
        end
        local normalized = tostring(value):lower():gsub("^%s+", ""):gsub("%s+$", ""):gsub("[%s%-]+", "_")
        if normalized == "last_rank" or normalized == "last_in_line" or normalized == "last_marching_order" or
           normalized == "caught_last" or normalized == "caught_last_in_marching_order" or
           normalized == "grapple_last" or normalized == "last_rank_grappled" then
            return "caught_last_marching_order"
        end
        if normalized == "trap_route" or normalized == "route_trap" or normalized == "dangerous_route" or
           normalized == "escape_route_dangerous" or normalized == "trigger_trap" then
            return "dangerous_escape_route"
        end
        if normalized == "" then
            return nil
        end
        return normalized
    end

    function resolver:getLastRetreatParticipant(participants)
        local selected = nil
        local selectedRank = nil
        for index, participant in ipairs(participants or {}) do
            if participant then
                local rank = tonumber(participant.marchingOrder or participant.marchingRank or participant.order or index) or index
                if not selected or rank > selectedRank then
                    selected = participant
                    selectedRank = rank
                end
            end
        end
        return selected
    end

    function resolver:findRetreatParticipant(participants, target)
        if type(target) == "table" then
            return target
        end
        if target == nil then
            return nil
        end

        local normalized = tostring(target):lower()
        if normalized == "last" or normalized == "last_in_line" or
           normalized == "last_in_marching_order" or normalized == "last_rank" then
            return self:getLastRetreatParticipant(participants)
        end

        for _, participant in ipairs(participants or {}) do
            if participant then
                local id = participant.id and tostring(participant.id):lower()
                local name = participant.name and tostring(participant.name):lower()
                if normalized == id or normalized == name then
                    return participant
                end
            end
        end
        return nil
    end

    function resolver:getRetreatComplication(action, participants)
        local source = action.retreatComplication or action.escapeComplication or action.complication
        local explicitTarget = action.retreatComplicationTarget or action.complicationTarget
        if source == false then
            return nil
        end
        if source == nil or source == true then
            source = {}
        elseif type(source) ~= "table" then
            source = {
                description = tostring(source),
            }
        end

        local id = self:normalizeRetreatComplicationId(
            source.id or source.type or source.kind or source.effect or source.complicationId
        ) or "gm_complication"
        local targetToken = source.target or source.targetId or source.actorId or explicitTarget
        local target = self:findRetreatParticipant(participants, targetToken)
        local targetRole = source.targetRole
        local rulebookExample = false
        local routeDangerous = source.routeDangerous == true or source.escapeRouteDangerous == true
        local description = source.description or source.summary or source.text or source.name

        if id == "caught_last_marching_order" then
            rulebookExample = true
            target = target or self:getLastRetreatParticipant(participants)
            targetRole = targetRole or "last_in_marching_order"
            description = description or "The pursuing creature catches up and grapples the last adventurer in the marching order."
        elseif id == "dangerous_escape_route" then
            rulebookExample = true
            routeDangerous = true
            description = description or "The retreat triggers a trap or makes the obvious escape route dangerous."
        else
            description = description or "The GM introduces a retreat complication."
        end

        local complication = {
            id = id,
            description = description,
            target = target,
            targetId = target and (target.id or target.name) or targetToken,
            targetName = target and target.name or nil,
            targetRole = targetRole,
            route = source.route or source.escapeRoute,
            trap = source.trap,
            hazard = source.hazard,
            routeDangerous = routeDangerous,
            rulebookExample = rulebookExample,
            gmAuthored = source.gmAuthored ~= false,
        }

        return complication
    end

    function resolver:getRetreatPursuitAdjudication(action, branch, pursuit, mobility)
        local authored = action.retreatAdjudication or action.retreatPursuit or action.pursuitAdjudication
        if authored == false then
            return nil
        end
        if authored ~= nil and type(authored) ~= "table" then
            authored = {
                description = tostring(authored),
            }
        end
        authored = authored or {}

        local option = action.retreatOption
        local reason = authored.reason or authored.description or authored.summary or authored.text or
            action.retreatPursuitReason or action.pursuitReason or action.enemyPursuitReason or
            action.escapeReason or (type(option) == "table" and option.description)
        local source = authored.source or action.retreatPursuitSource or
            (type(option) == "table" and "command_board") or "gm"

        if not reason or reason == "" then
            if branch == "impossible" then
                reason = "The pursuer is too fast or has magical locomotion."
            elseif branch == "no_pursuit" then
                reason = "The enemy is slow, awkward, tied to its lair, or unwilling to pursue."
            else
                reason = "The enemy's mobility is equivalent, or terrain gives the guild a chance to shake pursuit."
            end
        end

        return {
            branch = branch,
            reason = reason,
            source = source,
            pursuit = pursuit,
            mobility = mobility,
            optionId = action.retreatOptionId or authored.optionId or (type(option) == "table" and option.id),
            optionName = authored.optionName or (type(option) == "table" and option.name),
            enemyTiedToLair = action.enemyTiedToLair == true,
            enemyWillNotPursue = action.enemyWillNotPursue == true,
            escapeImpossible = action.escapeImpossible == true or action.canRetreat == false,
        }
    end

    function resolver:retreatFavorTargetMatches(test, target)
        if not test or target == nil then
            return false
        end
        local normalized = tostring(target):lower()
        if normalized == "high" then
            normalized = "highest"
        elseif normalized == "low" then
            normalized = "lowest"
        end
        return normalized == tostring(test.role or ""):lower() or
            normalized == tostring(test.actorId or ""):lower() or
            normalized == tostring(test.actorName or ""):lower()
    end

    function resolver:buildRetreatGroupTestRequest(action)
        local request = {
            attribute = "pentacles",
            targetSuit = constants.SUITS.PENTACLES,
            testers = self:getRetreatGroupTesters(self:getRetreatParticipants(action)),
        }
        local tactics = self:getRetreatCleverTactics(action)
        if #tactics > 0 then
            local favorTarget = action.retreatFavorTarget or action.favorTarget or action.cleverTacticFavorTarget
            request.cleverTactics = tactics
            request.favorTarget = favorTarget
            request.favorChoiceRequired = favorTarget == nil

            for _, test in ipairs(request.testers) do
                if self:retreatFavorTargetMatches(test, favorTarget) then
                    test.favor = true
                    test.favorSource = "clever_retreat_tactic"
                end
            end
        end
        return request
    end

    function resolver:getRetreatTestCard(cards, test, index)
        if type(cards) ~= "table" then
            return nil
        end
        return cards[test.role] or cards[test.actorId] or cards[test.actorName] or cards[index]
    end

    function resolver:getRetreatTestResults(action)
        if type(action.testResults) == "table" then
            return action.testResults
        end
        if type(action.groupTestResults) == "table" then
            return action.groupTestResults
        end
        if type(action.retreatTests) == "table" then
            return action.retreatTests
        end

        local cards = action.retreatTestCards or action.groupTestCards or action.testCards
        if type(cards) == "table" then
            local request = self:buildRetreatGroupTestRequest(action)
            local results = {}
            for index, test in ipairs(request.testers or {}) do
                local card = self:getRetreatTestCard(cards, test, index)
                if card then
                    results[#results + 1] = fate_resolver.resolveTest(
                        test.pentacles or 0,
                        constants.SUITS.PENTACLES,
                        card,
                        test.favor
                    )
                end
            end
            if #results < #(request.testers or {}) then
                return {}
            end
            return results
        end

        local tests = {}
        if action.highTestResult then
            tests[#tests + 1] = action.highTestResult
        end
        if action.lowTestResult then
            tests[#tests + 1] = action.lowTestResult
        end
        return tests
    end

    function resolver:markRetreatParticipants(participants)
        for _, participant in ipairs(participants or {}) do
            if participant then
                participant.retreated = true
                participant.fledChallenge = true
                participant.conditions = participant.conditions or {}
                participant.conditions.fled = true
            end
        end
    end

    function resolver:finishRetreat(action, result, outcome)
        local participants = self:getRetreatParticipants(action)
        result.participants = participants
        result.retreatOutcome = outcome
        result.escaped = true
        self:markRetreatParticipants(participants)

        local controller = action.challengeController or self.challengeController
        if controller and controller.endChallenge and action.endChallenge ~= false then
            controller:endChallenge("fled", {
                retreat = result,
                participants = participants,
                outcome = "fled",
            })
            result.challengeEnded = true
        end

        self.eventBus:emit("retreat_resolved", {
            actor = action.actor,
            action = action,
            result = result,
            participants = participants,
        })
    end

    function resolver:resolveFlee(action, result)
        result.effects[#result.effects + 1] = "retreat"

        local pursuit = tostring(action.pursuit or action.enemyPursuit or action.pursuitType or ""):lower()
        local mobility = tostring(action.enemyMobility or action.pursuerMobility or ""):lower()

        if action.canRetreat == false or action.escapeImpossible == true or
           action.enemyAutomaticallyCatches == true or action.automaticPursuit == true or
           pursuit == "automatic" or pursuit == "cannot_escape" or mobility == "fast" or mobility == "magical" then
            result.success = false
            result.retreatOutcome = "impossible"
            result.retreatPursuit = self:getRetreatPursuitAdjudication(action, "impossible", pursuit, mobility)
            result.retreatAdjudication = result.retreatPursuit
            result.description = "The pursuer is too fast or too magical to escape."
            result.effects[#result.effects + 1] = "retreat_impossible"
            return
        end

        if action.enemyWillNotPursue == true or action.enemyTiedToLair == true or
           pursuit == "none" or pursuit == "no_pursuit" or pursuit == "will_not_pursue" or
           mobility == "slow" or mobility == "awkward" or mobility == "tied_to_lair" then
            result.success = true
            result.retreatPursuit = self:getRetreatPursuitAdjudication(action, "no_pursuit", pursuit, mobility)
            result.retreatAdjudication = result.retreatPursuit
            result.description = "The guild retreats; the enemy cannot or will not pursue."
            result.effects[#result.effects + 1] = "retreat_clean"
            result.effects[#result.effects + 1] = "retreat_no_pursuit"
            self:finishRetreat(action, result, "clean")
            return
        end

        local tests = self:getRetreatTestResults(action)
        if #tests == 0 then
            result.success = false
            result.needsGroupTest = true
            result.groupTestAttribute = "pentacles"
            result.groupTestRequest = self:buildRetreatGroupTestRequest(action)
            result.retreatPursuit = self:getRetreatPursuitAdjudication(action, "equivalent", pursuit, mobility)
            result.retreatAdjudication = result.retreatPursuit
            result.description = "Retreat requires a Pentacles group test from the highest and lowest Pentacles adventurers."
            result.effects[#result.effects + 1] = "retreat_group_test_required"
            return
        end

        local group = fate_resolver.resolveGroupTest(tests)
        result.groupTest = group
        result.groupTestAttribute = "pentacles"
        result.groupTestRequest = self:buildRetreatGroupTestRequest(action)
        result.retreatPursuit = self:getRetreatPursuitAdjudication(action, "equivalent", pursuit, mobility)
        result.retreatAdjudication = result.retreatPursuit

        if group.result == fate_resolver.GROUP_RESULTS.SUCCESS then
            result.success = true
            result.description = "The guild gets away cleanly."
            result.effects[#result.effects + 1] = "retreat_clean"
            self:finishRetreat(action, result, "clean")
        elseif group.result == fate_resolver.GROUP_RESULTS.TIGHT_SPOT then
            local participants = self:getRetreatParticipants(action)
            local complication = self:getRetreatComplication(action, participants)
            result.success = true
            result.complication = complication or true
            result.retreatComplication = complication
            result.description = complication and complication.description or
                "The guild escapes, but the GM introduces a complication."
            result.effects[#result.effects + 1] = "retreat_complication"
            self:finishRetreat(action, result, "complication")
        else
            result.success = false
            result.cornered = true
            result.description = "The guild is cornered with no clear path of escape."
            result.effects[#result.effects + 1] = group.result == fate_resolver.GROUP_RESULTS.DISASTER
                and "retreat_disaster" or "retreat_cornered"
        end
    end

    function resolver:findTrivialPickUpItem(action, target)
        local item = action.item or action.groundItem
        local itemId = action.itemId or (type(item) == "table" and item.id or nil)
        if type(item) == "string" then
            itemId = itemId or item
            item = nil
        end
        local groundItems = action.groundItems
        local owner = action.itemOwner or action.groundOwner or action.sourceActor or action.owner

        if target and target.groundItems then
            owner = owner or target
        elseif not item and target and not target.isOpen and not target.activated then
            item = target
            itemId = (type(item) == "table" and item.id or nil) or itemId
        end

        if owner and owner.groundItems then
            groundItems = owner.groundItems
        end

        if groundItems then
            for index, candidate in ipairs(groundItems) do
                if candidate == item or (itemId and candidate.id == itemId) then
                    return candidate, groundItems, index, owner
                end
            end
            if not item and #groundItems > 0 then
                return groundItems[#groundItems], groundItems, #groundItems, owner
            end
        end

        return item, nil, nil, owner
    end

    function resolver:clearGroundItemMarkers(item)
        if not item then
            return
        end
        item.dropped = false
        item.isDropped = false
        item.onGround = false
        item.groundZone = nil
        item.droppedBy = nil
        local location = normalizeTalentKey(item.location)
        if location == "ground" or location == "dropped" or location == "floor" then
            item.location = nil
        end
    end

    function resolver:resolveTrivialPickUpItem(action, result, target)
        local actor = action.actor
        if not actor then
            result.success = false
            result.description = "No actor to pick up an item."
            result.effects[#result.effects + 1] = "trivial_pickup_no_actor"
            return
        end

        actor.inventory = actor.inventory or inventory.createInventory()
        if action.droppedItem or action.droppedItems then
            result.success = false
            result.description = "Dropped items require Recover during Challenges."
            result.effects[#result.effects + 1] = "trivial_pickup_requires_recover"
            return
        end

        local item, groundItems, groundIndex = self:findTrivialPickUpItem(action, target)
        if not item then
            result.success = false
            result.description = "No item to pick up."
            result.effects[#result.effects + 1] = "trivial_pickup_no_item"
            return
        end

        if item.dropped == true or item.isDropped == true then
            result.success = false
            result.description = "Dropped items require Recover during Challenges."
            result.effects[#result.effects + 1] = "trivial_pickup_requires_recover"
            return
        end

        local existing = item.id and actor.inventory:findItem(item.id)
        if existing then
            result.success = false
            result.description = "Item is already carried."
            result.effects[#result.effects + 1] = "trivial_pickup_already_carried"
            return
        end

        local destination = action.pickupLocation or action.destinationLocation or action.toLocation or
            inventory.LOCATIONS.HANDS
        local canStore, storeReason = self:canStoreItemInLocation(actor.inventory, item, destination)
        if not canStore then
            result.success = false
            result.description = "Cannot carry " .. (item.name or "item") .. "."
            result.effects[#result.effects + 1] = "trivial_pickup_blocked"
            result.effects[#result.effects + 1] = storeReason or "destination_full"
            return
        end

        if groundItems and groundIndex then
            table.remove(groundItems, groundIndex)
        end

        local ok, err = actor.inventory:addItem(item, destination)
        if not ok then
            if groundItems and groundIndex then
                table.insert(groundItems, groundIndex, item)
            end
            result.success = false
            result.description = "Cannot carry " .. (item.name or "item") .. "."
            result.effects[#result.effects + 1] = "trivial_pickup_blocked"
            result.effects[#result.effects + 1] = err or "inventory_add_failed"
            return
        end

        self:clearGroundItemMarkers(item)

        result.success = true
        result.item = item
        result.pickedUpItem = item
        result.pickupLocation = destination
        result.description = "Picked up " .. (item.name or "item") .. "."
        result.effects[#result.effects + 1] = "item_picked_up"
        result.effects[#result.effects + 1] = "ground_item_picked_up"

        self.eventBus:emit(events.EVENTS.INVENTORY_CHANGED, {
            entity = actor,
            item = item,
            location = destination,
            reason = "trivial_pick_up_item",
        })
    end

    function resolver:resolveSleepWakeAttempt(action, result)
        action = action or {}
        result = result or {
            success = false,
            effects = {},
            description = "",
        }
        result.effects = result.effects or {}

        local target = action.target or action.subject or action.sleeper
        if not target then
            result.success = false
            result.description = "No sleeper to awaken."
            result.effects[#result.effects + 1] = "sleep_wake_target_missing"
            action.result = result
            return result
        end

        target.conditions = target.conditions or {}
        if not (target.conditions.sleeping or target.conditions.knocked_out or target.conditions.knockout) then
            result.success = false
            result.description = (target.name or "Target") .. " is already awake."
            result.effects[#result.effects + 1] = "sleep_wake_target_awake"
            action.result = result
            return result
        end

        local wakeIntent = normalizeTrivialIntent({
            trivialAction = action.wakeMethod or action.method or action.trivialAction or
                action.intent or action.action,
        }) or "wake"
        local sharpSlap = wakeIntent == "sharp_slap" or wakeIntent == "slap" or
            wakeIntent == "slap_awake" or wakeIntent == "wake_with_sharp_slap"
        local sleep = target.sleep or {}
        local requiresSharpSlap = sleep.canAwakenWithSharpSlap == true or
            sleep.peacefulWakeMethod == "sharp_slap" or sleep.wake == "sharp_slap"

        if requiresSharpSlap and not sharpSlap then
            result.success = false
            result.description = (target.name or "Target") .. " can only be awoken with a sharp slap."
            result.effects[#result.effects + 1] = "sleep_wake_requires_sharp_slap"
            action.result = result
            return result
        end

        target.conditions.knocked_out = false
        target.conditions.knockout = false
        target.conditions.sleeping = false
        target.doesNotAgeWhileAsleep = nil
        target.requiresNoFoodWhileAsleep = nil

        if target.sleep then
            target.sleep.active = false
            target.sleep.awakened = true
            target.sleep.awakenedBy = action.actor
            target.sleep.awakenedById = action.actor and action.actor.id
            target.sleep.awakenedMethod = sharpSlap and "sharp_slap" or wakeIntent
        end

        result.success = true
        result.sleep = target.sleep
        result.effects[#result.effects + 1] = "sleep_awakened"
        result.effects[#result.effects + 1] = sharpSlap and "sleep_awakened_by_sharp_slap" or "awakened"
        result.effects[#result.effects + 1] = "knockout_cleared"
        result.description = sharpSlap and
            ((target.name or "Target") .. " wakes after a sharp slap.") or
            ((target.name or "Target") .. " wakes.")
        action.result = result
        return result
    end

    function resolver:isTrivialActionContested(action, target)
        if not action then
            return false
        end
        if action.allowContestedTrivialAction == true then
            return false
        end
        if action.contestedTrivialAction ~= nil then
            return action.contestedTrivialAction == true
        end
        if action.contested ~= nil then
            return action.contested == true
        end
        if action.opposed == true or action.requiresContest == true or action.targetInitiative ~= nil then
            return true
        end

        local intent = normalizeTrivialIntent(action)
        local targetConditions = target and target.conditions or {}
        if (intent == "wake" or intent == "awaken" or intent == "wake_up" or
            intent == "sharp_slap" or intent == "slap_awake" or intent == "wake_with_sharp_slap") and
           (targetConditions.sleeping or targetConditions.knocked_out or targetConditions.knockout) then
            return false
        end

        local actor = action.actor
        if target and target ~= actor and self:isCommandCombatantTarget(target) then
            if actor and actor.isPC ~= nil and target.isPC ~= nil then
                return actor.isPC ~= target.isPC
            end
            return action.hostile == true or action.againstCombatant == true
        end

        return false
    end

    function resolver:resolveTrivialAction(action, result)
        local actor = action.actor
        local intent = normalizeTrivialIntent(action)
        local target = action.target or action.object or action.feature

        result.success = true
        result.effects[#result.effects + 1] = "trivial_action"

        if self:isTrivialActionContested(action, target) then
            result.success = false
            result.description = "Trivial actions must be uncontested."
            result.effects[#result.effects + 1] = "trivial_action_contested"
            return
        end

        local totemMouthUse = self:applyTotemMouthUse(actor, intent, action, result)

        if intent == "wake" or intent == "awaken" or intent == "wake_up" or
           intent == "sharp_slap" or intent == "slap_awake" or intent == "wake_with_sharp_slap" then
            self:resolveSleepWakeAttempt(action, result)
            return
        end

        if intent == "eat" or intent == "drink" then
            result.description = intent == "eat" and "Ate." or "Drank."
            if totemMouthUse then
                result.description = result.description .. " Totem ends."
            end
            result.effects[#result.effects + 1] = intent
            return
        end

        if intent == "drop_prone" or intent == "drop_prone_to_avoid" then
            actor.conditions = actor.conditions or {}
            actor.conditions.prone = true
            result.description = "Dropped prone."
            result.effects[#result.effects + 1] = "dropped_prone"
            result.effects[#result.effects + 1] = "prone"
            return
        end

        if intent == "open_door" or intent == "open" then
            if target then
                target.isOpen = true
                target.open = true
                target.state = action.targetState or "open"
            end
            result.description = "Opened."
            result.effects[#result.effects + 1] = "opened"
            return
        end

        if intent == "throw_lever" or intent == "pull_lever" or intent == "lower_crossbar" then
            if target then
                target.activated = true
                target.state = action.targetState or "activated"
            end
            result.description = "Activated."
            result.effects[#result.effects + 1] = "activated"
            return
        end

        if intent == "pick_up_item" or intent == "pickup_item" or intent == "pick_up" or
           intent == "pickup" or intent == "take_item" or intent == "pick_up_with_mouth" then
            self:resolveTrivialPickUpItem(action, result, target)
            return
        end

        result.description = "Trivial action completed."
    end

    function resolver:isRestrainedForFreeMovement(actor)
        if not actor then
            return false
        end

        local conditions = actor.conditions or {}
        return conditions.rooted == true or
            conditions.restrained == true or
            conditions.manacled == true or
            conditions.chain_bound == true or
            conditions.swallowed == true or
            actor.restrained == true or
            actor.manacled == true or
            actor.griffinGrabbedBy ~= nil or
            actor.animateStatueGrabbedBy ~= nil or
            actor.titanGrabbedBy ~= nil or
            actor.swallowedByDevil ~= nil or
            actor.rootedBy ~= nil
    end

    function resolver:resolveFreeAction(action, result)
        local actor = action.actor
        if not actor then
            result.description = "No actor"
            result.effects[#result.effects + 1] = "free_action_no_actor"
            action.result = result
            return result
        end

        local conditions = actor.conditions or {}
        if conditions.dead or actor.dead or conditions.deaths_door or
           conditions.knocked_out or conditions.knockout then
            result.description = "Cannot take free actions while incapacitated."
            result.effects[#result.effects + 1] = "free_action_blocked"
            action.result = result
            return result
        end

        local intent = normalizeTrivialIntent({
            trivialAction = action.freeAction or action.freeActionType or action.intent or action.action,
        })
        result.freeAction = true
        result.cardless = true
        result.actionCost = "free"
        result.effects[#result.effects + 1] = "free_action"

        if intent == "talk" or intent == "speak" or intent == "roleplay" or intent == "role_play" then
            if conditions.silenced or actor.silenced then
                result.description = "Cannot speak while Silenced."
                result.effects[#result.effects + 1] = "free_speech_blocked"
                action.result = result
                return result
            end

            local totemMouthUse = self:applyTotemMouthUse(actor, "talk", action, result)
            local animalSpeech = self:evaluateSpeakToAnimalSpeech(
                actor,
                action.target or action.listener or action.audience or action.recipient
            )
            if animalSpeech.active then
                result.success = true
                result.speech = action.speech or action.text
                result.speakToAnimalSpeech = animalSpeech
                for _, effect in ipairs(animalSpeech.effects or {}) do
                    result.effects[#result.effects + 1] = effect
                end
                if animalSpeech.garbledForNonAnimals then
                    result.description = "Speech is garbled by the dire spider egg."
                else
                    result.description = "Spoke freely to an animal."
                end
                action.result = result
                return result
            end

            result.success = true
            result.speech = action.speech or action.text
            result.description = totemMouthUse and "Spoke freely. Totem ends." or "Spoke freely."
            result.effects[#result.effects + 1] = "free_talk"
            action.result = result
            return result
        end

        if intent == "move_within_zone" or intent == "within_zone_move" or
           intent == "reposition" or intent == "shift_position" then
            if action.destinationZone and actor.zone and action.destinationZone ~= actor.zone then
                result.description = "Leaving the zone requires a Challenge card."
                result.effects[#result.effects + 1] = "free_movement_requires_move_action"
                action.result = result
                return result
            end

            if self:isRestrainedForFreeMovement(actor) then
                result.description = "Cannot move freely while restrained."
                result.effects[#result.effects + 1] = "free_movement_restrained"
                action.result = result
                return result
            end

            result.success = true
            result.description = "Moved within the zone."
            result.effects[#result.effects + 1] = "free_within_zone_move"
            if action.position or action.positionInZone then
                actor.positionInZone = action.position or action.positionInZone
                result.positionInZone = actor.positionInZone
            end
            action.result = result
            return result
        end

        result.success = true
        result.description = "Free action completed."
        action.result = result
        return result
    end

    function resolver:resolveGenericAction(action, result)
        local actionDef = action.actionDef or self:getActionDef(action)
        local actionType = self:normalizeActionType(action.type)

        if actionDef and actionDef.autoSuccess then
            result.success = true
        end

        if result.success then
            if actionType == M.ACTION_TYPES.BID_LORE then
                result.description = "Lore bid offered."
                result.effects[#result.effects + 1] = "lore_bid"
            elseif actionType == M.ACTION_TYPES.TRIVIAL_ACTION then
                self:resolveTrivialAction(action, result)
            elseif actionType == M.ACTION_TYPES.PULL_ITEM_BELT then
                result.description = "Pulled item from belt."
                result.effects[#result.effects + 1] = "item_pulled_belt"
            elseif actionType == M.ACTION_TYPES.TEST_FATE then
                result.description = "Test of Fate requested."
            else
                result.description = "Action succeeded!"
            end
        else
            result.description = "Action failed!"
        end
    end

    ----------------------------------------------------------------------------
    -- S7.8: RELOAD ACTION
    ----------------------------------------------------------------------------

    --- Resolve reload action for crossbows
    function resolver:resolveReload(action, result)
        local actor = action.actor
        local weapon = action.weapon

        if not weapon and actor and actor.inventory and actor.inventory.getWieldedWeapon then
            weapon = actor.inventory:getWieldedWeapon()
        end
        if not weapon then
            weapon = actor.weapon
        end

        -- Must have a crossbow equipped
        if not weapon or not M.isWeaponType(weapon, "CROSSBOW") then
            result.success = false
            result.description = "No crossbow to reload!"
            return
        end

        -- Check if already loaded
        if weapon.isLoaded then
            result.success = false
            result.description = "Crossbow is already loaded!"
            return
        end

        local ammoType = self:getMissileAmmoType(weapon)
        if actor and (actor.ammo ~= nil or self:hasTypedAmmunition(actor)) and
            self:getMissileAmmoCount(actor, ammoType) <= 0 then
            result.success = false
            result.description = "No bolt to reload!"
            result.effects[#result.effects + 1] = "no_ammo"
            result.effects[#result.effects + 1] = "reload_no_bolt"
            return
        end

        -- Reload succeeds (no test required)
        result.success = true
        weapon.isLoaded = true
        result.weapon = weapon
        result.reloadedWeapon = weapon
        result.ammoType = ammoType
        result.ammoTracked = actor and (actor.ammo ~= nil or self:hasTypedAmmunition(actor)) or false
        result.ammoAvailable = actor and self:getMissileAmmoCount(actor, ammoType) or nil
        result.ammoRemaining = result.ammoAvailable
        result.description = "Crossbow reloaded!"
        result.effects[#result.effects + 1] = "reloaded"
    end

    ----------------------------------------------------------------------------
    -- S6.3/S12.1: ENGAGEMENT SYSTEM
    -- Delegates to zoneSystem as single source of truth
    ----------------------------------------------------------------------------

    --- Form engagement between two entities
    function resolver:formEngagement(entity1, entity2)
        if not entity1 or not entity2 then return end

        -- S12.1: Delegate to zoneSystem
        if self.zoneSystem then
            self.zoneSystem:engage(entity1.id, entity2.id)
        end

        -- Set is_engaged flag on entities (convenience flag)
        entity1.is_engaged = true
        entity2.is_engaged = true

        -- Emit arena event for visual feedback
        self.eventBus:emit("engagement_formed", {
            entity1 = entity1,
            entity2 = entity2,
        })
    end

    --- Break engagement between two specific entities
    function resolver:breakEngagement(entity1, entity2)
        if not entity1 or not entity2 then return end

        -- S12.1: Delegate to zoneSystem
        if self.zoneSystem then
            self.zoneSystem:disengage(entity1.id, entity2.id)
        end

        -- Update is_engaged flag based on remaining engagements
        entity1.is_engaged = self:hasAnyEngagement(entity1)
        entity2.is_engaged = self:hasAnyEngagement(entity2)

        -- Emit arena event for visual feedback
        self.eventBus:emit("engagement_broken", {
            entity1 = entity1,
            entity2 = entity2,
        })
    end

    --- Clear all engagements for an entity (on defeat)
    function resolver:clearAllEngagements(entity, allEntities)
        if not entity then return end

        local engagedIds = {}
        if self.zoneSystem and self.zoneSystem.getEngagedWith then
            for _, id in ipairs(self.zoneSystem:getEngagedWith(entity.id) or {}) do
                engagedIds[#engagedIds + 1] = id
            end
        end
        local wasEngaged = entity.is_engaged or #engagedIds > 0

        -- S12.1: Delegate to zoneSystem
        if self.zoneSystem then
            self.zoneSystem:disengageAll(entity.id)
        end

        entity.is_engaged = false

        if allEntities then
            local engagedSet = {}
            for _, id in ipairs(engagedIds) do
                engagedSet[id] = true
            end

            for _, other in ipairs(allEntities) do
                if other ~= entity and engagedSet[other.id] then
                    other.is_engaged = self:hasAnyEngagement(other)
                end
            end
        end

        if wasEngaged then
            self.eventBus:emit("engagements_cleared", {
                entity = entity,
                engagedIds = engagedIds,
            })
        end
    end

    --- Check if entity has any engagements
    function resolver:hasAnyEngagement(entity)
        if not entity then return false end

        -- S12.1: Delegate to zoneSystem
        if self.zoneSystem then
            return self.zoneSystem:isEngaged(entity.id)
        end
        return false
    end

    --- Check if two entities are engaged
    function resolver:areEngaged(entity1, entity2)
        if not entity1 or not entity2 then return false end

        -- S12.1: Delegate to zoneSystem
        if self.zoneSystem then
            return self.zoneSystem:areEngaged(entity1.id, entity2.id)
        end
        return false
    end

    --- Get all entities engaged with a given entity
    -- @param entity table: The entity to check
    -- @param allEntities table: Array of all entities in the challenge
    -- @return table: Array of engaged entities
    function resolver:getEngagedEnemies(entity, allEntities)
        if not entity then return {} end

        -- S12.1: Get engaged IDs from zoneSystem
        local engagedIds = {}
        if self.zoneSystem then
            engagedIds = self.zoneSystem:getEngagedWith(entity.id)
        end

        -- Convert IDs to entity references
        local enemies = {}
        local idSet = {}
        for _, id in ipairs(engagedIds) do
            idSet[id] = true
        end

        for _, e in ipairs(allEntities or {}) do
            if idSet[e.id] then
                enemies[#enemies + 1] = e
            end
        end
        return enemies
    end

    --- Resolve movement adjacency using zone registry when available,
    -- otherwise fall back to challenge zone data.
    function resolver:getZoneIds(action)
        if self.zoneSystem and self.zoneSystem.getAllZoneIds then
            local ids = self.zoneSystem:getAllZoneIds()
            if ids and #ids > 0 then
                return ids
            end
        end

        local ids = {}
        local zones = action and action.challengeController and action.challengeController.zones
        for _, zone in ipairs(zones or {}) do
            ids[#ids + 1] = zone.id
        end
        return ids
    end

    function resolver:zoneExists(action, zoneId)
        if not zoneId then
            return false
        end

        if self.zoneSystem and self.zoneSystem.getZone and self.zoneSystem:getZone(zoneId) then
            return true
        end

        for _, id in ipairs(self:getZoneIds(action)) do
            if id == zoneId then
                return true
            end
        end

        return false
    end

    function resolver:areZonesAdjacent(action, fromZoneId, toZoneId)
        if self.zoneSystem and self.zoneSystem.getZone and self.zoneSystem.areZonesAdjacent then
            if self.zoneSystem:getZone(fromZoneId) and self.zoneSystem:getZone(toZoneId) then
                return self.zoneSystem:areZonesAdjacent(fromZoneId, toZoneId)
            end
        end

        local zones = action and action.challengeController and action.challengeController.zones
        if not zones or #zones == 0 then
            return true
        end

        local byId = {}
        for _, zone in ipairs(zones) do
            byId[zone.id] = zone
        end

        local fromZone = byId[fromZoneId]
        local toZone = byId[toZoneId]
        if not fromZone or not toZone then
            return false
        end

        if fromZone.adjacent_to then
            for _, adjId in ipairs(fromZone.adjacent_to) do
                if adjId == toZoneId then
                    return true
                end
            end
            return false
        end

        if toZone.adjacent_to then
            for _, adjId in ipairs(toZone.adjacent_to) do
                if adjId == fromZoneId then
                    return true
                end
            end
            return false
        end

        return true
    end

    function resolver:getZoneDistance(action, fromZoneId, toZoneId)
        if not toZoneId then
            return 0, nil
        end
        if not fromZoneId or fromZoneId == toZoneId then
            return 0, nil
        end

        local zoneIds = self:getZoneIds(action)
        if #zoneIds == 0 then
            return 1, nil
        end

        if not self:zoneExists(action, fromZoneId) or not self:zoneExists(action, toZoneId) then
            return nil, "zone_not_found"
        end

        local queue = { { id = fromZoneId, distance = 0 } }
        local seen = { [fromZoneId] = true }
        local index = 1

        while index <= #queue do
            local current = queue[index]
            index = index + 1

            for _, nextId in ipairs(zoneIds) do
                if not seen[nextId] and self:areZonesAdjacent(action, current.id, nextId) then
                    local distance = current.distance + 1
                    if nextId == toZoneId then
                        return distance, nil
                    end
                    seen[nextId] = true
                    queue[#queue + 1] = { id = nextId, distance = distance }
                end
            end
        end

        return nil, "zones_not_connected"
    end

    function resolver:canMoveBetweenZones(action, fromZoneId, toZoneId, opts)
        opts = opts or {}
        local maxDistance = opts.maxDistance or action.maxMoveDistance or 1
        local distance, err = self:getZoneDistance(action, fromZoneId, toZoneId)

        if err then
            return false, err
        end
        if not distance or distance <= maxDistance then
            return true, nil
        end

        return false, "zones_too_far"
    end

    function resolver:getAcrobatTraversalMode(action)
        if not action then
            return nil
        end

        local explicitMode = action.traversalMode or action.traversal or action.movementMode or action.terrainMode
        local mode = explicitMode and normalizeTalentKey(explicitMode) or nil

        if action.climb == true or action.climbing == true or action.verticalTraversal == true then
            mode = mode or "climb"
        elseif action.narrowLedge == true or action.ledge == true then
            mode = mode or "ledge"
        elseif action.tightrope == true then
            mode = mode or "tightrope"
        end

        if action.acrobatTraversal == true or action.requiresAcrobatTraversal == true or action.difficultTraversal == true then
            mode = mode or "difficult_terrain"
        end

        local acrobatModes = {
            climb = true,
            climbing = "climb",
            vertical = "climb",
            vertical_terrain = "climb",
            sheer_surface = "climb",
            ledge = true,
            narrow_ledge = "ledge",
            tightrope = true,
            difficult_terrain = true,
        }
        local mapped = acrobatModes[mode]
        if mapped == true then
            return mode
        end
        if mapped then
            return mapped
        end

        return nil
    end

    function resolver:actorCanSlimeSqueeze(actor)
        if not actor then
            return false
        end
        local conditions = actor.conditions or {}
        if conditions.squeeze_through_gaps == true or conditions.shapeless_body == true or
            actor.squeezeThroughGaps == true or actor.shapelessBody == true
        then
            return true
        end
        if self:isSlime(actor) then
            local slime = actor.slime or {}
            return slime.canPassKeyholeSpaces ~= false
        end
        return false
    end

    function resolver:actorCanMistPassCracks(actor)
        if not actor then
            return false
        end
        local conditions = actor.conditions or {}
        return conditions.can_pass_cracks == true or conditions.mist_form == true or
            conditions.vampire_mist == true or actor.canPassCracks == true or actor.mistForm == true
    end

    function resolver:actorCanWaterWalk(actor)
        if not actor then
            return false
        end
        local conditions = actor.conditions or {}
        return actor.canWalkOnWater == true or actor.waterWalking == true or
            conditions.can_walk_on_water == true or conditions.water_walking == true
    end

    function resolver:actorCanWinterWolfElementalTravel(actor, travel)
        if not self:isWinterWolf(actor) then
            return false
        end

        local elementalTravel = actor.winterWolf and actor.winterWolf.elementalTravel or {}
        if not travel then
            return true
        end
        if travel.medium == "water" then
            return elementalTravel.walksOnWater ~= false
        end
        if travel.medium == "cloud" then
            return elementalTravel.treatsCloudsAsSolid ~= false
        end
        if travel.medium == "vapor" then
            return elementalTravel.treatsVaporsAsSolid ~= false
        end
        if travel.medium == "mist" then
            return elementalTravel.treatsMistsAsSolid ~= false
        end

        return true
    end

    function resolver:getWinterWolfElementalTravel(action)
        if not action then
            return nil
        end

        local explicitMode = action.traversalMode or action.traversal or action.movementMode or
            action.terrainMode or action.elementalTravelMode
        local mode = explicitMode and normalizeTalentKey(explicitMode) or nil
        local explicitTraversal = action.requiresElementalTravel == true or action.elementalTravel == true or
            action.winterWolfElementalTravel == true or explicitMode ~= nil or
            action.waterTraversal == true or action.walkOnWater == true or action.cloudTraversal == true or
            action.vaporTraversal == true or action.mistTraversal == true
        if not explicitTraversal then
            return nil
        end

        local zone = self:getActionZoneTarget(action, action.destinationZone or action.targetZone or action.zone)
        local props = zone and zone.properties or {}
        local zoneKind = normalizeTalentKey(zone and (zone.kind or zone.type or zone.terrain or props.kind or
            props.type or props.terrain))
        local zoneName = normalizeTalentKey(zone and zone.name)

        local water = action.waterTraversal == true or action.walkOnWater == true or action.waterSurface == true or
            action.bodyOfWater == true or action.isBodyOfWater == true or
            mode == "water" or mode == "water_surface" or mode == "walk_on_water" or
            mode == "water_walk" or mode == "water_walking" or mode == "river" or mode == "pool" or
            mode == "lake" or zoneKind == "water" or zoneKind == "water_surface" or
            zoneKind == "river" or zoneKind == "pool" or props.water == true or
            props.waterSurface == true or props.bodyOfWater == true
        local cloud = action.cloudTraversal == true or mode == "cloud" or mode == "clouds" or
            mode == "snow_cloud" or zoneKind == "cloud" or zoneKind == "clouds" or
            zoneKind == "snow_cloud" or props.cloud == true or props.clouds == true or
            zoneName:find("cloud", 1, true) ~= nil
        local vapor = action.vaporTraversal == true or action.vapourTraversal == true or
            mode == "vapor" or mode == "vapors" or mode == "vapour" or mode == "vapours" or
            zoneKind == "vapor" or zoneKind == "vapors" or zoneKind == "vapour" or
            zoneKind == "vapours" or props.vapor == true or props.vapors == true or
            props.vapour == true or props.vapours == true or zoneName:find("vapor", 1, true) ~= nil or
            zoneName:find("vapour", 1, true) ~= nil
        local mist = action.mistTraversal == true or mode == "mist" or mode == "mists" or
            mode == "fog" or mode == "fogs" or zoneKind == "mist" or zoneKind == "mists" or
            zoneKind == "fog" or zoneKind == "fogs" or props.mist == true or props.mists == true or
            props.fog == true or props.fogs == true or zoneName:find("mist", 1, true) ~= nil or
            zoneName:find("fog", 1, true) ~= nil

        if water then
            return {
                medium = "water",
                mode = mode or "water_surface",
                freezesUnderPaws = true,
            }
        end
        if cloud then
            return {
                medium = "cloud",
                mode = mode or "cloud",
                treatsAsSolid = true,
            }
        end
        if vapor then
            return {
                medium = "vapor",
                mode = mode or "vapor",
                treatsAsSolid = true,
            }
        end
        if mist then
            return {
                medium = "mist",
                mode = mode or "mist",
                treatsAsSolid = true,
            }
        end

        return nil
    end

    function resolver:getSlimeSqueezeTraversal(action)
        if not action then
            return nil
        end

        local explicitMode = action.traversalMode or action.traversal or action.movementMode or
            action.terrainMode or action.gapTraversalMode
        local mode = explicitMode and normalizeTalentKey(explicitMode) or nil
        local gapSize = normalizeTalentKey(action.gapSize or action.gapWidth or action.openingSize or
            action.passageSize or action.creviceSize)
        local handSized = action.handSizedGap == true or action.hand_size_gap == true or
            action.hand_sized_gap == true or action.gapFitsHand == true or
            action.canReachHandThrough == true or gapSize == "hand" or gapSize == "hand_sized" or
            gapSize == "hand_size" or gapSize == "hand_width" or gapSize == "fits_hand"

        if not mode and (handSized or action.requiresSqueezeTraversal == true or
           action.squeezeThroughGap == true or action.squeezeGap == true or action.gapTraversal == true or
           action.throughBars == true or action.throughGrate == true or action.throughPortcullis == true or
           action.narrowGap == true or action.crack == true or action.cracks == true or
           action.crevice == true or action.keyhole == true or action.underDoor == true) then
            mode = handSized and "hand_sized_gap" or "squeeze"
        end

        local squeezeModes = {
            squeeze = true,
            squeeze_gap = true,
            squeeze_through_gap = true,
            hand_gap = true,
            hand_sized_gap = true,
            hand_size_gap = true,
            gap = true,
            narrow_gap = true,
            crack = true,
            cracks = true,
            crevice = true,
            bars = true,
            grate = true,
            portcullis = true,
            keyhole = true,
            under_door = true,
            door_gap = true,
        }
        if squeezeModes[mode] then
            return {
                mode = mode,
                handSizedGap = handSized or mode == "hand_gap" or mode == "hand_sized_gap" or
                    mode == "hand_size_gap",
            }
        end

        return nil
    end

    function resolver:itemMatchesTraversalGearTag(item, tag)
        if not item or not tag then
            return false
        end

        local wanted = normalizeTalentKey(tag)
        local props = item.properties or {}
        local function matches(value)
            return normalizeTalentKey(value) == wanted
        end

        if matches(item.templateId) or matches(item.id) or matches(item.name) or matches(item.type) or
           matches(item.itemType) or matches(item.toolType) or matches(props.toolType) or matches(props.type) or
           matches(props.itemType) then
            return true
        end
        if props[wanted] == true then
            return true
        end

        for _, tags in ipairs({ item.tags, props.tags }) do
            if type(tags) == "table" then
                for key, value in pairs(tags) do
                    if matches(value) or (value == true and matches(key)) then
                        return true
                    end
                end
            elseif matches(tags) then
                return true
            end
        end

        return false
    end

    function resolver:findTraversalGear(action, tags)
        if not action or type(tags) ~= "table" then
            return nil, nil
        end

        local function matchesAny(item)
            for _, tag in ipairs(tags) do
                if self:itemMatchesTraversalGearTag(item, tag) then
                    return true
                end
            end
            return false
        end

        for _, item in ipairs({
            action.item,
            action.requiredItem,
            action.tool,
            action.gear,
            action.grapplingHook,
            action.rope,
        }) do
            if matchesAny(item) then
                return item, "action"
            end
        end

        local inv = action.actor and action.actor.inventory
        if inv and inv.findItemByPredicate then
            local found, location = inv:findItemByPredicate(matchesAny)
            if found then
                return found, location
            end
        end

        for _, locationName in ipairs({ "hands", "belt", "pack" }) do
            local items = inv and inv[locationName] or {}
            for _, item in ipairs(items or {}) do
                if matchesAny(item) then
                    return item, locationName
                end
            end
        end

        return nil, nil
    end

    function resolver:hasGrapplingHookAndRope(action)
        local hook, hookLocation = self:findTraversalGear(action, { "grappling_hook", "grapple" })
        local rope, ropeLocation = self:findTraversalGear(action, { "rope" })
        if hook and rope then
            return true, {
                hook = hook,
                hookLocation = hookLocation,
                rope = rope,
                ropeLocation = ropeLocation,
            }
        end
        return false, nil
    end

    function resolver:shouldRequestTraversalTestOfFate(action)
        return action and (
            action.promptTraversalTestOfFate == true or
            action.requestTraversalTestOfFate == true or
            action.deferTraversalTestOfFate == true
        )
    end

    function resolver:requestTraversalTestOfFate(action, result, detail)
        detail = detail or {}
        local mode = detail.mode or self:getAcrobatTraversalMode(action)
        local request = {
            entity = action.actor,
            actor = action.actor,
            attribute = action.traversalTestAttribute or "pentacles",
            targetSuit = action.traversalTestSuit or constants.SUITS.PENTACLES,
            favor = action.traversalTestFavor,
            description = action.traversalTestDescription or detail.description or "Traversal Test of Fate",
            action = action,
            actionCard = action.card,
            traversalTest = true,
            traversalMode = mode,
            traversal = action.traversal or action.traversalMode or mode,
            destinationZone = action.destinationZone,
            reason = detail.reason,
        }

        result.pendingTestOfFate = true
        result.pendingTraversalTestOfFate = true
        result.traversalRequiresTest = true
        result.traversalTestRequest = request
        result.description = "Traversal Test of Fate underway."

        action.pendingTraversalTestOfFate = request
        action.result = result
        self.eventBus:emit(events.EVENTS.REQUEST_TEST_OF_FATE, request)

        return request
    end

    function resolver:resolveAcrobatTraversal(action, result)
        local slimeTraversal = self:getSlimeSqueezeTraversal(action)
        if slimeTraversal then
            result.smallGapTraversal = {
                mode = slimeTraversal.mode,
                handSizedGap = slimeTraversal.handSizedGap == true,
            }

            if self:actorCanSlimeSqueeze(action.actor) then
                result.slimeSqueezeTraversal = result.smallGapTraversal
                result.slimeSqueezeTraversal.noTestFate = true
                result.effects[#result.effects + 1] = "slime_squeeze_traversal"
                result.effects[#result.effects + 1] = "traversal_no_test"
                if self:isSlime(action.actor) then
                    result.slimeBodyTraversal = result.smallGapTraversal
                    result.effects[#result.effects + 1] = "slime_body_squeeze_traversal"
                end
                if slimeTraversal.handSizedGap then
                    result.effects[#result.effects + 1] = "hand_sized_gap_passed"
                end
                return true
            end

            if self:actorCanMistPassCracks(action.actor) then
                result.vampireMistTraversal = result.smallGapTraversal
                result.vampireMistTraversal.noTestFate = true
                result.effects[#result.effects + 1] = "vampire_mist_crack_traversal"
                result.effects[#result.effects + 1] = "mist_pass_cracks"
                result.effects[#result.effects + 1] = "traversal_no_test"
                return true
            end

            do
                result.success = false
                result.description = "Traversal blocked: cannot squeeze through the gap."
                result.effects[#result.effects + 1] = "slime_squeeze_required"
                result.effects[#result.effects + 1] = "small_gap_traversal_blocked"
                result.effects[#result.effects + 1] = "squeeze_traversal_blocked"
                return false
            end
        end

        local winterWolfTravel = self:getWinterWolfElementalTravel(action)
        if winterWolfTravel then
            result.winterWolfElementalTravel = {
                mode = winterWolfTravel.mode,
                medium = winterWolfTravel.medium,
                noTestFate = false,
            }

            if self:actorCanWinterWolfElementalTravel(action.actor, winterWolfTravel) then
                result.winterWolfElementalTravel.noTestFate = true
                result.effects[#result.effects + 1] = "winter_wolf_elemental_travel"
                result.effects[#result.effects + 1] = "traversal_no_test"
                if winterWolfTravel.medium == "water" then
                    result.effects[#result.effects + 1] = "water_frozen_under_paws"
                elseif winterWolfTravel.medium == "cloud" then
                    result.effects[#result.effects + 1] = "clouds_treated_as_solid"
                elseif winterWolfTravel.medium == "vapor" then
                    result.effects[#result.effects + 1] = "vapors_treated_as_solid"
                elseif winterWolfTravel.medium == "mist" then
                    result.effects[#result.effects + 1] = "mists_treated_as_solid"
                end
                return true
            end

            if winterWolfTravel.medium == "water" and self:actorCanWaterWalk(action.actor) then
                result.winterWolfElementalTravel.noTestFate = true
                result.effects[#result.effects + 1] = "water_walking_traversal"
                result.effects[#result.effects + 1] = "traversal_no_test"
                return true
            end

            local testResult = action.traversalTestResult or action.testResult
            if testResult then
                result.traversalTestResult = testResult
                if testResult.success then
                    result.effects[#result.effects + 1] = "traversal_test_passed"
                    return true
                end

                result.success = false
                result.description = "Traversal failed."
                result.effects[#result.effects + 1] = "traversal_test_failed"
                return false
            end

            result.success = false
            result.description = "Traversal requires a Test of Fate without winter wolf elemental travel."
            result.effects[#result.effects + 1] = "winter_wolf_elemental_travel_required"
            result.effects[#result.effects + 1] = "traversal_test_required"
            result.traversalRequiresTest = true
            if self:shouldRequestTraversalTestOfFate(action) then
                self:requestTraversalTestOfFate(action, result, {
                    mode = winterWolfTravel.mode,
                    reason = "winter_wolf_elemental_travel_required",
                    description = "Elemental travel Test of Fate",
                })
            end
            return false
        end

        local mode = self:getAcrobatTraversalMode(action)
        if not mode then
            return true
        end

        result.acrobatTraversal = {
            mode = mode,
            asMiscAction = true,
            noTestFate = false,
        }

        if mode == "climb" then
            local hasGear, gear = self:hasGrapplingHookAndRope(action)
            if hasGear then
                result.acrobatTraversal.noTestFate = true
                result.acrobatTraversal.gear = "grappling_hook_and_rope"
                result.grapplingHookTraversal = gear
                result.effects[#result.effects + 1] = "grappling_hook_traversal"
                result.effects[#result.effects + 1] = "traversal_no_test"
                return true
            end
        end

        local testResult = action.traversalTestResult or action.testResult
        if testResult then
            result.traversalTestResult = testResult
            if testResult.success then
                result.effects[#result.effects + 1] = "traversal_test_passed"
                return true
            end

            result.success = false
            result.description = "Traversal failed."
            result.effects[#result.effects + 1] = "traversal_test_failed"
            return false
        end

        if not entityHasUsableTalent(action.actor, "acrobat") then
            result.success = false
            result.description = "Traversal requires a Test of Fate without Acrobat."
            result.effects[#result.effects + 1] = "traversal_test_required"
            result.effects[#result.effects + 1] = "acrobat_traversal_blocked"
            result.traversalRequiresTest = true
            if self:shouldRequestTraversalTestOfFate(action) then
                self:requestTraversalTestOfFate(action, result, {
                    mode = mode,
                    reason = "acrobat_traversal_blocked",
                    description = "Acrobatic traversal Test of Fate",
                })
            end
            return false
        end

        result.acrobatTraversal.noTestFate = true
        result.effects[#result.effects + 1] = "acrobat_traversal"
        result.effects[#result.effects + 1] = "traversal_no_test"
        return true
    end

    ----------------------------------------------------------------------------
    -- S6.3: PARTING BLOWS
    ----------------------------------------------------------------------------

    --- Check and apply parting blows when entity tries to move while engaged
    -- @param entity table: The moving entity
    -- @param allEntities table: All entities in the challenge
    -- @return table: { blocked = bool, wounds = number, attackers = { ... } }
    function resolver:getPartingBlowChoice(attacker, action)
        if not (attacker and action) then
            return nil
        end

        local choices = action.partingBlowChoices or action.partingBlows or
            action.partingBlowDecisions or action.partingBlowById
        local choice = nil
        if type(choices) == "table" then
            choice = choices[attacker] or choices[attacker.id] or choices[attacker.name]
        end

        local allowPass = action.allowPassById or action.partingBlowAllowPassById or
            action.partingBlowDeclinesById
        if choice == nil and type(allowPass) == "table" and attacker.id and allowPass[attacker.id] ~= nil then
            choice = allowPass[attacker.id] and "allow" or "strike"
        end

        if choice == nil and self:entityInList(action.partingBlowDeclines or action.allowPassers, attacker) then
            choice = "allow"
        end

        if type(choice) == "table" then
            if choice.allowPass ~= nil then
                choice = choice.allowPass and "allow" or "strike"
            elseif choice.strike ~= nil then
                choice = choice.strike and "strike" or "allow"
            elseif choice.partingBlow ~= nil then
                choice = choice.partingBlow and "strike" or "allow"
            end
        end

        if choice == false then
            return "allow"
        end
        if choice == true then
            return "strike"
        end

        local normalized = normalizeTalentKey(choice)
        if normalized == "allow" or normalized == "allow_pass" or normalized == "pass" or
           normalized == "decline" or normalized == "no_parting_blow" then
            return "allow"
        end
        if normalized == "strike" or normalized == "wound" or normalized == "parting_blow" then
            return "strike"
        end
        return nil
    end

    function resolver:getAvoidFailureWoundChoice(attacker, action)
        if not (attacker and action) then
            return nil
        end

        local choices = action.avoidFailureChoices or action.avoidWoundChoices or
            action.avoidFailureWounds or action.avoidWoundById
        local choice = nil
        if type(choices) == "table" then
            choice = choices[attacker] or choices[attacker.id] or choices[attacker.name]
        end

        local declines = action.avoidWoundDeclinesById or action.avoidFailureDeclinesById
        if choice == nil and type(declines) == "table" and attacker.id and declines[attacker.id] ~= nil then
            choice = declines[attacker.id] and "decline" or "wound"
        end

        if choice == nil and self:entityInList(action.avoidWoundDeclines or action.avoidFailureDeclines, attacker) then
            choice = "decline"
        end

        if type(choice) == "table" then
            if choice.declineWound ~= nil then
                choice = choice.declineWound and "decline" or "wound"
            elseif choice.allowPass ~= nil then
                choice = choice.allowPass and "decline" or "wound"
            elseif choice.wound ~= nil then
                choice = choice.wound and "wound" or "decline"
            end
        end

        if choice == false then
            return "decline"
        end
        if choice == true then
            return "wound"
        end

        local normalized = normalizeTalentKey(choice)
        if normalized == "decline" or normalized == "allow" or normalized == "allow_pass" or
           normalized == "pass" or normalized == "no_wound" or normalized == "no_avoid_wound" then
            return "decline"
        end
        if normalized == "wound" or normalized == "strike" or normalized == "avoid_wound" then
            return "wound"
        end
        return nil
    end

    function resolver:checkPartingBlows(entity, allEntities, action)
        local result = {
            blocked = false,
            wounds = 0,
            attackers = {},
            allowedPassers = {},
        }

        if not entity or not entity.is_engaged then
            return result
        end

        -- S12.1: Get engaged enemies from zoneSystem
        local engagedIds = {}
        if self.zoneSystem then
            engagedIds = self.zoneSystem:getEngagedWith(entity.id)
        end

        -- Convert to a set for fast lookup
        local engagedSet = {}
        for _, id in ipairs(engagedIds) do
            engagedSet[id] = true
        end

        -- Find all engaged enemies in the same zone
        for _, e in ipairs(allEntities or {}) do
            if engagedSet[e.id] and e.zone == entity.zone then
                if self:getPartingBlowChoice(e, action) == "allow" then
                    result.allowedPassers[#result.allowedPassers + 1] = e
                    self.eventBus:emit("parting_blow_declined", {
                        attacker = e,
                        victim = entity,
                    })
                else
                    -- Enemy gets a free parting blow
                    result.attackers[#result.attackers + 1] = e
                    result.wounds = result.wounds + 1

                    -- Emit parting blow event
                    self.eventBus:emit(events.EVENTS.PARTING_BLOW, {
                        attacker = e,
                        victim = entity,
                    })
                end
            end
        end

        -- Apply wounds to the mover
        if result.wounds > 0 then
            for _ = 1, result.wounds do
                local woundResult = entity:takeWound(false)

                self.eventBus:emit(events.EVENTS.WOUND_TAKEN, {
                    entity = entity,
                    result = woundResult,
                    source = "parting_blow",
                })

                -- Check if mover is incapacitated
                if entity.conditions and entity.conditions.deaths_door then
                    result.blocked = true
                    break
                end
                if entity.conditions and entity.conditions.dead then
                    result.blocked = true
                    break
                end
            end
        end

        return result
    end

    ----------------------------------------------------------------------------
    -- S6.3: MOVE/DASH/AVOID RESOLUTION
    ----------------------------------------------------------------------------

    --- Resolve movement action (subject to parting blows)
    function resolver:resolveMove(action, result, allEntities)
        local actor = action.actor
        local destZone = action.destinationZone
        local oldZone = actor.zone

        -- S7.2: Check for rooted condition
        if actor.conditions and actor.conditions.rooted then
            result.success = false
            result.description = "Rooted! Cannot move."
            result.effects[#result.effects + 1] = "rooted_blocked"
            return
        end

        if not self:resolveAcrobatTraversal(action, result) then
            return
        end

        local dragonFlightEffect, dragonFlightDoom = self:getDragonFlightEffect(action)
        if dragonFlightEffect and not self:validateDragonFlight(action, result) then
            return
        end
        local harpyFlightEffect, harpyFlightDoom = self:getHarpyFlightEffect(action)
        if harpyFlightEffect and not self:validateHarpyFlight(action, result) then
            return
        end

        if destZone then
            local canMove, moveError = self:canMoveBetweenZones(action, oldZone, destZone)
            if not canMove then
                result.success = false
                if moveError == "zone_not_found" then
                    result.description = "Move failed: destination zone is invalid."
                    result.effects[#result.effects + 1] = "zone_not_found"
                else
                    result.description = "Move failed: destination zone is not adjacent."
                    result.effects[#result.effects + 1] = "non_adjacent_move_blocked"
                end
                return
            end
        end

        -- Check for parting blows if engaged
        if actor.is_engaged then
            local partingResult = self:checkPartingBlows(actor, allEntities, action)

            if partingResult.blocked then
                result.success = false
                result.description = "Movement blocked! "
                if #partingResult.attackers > 0 then
                    result.description = result.description .. "Took " .. partingResult.wounds .. " parting blow(s) and fell!"
                end
                result.effects[#result.effects + 1] = "parting_blow_blocked"
                return
            end

            if partingResult.wounds > 0 then
                result.effects[#result.effects + 1] = "parting_blows"
                result.partingBlows = partingResult
            end
            if #partingResult.allowedPassers > 0 then
                result.effects[#result.effects + 1] = "parting_blow_declined"
                result.partingBlows = partingResult
            end
        end

        -- Movement succeeds
        result.success = true
        if destZone then
            if self.zoneSystem and actor and actor.id then
                local placed, err = self.zoneSystem:placeEntity(actor.id, destZone)
                if not placed then
                    result.success = false
                    result.description = "Move failed: destination zone could not be entered."
                    result.effects[#result.effects + 1] = "zone_sync_failed"
                    if err then
                        result.effects[#result.effects + 1] = "zone_sync_error_" .. tostring(err)
                    end
                    return
                end
            end

            actor.zone = destZone
            self:discardMovedAwayProtectedDefense(actor, oldZone, destZone, action, result)
            self:applyGriffinGrabMove(actor, oldZone, destZone, action, result)
            self:applyAnimateStatueGrabMove(actor, oldZone, destZone, action, result)
            self:applyTitanGrabMove(actor, oldZone, destZone, action, result)
            self:moveDevilBiteTargets(actor, oldZone, destZone, action, result)
            self:moveSlimeEngulfedTargets(actor, oldZone, destZone, action, result)
            if self:isBrainSpider(actor) then
                self:applyBrainSpiderWallCrawlingMove(action, result, destZone)
            end
            if dragonFlightEffect then
                self:applyDragonFlight(action, result, allEntities, dragonFlightEffect, dragonFlightDoom)
            end
            if harpyFlightEffect then
                self:applyHarpyFlight(action, result, allEntities, harpyFlightEffect, harpyFlightDoom)
            end
            result.description = "Moved to " .. destZone
            result.oldZone = oldZone
            result.newZone = destZone
            result.destinationZone = destZone
            result.movementType = action.type or M.ACTION_TYPES.MOVE
            result.partingBlowWounds = result.partingBlows and result.partingBlows.wounds or 0
            result.partingBlowDeclines = result.partingBlows and result.partingBlows.allowedPassers or nil
            result.movement = {
                actor = actor,
                oldZone = oldZone,
                newZone = destZone,
                destinationZone = destZone,
                movementType = result.movementType,
                partingBlows = result.partingBlows,
                partingBlowWounds = result.partingBlowWounds,
                partingBlowDeclines = result.partingBlowDeclines,
            }
            self:applyCaltropZoneEntry(actor, destZone, action, result)
            self:applyFrictionlessPuddleZoneEntry(actor, destZone, action, result)

            -- Emit event for arena view to update display
            self.eventBus:emit("entity_zone_changed", {
                entity = actor,
                oldZone = oldZone,
                newZone = destZone,
            })

            print("[MOVE] " .. (actor.name or actor.id) .. " moved from " .. (oldZone or "?") .. " to " .. destZone)
        else
            if dragonFlightEffect then
                self:applyDragonFlight(action, result, allEntities, dragonFlightEffect, dragonFlightDoom)
            end
            if harpyFlightEffect then
                self:applyHarpyFlight(action, result, allEntities, harpyFlightEffect, harpyFlightDoom)
            end
            result.description = "Movement complete"
        end
        result.effects[#result.effects + 1] = "moved"

        -- Clear engagements (they're now in different zones)
        if actor.is_engaged then
            self:clearAllEngagements(actor, allEntities)
        end
    end

    --- Resolve Dash action (faster move, still subject to parting blows)
    function resolver:resolveDash(action, result, allEntities)
        local actor = action.actor

        -- S7.2: Check for rooted condition
        if actor.conditions and actor.conditions.rooted then
            result.success = false
            result.description = "Rooted! Cannot dash."
            result.effects[#result.effects + 1] = "rooted_blocked"
            return
        end

        if actor.cannotDash then
            result.success = false
            result.description = "Cannot dash."
            result.effects[#result.effects + 1] = "dash_blocked"
            return
        end

        if self:resolveTitanSporehulkClimb(action, result) then
            return
        end

        local greatLeapEffect = nil
        if self:isBrainSpider(actor) then
            greatLeapEffect = self:getBrainSpiderGreatLeap(action)
        end

        action.maxMoveDistance = greatLeapEffect and (greatLeapEffect.moveZones or 2) or 2
        if greatLeapEffect and greatLeapEffect.clearsInterveningObstacles ~= false then
            action.clearsInterveningObstacles = true
        end

        -- Dash leaves the current zone and can cover up to two zone steps.
        self:resolveMove(action, result, allEntities)

        if result.success then
            if greatLeapEffect then
                self:applyBrainSpiderGreatLeapResult(action, result, greatLeapEffect)
            end
            result.description = "Dashed! " .. (result.description or "")
            result.effects[#result.effects + 1] = "dashed"
        end
    end

    --- Resolve Avoid action (escape engagement without parting blows)
    function resolver:resolveAvoid(action, result)
        local actor = action.actor
        local card = action.card
        local destinationZone = action.destinationZone

        -- S7.2: Check for rooted condition
        if actor.conditions and actor.conditions.rooted then
            result.success = false
            result.description = "Rooted! Cannot avoid."
            result.effects[#result.effects + 1] = "rooted_blocked"
            return
        end

        if destinationZone then
            local canMove, moveError = self:canMoveBetweenZones(action, actor.zone, destinationZone)
            if not canMove then
                result.success = false
                if moveError == "zone_not_found" then
                    result.description = "Avoid failed: destination zone is invalid."
                    result.effects[#result.effects + 1] = "zone_not_found"
                else
                    result.description = "Avoid failed: destination zone is not adjacent."
                    result.effects[#result.effects + 1] = "non_adjacent_move_blocked"
                end
                return
            end
        end

        local avoidValue = result.testValue or ((card.value or 0) + (actor.pentacles or 0))
        local engagedEnemies = self:getEngagedEnemies(actor, action.allEntities)
        local failures = 0
        local wounds = 0
        local declinedWounds = {}
        local avoidOpponents = {}
        result.avoidValue = avoidValue

        if #engagedEnemies == 0 and action.target then
            local targetInitiative = self:getTargetInitiative(action.target, action) or
                (10 + (action.target.pentacles or 0))
            result.targetInitiative = targetInitiative
            result.avoidTarget = action.target
            result.avoidOpponents = {
                {
                    opponent = action.target,
                    initiative = targetInitiative,
                    avoided = avoidValue > targetInitiative,
                    blocked = avoidValue <= targetInitiative,
                }
            }
            if avoidValue <= targetInitiative then
                result.success = false
                result.description = "Avoid failed: target blocked movement."
                result.effects[#result.effects + 1] = "avoid_blocked"
                return
            end
            result.effects[#result.effects + 1] = "avoid_target_passed"
        end

        for _, enemy in ipairs(engagedEnemies) do
            local enemyInit = self:getTargetInitiative(enemy, action) or (10 + (enemy.pentacles or 0))
            local opponentResult = {
                opponent = enemy,
                initiative = enemyInit,
                avoided = avoidValue >= enemyInit,
                failed = avoidValue < enemyInit,
                woundDealt = false,
                woundDeclined = false,
            }
            if avoidValue < enemyInit then
                failures = failures + 1

                if self:getAvoidFailureWoundChoice(enemy, action) == "decline" then
                    declinedWounds[#declinedWounds + 1] = enemy
                    opponentResult.woundDeclined = true
                    result.effects[#result.effects + 1] = "avoid_wound_declined"
                    self.eventBus:emit("avoid_wound_declined", {
                        attacker = enemy,
                        victim = actor,
                    })
                else
                    wounds = wounds + 1
                    opponentResult.woundDealt = true
                    local woundResult = actor:takeWound(false)
                    self.eventBus:emit(events.EVENTS.WOUND_TAKEN, {
                        entity = actor,
                        result = woundResult,
                        source = "avoid_failed",
                    })
                end
            end
            avoidOpponents[#avoidOpponents + 1] = opponentResult
        end
        result.avoidFailures = failures
        result.avoidWounds = wounds
        if #avoidOpponents > 0 then
            result.avoidOpponents = avoidOpponents
        end
        if #declinedWounds > 0 then
            result.avoidWoundDeclines = declinedWounds
        end

        result.success = (failures == 0)
        if result.success then
            result.description = "Avoided successfully."
            result.effects[#result.effects + 1] = "avoid_success"
        else
            result.description = "Avoided, but took " .. wounds .. " Wound(s)."
            result.effects[#result.effects + 1] = "avoid_failed"
        end

        -- Clear engagements and move regardless of success
        self:clearAllEngagements(actor, action.allEntities)

        if destinationZone then
            local oldZone = actor.zone
            if self.zoneSystem and actor and actor.id then
                local placed, err = self.zoneSystem:placeEntity(actor.id, destinationZone)
                if not placed then
                    result.success = false
                    result.description = "Avoid failed: destination zone could not be entered."
                    result.effects[#result.effects + 1] = "zone_sync_failed"
                    if err then
                        result.effects[#result.effects + 1] = "zone_sync_error_" .. tostring(err)
                    end
                    return
                end
            end
            actor.zone = destinationZone
            self:discardMovedAwayProtectedDefense(actor, oldZone, destinationZone, action, result)
            result.oldZone = oldZone
            result.newZone = destinationZone
            result.destinationZone = destinationZone
            result.movementType = action.type or M.ACTION_TYPES.AVOID
            result.avoidMovement = {
                actor = actor,
                oldZone = oldZone,
                newZone = destinationZone,
                destinationZone = destinationZone,
                movementType = result.movementType,
                avoidValue = result.avoidValue,
                targetInitiative = result.targetInitiative,
                avoidFailures = result.avoidFailures,
                avoidWounds = result.avoidWounds,
                avoidWoundDeclines = result.avoidWoundDeclines,
                avoidOpponents = result.avoidOpponents,
            }
            result.description = result.description .. " Moved to " .. destinationZone

            self.eventBus:emit("entity_zone_changed", {
                entity = actor,
                oldZone = oldZone,
                newZone = destinationZone,
            })
        end
    end

    ----------------------------------------------------------------------------
    -- THE FOOL INTERRUPT (S4.9)
    -- The Fool allows an immediate action out of turn order
    -- Playing The Fool grants a free action with a follow-up card
    ----------------------------------------------------------------------------

    --- Resolve The Fool interrupt
    -- @param action table: { actor, card (The Fool), followUpCard, followUpAction, target }
    -- @param result table: Result to populate
    -- @return table: The result
    function resolver:resolveFoolInterrupt(action, result)
        result.success = true
        result.isFoolInterrupt = true
        result.foolInterrupt = true
        result.effects[#result.effects + 1] = "fool_interrupt"

        -- The Fool by itself just grants the interrupt opportunity
        -- If there's a follow-up action specified, resolve that instead
        local foolFollowUpActionType = action.foolFollowUpAction or action.followUpAction

        if action.followUpCard and foolFollowUpActionType then
            -- Create a sub-action using the follow-up card while preserving
            -- target, zone, controller, and special action metadata.
            local followUpAction = {}
            for key, value in pairs(action) do
                followUpAction[key] = value
            end
            followUpAction.card = action.followUpCard
            followUpAction.type = foolFollowUpActionType
            followUpAction.followUpCard = nil
            followUpAction.foolFollowUpAction = nil
            if not action.foolFollowUpAction then
                followUpAction.followUpAction = nil
            end
            followUpAction.foolCard = action.foolCard or action.card
            followUpAction.isFoolInterrupt = true
            followUpAction.foolInterrupt = true
            followUpAction.isInterrupt = true

            -- Resolve the follow-up action
            local followUpResult = self:resolve(followUpAction)

            -- Merge results
            result.followUpResult = followUpResult
            result.description = "The Fool! Immediate action: " .. (followUpResult.description or "")
            result.damageDealt = followUpResult.damageDealt
            result.isGreat = followUpResult.isGreat

            -- Copy effects from follow-up
            for _, effect in ipairs(followUpResult.effects) do
                result.effects[#result.effects + 1] = effect
            end
        else
            -- No follow-up specified - Fool grants free movement or simple action
            result.description = "The Fool! You may take an immediate action."
            result.effects[#result.effects + 1] = "pending_fool_action"

            -- Emit event for UI to prompt for follow-up action
            self.eventBus:emit("fool_interrupt", {
                actor = action.actor,
                awaitingFollowUp = true,
            })
        end

        -- Attach result
        action.result = result

        return result
    end

    ----------------------------------------------------------------------------
    -- DAMAGE APPLICATION (S7.6: Updated with weapon cleave, S7.7: damage types)
    ----------------------------------------------------------------------------

    function resolver:getIndexedWoundOptions(woundOptions, entity, woundIndex)
        if not woundOptions then
            return nil
        end

        if type(woundOptions) ~= "table" then
            return { choice = woundOptions }
        end

        if entity and entity.id and woundOptions[entity.id] ~= nil then
            return self:getIndexedWoundOptions(woundOptions[entity.id], entity, woundIndex)
        end

        if woundOptions[woundIndex] ~= nil then
            return self:getIndexedWoundOptions(woundOptions[woundIndex], entity, woundIndex)
        end

        return woundOptions
    end

    function resolver:getActionWoundOptions(action, entity)
        if not action then
            return nil
        end

        if action.targetWoundOptions then
            return action.targetWoundOptions
        end
        if action.woundOptions then
            return action.woundOptions
        end
        if action.targetWoundChoices then
            return action.targetWoundChoices
        end
        if action.woundChoices then
            return action.woundChoices
        end
        if action.targetWoundChoice or action.woundChoice or action.targetWoundTalentId or action.woundTalentId then
            return {
                choice = action.targetWoundChoice or action.woundChoice,
                talentId = action.targetWoundTalentId or action.woundTalentId,
                useAegis = action.useAegis,
                enterBerserkergang = action.enterBerserkergang or action.enterBerserk,
            }
        end

        return nil
    end

    function resolver:isBerserkergangActive(actor)
        if not actor then
            return false
        end
        local conditions = actor.conditions or {}
        return conditions.berserkergang == true or
            (actor.berserkergang and actor.berserkergang.active ~= false)
    end

    function resolver:hasBerserkergangAttackFavor(actor, actionType)
        if not self:isBerserkergangActive(actor) then
            return false
        end
        local normalizedType = self:normalizeActionType(actionType)
        return normalizedType == M.ACTION_TYPES.MELEE or normalizedType == M.ACTION_TYPES.MISSILE
    end

    function resolver:isBiteDamageSource(weapon, damageContext)
        damageContext = damageContext or {}
        local action = damageContext.action or {}
        if damageContext.bite == true or damageContext.source == "bite" or action.bite == true then
            return true
        end
        local actionType = self:normalizeActionType(action.type or "")
        if actionType == M.ACTION_TYPES.DEVIL_BITE then
            return true
        end
        local props = weapon and weapon.properties or {}
        local weaponKey = normalizeTalentKey(weapon and (weapon.weaponType or weapon.type or weapon.name or weapon.id))
        return weaponKey == "bite" or weaponKey == "fangs" or weaponKey == "teeth" or
            props.bite == true or props.fangs == true
    end

    function resolver:destroyWeaponForQuicksilverBlood(weapon, effects, victim)
        if not weapon or weapon.destroyed then
            return false
        end
        if not itemMatchesMaterial(weapon, "metal") then
            return false
        end

        weapon.destroyed = true
        weapon.broken = true
        weapon.notches = weapon.durability or weapon.notches or 1
        weapon.properties = weapon.properties or {}
        weapon.properties.destroyed = true
        weapon.properties.broken = true
        effects[#effects + 1] = "quicksilver_blood_weapon_destroyed"
        effects[#effects + 1] = "weapon_destroyed"
        self.eventBus:emit("quicksilver_blood_weapon_destroyed", {
            target = victim,
            weapon = weapon,
        })
        return true
    end

    function resolver:applyPoisonBloodReaction(victim, weapon, damageContext, effects)
        if not self:isBiteDamageSource(weapon, damageContext) then
            return false
        end
        local action = damageContext and damageContext.action or {}
        local attacker = (damageContext and (damageContext.attacker or damageContext.sourceEntity)) or action.actor
        if not attacker or attacker == victim or not attacker.takeWound then
            return false
        end
        if self:isDevil(attacker) or attacker.poisonImmune == true or
           (attacker.conditions and attacker.conditions.poisonImmune) then
            effects[#effects + 1] = "poison_blood_blocked"
            effects[#effects + 1] = "poison_immunity"
            return false
        end

        local poisonResult = attacker:takeWound("critical", {
            source = "poison_blood",
            attacker = victim,
        })
        victim.poisonBloodReaction = {
            attacker = attacker,
            result = poisonResult,
        }
        effects[#effects + 1] = "poison_blood_critical"
        effects[#effects + 1] = "critical"
        self.eventBus:emit("poison_blood_critical", {
            target = victim,
            attacker = attacker,
            result = poisonResult,
        })
        return true
    end

    function resolver:recordBerserkergangAllyEnemy(victim, damageContext)
        if not self:isBerserkergangActive(victim) then
            return false
        end
        local action = damageContext and damageContext.action or {}
        local attacker = (damageContext and (damageContext.attacker or damageContext.sourceEntity)) or action.actor
        if not attacker or attacker == victim or attacker.isPC ~= victim.isPC then
            return false
        end
        victim.berserkergang = victim.berserkergang or { active = true }
        victim.berserkergang.enemies = victim.berserkergang.enemies or {}
        victim.berserkergang.enemies[attacker.id or attacker.name or tostring(attacker)] = true
        return true
    end

    function resolver:applyWoundedTalentDamageReaction(entity, woundResult, weapon, damageContext, effects)
        if woundResult ~= "talent_wounded" or not entity then
            return false
        end
        local talentId = entity.lastWoundedTalentId
        local talentKey = normalizeTalentKey(talentId)
        if talentKey == "" then
            return false
        end

        local applied = false
        if talentKey == "quicksilver_blood" then
            applied = self:destroyWeaponForQuicksilverBlood(weapon, effects, entity) or applied
        elseif talentKey == "poison_blood" then
            applied = self:applyPoisonBloodReaction(entity, weapon, damageContext or {}, effects) or applied
        elseif talentKey == "blur" then
            effects[#effects + 1] = "blur_shrouded"
            applied = true
        elseif talentKey == "berserkergang" and self:isBerserkergangActive(entity) then
            effects[#effects + 1] = "berserkergang_entered"
            applied = true
        end

        return applied
    end

    function resolver:clearBerserkergang(actor, reason)
        if not actor or not self:isBerserkergangActive(actor) then
            return false
        end
        actor.conditions = actor.conditions or {}
        actor.conditions.berserkergang = false
        actor.conditions.berserk = false
        actor.berserkergang = actor.berserkergang or {}
        actor.berserkergang.active = false
        actor.berserkergang.endedReason = reason or "ended"
        return true
    end

    function resolver:berserkergangEnemiesDefeated(actor, allEntities)
        if not actor or type(allEntities) ~= "table" then
            return false
        end
        local extraEnemies = actor.berserkergang and actor.berserkergang.enemies or {}
        local sawEnemy = false
        for _, entity in ipairs(allEntities) do
            if entity ~= actor then
                local key = entity.id or entity.name or tostring(entity)
                local isEnemy = entity.isPC ~= actor.isPC or extraEnemies[key] == true
                if isEnemy then
                    sawEnemy = true
                    if not self:isDefeatedForDefense(entity) then
                        return false
                    end
                end
            end
        end
        return sawEnemy
    end

    function resolver:endBerserkergang(actor, opts)
        opts = opts or {}
        if not self:isBerserkergangActive(actor) then
            return { success = false, reason = "not_berserk" }
        end
        if self:berserkergangEnemiesDefeated(actor, opts.allEntities or opts.combatants) then
            self:clearBerserkergang(actor, "enemies_defeated")
            return { success = true, reason = "enemies_defeated", resolveSpent = 0 }
        end
        if opts.spendResolve or opts.endEarly then
            if type(actor.resolve) == "table" then
                if (actor.resolve.current or 0) <= 0 then
                    return { success = false, reason = "resolve_required" }
                end
                actor.resolve.current = actor.resolve.current - 1
            elseif (actor.resolve or 0) > 0 then
                actor.resolve = actor.resolve - 1
            else
                return { success = false, reason = "resolve_required" }
            end
            self:clearBerserkergang(actor, "resolve_spent")
            return { success = true, reason = "resolve_spent", resolveSpent = 1 }
        end
        return { success = false, reason = "enemies_remain" }
    end

    function resolver:aegisEntityMatches(candidate, entity)
        if not candidate or not entity then
            return false
        end
        local actor = candidate.actor or candidate.entity or candidate.defender or candidate
        return actor == entity or (actor.id and entity.id and actor.id == entity.id)
    end

    function resolver:aegisSelectionIncludesEntity(selection, entity)
        if not selection then
            return true
        end
        if not entity then
            return false
        end

        if entity.id and selection[entity.id] ~= nil then
            return self:aegisEntityMatches(selection[entity.id], entity) or selection[entity.id] == true
        end

        for _, candidate in pairs(selection) do
            if self:aegisEntityMatches(candidate, entity) then
                return true
            end
        end

        return false
    end

    function resolver:damageOptionsElectAegis(woundOptions, damageContext)
        if damageContext and (damageContext.useAegis == true or damageContext.aegis == true) then
            return true
        end

        if type(woundOptions) ~= "table" then
            return normalizeTalentKey(woundOptions) == "aegis"
        end

        if woundOptions.useAegis == true or woundOptions.aegis == true or woundOptions.aegisShield == true then
            return true
        end

        local choice = normalizeTalentKey(woundOptions.choice or woundOptions.woundChoice)
        return choice == "aegis" or choice == "shield_aegis"
    end

    function resolver:aegisElectionAppliesToEntity(entity, woundOptions, damageContext)
        local action = damageContext and damageContext.action or {}
        local selectedActors = damageContext and damageContext.aegisActors or action.aegisActors
        if selectedActors ~= nil and selectedActors ~= false then
            return self:aegisSelectionIncludesEntity(selectedActors, entity)
        end

        local optionActor = nil
        if type(woundOptions) == "table" then
            optionActor = woundOptions.aegisActor
        end
        local actor = damageContext and damageContext.aegisActor or action.aegisActor or optionActor
        if actor ~= nil and actor ~= false then
            return self:aegisEntityMatches(actor, entity)
        end

        return true
    end

    function resolver:isAegisPhysicalSource(effects, weapon, damageContext)
        if damageContext then
            if damageContext.aegisPhysical ~= nil then
                return damageContext.aegisPhysical == true
            end
            if damageContext.physical ~= nil then
                return damageContext.physical == true
            end

            local source = normalizeTalentKey(damageContext.source or damageContext.damageSource)
            if source == "attack" or source == "trap" or source == "hazard" or source == "physical" then
                return true
            end
        end

        if weapon then
            return true
        end

        for _, effect in ipairs(effects or {}) do
            local normalized = normalizeTalentKey(effect)
            if normalized == "physical" or normalized == "weapon" or normalized == "attack" or
               normalized == "melee" or normalized == "missile" or normalized == "trap" then
                return true
            end
        end

        return false
    end

    function resolver:resolveAegisDamageSubstitution(entity, effects, weapon, woundOptions, damageContext)
        if not entityHasUsableTalent(entity, "aegis") then
            return nil
        end
        if not self:damageOptionsElectAegis(woundOptions, damageContext) then
            return nil
        end
        if not self:aegisElectionAppliesToEntity(entity, woundOptions, damageContext) then
            return nil
        end
        if damageContext and normalizeTalentKey(damageContext.source or damageContext.damageSource) == "attack" and
           weapon and M.isWeaponType(weapon, "FLAIL") then
            effects[#effects + 1] = "flail_shield_bypass"
            return nil
        end
        if not self:isAegisPhysicalSource(effects, weapon, damageContext) then
            return nil
        end

        local shield, location = self:getIntactShield(entity)
        if not shield then
            return nil
        end

        local notchResult = inventory.addNotch(shield)
        local record = {
            entity = entity,
            shield = shield,
            location = location,
            notchResult = notchResult,
            prevented = true,
        }

        effects[#effects + 1] = "aegis_shield_notched"
        effects[#effects + 1] = "aegis_effect_prevented"
        if notchResult == "destroyed" then
            effects[#effects + 1] = "shield_destroyed"
        end

        self.eventBus:emit(events.EVENTS.ITEM_DAMAGE_ABSORBED, {
            entity = entity,
            item = shield,
            itemId = shield.id,
            location = location,
            talent = "aegis",
            notchResult = notchResult,
            destroyed = notchResult == "destroyed",
        })

        return record
    end

    function resolver:woundOptionsHaveExplicitChoice(woundOptions, entity)
        local options = self:getIndexedWoundOptions(woundOptions, entity, 1)
        if type(options) ~= "table" then
            return options ~= nil
        end
        return options.choice ~= nil or options.woundChoice ~= nil
    end

    function resolver:shouldRequestWoundChoice(entity, amount, damageType, woundOptions, damageContext)
        if not entity or not entity.isPC or not entity.getAvailableWoundChoices then
            return false
        end
        if (amount or 0) <= 0 then
            return false
        end
        if self:woundOptionsHaveExplicitChoice(woundOptions, entity) then
            return false
        end

        damageContext = damageContext or {}
        local action = damageContext.action or {}
        if damageContext.woundChoiceResolved == true or action.woundChoiceResolved == true then
            return false
        end
        if not (damageContext.promptWoundChoice == true or action.promptWoundChoice == true or
                damageContext.requestWoundChoice == true or action.requestWoundChoice == true) then
            return false
        end

        local choices = entity:getAvailableWoundChoices(damageType)
        return #choices > 1
    end

    function resolver:requestWoundChoice(entity, amount, effects, weapon, allEntities, woundOptions, damageContext, damageType)
        damageContext = damageContext or {}
        local action = damageContext.action or {}
        local result = damageContext.result
        local choices = entity:getAvailableWoundChoices(damageType)
        local talentChoices = entity.getAvailableWoundTalentChoices and entity:getAvailableWoundTalentChoices() or {}
        local promptAmount = math.min(tonumber(amount) or 1, 1)
        local remainingAmount = math.max((tonumber(amount) or promptAmount) - promptAmount, 0)
        local pending = {
            pendingWoundChoice = true,
            entity = entity,
            amount = promptAmount,
            totalAmount = amount,
            remainingAmount = remainingAmount,
            damageType = damageType,
            effects = effects,
            weapon = weapon,
            allEntities = allEntities,
            woundOptions = woundOptions,
            damageContext = damageContext,
            choices = choices,
            talentChoices = talentChoices,
            action = action,
            result = result,
        }

        effects[#effects + 1] = "wound_choice_required"
        if result then
            result.pendingWoundChoice = pending
            result.effects = result.effects or effects
            result.description = (result.description or "") .. "Wound choice required. "
        end
        action.pendingWoundChoice = pending

        self.eventBus:emit(events.EVENTS.REQUEST_WOUND_CHOICE, pending)
        return pending
    end

    function resolver:copyWoundChoiceDamageContext(damageContext)
        local copy = {}
        for key, value in pairs(damageContext or {}) do
            copy[key] = value
        end
        return copy
    end

    function resolver:resolvePendingWoundChoice(action, choiceData)
        action = action or {}
        choiceData = choiceData or {}
        local pending = action.pendingWoundChoice or
            (action.result and action.result.pendingWoundChoice) or choiceData.pendingWoundChoice
        if not pending then
            return false, "no_pending_wound_choice"
        end

        local choice = choiceData.choice or choiceData.woundChoice
        local entity = pending.entity
        local ok, reason = entity and entity.canTakeWoundChoice and entity:canTakeWoundChoice(choice, pending.damageType)
        if not ok then
            return false, reason or "invalid_wound_choice"
        end

        local options = {
            choice = choice,
            woundChoice = choice,
            talentId = choiceData.talentId or choiceData.woundTalentId,
            enterBerserkergang = choiceData.enterBerserkergang or choiceData.enterBerserk,
        }
        local damageContext = self:copyWoundChoiceDamageContext(pending.damageContext)
        damageContext.woundChoiceResolved = true

        local woundResult = self:applyDamage(entity, pending.amount, pending.effects, pending.weapon,
            pending.allEntities, options, damageContext)
        action.pendingWoundChoice = nil
        if action.result then
            action.result.pendingWoundChoice = nil
            action.result.woundChoice = choice
            action.result.woundChoiceResult = woundResult
            action.result.woundChoices = action.result.woundChoices or {}
            action.result.woundChoices[#action.result.woundChoices + 1] = {
                choice = choice,
                talentId = options.talentId,
                result = woundResult,
            }
            action.result.effects = action.result.effects or pending.effects
        end

        local remainingAmount = tonumber(pending.remainingAmount) or 0
        if remainingAmount > 0 then
            local remainingContext = self:copyWoundChoiceDamageContext(pending.damageContext)
            remainingContext.woundChoiceResolved = nil
            if self:shouldRequestWoundChoice(entity, remainingAmount, pending.damageType,
                    pending.woundOptions, remainingContext) then
                local nextPending = self:requestWoundChoice(entity, remainingAmount, pending.effects,
                    pending.weapon, pending.allEntities, pending.woundOptions, remainingContext,
                    pending.damageType)
                return true, nextPending
            end

            local remainingResult = self:applyDamage(entity, remainingAmount, pending.effects,
                pending.weapon, pending.allEntities, pending.woundOptions, remainingContext)
            if action.result then
                action.result.remainingWoundChoiceResult = remainingResult
            end
        end

        return true, woundResult
    end

    function resolver:resolveAnimalCompanionDamage(entity, amount, effects, damageType, damageContext)
        if not animal_companions.isAnimalCompanion(entity) or entity.takeWound then
            return nil
        end

        local owner = damageContext and (damageContext.owner or damageContext.companionOwner or
            damageContext.master) or entity.owner or entity.master
        local record = {
            result = "animal_companion_damage",
            entity = entity,
            woundResults = {},
        }

        for woundIndex = 1, amount do
            local woundResult, detail = animal_companions.takeWound(entity, {
                damageType = damageType,
                owner = owner,
                allowFamiliarResolve = damageContext and damageContext.allowFamiliarResolve,
            })
            record.woundResults[#record.woundResults + 1] = woundResult
            effects[#effects + 1] = "animal_companion_" .. tostring(woundResult)
            if detail and detail.resolveSpent then
                effects[#effects + 1] = "familiar_resolve_spent"
                record.familiarResolveSpent = true
            end

            print("[DAMAGE] " .. (entity.name or entity.id or "Animal companion") ..
                  " takes " .. damageType .. " wound -> " .. tostring(woundResult))

            self.eventBus:emit(events.EVENTS.WOUND_TAKEN, {
                entity = entity,
                result = woundResult,
                damageType = damageType,
            })

            if entity.conditions and (entity.conditions.dead or entity.conditions.deaths_door or
               entity.conditions.out_of_action) then
                record.defeated = true
                if entity.conditions.dead then
                    self:clearAllEngagements(entity)
                end
                self.eventBus:emit(events.EVENTS.ENTITY_DEFEATED, {
                    entity = entity,
                })
                break
            end
        end

        return record
    end

    function resolver:damageHasAnyTag(effects, weapon, damageContext, tags)
        if not tags then
            return false
        end

        if damageContext then
            for tag in pairs(tags) do
                if damageContext[tag] == true then
                    return true
                end
            end
            for _, key in ipairs({ "damageType", "element", "source", "damageSource", "effect" }) do
                local normalized = normalizeTalentKey(damageContext[key])
                if normalized and tags[normalized] then
                    return true
                end
            end
        end

        for _, effect in ipairs(effects or {}) do
            local normalized = normalizeTalentKey(effect)
            if normalized and tags[normalized] then
                return true
            end
        end

        local props = weapon and weapon.properties or {}
        for _, value in ipairs({
            weapon and weapon.damageType,
            weapon and weapon.element,
            weapon and weapon.material,
            props.damageType,
            props.element,
            props.material,
        }) do
            local normalized = normalizeTalentKey(value)
            if normalized and tags[normalized] then
                return true
            end
        end

        for tag in pairs(tags) do
            if weapon and weapon[tag] == true or props[tag] == true then
                return true
            end
        end

        return false
    end

    function resolver:resolveAlchemicalPotionDamageImmunity(entity, amount, effects, weapon, damageContext)
        if not entity or (amount or 0) <= 0 then
            return nil
        end

        local conditions = entity.conditions or {}
        if (conditions.fire_immunity or conditions.heat_immunity) and
           self:damageHasAnyTag(effects, weapon, damageContext, {
               fire = true,
               heat = true,
               flame = true,
               flames = true,
               burning = true,
               hellfire = true,
               heavenfire = true,
           }) then
            effects[#effects + 1] = "alchemical_fire_immunity"
            self.eventBus:emit("alchemical_damage_immunity", {
                entity = entity,
                element = "fire",
                source = "devil_potion",
            })
            return {
                result = "immune",
                immune = true,
                reason = "alchemical_fire_immunity",
                element = "fire",
            }
        end

        if (conditions.cold_immunity or conditions.ice_damage_immunity) and
           self:damageHasAnyTag(effects, weapon, damageContext, {
               cold = true,
               ice = true,
               frost = true,
               freezing = true,
               blizzard = true,
           }) then
            effects[#effects + 1] = "alchemical_cold_immunity"
            self.eventBus:emit("alchemical_damage_immunity", {
                entity = entity,
                element = "cold",
                source = "winter_wolf_potion",
            })
            return {
                result = "immune",
                immune = true,
                reason = "alchemical_cold_immunity",
                element = "cold",
            }
        end

        if (conditions.water_breathing or conditions.underwater_breathing or conditions.gills) and
           self:damageHasAnyTag(effects, weapon, damageContext, {
               drowning = true,
               suffocation = true,
               underwater = true,
               underwater_suffocation = true,
               asphyxiation = true,
           }) then
            effects[#effects + 1] = "alchemical_water_breathing"
            self.eventBus:emit("alchemical_damage_immunity", {
                entity = entity,
                element = "drowning",
                source = "kelpie_potion",
            })
            return {
                result = "immune",
                immune = true,
                reason = "alchemical_water_breathing",
                element = "drowning",
            }
        end

        if (conditions.ingestion_immunity or conditions.harmless_swallowing) and
           self:damageHasAnyTag(effects, weapon, damageContext, {
               ingestion = true,
               ingested = true,
               swallowing = true,
               swallowed = true,
               eaten = true,
               eating = true,
               digestive = true,
               harmful_food = true,
               glass_shards = true,
               live_coals = true,
           }) then
            effects[#effects + 1] = "alchemical_ingestion_immunity"
            self.eventBus:emit("alchemical_damage_immunity", {
                entity = entity,
                element = "ingestion",
                source = "ogre_potion",
            })
            return {
                result = "immune",
                immune = true,
                reason = "alchemical_ingestion_immunity",
                element = "ingestion",
            }
        end

        return nil
    end

    function resolver:resolveElementProtectionDamage(entity, amount, effects, weapon, damageContext)
        if not entity or (amount or 0) <= 0 then
            return nil
        end

        local checks = {
            {
                element = "fire",
                tags = {
                    fire = true,
                    heat = true,
                    flame = true,
                    flames = true,
                    burning = true,
                    hellfire = true,
                    heavenfire = true,
                },
            },
            {
                element = "water",
                tags = {
                    cold = true,
                    ice = true,
                    icy = true,
                    icy_blast = true,
                    frost = true,
                    freezing = true,
                    blizzard = true,
                },
            },
            {
                element = "air",
                tags = {
                    suffocation = true,
                    asphyxiation = true,
                    breathless = true,
                    drowning = true,
                    underwater_suffocation = true,
                },
            },
            {
                element = "earth",
                tags = {
                    falling = true,
                    fall = true,
                    falling_damage = true,
                },
            },
        }

        for _, check in ipairs(checks) do
            if self:doesElementProtectionBlock(entity, check.element) and
               self:damageHasAnyTag(effects, weapon, damageContext, check.tags) then
                effects[#effects + 1] = "element_protection_blocked"
                effects[#effects + 1] = "protection_from_elements_" .. check.element .. "_block"
                self.eventBus:emit("element_protection_damage_blocked", {
                    entity = entity,
                    element = check.element,
                    source = "protection_from_elements",
                })
                return {
                    result = "immune",
                    immune = true,
                    reason = "protection_from_elements_" .. check.element .. "_block",
                    element = check.element,
                }
            end
        end

        return nil
    end

    --- Apply damage to an entity
    -- @param entity table: Target entity
    -- @param amount number: Number of wounds
    -- @param effects table: Effect flags (pierce_armor, piercing, critical, etc.)
    -- @param weapon table: Optional weapon for cleave check
    -- @param allEntities table: Optional list of all entities for cleave targeting
    -- @param woundOptions table|string: Optional PC wound choice data for explicit wound selection
    -- @param damageContext table|nil: Optional source metadata, e.g. { source = "attack", useAegis = true }
    function resolver:applyDamage(entity, amount, effects, weapon, allEntities, woundOptions, damageContext)
        effects = effects or {}

        local alchemicalImmunityResult = self:resolveAlchemicalPotionDamageImmunity(entity, amount, effects, weapon, damageContext)
        if alchemicalImmunityResult then
            return alchemicalImmunityResult
        end

        local elementProtectionResult = self:resolveElementProtectionDamage(entity, amount, effects, weapon, damageContext)
        if elementProtectionResult then
            return elementProtectionResult
        end

        local yellowKingSkullResult = self:resolveYellowKingCrystalSkullDamage(entity, amount, effects, weapon, damageContext)
        if yellowKingSkullResult then
            return yellowKingSkullResult
        end

        local titanResult = self:resolveTitanSporehulkDamage(entity, amount, effects, weapon, damageContext)
        if titanResult then
            return titanResult
        end

        local bloodybonesResult = self:resolveBloodybonesImmuneDamage(entity, amount, effects, weapon, damageContext)
        if bloodybonesResult then
            return bloodybonesResult
        end

        local vampireMistResult = self:resolveVampireMistFormDamage(entity, amount, effects, weapon, damageContext)
        if vampireMistResult then
            return vampireMistResult
        end

        local vampireInvulnerableResult = self:resolveVampireInvulnerabilityDamage(entity, amount, effects, weapon, damageContext)
        if vampireInvulnerableResult then
            return vampireInvulnerableResult
        end

        local wraithShadowResult = self:resolveWraithShadowFormDamage(entity, amount, effects, weapon, damageContext)
        if wraithShadowResult then
            return wraithShadowResult
        end

        local jinnSmokelessFireResult = self:resolveJinnBodyOfSmokelessFireDamage(entity, amount, effects, weapon, damageContext)
        if jinnSmokelessFireResult then
            return jinnSmokelessFireResult
        end

        local eliteIntangibleResult = self:resolveEliteIntangibleDamage(entity, amount, effects, weapon, damageContext)
        if eliteIntangibleResult then
            return eliteIntangibleResult
        end

        local eliteInvulnerableResult = self:resolveEliteInvulnerableDamage(entity, amount, effects, weapon, damageContext)
        if eliteInvulnerableResult then
            return eliteInvulnerableResult
        end

        local eliteThresholdResult = self:resolveEliteThresholdDamage(entity, amount, effects, weapon, damageContext)
        if eliteThresholdResult then
            return eliteThresholdResult
        end

        local elementalImmunityResult = self:resolveElementalImmunityDamage(entity, amount, effects, weapon, damageContext)
        if elementalImmunityResult then
            return elementalImmunityResult
        end

        local devilWeaponResult = self:resolveDevilUntouchedByHotIronDamage(entity, amount, effects, weapon, damageContext)
        if devilWeaponResult then
            return devilWeaponResult
        end

        local brainSpiderSquishyResult = self:resolveBrainSpiderSquishyDamage(entity, amount, effects, weapon, damageContext)
        if brainSpiderSquishyResult then
            return brainSpiderSquishyResult
        end

        local sorcerousStrangeBodyResult = self:resolveSorcerousStrangeBodyDamage(entity, amount, effects, weapon, damageContext)
        if sorcerousStrangeBodyResult then
            return sorcerousStrangeBodyResult
        end

        local weaponImmunityKey = self:getWeaponImmunityKey(weapon)
        local zombieLastGraspResult = self:resolveZombieLastGraspWound(entity, amount, effects, allEntities, damageContext)
        if zombieLastGraspResult then
            if zombieLastGraspResult.remainingAmount <= 0 then
                return zombieLastGraspResult
            end
            amount = zombieLastGraspResult.remainingAmount
        end

        if self:isMimicTarget(entity) and entity.mimicWeaponImmunityType and
           weaponImmunityKey == entity.mimicWeaponImmunityType then
            effects[#effects + 1] = "mimic_harden_immune"
            self.eventBus:emit("mimic_harden_immune", {
                entity = entity,
                weapon = weapon,
                weaponType = weaponImmunityKey,
            })
            return {
                result = "immune",
                immune = true,
                weaponType = weaponImmunityKey,
            }
        end

        if self:isSkeletonPiercingWeaponImmune(entity, weapon) then
            effects[#effects + 1] = "skeleton_fleshless_piercing_immune"
            self.eventBus:emit("skeleton_fleshless_piercing_immune", {
                entity = entity,
                weapon = weapon,
            })
            return {
                result = "immune",
                immune = true,
                reason = "skeleton_fleshless",
                weaponType = weaponImmunityKey,
            }
        end

        if self:isSlimeImpermeableWeapon(entity, weapon) then
            effects[#effects + 1] = "slime_impermeable_membrane_immune"
            self.eventBus:emit("slime_impermeable_membrane_immune", {
                entity = entity,
                weapon = weapon,
            })
            return {
                result = "immune",
                immune = true,
                reason = "slime_impermeable_membrane",
                weaponType = weaponImmunityKey,
            }
        end

        local kelpieThresholdResult = self:resolveKelpieThreshold(entity, amount, effects, weapon, damageContext)
        if kelpieThresholdResult then
            return kelpieThresholdResult
        end

        amount = self:applyWinterWolfFireVulnerability(entity, amount, effects, weapon, damageContext)
        amount = self:applySorcerousStrangeBodyVulnerability(entity, amount, effects, weapon, damageContext)

        local dungeonLordPoolResult = self:resolveDungeonLordPoolDamage(entity, amount, effects, weapon, damageContext)
        if dungeonLordPoolResult then
            return dungeonLordPoolResult
        end

        -- S7.7: Determine damage type from effects
        local damageType = "normal"
        for _, eff in ipairs(effects) do
            if eff == "critical" then
                damageType = "critical"
                break
            elseif eff == "piercing" or eff == "pierce_armor" then
                damageType = "piercing"
            end
        end

        local animalCompanionResult = self:resolveAnimalCompanionDamage(entity, amount, effects, damageType, damageContext)
        if animalCompanionResult then
            return animalCompanionResult
        end

        local aegisOptions = self:getIndexedWoundOptions(woundOptions, entity, 1)
        local aegisResult = self:resolveAegisDamageSubstitution(entity, effects, weapon, aegisOptions, damageContext)
        if aegisResult then
            print("[DAMAGE] " .. (entity.name or entity.id) .. " uses Aegis; " ..
                  (aegisResult.shield.name or "shield") .. " -> " .. tostring(aegisResult.notchResult))
            if damageContext and damageContext.result then
                damageContext.result.aegisResult = aegisResult
                damageContext.result.aegisResults = damageContext.result.aegisResults or {}
                damageContext.result.aegisResults[#damageContext.result.aegisResults + 1] = aegisResult
            end
            return aegisResult
        end

        if self:shouldRequestWoundChoice(entity, amount, damageType, woundOptions, damageContext) then
            return self:requestWoundChoice(entity, amount, effects, weapon, allEntities, woundOptions,
                damageContext, damageType)
        end

        local wasDefeated = false
        local damageApplied = false
        for woundIndex = 1, amount do
            -- Call entity's takeWound with damage type (S7.7)
            local woundResult = entity:takeWound(damageType,
                self:getIndexedWoundOptions(woundOptions, entity, woundIndex))
            if woundResult and woundResult ~= "invulnerable" then
                damageApplied = true
            end
            if woundResult and woundResult ~= "invulnerable" then
                self:recordBerserkergangAllyEnemy(entity, damageContext)
                self:applyWoundedTalentDamageReaction(entity, woundResult, weapon, damageContext, effects)
            end

            print("[DAMAGE] " .. (entity.name or entity.id) .. " takes " .. damageType .. " wound -> " .. (woundResult or "?"))
            print("  Armor: " .. (entity.armorNotches or 0) ..
                  " | Conditions: stag=" .. tostring(entity.conditions and entity.conditions.staggered) ..
                  " inj=" .. tostring(entity.conditions and entity.conditions.injured) ..
                  " dd=" .. tostring(entity.conditions and entity.conditions.deaths_door) ..
                  " dead=" .. tostring(entity.conditions and entity.conditions.dead))

            -- Emit wound event for visual
            self.eventBus:emit(events.EVENTS.WOUND_TAKEN, {
                entity = entity,
                result = woundResult,
                damageType = damageType,
            })

            self:handleConcentrationHurt(entity, woundResult, damageType)

            -- Check for defeat
            if entity.conditions and (entity.conditions.dead or entity.conditions.deaths_door) then
                wasDefeated = true
                if self:isDevil(entity) then
                    local devilReleaseReason = entity.conditions.dead and "devil_destroyed" or "devil_defeated"
                    self:releaseDevilSwallowedCreatures(entity, effects, devilReleaseReason)
                end
                    if entity.conditions.dead then
                        print("[DEFEAT] " .. (entity.name or entity.id) .. " is DEAD!")
                        self:resolveYellowKingBodyDefeat(entity, effects, damageContext)
                        self:restoreWraithDrainedXP(entity, effects)
                        local releasedBadLittleHands = self:releaseAllBadLittleHandsItems(entity, "kill")
                    if #releasedBadLittleHands > 0 then
                        effects[#effects + 1] = "bad_little_hands_items_released_on_defeat"
                        self.eventBus:emit("bad_little_hands_items_released", {
                            entity = entity,
                            released = releasedBadLittleHands,
                            reason = "kill",
                        })
                    end
                    -- S6.3: Clear all engagements when defeated
                    self:clearAllEngagements(entity)

                    self.eventBus:emit(events.EVENTS.ENTITY_DEFEATED, {
                        entity = entity,
                    })
                end
                break
            end
        end

        if damageApplied then
            local ungoatRetribution = self:applyUngoatMaleficentRetribution(entity, effects, damageContext)
            if ungoatRetribution then
                entity.lastUngoatMaleficentRetribution = ungoatRetribution
            end
            self:clearFungoidPerfectImitation(entity, effects)
            self:applySlimeAcidicWeaponNotch(entity, weapon, effects)
            self:syncSlimeDynamicAttributes(entity)
            local attackAction = damageContext and damageContext.action
            local berserker = attackAction and attackAction.actor
            local combatants = allEntities or (attackAction and attackAction.allEntities)
            if self:isBerserkergangActive(berserker) and
               self:berserkergangEnemiesDefeated(berserker, combatants) then
                self:clearBerserkergang(berserker, "enemies_defeated")
                effects[#effects + 1] = "berserkergang_ended"
            end
        end

        if self:isMimicTarget(entity) and weaponImmunityKey and amount > 0 then
            entity.lastWoundingWeaponType = weaponImmunityKey
            entity.lastWoundingWeaponName = weapon and (weapon.weaponType or weapon.name or weapon.templateId) or weaponImmunityKey
        end

        -- S7.6: Axe Cleave - on defeat, reuse the Attack value against another opponent
        if wasDefeated and weapon and M.isWeaponType(weapon, "AXE") and allEntities then
            self:triggerAxeCleave(entity, weapon, allEntities, damageContext)
        end
    end

    function resolver:getAxeCleaveTargetInitiative(target, action)
        local maps = {
            action and action.cleaveTargetInitiatives or false,
            action and action.targetInitiatives or false,
            action and action.initiatives or false,
            action and action.initiativeValues or false,
        }
        for _, map in ipairs(maps) do
            if type(map) == "table" and target then
                local value = map[target] or map[target.id] or map[target.name]
                if type(value) == "table" then
                    value = value.value or (value.card and value.card.value)
                end
                value = tonumber(value)
                if value then
                    return value
                end
            end
        end

        local cleaveAction = action and {
            actor = action.actor,
            target = target,
            challengeController = action.challengeController,
            allEntities = action.allEntities,
        } or nil
        return self:getTargetInitiative(target, cleaveAction) or (10 + (target and target.pentacles or 0))
    end

    --- S7.6: Trigger axe cleave attack on another opponent in the same zone.
    function resolver:triggerAxeCleave(defeatedEntity, weapon, allEntities, damageContext)
        local action = damageContext and damageContext.action
        local attacker = action and action.actor
        local attackValue = damageContext and damageContext.attackValue
        if not defeatedEntity or not attacker or not attackValue then
            return nil
        end

        local zone = defeatedEntity.zone
        local cleaveTarget = nil

        -- Find another still-active opponent in the same zone.
        for _, e in ipairs(allEntities or {}) do
            local isOpponent = e ~= defeatedEntity and e ~= attacker and e.isPC ~= attacker.isPC
            if isOpponent and e.zone == zone and not self:isDefeatedForDefense(e) then
                cleaveTarget = e
                break
            end
        end

        if not cleaveTarget then
            return nil
        end

        local initiative = self:getAxeCleaveTargetInitiative(cleaveTarget, action)
        local defenderHasShield = self:entityHasShield(cleaveTarget)
        local success = (attackValue > initiative) or (attackValue == initiative and not defenderHasShield)
        local detail = {
            source = defeatedEntity,
            attacker = attacker,
            target = cleaveTarget,
            weapon = weapon,
            attackValue = attackValue,
            initiative = initiative,
            success = success,
            damageDealt = success and 1 or 0,
        }

        local sourceResult = damageContext and damageContext.result
        if sourceResult then
            sourceResult.axeCleave = detail
            sourceResult.effects = sourceResult.effects or {}
            sourceResult.effects[#sourceResult.effects + 1] = success and "axe_cleave" or "axe_cleave_missed"
            appendResultSentence(sourceResult, success and "Axe cleave hits another opponent." or "Axe cleave misses.")
        end

        if success then
            print("[CLEAVE] Axe cleaves into " .. (cleaveTarget.name or cleaveTarget.id) .. "!")
            self:applyDamage(cleaveTarget, 1, {}, weapon, nil, nil, {
                source = "axe_cleave",
                action = action,
                attackValue = attackValue,
            })
        end

        self.eventBus:emit("axe_cleave", detail)
        return detail
    end

    return resolver
end

return M
